// ==========================================
// ★ K 의 방 — S등급 직업 갈림길 · 파괴
// 전사 · 화염술사 · 권사 · 폭파공 · 대검사
// 파괴: 이쪽보다 영리한 것 앞에서, 그래도 부수는 손
// ==========================================

// ------------------------------------------
// 전사 · 무력
// ------------------------------------------
kJob('warrior', 'S', [

{ at:'S', t:'어둠 — 보폭을 맞추는 것',
  x:`불빛이 닿는 데까지가 길이다. 그 너머에서 발소리가 따라온다.<br><br>
    이쪽이 멈추면 멈춘다. 걸으면 걷는다. 반 박자 늦게. 수를 세어 보면 꼭 한 걸음이 남는다.<br>
    짐승은 보폭을 못 맞춘다. 이건 맞춘다. 맞출 줄 아는 것이 뒤에 있다.<br><br>
    무기 자루가 땀에 젖는다. 맨 뒤는 늘 무기 든 사람 자리다. 오늘은 그 자리가 제일 어둡다.`,
  o:[
    { l:'① 걸음을 끊지 않고, 반 박자에 뒤로 날을 찌른다.', k:'break', dc:24, cost:{ might:30 },
      ok:`왼발이 닿는 순간 허리만 돌려 뒤로 찔렀다. 돌아보지 않았다. 걸음은 그대로.<br><br>
        날 끝에 무엇이 걸렸다. 단단한 껍질 밑의 무른 것. 쇳소리 같은 비명이 났다가 뚝 끊겼다.<br>
        발소리가 사라졌다. 대신 저 멀리서 같은 비명이 둘 더 울렸다. 대답이다.<br><br>
        돌아보지 않고 찌르는 법을 몸이 외웠다. 등에도 눈이 있는 것처럼 저것들이 물러섰다.`,
      ng:`찔렀다. 허공이다. 반 박자가 아니었다. 저것이 먼저 박자를 바꿨다.<br><br>
        목덜미에 바람이 스쳤다. 턱 바로 밑을 무엇이 지나갔다. 비린 냄새가 남았다.<br>
        발소리가 다시 시작된다. 이번에는 양쪽에서. 박자가 서로 어긋난다. 일부러.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 보폭을 그대로 둔다 — 걸음 자체를 자세로 만든다.', k:'steady', dc:23, wake:1,
      ok:`보폭을 안 바꿨다. 어깨 힘을 빼고, 무기는 낮게, 걸음만 반듯하게.<br><br>
        따라오던 발소리가 흔들리기 시작했다. 맞추는 쪽이 먼저 지친다. 흉내에는 끝이 있다.<br>
        모퉁이를 돌 때쯤 발소리가 떨어져 나갔다. 흉내 낼 틈을 끝까지 안 줬다.<br><br>
        걷는 것도 자세라는 걸 알았다. 등 뒤에 무엇이 있어도 흐트러지지 않는 걸음. 그게 무기보다 먼저다.`,
      ng:`세 걸음을 못 갔다. 무릎이 제멋대로 빨라졌다. 몸이 먼저 도망치려 한다.<br><br>
        발소리가 그 틈에 바짝 붙었다. 숨소리가 들릴 거리다. 숨이 둘이다.<br>
        앞사람이 손을 뻗어 이쪽 소매를 잡아 끌었다. 불빛 안으로. 등이 식은땀으로 붙었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-20 } },
    { l:'③ 걸음 수를 센다 — 남는 한 걸음이 어디서 나는지.', k:'sense', dc:25,
      ok:`열 걸음을 세었다. 열한 번째 소리. 위치가 안 맞는다. 뒤가 아니다.<br><br>
        위다. 천장 배관을 짚으며 따라오고 있다. 발소리처럼 들리게. 바닥을 보게 하려고.<br>
        불빛을 위로 돌리자 긴 것이 배관 사이로 미끄러져 사라졌다. 꼬리가 마지막까지 남았다.<br><br>
        그 뒤로는 모두 위를 한 번씩 보며 걸었다. 발소리는 다시 나지 않았다.`,
      ng:`수를 세다가 이쪽 걸음이 꼬였다. 수를 세는 것도 걸음을 바꾸는 일이다.<br><br>
        발소리가 뚝 멎었다. 멎은 쪽이 더 나쁘다. 어디서 기다리는지 모르게 된다.<br>
        한참을 등을 맞대고 서 있다가 걸었다. 복도가 두 배로 길어졌다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-18 } }
  ] },

{ at:'S', t:'검은 피 — 날이 운다',
  x:`작은 것 하나를 베어 넘겼다. 문제는 그다음이다.<br><br>
    날에 묻은 피가 끓는다. 연기가 난다. 쇠가 타는 냄새. 날 위로 가는 홈이 파이며 번져 간다.<br>
    바닥에 떨어진 핏방울은 벌써 철판을 뚫고 아래층으로 듣고 있다.<br><br>
    닦을 시간은 길지 않다. 그리고 이 냄새를 맡고 오는 것들이 있다.`,
  o:[
    { l:'① 날을 바닥에 박고 긁어내린다 — 피째 갈아 낸다.', k:'fix', dc:24, wake:1,
      ok:`날을 비스듬히 바닥에 대고 체중으로 긁어내렸다. 불꽃과 검은 피가 같이 밀려 나갔다.<br><br>
        날에 홈이 하나 남았다. 깊지 않다. 쓸 수 있다.<br>
        베고 나서 세 호흡 안에 긁는다. 그게 손에 붙었다. 베는 법만 알던 손에 거두는 법이 생겼다.<br><br>
        다음부터는 벨 자리부터 골랐다. 피가 이쪽으로 안 쏟아지는 각도. 무기가 가르쳐 준 셈이다.`,
      ng:`긁는 사이 피가 자루 쪽으로 흘렀다. 장갑에서 연기가 났다.<br><br>
        급히 장갑을 벗어 던졌다. 장갑은 바닥에서 오그라들며 녹았다. 손등이 화끈거린다.<br>
        날은 살렸다. 손은 한동안 자루를 쥘 때마다 아렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 날이 녹기 전에 한 놈 더 — 어차피 올 것들이다.', k:'break', dc:25,
      ok:`냄새를 맡고 온 둘째 놈이 모퉁이를 도는 순간을 쳤다. 녹아 가는 날이라도 무게는 그대로다.<br><br>
        이번에는 비껴 베었다. 피가 저쪽으로 쏟아지게. 놈은 제 피 웅덩이 위로 넘어졌다.<br>
        날은 거기까지였다. 반 뼘이 녹아 없어졌다. 짧아진 무기를 들어 보았다. 아직 무기다.<br><br>
        짧아진 만큼 한 발 더 들어가면 된다. 그 한 발을 아까워하지 않기로 했다.`,
      ng:`둘째 놈이 모퉁이를 안 돌았다. 모퉁이 앞에서 멈춰 기다렸다. 이쪽 날이 녹는 걸 아는 것처럼.<br><br>
        날이 뚝 부러졌다. 소리를 듣고 그제야 놈이 들어왔다. 반 토막 날로 받아 내며 물러섰다.<br>
        일행 창이 놈을 꿰고서야 끝났다. 부러진 날은 바닥에서 아직 연기를 내고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-15 } }
  ] },

{ at:'S', t:'업힌 동료 — 한 손의 무기',
  x:`동료 하나가 다리를 물렸다. 걷지 못한다. 업는 수밖에 없다.<br><br>
    업으면 무기는 한 손이다. 한 손 무기는 반쪽 무기다. 그걸 저것들도 안다.<br>
    어둠 속에서 따라오는 숨소리가 아까보다 가깝다. 다친 냄새를 맡으면 대담해진다.<br><br>
    동료가 등 뒤에서 작게 말한다. 두고 가도 된다고. 대답하지 않았다.`,
  o:[
    { l:'① 동료를 다른 일행에게 넘기고 맨 뒤를 막는다.', k:'bond', dc:24,
      ok:`등의 무게를 일행에게 옮겼다. 두 손이 돌아왔다. 무기가 제 무게를 되찾았다.<br><br>
        맨 뒤에 섰다. 숨소리가 한 번 들어왔다가, 두 손으로 선 이쪽을 보고 물러났다.<br>
        저것들은 계산을 한다. 계산이 안 맞으면 안 온다. 맞을 때까지 기다릴 뿐이다.<br><br>
        업는 건 이쪽 일이 아니었다. 업는 사람을 지키는 게 이쪽 일이다. 역할이 제자리를 찾았다.`,
      ng:`넘기는 사이가 틈이었다. 어둠이 그 틈에 들어왔다.<br><br>
        동료를 받던 일행이 넘어지며 셋이 엉켰다. 발톱이 어깨를 긋고 지나갔다.<br>
        쫓아내긴 했다. 피 냄새가 하나 더 늘었다. 숨소리들이 늘어난 건 그다음부터다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-16 } },
    { l:'② 업은 채 싸운다 — 한 손 무기로 버틴다.', k:'break', dc:26, cost:{ might:34 },
      ok:`들어오는 놈을 한 손으로 받아쳤다. 무게가 모자라는 만큼 허리를 더 돌렸다. 등의 동료가 균형추가 됐다.<br><br>
        놈의 턱이 돌아갔다. 한 손인데 두 손 소리가 났다. 숨소리들이 멀어졌다.<br>
        등 뒤에서 동료가 중얼거렸다. 방금 그거 뭐였느냐고. 글쎄. 이쪽도 처음 해 봤다.<br><br>
        업은 무게도 쓰기 나름이다. 버리는 무게가 아니라 싣는 무게. 허리가 그 차이를 기억했다.`,
      ng:`한 손 무기가 놈의 껍질에 튕겼다. 반동이 고스란히 어깨로 왔다.<br><br>
        휘청하는 사이 등의 동료가 미끄러졌다. 붙잡느라 무기를 떨궜다. 주울 때까지 일행이 막았다.<br>
        둘 다 살았다. 어깨는 며칠 올라가지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-34, mind:-14 } }
  ] },

{ at:'S', t:'천장의 숨 — 내려오지 않는 것',
  x:`천장이 높은 방이다. 불빛이 거기까지 안 닿는다.<br><br>
    위에서 숨소리가 난다. 길게 들이쉬고, 오래 참고, 천천히 내쉰다. 이쪽 수를 세는 숨이다.<br>
    내려오지 않는다. 내려올 때를 고르고 있다. 제일 약한 사람이 제일 뒤에 처질 때.<br><br>
    방은 길다. 다 건너려면 그 숨 밑을 스무 걸음 걸어야 한다.`,
  o:[
    { l:'① 먼저 친다 — 천장을 보고 무기를 던져 올린다.', k:'break', dc:26,
      doom:{ title:'천장의 긴 팔', what:'천장 어둠 속으로 끌려 올라갑니다', dc:19, sec:45,
        text:`던진 무기가 어둠에 박히는 소리가 났다. 맞았다. 그런데 떨어지는 건 무기뿐이다.<br><br>
          숨소리가 멎었다. 다음 순간 긴 것이 떨어져 내려왔다. 팔이다. 팔만.<br>
          팔이 이쪽 어깨를 감고 끌어 올린다. 바닥이 멀어진다. 일행 불빛이 손바닥만 해진다.<br><br>
          위에서 숨소리가 다시 시작됐다. 아주 가까이서. 이번에는 참지 않는 숨이다.`,
        dieText:`무기가 바닥에 떨어져 있었다. 주인은 없다.<br><br>
          천장에서 한참 동안 소리가 났다. 일행은 듣지 않으려고 뛰었다.<br>
          방을 다 건넌 뒤에야 숨소리가 멎었다. 들이쉬고, 오래 참고, 내쉬는 숨. 하나 줄어든 수를 세는 숨.`,
      },
      ok:`무기를 던지지 않았다. 던지는 척만 했다. 팔을 크게 들어 올리는 동작만.<br><br>
        숨이 흐트러졌다. 위에서 무엇이 급히 자리를 옮기는 소리. 배관이 울었다.<br>
        자리를 옮기는 소리를 따라 불빛을 돌렸다. 꼬리. 접힌 다리. 천장 구석에 웅크린 윤곽이 한 번 드러났다.<br><br>
        보인 것은 못 덮친다. 놈이 구석에 머무는 사이 스무 걸음을 다 건넜다.`,
      win:{ exp:21, dream:3 } },
    { l:'② 숨에 맞춘다 — 저것이 내쉴 때만 걷는다.', k:'hide', dc:25,
      ok:`들이쉴 때 멈추고 내쉴 때 걸었다. 내쉬는 숨은 제 소리에 귀가 먹는다.<br><br>
        스무 걸음이 마흔 걸음이 됐다. 마지막 걸음에서 숨이 뚝 멎었다. 다 건넌 뒤였다.<br>
        문을 닫고 나서야 모두 참았던 제 숨을 쉬었다.<br><br>
        문 너머에서 길게 내쉬는 소리가 들렸다. 아쉬움 같은 것이 섞여 있었다.`,
      ng:`반쯤 건넜을 때 동료 하나가 발을 헛디뎠다. 쇳조각이 굴렀다.<br><br>
        숨이 멎었다. 위에서 무게가 옮겨 가는 소리가 바로 머리 위까지 왔다.<br>
        남은 열 걸음을 그냥 뛰었다. 등 뒤 바닥에 무엇이 떨어지는 소리가 났다. 무거운 것이. 돌아보지 않았다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-17, spirit:-19 } },
    { l:'③ 무기 든 사람이 가운데 선다 — 대형을 뒤집는다.', k:'fix', dc:24,
      ok:`약한 사람을 가운데가 아니라 맨 앞에 세웠다. 무기 든 이쪽이 한가운데. 어디로 떨어져도 닿는 자리.<br><br>
        숨소리가 몇 번이나 자리를 옮겼다. 떨어질 자리를 못 고른다. 어느 자리든 무기 밑이다.<br>
        그대로 다 건넜다. 놈은 끝까지 안 내려왔다.<br><br>
        계산하는 것한테는 계산을 깨 주면 된다. 대형이 그 답이었다.`,
      ng:`대형을 바꾸는 사이 줄이 흐트러졌다. 뒤가 비었다.<br><br>
        숨소리가 그 위로 갔다. 맨 뒷사람이 비명을 삼키며 주저앉았다. 어깨에 긁힌 자국 넷.<br>
        떨어졌다 올라간 것이다. 간을 본 것이다. 다음엔 간만 보지 않을 것이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S', t:'두 번은 안 통한다',
  x:`같은 종류 셋째 놈이다. 첫째는 내려치기에 죽었다. 둘째는 내려치는 척 올려치기에 죽었다.<br><br>
    셋째는 거리 밖에 서 있다. 이쪽 무기가 닿는 금을 아는 것처럼 꼭 한 뼘 밖에.<br>
    이쪽이 디디면 물러나고, 물러나면 디딘다. 눈이 무기 끝만 본다.<br><br>
    보고 배운 것이다. 죽은 둘에게서. 이제 이쪽 수는 두 개가 아니라 영 개다.`,
  o:[
    { l:'① 세 번째 수를 만든다 — 무기를 바꿔 쥔다.', k:'break', dc:25, wake:1, cost:{ might:31 },
      ok:`자루를 거꾸로 쥐었다. 닿는 금이 한 뼘 줄었다. 놈이 그 한 뼘을 모른 채 디뎠다.<br><br>
        짧아진 금 안으로 들어온 순간, 쥔 손을 되돌리며 쳤다. 원래 금으로. 놈의 눈이 마지막까지 무기 끝을 봤다. 끝은 이미 다른 데 있었다.<br><br>
        무기의 금은 하나가 아니다. 쥐는 법 수만큼 있다. 죽은 둘이 가르쳐 준 걸 셋째가 완성시켰다. 이쪽 손에서.`,
      ng:`바꿔 쥐는 손이 반 박자 느렸다. 놈이 그 반 박자에 들어왔다 나갔다.<br><br>
        옆구리가 뜨겁다. 깊지는 않다. 금 긋듯 긋고 나간 것이다.<br>
        놈은 다시 한 뼘 밖에 섰다. 이제 바꿔 쥐는 수까지 봤다. 넷째 수가 필요해졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 거리 싸움을 버린다 — 벽까지 몰아붙인다.', k:'evade', dc:24,
      ok:`금을 재는 싸움은 넓은 데서나 된다. 한 발씩, 놈을 벽 모서리로 몰았다.<br><br>
        물러나던 놈의 등이 벽에 닿았다. 물러날 금이 없어졌다. 금이 없으면 계산도 없다.<br>
        그다음은 계산이 필요 없는 일이었다.<br><br>
        벽에 흘러내린 검은 피가 벽돌을 파먹는 걸 보며 숨을 돌렸다.`,
      ng:`몰아붙이다 이쪽 등이 먼저 기둥에 닿았다. 방 모양을 놈이 더 잘 알았다.<br><br>
        몰린 건 이쪽이 됐다. 기둥을 끼고 세 바퀴를 돌며 버텼다.<br>
        일행이 옆에서 들이치고서야 놈이 물러갔다. 등이 벽에 닿는 느낌을 한동안 잊지 못했다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-29, spirit:-17 } }
  ] },

{ at:'S', t:'알 무더기 — 식은 것과 따뜻한 것',
  x:`길이 알 무더기 사이로 나 있다. 가죽 같은 알이 허리 높이까지 쌓였다.<br><br>
    대부분 식었다. 몇 개가 따뜻하다. 따뜻한 것은 겉이 천천히 오르내린다. 숨처럼.<br>
    지나가려면 무더기에 어깨가 스친다. 돌아가는 길은 없다.<br><br>
    어미가 어디 있는지는 모른다. 어미가 없는 알 무더기는 없다.`,
  o:[
    { l:'① 따뜻한 것부터 부순다 — 깨기 전에 깬다.', k:'break', dc:26,
      doom:{ title:'무더기 밑의 어미', what:'알 무더기 밑으로 끌려 들어갑니다', dc:20, sec:40,
        text:`첫 알을 내려치는 순간 무더기 전체가 움직였다. 알이 쌓인 게 아니었다. 얹혀 있던 것이다.<br><br>
          무더기 밑에서 올라온 것이 이쪽 다리를 감았다. 어미는 멀리 있지 않았다. 밑에 있었다.<br>
          알들이 사태처럼 쏟아지며 몸이 그 밑으로 끌려 들어간다. 가죽 알들이 사방에서 몸을 눌렀다. 따뜻했다. 그게 제일 싫었다.`,
        dieText:`무더기가 다시 잠잠해졌다. 쏟아졌던 알들이 제자리를 찾듯 쌓였다.<br><br>
          무더기 가운데 알 하나가 새로 생긴 것 같다고, 일행 중 하나가 말했다. 아무도 확인하러 가지 않았다.<br>
          돌아 나올 때까지 그 알은 따뜻했다.`,
      },
      ok:`부수기 전에 무더기 밑을 먼저 찔러 봤다. 날이 무른 것에 닿았다. 밑이 비어 있지 않다.<br><br>
        부수는 건 그만뒀다. 대신 식은 알 쪽으로만 몸을 붙여 지났다. 따뜻한 것들은 건드리지 않았다.<br>
        다 지나고 나서 뒤를 봤다. 무더기 한가운데가 천천히 내려앉았다 올라왔다. 숨이었다. 무더기 전체가.`,
      win:{ exp:21, dream:3 } },
    { l:'② 식은 알만 골라 디디며 소리 없이 지난다.', k:'hide', dc:25,
      ok:`식은 알은 밟아도 운다. 낮게. 그래서 밟지 않고 알과 알 사이 바닥만 디뎠다.<br><br>
        어깨가 따뜻한 알 하나에 스쳤다. 겉이 움찔했다. 멈춰 서서 열을 셌다. 다시 잠잠해졌다.<br>
        다 건너는 데 한참 걸렸다. 아무것도 깨어나지 않았다.<br><br>
        나와서 보니 바닥에 디딘 자리마다 끈적한 것이 묻어 있었다. 알 사이 바닥이 바닥이 아니었을지도 모른다.`,
      ng:`발밑에서 식은 알 하나가 터졌다. 식은 게 아니라 죽은 알이었다. 안의 것이 녹아 있었다.<br><br>
        냄새가 확 퍼졌다. 무더기 여기저기서 따뜻한 알들이 일제히 흔들리기 시작했다.<br>
        걸음이 뜀이 됐다. 뒤에서 젖은 것이 깨지는 소리가 몇 번이나 났다. 세지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-21 } }
  ] },

{ at:'S', t:'꺼져 가는 불 — 마지막 한 수',
  x:`들고 온 불이 깜빡인다. 길어야 백 걸음 치 기름이 남았다.<br><br>
    어둠 속의 것들이 그걸 안다. 불빛 금 바로 밖에 와 앉아 있다. 여럿이. 기다린다.<br>
    불이 죽는 순간이 저것들의 시작이다. 그 전에 이쪽 일을 끝내야 한다.<br><br>
    문까지 백스무 걸음. 스무 걸음이 모자란다.`,
  o:[
    { l:'① 불빛 금 바로 밖을 먼저 쓸어버린다 — 금을 넓힌다.', k:'break', dc:25, wake:1, cost:{ might:33 },
      ok:`불이 살아 있을 때 금 밖으로 먼저 나갔다. 저것들 계산에 없는 수다.<br><br>
        제일 가까이 앉은 놈을 쳤다. 기다리던 자세 그대로 넘어갔다. 기다리는 것들은 맞는 데 약하다.<br>
        남은 것들이 금에서 물러났다. 넓어진 금만큼 걸음을 벌었다. 문까지 닿았다. 불은 문 앞에서 죽었다.<br><br>
        불이 지키는 게 아니었다. 불 든 쪽이 무서워야 금이 산다. 그걸 저것들 눈에 새겨 줬다.`,
      ng:`금 밖으로 나가자 저것들이 흩어졌다. 치려던 놈이 비켜나고, 비어 있던 자리가 등 뒤를 물었다.<br><br>
        어깨를 물린 채 금 안으로 되밟아 들어왔다. 불빛 안까지는 안 따라온다. 아직은.<br>
        남은 기름이 더 줄었다. 물린 자리가 욱신거렸다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-35, spirit:-16 } },
    { l:'② 불을 반으로 나눈다 — 두 군데를 보게 만든다.', k:'luck', dc:24,
      ok:`기름을 반 덜어 헝겊에 적셔 반대쪽으로 던졌다. 불 둘.<br><br>
        어둠 속 눈들이 갈라졌다. 반은 저쪽 불로. 보는 눈이 반이면 금도 반만 지키면 된다.<br>
        남은 불로 스무 걸음을 벌었다. 문이 닫히는 순간 두 불이 거의 동시에 죽었다.<br>
        문 너머에서 두 무리가 서로 부딪는 소리가 났다. 잠깐이지만, 고소했다.`,
      ng:`던진 불이 바닥에 닿기 전에 꺼졌다. 기름만 날린 셈이다.<br><br>
        남은 불이 눈에 띄게 줄었다. 어둠 속의 것들이 반 걸음 다가앉았다. 금이 좁아진 걸 안다.<br>
        마지막 서른 걸음은 거의 뛰었다. 등 뒤에서 금이 닫히는 소리가 들리는 것 같았다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-15, spirit:-18 } }
  ] },

{ at:'S', t:'동료의 목소리 — 두 개',
  x:`갈림길에서 동료 목소리가 났다. 이쪽이다, 하고. 왼쪽 길에서.<br><br>
    문제는 그 동료가 오른쪽 길로 먼저 갔다는 것이다. 그리고 오른쪽에서도 같은 목소리가 났다. 이쪽이다, 하고.<br>
    두 목소리가 번갈아 부른다. 같은 억양, 같은 숨. 하나는 동료고 하나는 아니다.<br><br>
    무기 든 사람이 앞장서서 골라야 한다. 모두 이쪽을 보고 있다.`,
  o:[
    { l:'① 둘 다 안 간다 — 그 자리에서 무기로 바닥을 세 번 친다.', k:'break', dc:24, wake:1,
      ok:`바닥을 쇳소리 나게 세 번 쳤다. 일행끼리 정해 둔 신호다. 진짜라면 이 소리에 돌아온다.<br><br>
        오른쪽에서 동료가 뛰어나왔다. 왼쪽 목소리는 계속 부른다. 이쪽이다. 이쪽이다. 돌아온 동료 목소리로.<br>
        왼쪽 어둠에 대고 무기를 들어 보였다. 목소리가 뚝 그쳤다.<br><br>
        목소리는 흉내 내도 약속은 흉내 못 낸다. 신호가 무기만큼 든든해졌다.`,
      ng:`세 번 치는 소리가 두 길에 다 울렸다. 왼쪽 것이 그 소리마저 배웠다.<br><br>
        잠시 뒤 왼쪽에서 쇳소리 세 번이 돌아왔다. 박자까지 같다.<br>
        오른쪽에서 돌아온 진짜 동료와 함께 왼쪽 소리를 들었다. 쇳소리 세 번. 그리고 낮은 웃음 비슷한 것. 신호를 바꿔야 했다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 목소리에게 묻는다 — 동료만 아는 것을.', k:'gaze', dc:25,
      ok:`어젯밤 불침번 순서를 물었다. 오른쪽이 바로 답했다. 왼쪽은 반 박자 늦게 같은 답을 했다.<br><br>
        늦은 쪽이 베낀 쪽이다. 베끼는 것은 들은 다음에야 안다.<br>
        오른쪽으로 갔다. 동료가 거기 있었다. 왼쪽 목소리는 한참을 더 불렀다. 나중에는 묻지 않은 답까지 외우며.`,
      ng:`물었다. 두 쪽 다 맞게 답했다. 동시에.<br><br>
        그제야 알았다. 저것은 들어서 베끼는 게 아니다. 동료가 아는 걸 안다.<br>
        둘 다 버리고 셋째 길로 돌아 나왔다. 한참 뒤 진짜 동료와 만났다. 동료는 아무도 부른 적이 없다고 했다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-19, spirit:-20 } }
  ] },

{ at:'S', t:'좁은 틈 — 빗장이 되는 날',
  x:`무너진 벽 틈으로 하나씩 빠져나가야 한다. 어깨가 겨우 지나는 틈이다.<br><br>
    문제는 뒤다. 쫓아오는 것들이 복도 끝에 보인다. 하나가 지나는 동안 틈은 막을 수 없다.<br>
    마지막 사람이 제일 위험하다. 늘 그렇듯 그게 무기 든 사람 몫이다.<br><br>
    틈 양옆 벽은 아직 단단하다. 쇠 빗장을 걸 고리 같은 건 없다.`,
  o:[
    { l:'① 무기를 틈에 가로질러 박는다 — 날이 빗장이 된다.', k:'break', dc:25, wake:1, cost:{ might:29 },
      ok:`마지막으로 빠져나오며 무기를 틈에 가로로 박았다. 양 벽 틈새에 날과 자루 끝을 쐐기처럼.<br><br>
        첫 놈이 틈에 머리를 박았다가 날에 긁혀 물러났다. 틈이 좁아 몸을 돌려 들어올 수도 없다.<br>
        벽 너머에서 한참 긁는 소리가 났다. 무기는 버텼다.<br><br>
        무기를 두고 가는 게 아니다. 무기에게 자리를 맡기는 거다. 빈손이 그렇게 가볍고 든든한 건 처음이었다.`,
      ng:`박는 각도가 얕았다. 첫 놈이 들이받자 무기가 튕겨 빠졌다.<br><br>
        틈으로 팔이 하나 들어와 허우적댔다. 빠진 무기를 주워 그 팔을 치고서야 물러갔다.<br>
        결국 틈 앞에 서서 한참을 지켰다. 빗장 노릇을 몸이 했다. 무기보다 비싼 빗장이었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 틈 앞 바닥을 부순다 — 저것들 발밑을 꺼뜨린다.', k:'break', dc:26,
      ok:`틈 바로 앞 바닥이 비어 울렸다. 아래가 빈 철판이다. 모서리를 내려쳐 꺼뜨렸다.<br><br>
        구멍 하나. 뛰어넘자면 틈에 속도를 못 싣는다. 첫 놈이 구멍에 앞발을 빠뜨리고 허우적댔다.<br>
        그사이 다 빠져나왔다. 구멍과 틈, 둘 다 저것들한테는 숙제가 됐다.`,
      ng:`철판이 생각보다 두꺼웠다. 두 번 치는 사이 선두 놈이 거리를 다 좁혔다.<br><br>
        세 번째 치는 걸 포기하고 틈으로 몸을 던졌다. 발뒤꿈치를 무엇이 스쳤다.<br>
        빠져나와 보니 장화 뒤축이 한 입 뜯겨 있었다. 발은 멀쩡했다. 운이었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'숫자가 안 맞는다',
  x:`다섯이 들어왔다. 지금 불빛 가장자리에 여섯이 서 있다.<br><br>
    모두 고개를 숙이고 있거나 등을 보이고 있다. 누가 누군지 세다 보면 자리가 바뀐다.<br>
    여섯째는 섞여 있는 법을 안다. 수를 셀 때마다 다른 자리에 있다.<br><br>
    먼저 알은 척을 하면 흩어질 것이다. 그다음은 어둠 속에서 하나씩이다. 그건 저쪽 판이다.`,
  o:[
    { l:'① 모르는 척 대형을 짠다 — 여섯째 자리만 비게.', k:'fix', dc:25,
      ok:`쉬어 가자며 등을 맞대는 원을 짰다. 다섯 자리 원. 한 사람씩 이름을 부르며 자리를 줬다.<br><br>
        이름이 없는 하나가 원 밖에 남았다. 고개를 숙인 채. 모두의 등이 그쪽을 향해 좁혀졌다.<br>
        그것이 반 걸음 물러났다. 또 반 걸음. 그러다 어둠에 녹듯 사라졌다.<br><br>
        수를 세는 건 저쪽만 하는 게 아니다. 이쪽 원에는 이름이 있다. 그게 차이다.`,
      ng:`자리를 주다가 이름이 하나 꼬였다. 서로 네가 둘째라고 우기는 둘이 생겼다.<br><br>
        얼굴을 다 확인하는 소동이 났다. 끝나고 보니 다섯이었다. 처음부터 다섯이었는지는 아무도 모른다.<br>
        그날 밤 불침번은 둘씩 섰다. 서로의 얼굴을 보는 쪽으로.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 등 보인 것부터 어깨를 짚는다 — 아니면 그 자리에서 친다.', k:'break', dc:26,
      doom:{ title:'여섯째', what:'여섯째에게 어둠 밖으로 끌려갑니다', dc:20, sec:38,
        text:`네 번째 어깨가 돌처럼 차가웠다. 손을 떼기 전에 그 어깨가 돌아섰다.<br><br>
          동료 얼굴이다. 다만 숨을 안 쉰다. 차가운 손이 이쪽 손목을 마주 짚었다.<br>
          끌린다. 불빛 밖으로. 발을 버텨도 바닥이 미끄러진다. 남은 넷이 수를 세는 소리가 멀어진다. 하나, 둘, 셋, 넷. 다섯을 안 센다.`,
        dieText:`손목을 짚던 자리에 장갑 한 짝이 떨어져 있었다.<br><br>
          일행은 넷이 됐다. 넷이서 수를 셌다. 넷. 맞다. 맞는 게 이상할 만큼 맞다.<br>
          그 뒤로 불빛 가장자리에 다섯째가 와 서곤 했다. 익숙한 어깨로. 아무도 짚으러 가지 않았다.`,
      },
      ok:`하나씩 어깨를 짚었다. 체온. 체온. 체온. 네 번째에서 손이 멈췄다.<br><br>
        차다. 짚는 순간 휘둘렀다. 묻는 건 그다음이다.<br>
        그것은 소리 없이 꺾이며 어둠으로 쏟아져 사라졌다. 다섯이 남았다. 모두 체온이 있는 다섯.<br><br>
        미안하다는 말은 안 했다. 어깨를 짚는 손에 모두가 고분고분해진 건 그날부터다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S', t:'물러서는 싸움',
  x:`길을 잘못 들었다. 돌아 나가야 한다. 문제는 등을 보이면 덮치는 것들이 앞에 있다는 것이다.<br><br>
    뒷걸음으로 복도 하나를 다 물러나야 한다. 무기 든 사람이 맨 앞 — 아니, 이제는 맨 뒤다.<br>
    저것들은 서두르지 않는다. 뒷걸음이 흐트러질 때를 기다리며 따라 디딘다.<br><br>
    발꿈치 뒤는 안 보인다. 일행 목소리가 눈 대신이다.`,
  o:[
    { l:'① 물러나며 베는 금을 긋는다 — 한 걸음에 한 번.', k:'break', dc:25, wake:1, cost:{ might:35 },
      ok:`한 걸음 물러날 때마다 허공에 금 하나를 그었다. 닿는 데까지. 같은 높이, 같은 박자.<br><br>
        저것들이 금 앞에서 디디다 말기를 되풀이했다. 박자가 벽이 됐다.<br>
        복도 끝까지 마흔 금. 마지막 금을 긋고 문을 닫았다.<br><br>
        앞으로 가는 무기만 알았다. 물러나는 무기는 박자가 전부다. 어깨가 그 박자를 다 외울 때까지 문에 기대 있었다.`,
      ng:`스무 금쯤에서 팔이 무거워졌다. 금 사이가 벌어졌다.<br><br>
        벌어진 사이로 하나가 들어왔다. 발꿈치가 턱에 걸려 넘어지며 그 놈과 엉켰다.<br>
        일행이 끌어내 줬다. 남은 스무 걸음은 금이고 뭐고 그냥 뛰었다. 저것들 웃는 것 같은 소리가 따라왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 일행 목소리에 발을 맡긴다 — 눈은 앞에만.', k:'bond', dc:24,
      ok:`뒤는 일행이 불러 줬다. 왼쪽 턱. 오른쪽 파이프. 세 걸음 뒤 모퉁이.<br><br>
        눈은 앞의 것들에게서 떼지 않았다. 눈을 떼는 순간이 저것들 신호다. 끝까지 안 줬다.<br>
        모퉁이를 돌자 일행 손들이 어깨를 잡아 끌어 줬다. 문이 닫혔다.<br>
        눈싸움에 진 것들이 문을 한 번 치고 갔다. 진 건 안다는 뜻이다.`,
      ng:`목소리가 겹쳤다. 왼쪽, 아니 오른쪽. 그 사이 발이 턱에 걸렸다.<br><br>
        넘어진 등으로 저것들 발소리가 확 몰려왔다. 구르면서 휘둘러 첫 놈만 겨우 걷어냈다.<br>
        일으켜 세워질 때까지 몇 초가 몇 년 같았다. 그 뒤로 부르는 말은 한 사람만 하기로 했다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-27, spirit:-18 } }
  ] },

// ---------- S1 『표본실 — 착륙 이후』 ----------

{ at:'S1', t:'표본실 — 금 간 단지들',
  x:`표본실 선반에 단지가 줄지어 있다. 절반은 비었다. 금이 밖에서 안으로가 아니라 안에서 밖으로 나 있다.<br><br>
    남은 단지들 속에는 웅크린 것들이 떠 있다. 그중 몇 개의 액체가 탁하다. 탁한 것은 최근에 움직였다는 뜻이라고, 벽의 기록지가 말해 준다.<br>
    기록지 마지막 줄. 깨우지 말 것. 두 번 밑줄.<br><br>
    지나가려면 선반 사이를 통과해야 한다. 선반은 어깨 폭 하나 간격이다.`,
  o:[
    { l:'① 탁한 단지를 먼저 부순다 — 깨어나기 전에, 바닥에 쏟아 둔다.', k:'break', dc:26,
      ok:`탁한 단지 셋을 선반째 복도 반대쪽으로 밀어 넘겼다. 깨지는 건 저쪽 바닥. 쏟아진 것들이 몸을 펴기 전에 날이 먼저 닿았다.<br><br>
        셋 다 바닥에서 끝났다. 액체에 잠겨 있던 것들은 마른 데서 반 박자 느리다. 그 반 박자가 전부였다.<br>
        남은 맑은 단지들은 건드리지 않았다. 맑은 것들이 일제히 이쪽으로 돌아 떠 있는 걸 못 본 척하며 지났다.`,
      ng:`첫 단지를 넘기는 순간 안의 것이 유리를 박찼다. 깨어 있었다. 탁한 건 자는 게 아니라 숨는 거였다.<br><br>
        쏟아진 놈이 액체째 이쪽 발을 쓸었다. 넘어진 어깨 위 선반에서 단지들이 흔들렸다.<br>
        일행이 끌어내고 날이 마무리했다. 젖은 소매에서 밤새 비린내가 났다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 단지를 안 건드리고, 선반을 미리 묶어 고정한다.', k:'fix', dc:24,
      ok:`지날 길목 선반들을 배관에 끈으로 묶었다. 어깨가 스쳐도 안 흔들리게.<br><br>
        한가운데서 등짐이 선반을 제법 세게 쳤다. 선반은 묵직하게 버텼다. 단지 속 액체만 찰랑였다.<br>
        탁한 단지 하나가 그 찰랑임에 맞춰 안에서 톡, 톡, 유리를 두드렸다. 나가게 해 달라는 박자로. 아무도 대답하지 않았다.`,
      ng:`묶다가 끈이 선반 모서리 단지 하나를 쓸었다. 단지가 떨어져 깨졌다.<br><br>
        맑은 단지였다. 안의 것은 죽은 지 오래였다. 그런데 냄새가 문제였다.<br>
        복도 끝 어둠에서 무엇이 그 냄새에 길게 숨을 들이켜는 소리가 났다. 묶던 끈을 그대로 두고 빨리 지났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-15, spirit:-17 } }
  ] },

{ at:'S1', t:'아는 걸음 — 연구원이었던 것',
  x:`복도 끝에서 흰 가운이 걸어온다. 명찰이 있다. 얼굴도 있다.<br><br>
    걸음이 틀렸다. 무릎이 먼저 꺾이고 발이 따라간다. 거꾸로 배운 걸음이다. 안에서 조종하는 것이 겉모양만 베낀 걸음.<br>
    가운 안쪽 가슴께가 숨과 다른 박자로 불룩거린다.<br><br>
    그것이 손을 들어 보인다. 인사. 그것도 베낀 것이다.`,
  o:[
    { l:'① 사람 모양에 속지 않는다 — 가슴께, 안의 것을 노려 친다.', k:'break', dc:25, wake:1,
      ok:`얼굴을 안 봤다. 얼굴을 보면 손이 무뎌진다. 박자가 다른 가슴께만 보고 들어갔다.<br><br>
        한 번에 끝냈다. 가운이 무너지고, 안에서 다리 많은 것이 빠져나오려다 날 밑에서 멎었다.<br>
        겉의 사람은 이미 오래전에 없었다. 그건 확실했다. 확실해도 손은 떨렸다.<br><br>
        사람 모양을 치는 손은 무뎌진다. 모양 말고 박자를 보기로 했다. 박자는 거짓말을 못 한다. 그 눈이 생겼다.`,
      ng:`들어가는 순간 그것이 사람 목소리로 말했다. 살려 주세요.<br><br>
        날이 반 뼘 흔들렸다. 그 반 뼘에 안의 것이 가운을 찢고 튀어나와 천장으로 붙었다.<br>
        빈 가운만 바닥에 남았다. 천장 어둠에서 살려 주세요, 소리가 한 번 더 났다. 이번엔 웃음 섞인 박자로.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 인사를 받아 준다 — 손을 마주 들고 거리를 번다.', k:'evade', dc:24,
      ok:`손을 들어 보였다. 그것이 걸음을 멈추고 또 손을 들었다. 베끼는 중에는 못 움직인다.<br><br>
        손을 든 채 옆걸음으로 비켜 지났다. 그것은 끝까지 손을 들고 서 있었다. 베낄 다음 동작을 기다리며.<br>
        모퉁이에서 마지막으로 봤을 때도 들고 있었다. 누가 또 지나갈 때까지 저러고 있을 것이다.`,
      ng:`손을 드는데 그것이 베끼지 않고 성큼 다가왔다. 베끼기는 끝났다는 듯이.<br><br>
        가운 앞이 벌어지며 안의 것이 얼굴을 내밀었다. 숨이 닿는 거리였다.<br>
        뒤로 구르며 빠졌고, 일행 창이 사이를 막았다. 그 얼굴 아닌 얼굴이 꿈에 며칠 나왔다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-20, spirit:-19 } }
  ] },

{ at:'S1', t:'산성 피 — 발판이 사라진다',
  x:`격자 철판 복도에서 큰 놈 하나를 베어 넘겼다. 이겼다. 그런데 놈의 피가 문제다.<br><br>
    검은 피가 격자 바닥을 먹어 들어간다. 발밑에서 쇠가 꺼지는 소리가 번진다. 복도 전체가 발판째 녹는 중이다.<br>
    아래층은 어둡다. 아래에서 무언가가 녹아 떨어지는 쇳물 소리에 맞춰 움직이는 기척이 있다.<br><br>
    건너편 문까지 열 걸음. 녹는 속도가 더 빠르다.`,
  o:[
    { l:'① 죽은 놈을 발판으로 쓴다 — 몸뚱이 위로 건넌다.', k:'break', dc:25, cost:{ might:32 },
      ok:`놈의 몸뚱이를 날로 밀어 녹는 자리에 눕혔다. 제 피는 제 껍질을 못 녹인다.<br><br>
        껍질 위를 디뎌 건넜다. 일행이 뒤를 따랐다. 발밑에서 격자가 꺼지는 소리가 껍질 밑으로 지나갔다.<br>
        마지막 사람이 건너자마자 껍질째 아래로 내려앉았다. 아래 어둠에서 무엇이 그걸 받아 끄는 소리가 났다. 고맙다는 인사는 생략했다.`,
      ng:`몸뚱이를 미는 사이 피가 더 번졌다. 껍질이 자리에 눕기 전에 바닥이 먼저 꺼졌다.<br><br>
        몸뚱이가 아래로 떨어지고, 이쪽 발 하나도 꺼진 격자에 무릎까지 빠졌다.<br>
        일행이 겨드랑이를 끼고 뽑아냈다. 장딴지에 격자 자국이 깊게 남았다. 아래 어둠에서 기척이 한참 이쪽을 올려다봤다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-34, spirit:-15 } },
    { l:'② 피가 안 닿은 가장자리 보로만 — 벽을 짚고 건넌다.', k:'steady', dc:26,
      doom:{ title:'아래층의 것', what:'꺼진 바닥 밑으로 끌려 내려갑니다', dc:19, sec:42,
        text:`가장자리 보를 반쯤 건넜을 때 발밑 격자가 통째로 꺼졌다. 피가 번진 건 바닥만이 아니었다. 보 밑이 먼저 녹아 있었다.<br><br>
          떨어지다 모서리를 잡았다. 아래 어둠에서 차가운 것이 발목을 감았다. 기다리고 있었다. 쇳물 소리는 저것의 저녁 종이었다.<br>
          손가락이 모서리에서 하나씩 벗겨진다. 아래로. 아래로.`,
        dieText:`모서리에 장갑 자국만 남았다.<br><br>
          아래층에서 한동안 쇠 긁는 소리가 났다. 일행은 그 위 복도를 소리 죽여 건넜다.<br>
          건너편 문을 닫을 때, 아래에서 들리던 소리가 뚝 멎었다. 식사가 끝난 집 같은 고요였다.`,
      },
      ok:`벽에 붙은 보는 피가 안 닿았다. 벽을 손으로 짚고 보 위로만 디뎠다.<br><br>
        한가운데서 보가 한 번 울었다. 멈춰 서서 무게를 나눴다. 울음이 그쳤다.<br>
        열 걸음이 백 걸음 같았다. 다 건너자 등 뒤에서 복도 격자가 통째로 내려앉았다. 반 호흡 차이였다.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'S1', t:'격벽 — 닫히는 문',
  x:`경보가 울리고 격벽이 내려오기 시작했다. 복도를 자르는 두꺼운 문이다.<br><br>
    문 이쪽에 셋, 저쪽에 둘. 갈라지면 끝이다. 이 구역 불은 오늘 밤을 못 넘긴다.<br>
    격벽은 허리 높이까지 내려왔다. 기계는 협상을 모른다.<br><br>
    복도 끝 어둠에서, 경보 소리에 맞춰 다가오는 발소리가 하나 둘 셋.`,
  o:[
    { l:'① 격벽 밑에 어깨를 넣고 버틴다 — 둘이 지나올 때까지.', k:'break', dc:26, cost:{ might:38 },
      ok:`내려오는 문 밑에 어깨와 무기 자루를 같이 넣었다. 기계가 멈칫했다. 과부하음.<br><br>
        그 틈으로 둘이 굴러 들어왔다. 어깨를 빼자 격벽이 쾅 닫혔다.<br>
        닫힌 문 저쪽에서 발소리들이 문을 긁었다. 늦게 온 쪽은 저쪽이다.<br><br>
        어깨가 한동안 저렸다. 기계와 힘겨루기를 한 어깨다. 졌으면 반쪽이 될 뻔했다, 문도 일행도.`,
      ng:`어깨를 넣었는데 기계가 더 세게 눌렀다. 뼈가 우는 소리가 났다.<br><br>
        하나는 굴러 들어왔다. 마지막 하나가 남았을 때 어깨를 빼야 했다. 안 뺐으면 으스러졌다.<br>
        격벽이 닫혔다. 남은 동료는 옆 통로로 돌아 반나절 만에 합류했다. 혼자 보낸 반나절 이야기는 끝내 하지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-36, mind:-14 } },
    { l:'② 문보다 사람이 빠르다 — 둘을 차례로 굴려 당긴다.', k:'bond', dc:25,
      ok:`허리 높이 문 밑으로 손을 뻗었다. 하나, 당겨서 굴리고. 둘, 당겨서 굴리고.<br><br>
        둘째 발이 빠져나오는 위로 격벽이 닫혔다. 장화 코가 문에 집혀 벗겨졌다.<br>
        발은 다섯 식구 다 멀쩡했다. 장화 한 짝은 격벽 너머에 남았다. 그쪽 발소리들에게 선물로.`,
      ng:`첫째는 굴러 나왔다. 둘째가 배낭이 걸려 버둥댔다.<br><br>
        배낭끈을 끊고 당겼다. 격벽이 닫히며 배낭째 짐을 삼켰다. 불 기름 절반이 그 안에 있었다.<br>
        사람은 다 모였다. 그날부터 불을 반으로 줄여 켰다. 어둠이 반만큼 가까워졌다.`,
      win:{ exp:20, dream:2 }, lose:{ spirit:-22, mind:-14 } },
    { l:'③ 격벽 기계함을 부순다 — 문을 그 자리에 세운다.', k:'break', dc:25,
      ok:`문 옆 벽의 기계함을 자루 끝으로 쳐 열고, 맞물려 도는 톱니 사이에 쇳조각을 박았다.<br><br>
        격벽이 허리 높이에서 멎었다. 둘이 기어 나왔다.<br>
        문은 영영 반만 닫힌 채다. 발소리들이 그 밑을 기어 따라올 수 있다는 건 반나절 뒤에 알았다. 그래도 그 순간엔 그게 최선이었다.`,
      ng:`기계함이 생각보다 깊었다. 쇳조각이 톱니에 닿기 전에 튕겨 나왔다.<br><br>
        격벽은 그대로 내려왔다. 둘은 문틈에 손끝 인사만 남기고 갈렸다.<br>
        옆 통로로 도는 길에 작은 것 둘을 치렀다. 합류했을 때 저쪽 둘도 같은 수만큼 치른 뒤였다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S1', t:'통풍구 — 끌려 들어간 동료',
  x:`비명은 짧았다. 돌아보니 동료가 없다. 벽 통풍구 덮개가 안쪽으로 뜯겨 있다.<br><br>
    통풍구 안에서 끌리는 소리가 멀어진다. 장화 뒤축이 함석을 긁는 소리. 아직 버티고 있다는 소리다.<br>
    구멍은 어깨가 겨우 들어갈 크기다. 무기를 겨눌 공간은 없다.<br><br>
    함석 울리는 소리로 방향은 안다. 위로, 그리고 왼쪽으로.`,
  o:[
    { l:'① 소리를 앞질러 가 통풍구 벽을 밖에서 깬다.', k:'break', dc:26, wake:1,
      ok:`함석 소리를 따라 복도를 뛰었다. 끌리는 속도보다 복도가 빠르다. 소리를 앞질러 모퉁이 벽에 귀를 댔다.<br><br>
        온다. 셋을 세고 벽째 내려쳤다. 함석이 터지며 긴 것의 허리가 드러났다. 거기를 마저 쳤다.<br>
        구멍으로 동료 발목부터 끌어냈다. 얼굴이 하얬지만 숨은 붙어 있었다.<br><br>
        벽 안의 것은 벽 밖에서 치면 된다. 길은 저것들만 아는 게 아니다. 복도 전체가 이쪽 무기 자루가 됐다.`,
      ng:`앞지른 자리가 틀렸다. 벽을 깼는데 빈 통로다. 갈림길이 안에 있었다.<br><br>
        소리는 이미 멀다. 두 번째 벽을 깨고서야 따라잡았다. 동료는 끌려가며 제 손으로 통로 볼트를 붙잡아 버틴 채였다.<br>
        끌어내긴 했다. 동료 손바닥의 볼트 자국은 오래 갔다. 이쪽이 한 박자 늦었다는 자국이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 구멍으로 따라 들어간다 — 무기 대신 단도만 물고.', k:'steady', dc:26,
      doom:{ title:'통풍구의 긴 것', what:'통풍구 깊은 곳으로 끌려 들어갑니다', dc:20, sec:36,
        text:`팔꿈치로 기며 따라붙었다. 동료 장화가 손에 닿았다. 닿는 순간, 끌리는 속도가 갑자기 빨라졌다.<br><br>
          둘을 끌 힘이 있었다. 처음부터. 동료는 미끼 쪽이었는지도 모른다.<br>
          함석이 양어깨를 긁으며 몸이 미끄러져 들어간다. 뒤로 뻗은 발이 허공만 찬다. 입에 문 단도 맛이 쇠비린내로 변했다.`,
        dieText:`통풍구 입구에 단도 한 자루가 떨어져 있었다.<br><br>
          함석 소리는 두 겹이 되어 멀어졌다. 일행은 벽을 몇 군데나 깼지만 통로는 그때마다 비어 있었다.<br>
          그 구역 통풍구에서는 이따금 장화 뒤축 소리가 났다. 두 켤레분이었다.`,
      },
      ok:`팔꿈치로 기어 따라붙어 동료 발목을 잡았다. 그리고 몸을 비틀어 통로에 어깨를 가로질러 박았다. 사람 쐐기다.<br><br>
        끌던 것이 당겼다. 쐐기가 버텼다. 두 번. 세 번. 당기는 힘이 점점 짜증으로 변했다.<br>
        마침내 놓았다. 동료를 뒤로 밀어내며 둘이 엉덩이부터 빠져나왔다. 어깨 피부가 함석에 다 쓸렸지만, 둘 다 나왔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S1', t:'여왕의 방 앞 — 줄지어 선 것들',
  x:`천장 높은 홀. 저 끝에 커다란 문이 있고, 문 앞에 그것들이 줄지어 서 있다. 여섯. 미동도 없다.<br><br>
    지키는 자세가 아니다. 기다리는 자세다. 홀 안쪽 깊은 데서 느리고 큰 숨소리가 바닥을 타고 온다. 저것들의 어미이자 주인.<br>
    지나가야 하는 문은 그 옆의 작은 문이다. 줄 선 것들 앞 스무 걸음을 가로질러야 한다.<br><br>
    저것들 고개가 일제히 이쪽으로 돌았다. 몸은 그대로. 고개만.`,
  o:[
    { l:'① 가운데를 부순다 — 줄이 대형이 되기 전에.', k:'break', dc:26,
      doom:{ title:'여왕의 호위들', what:'큰 문 안쪽으로 끌려 들어갑니다', dc:20, sec:35,
        text:`가운데 놈을 꺾었다. 거기까지는 맞았다. 틀린 건 나머지 다섯의 반응이다.<br><br>
          흩어지지 않았다. 다섯이 동시에 조였다. 연습한 것처럼. 아니, 연습이 필요 없는 것처럼 — 한 몸의 다섯 손가락처럼.<br>
          팔다리가 하나씩 잡혔다. 들렸다. 저것들은 죽이지 않고 운반한다. 큰 문이 안쪽에서 열리고 있었다. 깊은 숨소리가 반겼다.`,
        dieText:`큰 문이 닫혔다. 홀에 남은 다섯이 다시 줄을 섰다. 빈자리 하나는 금방 대형이 메웠다.<br><br>
          문 안쪽에서 무슨 소리가 났는지는 쓰지 않는 편이 낫다. 일행은 작은 문으로 뛰었고, 아무도 뒤를 안 봤다.<br>
          그 줄이 왜 여섯이었는지 — 하나는 새 식구 자리였는지도 모른다고, 나중에 누가 말했다. 아무도 웃지 않았다.`,
      },
      ok:`치는 척만 했다. 가운데로 두 걸음 — 저것들이 조이기 시작하는 방향을 봤다. 그리고 반대로 꺾었다.<br><br>
        여섯이 한 몸처럼 조이는 대형은, 한 몸이라서 한 방향밖에 못 조인다. 빈 쪽 가장자리로 내달렸다.<br>
        작은 문을 통과할 때 맨 끝 놈의 발톱이 등짐을 긁었다. 짐 반쪽을 내주고 식구는 다 지났다.<br><br>
        문을 닫자 안쪽 깊은 숨이 한 번 길게 뒤척였다. 못마땅한 숨이었다.`,
      win:{ exp:23, dream:4 } },
    { l:'② 숨소리 박자에 걸음을 묻는다 — 느리게, 스무 걸음.', k:'hide', dc:25,
      ok:`안쪽의 큰 숨이 바닥을 울릴 때만 걸었다. 울림이 발소리를 먹는다.<br><br>
        줄 선 것들 고개가 이쪽을 따라 돌았다. 보고는 있다. 그러나 주인 숨에 겹친 것은 치지 않는다. 주인 것일지도 모르니까.<br>
        스무 걸음에 숨 여덟 번. 작은 문이 닫힐 때까지 여섯 고개가 끝까지 따라 돌았다.<br><br>
        문 너머에서 모두 주저앉았다. 누가 먼저랄 것 없이.`,
      ng:`일곱 번째 숨이 오지 않았다. 숨이 멎었다. 안쪽 것이 숨을 참았다.<br><br>
        발소리가 홀에 그대로 울렸다. 여섯 고개가 일제히 꺾이는 소리.<br>
        남은 거리를 전력으로 뛰었다. 작은 문을 닫는 등 뒤로 여섯 무게가 연달아 부딪쳤다. 문이 버텼다. 숨은 한참 뒤에 돌아왔다, 이쪽 것도 안쪽 것도.`,
      win:{ exp:19, dream:3 }, lose:{ mind:-21, spirit:-20 } }
  ] },

{ at:'S1', t:'배양조 — 자라는 중인 것',
  x:`방 한가운데 사람 키 두 배 배양조가 서 있다. 초록 불빛. 안에 웅크린 것이 떠 있다.<br><br>
    크다. 밖에 돌아다니는 것들보다 한 치수 크다. 계기판 바늘이 오른쪽 끝에 붙어 떨린다. 다 자랐다는 뜻일 것이다.<br>
    유리 안쪽에 긁힌 금이 보인다. 안에서 그은 금. 수십 줄. 날짜를 센 것처럼 가지런하다.<br><br>
    이 방을 지나면 다시 올 일은 없다. 저것이 나올 날은 이쪽이 못 고른다. 지금 고르면 지금이다.`,
  o:[
    { l:'① 지금 고른다 — 조를 깨고, 깨어나기 전에 끝낸다.', k:'break', dc:26, wake:1, cost:{ might:36 },
      ok:`유리 아래쪽을 쳤다. 액체가 쏟아져 나가게. 위를 깨면 저것 머리부터 나온다.<br><br>
        액체가 빠지며 그것이 바닥에 무릎부터 꺾여 내렸다. 폐로 첫 숨을 들이켜는 그 한 호흡 — 거기가 전부였다. 날이 먼저 닿았다.<br>
        다 자란 것도 첫 숨은 신생아다. 그 순서를 이제 안다.<br><br>
        계기판 바늘이 왼쪽 끝으로 떨어졌다. 방을 나올 때 초록 불이 꺼졌다. 수고했다는 것처럼. 기분 나쁜 칭찬이었다.`,
      ng:`유리가 한 번에 안 깨졌다. 금만 갔다. 안의 것이 눈을 떴다.<br><br>
        이쪽이 그은 금에 안쪽 금들이 마주 닿는 걸 보며 물러섰다. 저것이 안에서 마저 깼다.<br>
        액체와 유리와 그것이 한꺼번에 쏟아졌다. 첫 숨을 쉬기 전에 치기는 쳤다. 다만 혼자가 아니라 다섯이 달려들어서야 끝났다. 방이 반쯤 부서졌다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-37, mind:-15 } },
    { l:'② 전원을 찾는다 — 불빛과 열을 끊어 영영 못 깨게.', k:'gaze', dc:25,
      ok:`배양조 밑동 배선을 눈으로 따라갔다. 세 가닥. 두 가닥은 미끼처럼 겉돌고 한 가닥이 바닥 밑으로 들어간다.<br><br>
        그 한 가닥을 끊었다. 초록 불이 죽고 액체가 식기 시작했다.<br>
        안의 것이 긁던 금 위에 손끝을 댄 채 천천히 가라앉았다. 식는 것은 조용했다.<br>
        문을 닫기 전에 계기판을 봤다. 바늘이 돌아오고 있었다. 영 쪽으로.`,
      ng:`끊은 가닥이 미끼 쪽이었다. 경보가 울렸다.<br><br>
        배양조 불빛이 초록에서 붉은색으로 바뀌고, 액체에 거품이 올랐다. 비상 각성이라는 글자가 깜빡였다.<br>
        그 방에서 벌어진 일은 ①을 고른 것과 같아졌다. 준비 없이. 일행 모두 어딘가 하나씩 꿰매야 했다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-18 } }
  ] },

// ---------- S2 『백악기 정원』 ----------

{ at:'S2', t:'담장 — 시험하는 것들',
  x:`정원 안쪽 길은 낡은 쇠그물 담장을 따라 나 있다. 담장 너머는 키 큰 풀숲이다.<br><br>
    풀숲에서 그것들이 담장을 시험한다. 쿵 — 저만치서 한 번. 쿵 — 이쪽에서 한 번. 부딪치고 물러나고, 자리를 옮겨 또 부딪친다.<br>
    아무 데나 치는 게 아니다. 기둥과 기둥 사이, 녹이 깊은 자리만 골라 친다. 결과를 기억하고 다음 자리를 고른다.<br><br>
    제일 녹슨 기둥이 하필 이쪽이 지나야 할 길목에 있다.`,
  o:[
    { l:'① 다음에 칠 자리를 먼저 가 기다린다 — 그물 너머로 마중 낸다.', k:'break', dc:26, cost:{ might:35 },
      ok:`치는 순서에 규칙이 있다. 녹 깊은 순. 다음 자리는 이쪽 길목 기둥이다. 먼저 가 섰다.<br><br>
        풀이 갈라지며 달려드는 순간, 그물 코 사이로 날을 내질렀다. 부딪치러 온 콧등이 날에 마중 나왔다.<br>
        비명이 길었다. 풀숲 전체가 한 발 물러나는 소리가 났다.<br><br>
        그날 담장은 더 울리지 않았다. 시험에는 채점이 필요하다. 채점을 이쪽이 했다.`,
      ng:`순서를 읽은 것까지는 맞았다. 저쪽이 이쪽 머리 위를 한 수 더 읽었다.<br><br>
        기다리던 기둥은 조용했다. 대신 등 뒤 열 걸음 자리가 터졌다. 규칙을 보여 준 건 미끼였다.<br>
        뚫린 구멍으로 하나가 반쯤 들어온 걸 일행과 함께 도로 밀어냈다. 그물을 임시로 엮으며 생각했다. 저것들은 속임수까지 쓴다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-33, mind:-15 } },
    { l:'② 녹슨 기둥을 미리 보강한다 — 부러진 철근을 덧댄다.', k:'fix', dc:24,
      ok:`무너진 온실 뼈대에서 철근을 뽑아 와 녹슨 기둥에 겹쳐 묶었다. 둘이 하나 몫.<br><br>
        쿵. 예정대로 그 자리가 맞았다. 기둥이 울고, 버텼다.<br>
        그물 너머에서 그것이 기둥을 한참 들여다봤다. 어제와 다른 걸 아는 눈이었다. 그러곤 돌아서 풀숲으로 사라졌다. 다른 녹을 찾으러.<br>
        담장 전체를 다 보강할 수는 없다. 이쪽이 지나는 동안만 버티면 된다. 그거면 됐다.`,
      ng:`철근을 뽑는 소리가 너무 컸다. 시험하던 것들이 소리 쪽으로 관심을 옮겼다.<br><br>
        온실 뼈대 쪽 담장 — 보강 못 한 쪽 — 이 연달아 울렸다. 서둘러 묶고 뛰었다.<br>
        등 뒤에서 그물 터지는 소리가 났다. 길목은 지났으니 담장에게는 미안하게 됐다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-27, mind:-14 } },
    { l:'③ 담장에서 떨어져 걷는다 — 치는 박자 사이로만 길목을 지난다.', k:'evade', dc:25,
      ok:`부딪치고 물러나 자리를 옮기는 데 스무 호흡. 그 스무 호흡 동안만 걷고, 부딪칠 때는 엎드렸다.<br><br>
        길목 기둥 앞을 지나는 차례에 맞춰 저쪽 끝이 울렸다. 박자가 맞아떨어졌다.<br>
        다 지나고 돌아보니 길목 기둥이 그제야 쿵, 울렸다. 늦게 온 시험이 빈 길만 쳤다.`,
      ng:`박자를 반 호흡 놓쳤다. 길목 한가운데서 기둥이 울렸다.<br><br>
        그물이 안쪽으로 불룩 밀려 들어오며 쇠 끝이 어깨를 그었다. 기둥은 버텼다. 간신히.<br>
        그물 코 너머 한 뼘 거리에서 세로로 긴 눈동자가 이쪽을 들여다봤다. 그 눈을 아주 오래 잊지 못했다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S2', t:'물에 잠긴 고사리밭',
  x:`길이 끊기고 물이 시작된다. 허리까지 오는 검은 물. 고사리가 수면 위로 머리만 내밀고 끝없이 서 있다.<br><br>
    물속에서 무기는 반 박자 느리다. 그걸 아는 것들이 이 물에 산다.<br>
    스무 걸음쯤 앞 고사리 사이로 등줄기 하나가 수면을 가르고 지나갔다. 소리 없이. 이쪽을 한 바퀴 돌고 있다.<br><br>
    건너편 마른 땅까지 쉰 걸음. 물길 말고 다른 길은 없다.`,
  o:[
    { l:'① 물을 치지 않는다 — 수면 위로 나온 놈 등줄기만 노려 기다린다.', k:'break', dc:26, wake:1,
      ok:`물속을 휘젓는 건 저쪽 판에서 노는 짓이다. 무기를 수면 위에 뉘어 들고, 등줄기가 다시 금을 긋는 자리만 쟀다.<br><br>
        세 바퀴째, 등줄기가 닿는 금 위에 날을 먼저 두었다. 저것이 제 속도로 날 밑을 지나가 줬다.<br>
        물이 한 번 크게 뒤집히고 잠잠해졌다. 검붉은 것이 고사리 뿌리 쪽으로 번졌다.<br><br>
        물속 싸움은 물 위에서 끝내는 것이다. 수면이 금 긋는 판이 된다는 걸 손이 배웠다.`,
      ng:`등줄기가 금을 바꿨다. 수면 밑으로. 보이는 금은 미끼였다.<br><br>
        무릎 뒤를 무엇이 세게 쳤다. 물속에 반쯤 고꾸라지며 아무렇게나 휘둘렀다. 느린 날이 그래도 무언가에 닿았다.<br>
        일행이 겨드랑이를 잡아 세웠다. 입에 들어온 물에서 흙과 비린내 맛이 났다. 등줄기는 더 안 보였다. 그게 더 나빴다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-16 } },
    { l:'② 고사리 줄기를 베어 묶어 뗏목 삼는다 — 물에 몸을 안 담근다.', k:'fix', dc:25,
      doom:{ title:'물밑의 것', what:'검은 물 밑으로 끌려 들어갑니다', dc:19, sec:40,
        text:`뗏목이 반쯤 건넜을 때 밑에서 들어 올리는 힘이 왔다. 뗏목이 기울고, 몸이 물로 쏟아졌다.<br><br>
          발목에 턱이 닿았다. 이빨이 아니라 턱. 물고 가는 게 아니라 머금고 간다.<br>
          물이 귀를 덮었다. 위에서 일행이 수면을 두드리는 소리가 멀어진다. 고사리 뿌리들이 뺨을 스치며 지나갔다. 물밑은 생각보다 깊었다.`,
        dieText:`뗏목 반 토막이 건너편 기슭에 밀려와 닿았다.<br><br>
          물은 금방 잠잠해졌다. 고사리는 아무 일 없다는 듯 서 있었다.<br>
          일행은 남은 반 토막으로 하나씩 건넜다. 아무도 물 밑을 내려다보지 않았다. 내려다보면 마주 볼 것 같아서.`,
      },
      ok:`고사리 굵은 줄기를 베어 등짐 끈으로 엮었다. 한 사람씩 엎드려 타고 손으로 저었다.<br><br>
        등줄기가 뗏목 밑을 두 번 지났다. 물에 담긴 살이 없으니 물 것이 없다. 저것 계산에 없는 먹이 모양이었다.<br>
        쉰 걸음 물길을 넷이 두 번에 나눠 건넜다. 마지막 사람이 내리자 뗏목 꽁무니가 물밑에서 톡, 당겨졌다. 늦은 입질이었다.`,
      win:{ exp:21, dream:3 } }
  ] },

{ at:'S2', t:'큰 것 — 물결이 먼저 온다',
  x:`멀리서 쿵, 소리가 났다. 발밑 웅덩이에 가락지 같은 물결이 돋았다. 쿵. 물결. 쿵. 물결.<br><br>
    나무 위가 아니라 나무 너머로 그림자가 지나간다. 등성이 같은 등. 저게 이 정원의 큰 것이다.<br>
    싸울 상대가 아니다. 무기는 저것한테 이쑤시개다. 지금 할 일은 하나 — 지나갈 때까지 저것 눈에 담기지 않는 것.<br><br>
    문제는 길 한가운데 선 짐수레다. 일행 짐이 다 실려 있고, 저것이 오는 길목이다.`,
  o:[
    { l:'① 수레째 민다 — 발소리 박자에 맞춰, 쿵 할 때만 한 번씩.', k:'break', dc:26, cost:{ might:37 },
      ok:`쿵 — 수레를 어깨로 한 뼘 민다. 멎으면 같이 멎는다. 바퀴 소리를 저것 발소리가 덮는다.<br><br>
        길 밖 덤불까지 열두 번. 열두 번째 쿵에 수레가 덤불로 들어갔다.<br>
        큰 것이 길을 지나갔다. 방금 수레가 섰던 자리에 웅덩이만 한 발자국이 패였다.<br><br>
        어깨로 민 건 수레가 아니라 박자였다. 세상에서 제일 큰 것 발소리에 숨어 본 어깨는 웬만한 소리에 안 떤다.`,
      ng:`아홉 번째에서 바퀴가 돌에 걸렸다. 박자 밖에서 끼익, 소리가 났다.<br><br>
        쿵 소리가 멎었다. 큰 것이 멈추면 세상이 멈춘다. 수레를 버리고 덤불로 굴렀다.<br>
        큰 것이 수레를 코끝으로 한 번 뒤집어 보고 지나갔다. 짐 절반이 진흙에 쏟아졌다. 주워 담는 데 한나절, 심장이 제자리 찾는 데 또 한나절.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, spirit:-15 } },
    { l:'② 수레를 버린다 — 몸만 낮춰 길 밖으로.', k:'steady', dc:24, wake:1,
      ok:`짐은 다시 모을 수 있다. 사람은 못 모은다. 모두 길 밖 도랑에 엎드렸다.<br><br>
        큰 것이 지나갔다. 한 발 한 발이 땅을 통해 가슴을 쳤다. 수레에는 눈길도 안 줬다. 저것 눈에 수레는 돌멩이다.<br>
        어쩌면 이쪽도 돌멩이다. 그 생각이 이상하게 든든했다.<br><br>
        제일 큰 것 앞에서는 버리는 게 지키는 거다. 그 셈을 몸이 받아들였다. 무기 쥔 손에 힘이 덜 들어가게 됐다. 필요한 만큼만.`,
      ng:`도랑에 엎드리는데 등짐 쇠붙이가 서로 부딪쳐 울렸다.<br><br>
        큰 것 머리가 — 집채만 한 것이 — 이쪽 도랑 위로 천천히 내려왔다. 콧김이 풀을 눕혔다.<br>
        영원 같은 세 호흡 뒤에 머리가 올라갔다. 돌멩이로 봐 준 것이다. 엎드린 자리에 식은땀이 고였다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-19, spirit:-17 } }
  ] },

{ at:'S2', t:'반원 — 몰이사냥',
  x:`풀숲에서 그것들이 나왔다. 셋. 반원으로 벌려 선다. 서두르지 않는다.<br><br>
    등 뒤는 가시덤불이다. 저것들이 이쪽을 여기 세운 것이다. 아까부터. 길을 막는 척, 몰아 온 것이다.<br>
    가운데 놈이 제일 크다. 양 끝 둘이 번갈아 반 걸음씩 조인다. 가운데는 안 움직인다.<br><br>
    가운데가 움직일 때가 끝이다. 그 전에 반원을 깨야 한다.`,
  o:[
    { l:'① 가운데를 먼저 꺾는다 — 제일 큰 놈이 신호수다.', k:'break', dc:26,
      doom:{ title:'몰이의 끝', what:'가시덤불 너머로 물려 갑니다', dc:20, sec:37,
        text:`가운데로 들어갔다. 가운데 놈이 기다렸다는 듯 물러섰다. 신호수가 아니었다. 미끼였다.<br><br>
          양 끝 둘이 접히며 뒤를 물었다. 반원이 원이 되는 데 한 호흡도 안 걸렸다.<br>
          어깨와 다리를 각각 문 둘이 가시덤불 틈새로 몸을 끌고 들어간다. 가시가 배낭을 벗겨 냈다. 셋째가 그 뒤를 느긋하게 따라왔다. 몰이는 원래 느긋한 놈 몫이다.`,
        dieText:`가시덤불 틈새에 배낭만 걸려 있었다.<br><br>
          덤불 너머에서 셋이 나눠 먹는 소리가 났다고는 쓰지 않겠다. 일행은 반대쪽으로 뚫고 나왔다.<br>
          그날 이후 반원으로 선 것들을 보면 일행은 싸우기 전에 먼저 등 뒤부터 확인했다. 비싼 수업이었다.`,
      },
      ok:`가운데를 보는 척하며 양 끝 왼쪽 놈 조이는 박자를 쟀다. 반 걸음 — 디디는 그 발 위로 먼저 들어갔다.<br><br>
        왼쪽이 꺾이자 반원이 기울었다. 반원은 셋이 쳐야 반원이다. 둘이면 그냥 둘이다.<br>
        가운데 큰 놈이 그제야 움직였지만 늦었다. 일행 창끝이 벌써 둘을 마주 보고 있었다.<br>
        큰 놈은 죽은 왼쪽을 한 번 내려다보고 물러갔다. 계산이 안 맞으면 안 오는 것들이다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 가시덤불을 등지지 않는다 — 덤불을 베어 길을 내 뒤로 뺀다.', k:'break', dc:25, cost:{ might:33 },
      ok:`등 뒤가 벽인 건 저것들 계산이다. 계산을 베었다. 가시덤불을 어깨 폭만큼.<br><br>
        일행을 틈으로 먼저 물리고 마지막에 이쪽이 빠졌다. 덤불 가시가 저것들한테는 이쪽 무기보다 성가시다.<br>
        반원이 덤불 앞에서 멈췄다. 몰아넣은 우리가 뒷문을 달고 도망간 셈이다.<br>
        풀숲 너머에서 짜증 섞인 울음이 오래 울렸다. 사냥 설계가 무너진 울음이었다.`,
      ng:`덤불이 깊었다. 베어도 베어도 가시다. 그 사이 반원이 반의반으로 조여들었다.<br><br>
        결국 반쯤 낸 길로 몸을 욱여넣었다. 가시가 소매와 살을 같이 긁었다.<br>
        맨 뒤에서 빠지다 장딴지를 물렸다. 깊진 않다. 저쪽도 가시 때문에 입을 깊이 못 넣었다. 가시덤불이 반은 적이고 반은 아군이었다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-35, mind:-14 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 멈춘 추',
  x:`정원을 나가는 길은 결국 이 낡은 엘리베이터다. 쇠창살 승강기가 수풀에 반쯤 먹힌 채 서 있다.<br><br>
    동력은 죽었다. 손으로 감는 비상 권양기가 옆에 있다. 문제는 균형추다. 추가 녹슨 걸쇠에 걸려 중간에 멈춰 있다. 걸쇠를 깨뜨리지 않으면 권양기가 백 번을 돌아도 헛돈다.<br>
    걸쇠는 승강로 안쪽, 팔 하나 겨우 들어가는 틈 너머에 있다.<br><br>
    수풀 쪽에서, 쇠 냄새를 맡은 것들이 모여드는 기척이 시작됐다.`,
  o:[
    { l:'① 틈에 자루를 넣어 걸쇠를 단숨에 깬다 — 한 번에 안 되면 끝이다.', k:'break', dc:26, wake:1,
      ok:`자루 끝을 걸쇠 모서리에 맞추고, 비틀어 꺾는 게 아니라 때려 넣었다. 녹슨 쇠는 꺾으면 버티고 때리면 바스러진다.<br><br>
        한 번. 걸쇠가 가루째 떨어지고 추가 쿵 내려앉았다. 권양기가 팽팽해졌다.<br>
        일행이 감기 시작했다. 승강기가 떠올랐다. 수풀에서 나온 첫 놈이 창살을 긁었을 때는 이미 발 닿는 높이가 아니었다.<br><br>
        녹슨 것 깨는 법이 손에 남았다. 꺾지 말고 때릴 것. 오래된 것일수록 한 번에. 그 한 번을 고르는 눈이 생겼다.`,
      ng:`첫 타가 모서리를 빗나가 틈 안쪽 벽을 쳤다. 승강로 전체가 종처럼 울렸다.<br><br>
        수풀의 기척이 일제히 이쪽으로 꺾였다. 두 번째 타로 걸쇠는 깼다. 늦게.<br>
        올라가는 승강기 바닥 창살을 밑에서 뛰어오른 놈이 물고 매달렸다. 발로 세 번 밟고서야 떨어져 나갔다. 창살 한 칸이 휘어 그 모양대로 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 권양기 쪽을 맡는다 — 둘이 번갈아, 팔이 풀릴 때까지.', k:'steady', dc:25,
      ok:`걸쇠는 일행 한 명이 쇠지레로 맡고, 이쪽은 권양기를 잡았다. 걸쇠가 깨지는 순간 추 무게가 권양기로 한꺼번에 온다. 그때 놓치면 승강기가 바닥을 친다.<br><br>
        쿵 — 왔다. 손잡이가 튀려는 걸 체중으로 눌렀다. 버텼다. 감았다.<br>
        마흔 바퀴. 팔이 남의 것이 될 때쯤 승강기가 위 문턱에 닿았다. 밑에서 올려다보는 눈들을 내려다보며 창살 문을 닫았다.`,
      ng:`추 무게가 오는 순간 손잡이가 한 바퀴 역회전하며 손등을 쳤다.<br><br>
        승강기가 반 층 미끄러져 떨어졌다. 안에 탄 일행 비명. 다시 잡아 감았다.<br>
        올라는 갔다. 손등이 밤톨만 하게 부었다. 권양기에 맞은 건지 이쪽 실수에 맞은 건지, 둘 다였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'둥지 — 갓 깬 것들',
  x:`지름길 한가운데 둥지가 있다. 진흙과 나뭇가지. 그 안에 갓 깬 새끼들이 바글거린다.<br><br>
    주먹만 하다. 눈도 못 떴다. 그런데 벌써 이빨이 다 났고, 서로를 밀치며 허공을 문다.<br>
    어미는 안 보인다. 사냥 나갔을 것이다. 돌아올 시간은 모른다.<br><br>
    둥지를 돌아가면 반나절. 가로지르면 백 걸음. 새끼들 울음소리가 어미를 부르는 종이라는 것만은 확실하다.`,
  o:[
    { l:'① 울기 전에 지난다 — 둥지 가장자리로, 그림자도 안 밟고.', k:'hide', dc:25,
      ok:`새끼들은 눈이 아니라 그림자와 바람으로 안다. 바람을 등지지 않는 쪽 가장자리로 돌았다.<br><br>
        한 놈이 허공을 몇 번 물었지만 울지는 않았다. 백 걸음이 끝났다.<br>
        다 지나서 돌아보니 둥지 너머 수풀에 어미가 서 있었다. 언제부터인지 모른다. 이쪽을 보고 있었다.<br>
        물지 않았다. 둥지를 안 건드린 것을 — 그걸로 계산이 끝난 눈이었다. 서로 등을 돌렸다.`,
      ng:`가장자리 진흙이 무게에 꺼지며 발이 미끄러졌다. 새끼 하나가 발등을 물었다.<br><br>
        아프기보다 — 울었다. 그 놈이 울자 다 울었다. 수십 개 목청이 한 종소리가 됐다.<br>
        백 걸음을 전력으로 뛰었다. 등 뒤 수풀이 갈라지는 소리가 지름길이 아깝지 않게 만들었다. 겨우 따돌렸다. 발등 이빨 자국은 주먹만 한 것치고 깊었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 둥지를 지운다 — 어미가 돌아올 이유를 없앤다.', k:'break', dc:26,
      doom:{ title:'돌아온 어미', what:'어미에게 물려 수풀 깊이 실려 갑니다', dc:20, sec:36,
        text:`둥지에 날을 대는 순간 수풀이 터졌다. 어미는 사냥을 나간 게 아니었다. 둥지 사냥을 기다린 것이다. 이 둥지가 몇 번째 미끼인지 모른다.<br><br>
          턱이 어깨째 물었다. 발이 땅에서 떨어졌다. 수풀이 얼굴을 연달아 때리며 지나간다.<br>
          새끼 울음소리가 멀어진다. 저 소리 쪽이 아니라 반대쪽으로 간다. 새끼들 못 보는 데서 먹는 버릇 — 그 생각이 제일 차가웠다.`,
        dieText:`둥지는 그대로였다. 새끼들은 여전히 허공을 물고 있었다.<br><br>
          일행은 반나절 길로 돌아갔다. 아무도 지름길 말을 다시 꺼내지 않았다.<br>
          돌아가는 길 내내 수풀 안쪽에서 무엇이 나란히 따라 걸었다. 배가 부른 걸음이었다. 그래서 더 끔찍했다.`,
      },
      ok:`날을 대기 전에 수풀을 먼저 봤다. 바람이 없는데 흔들리는 가지 하나.<br><br>
        둥지에서 손을 뗐다. 대신 말린 고기 반 토막을 둥지 반대쪽 멀리 던졌다. 새끼들 고개가 일제히 그쪽으로 돌았다.<br>
        수풀의 그림자가 그 고갯짓을 따라 옮겨 가는 사이, 가장자리로 지났다. 어미 눈을 못 본 게 아니라 — 어미 눈이 이쪽을 안 본 백 걸음이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'S2', t:'먹이대 — 오래된 뼈 무더기',
  x:`옛 사육사들이 쓰던 먹이대가 공터에 서 있다. 쇠기둥 위 평상. 그 밑에 뼈가 무더기로 쌓였다.<br><br>
    여기 사는 것들은 아직 이 자리를 기억한다. 해 질 녘이면 와서 기다린다고, 평상 위 사육일지가 말해 준다. 급여 중단, 이라는 마지막 장이 비에 불어 있다.<br>
    지금은 한낮. 공터는 비었다. 뼈 무더기 사이에 뜯다 만 짐짝들 — 사육사들 것이었을 가방과 장화가 섞여 있다.<br><br>
    여기를 지나는 길이 제일 빠르다. 해는 아직 높다. 높다고 믿고 싶다.`,
  o:[
    { l:'① 먹이대 기둥을 꺾어 평상을 무너뜨린다 — 기다릴 자리를 없앤다.', k:'break', dc:25, wake:1, cost:{ might:34 },
      ok:`녹슨 기둥 두 개를 꺾었다. 평상이 뼈 무더기 위로 내려앉으며 공터의 모양이 바뀌었다.<br><br>
        기억 속 자리와 다른 자리는 저것들을 머뭇거리게 한다. 머뭇거림이 이쪽 몫의 시간이다.<br>
        공터를 다 건널 때까지 아무것도 안 왔다. 해 질 녘, 멀리서 우는 소리가 들렸다. 약속 장소가 없어진 것들의 소리였다.<br><br>
        부수는 게 길을 여는 거라는 건 알았다. 부수는 게 시간을 번다는 건 여기서 배웠다. 자리를 부수면 습관이 무너진다.`,
      ng:`첫 기둥이 꺾이며 평상이 비스듬히 미끄러졌다. 쇠가 쇠를 긁는 소리가 공터에 길게 울렸다.<br><br>
        저녁 종으로 들렸을 것이다. 수풀 저쪽에서 대답이 왔다. 이른 손님들.<br>
        반쯤 무너진 평상을 두고 뛰었다. 공터 끝에서 돌아보니 그것들이 기운 평상 주위를 돌며 어리둥절해 있었다. 그 어리둥절함 덕에 산 셈이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, spirit:-15 } },
    { l:'② 뼈 무더기를 뒤진다 — 사육사들 짐에 쓸 만한 게 남았을 것이다.', k:'luck', dc:24,
      ok:`장화 속, 가방 밑. 사육사들은 급하게 당한 게 아니라 급하게 떠났다. 짐이 덜 뜯겼다.<br><br>
        밀봉된 비상식 꾸러미 하나가 가방 바닥에 멀쩡했다. 사육사용 소금 덩이도.<br>
        가방 주인 명찰에 묻은 것은 못 본 척했다. 산 사람이 쓰는 게 짐의 도리다.<br>
        해가 기울기 전에 공터를 벗어났다. 등 뒤 먹이대에 하나둘 모여드는 그림자들을 못 본 척하는 데는 익숙해졌다.`,
      ng:`가방 하나를 당기자 뼈 무더기가 와르르 흘렀다. 무더기 속에서 자던 작은 것들이 쏟아져 나왔다.<br><br>
        주먹만 한 것들인데 수가 많았다. 장딴지와 손등을 물어뜯기며 공터를 뛰었다.<br>
        건진 건 긁힌 소금 덩이 하나. 셈이 맞는 장사였는지는 밤에 상처가 부어오르고서야 알게 됐다. 밑지는 장사였다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-26, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 화염술사 · 마력
// ------------------------------------------
kJob('pyro', 'S', [

{ at:'S', t:'불빛의 값 — 보이는 쪽은 이쪽이다',
  x:`여기서 불은 두 가지 일을 한다. 길을 보여 주고, 이쪽을 보여 준다.<br><br>
    어둠 속의 것들은 불을 안 무서워하게 된 지 오래다. 불빛은 저것들한테 저녁상 등불이다.<br>
    손끝 불꽃을 줄이면 길이 안 보이고, 키우면 이쪽이 더 멀리서 보인다.<br>
    일행이 이쪽 손끝만 보고 있다. 불 크기를 정하는 건 늘 불 쓰는 사람 몫이다.`,
  o:[
    { l:'① 불을 낮게 깐다 — 발밑만 비추는 바닥불로 바꾼다.', k:'fix', dc:24, wake:1,
      ok:`불꽃을 손끝에서 떼어 바닥에 깔았다. 무릎 아래만 밝은 낮은 불. 멀리서 보면 불빛이 아니라 바닥의 얼룩이다.<br><br>
        어둠 속 기척들이 불빛을 못 찾고 서성였다. 저것들은 눈높이의 불을 배웠다. 바닥의 불은 아직이다.<br><br>
        불은 밝으라고만 있는 게 아니다. 어디를 밝히느냐가 기술이다. 손끝이 그 높이를 외웠다.`,
      ng:`바닥불이 기름때에 옮겨붙었다. 낮게 깔려던 불이 줄을 그으며 번졌다.<br><br>
        복도 절반이 환해졌다. 이쪽 다섯 명 그림자가 벽에 크게 걸렸다.<br>
        기척들이 일제히 방향을 잡는 소리가 났다. 불을 밟아 끄고 한참을 돌아서 걸었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 불을 아예 띄워 보낸다 — 가짜 일행을 저쪽 복도에 만든다.', k:'break', dc:25, cost:{ mana:30 },
      ok:`불덩이 다섯을 빚어 옆 복도로 천천히 흘려보냈다. 사람 걸음 속도로, 사람 키 높이로.<br><br>
        기척들이 그 불들을 따라갔다. 다섯 불빛이 다섯 사람인 줄 아는 것이다.<br>
        이쪽은 어둠 속을 손끝 온기만으로 더듬어 건넜다. 멀리서 불덩이들이 하나씩 꺼지는 소리 — 덮치는 소리가 들렸다. 허공을 문 저것들 몫이다.`,
      ng:`불덩이들이 복도 바람에 흩어졌다. 다섯이 둘이 되고, 둘이 금방 꺼졌다.<br><br>
        기척들이 되돌아왔다. 속은 걸 아는 걸음이었다. 빨라진 걸음.<br>
        마력만 쓰고 시간은 못 벌었다. 남은 길을 거의 뛰다시피 건넜다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-15, spirit:-16 } }
  ] },

{ at:'S', t:'목덜미의 것 — 사람을 안 태우는 불',
  x:`동료 목덜미에 그것이 붙었다. 손가락 길이. 다리가 많고, 꼬리가 벌써 옷깃 밑으로 파고들었다.<br><br>
    떼면 살을 물고 들어간다. 두면 밤 사이에 안으로 들어간다. 태우는 수밖에 없다.<br>
    문제는 자리다. 목덜미. 불과 살갗 사이에 종이 한 장 틈도 없다.<br><br>
    동료가 이를 악물고 말한다. 해라. 네 불이면 된다.`,
  o:[
    { l:'① 바늘 불 — 불을 바늘 끝만큼 모아 그것 머리만 지진다.', k:'break', dc:26, wake:1, cost:{ mana:34 },
      ok:`불꽃을 바늘 끝 크기로 모았다. 손끝이 아니라 그 한 점에만 열이 서게.<br><br>
        그것 머리 — 다리들이 모이는 한가운데 — 에 점을 찍었다. 타는 냄새. 다리들이 일제히 오그라들며 그것이 바닥에 떨어졌다.<br>
        동료 목덜미에는 발갛게 점 하나. 데인 자국이 아니라 닿은 자국이다.<br><br>
        큰불은 누구나 지른다. 불을 바늘로 쓰는 건 다른 일이다. 그 한 점을 쥐는 법이 손에 남았다.`,
      ng:`한 점으로 모이기 직전에 그것이 움직였다. 열을 느끼는 것이다.<br><br>
        꼬리가 옷깃 밑으로 확 파고들었다. 동료가 짧게 소리를 질렀다.<br>
        결국 옷을 찢고 일행 둘이 잡은 채 지졌다. 그것은 죽었다. 동료 어깨에 지진 자국과 물린 자국이 나란히 남았다. 둘 다 이쪽 책임 같았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 열로 꾄다 — 그것이 좋아할 온도를 손바닥에 만들어 옮겨 태운다.', k:'gaze', dc:25,
      ok:`그것이 목덜미를 고른 이유는 온도다. 맥이 뛰는 따뜻한 자리.<br><br>
        손바닥을 그보다 반 도 따뜻하게 데워 목덜미 옆에 댔다. 그것이 다리를 하나씩 옮겨 손바닥으로 넘어왔다. 더 좋은 집으로 이사 오듯.<br>
        손바닥 위에서 불로 바꿨다. 이사가 끝나기 전에.<br>
        동료가 목을 쓸며 물었다. 손은 괜찮으냐고. 불 쓰는 손은 제 불에 안 덴다. 대체로.`,
      ng:`반 도가 아니라 한 도를 넘겼다. 그것이 수상한 온기를 알아챘다.<br><br>
        손바닥으로 오는 대신 옷깃 밑으로 숨었다. 등 쪽으로 내려간다.<br>
        동료 옷을 다 벗겨 세 사람이 털어내고서야 바닥에 떨어진 놈을 밟았다. 동료는 그날 밤 내내 등을 벽에 대고 잤다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-18, spirit:-19 } }
  ] },

{ at:'S', t:'꺼진 불 — 잿속의 씨앗',
  x:`밤 한가운데서 불이 죽었다. 기름이 다한 게 아니다. 무언가가 공기를 바꿨다. 숨이 갑갑하다.<br><br>
    어둠이 꽉 찼다. 일행 숨소리 사이로 다른 숨소리들이 섞여 든다. 불이 죽기를 기다린 것들.<br>
    잿더미 속에 불씨가 몇 점 남았다. 맨눈에는 안 보인다. 불 쓰는 손에만 느껴진다.<br><br>
    시간은 불씨가 식을 때까지다.`,
  o:[
    { l:'① 불씨를 한 점으로 모아 단숨에 세운다 — 어둠을 한 번에 걷는다.', k:'break', dc:26, cost:{ mana:36 },
      ok:`잿속 불씨 네 점을 손바닥 위로 불러 모았다. 한 점으로 겹치고, 숨을 불어 넣는 대신 마력을 부었다.<br><br>
        어둠이 소리를 지르며 물러났다 — 불기둥이 천장을 핥았다. 바로 코앞까지 와 있던 것들의 윤곽이 한순간 다 드러났다. 여섯. 생각보다 많았다.<br>
        불기둥이 장작불 크기로 내려앉을 때까지 저것들은 돌아오지 못했다. 공기를 바꾼 놈이 어느 놈이었는지는 못 봤다. 다음엔 그놈부터다.`,
      ng:`불씨 두 점이 손바닥에 오기 전에 식었다. 남은 두 점으로는 기둥이 안 선다.<br><br>
        작은 불꽃 하나가 겨우 섰다. 촛불만 한 것. 그 불빛 가장자리에 저것들 발끝이 보였다.<br>
        촛불 하나로 등을 맞대고 새벽까지 버텼다. 제일 긴 밤이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 불씨를 나눈다 — 일행 손마다 한 점씩 쥐여 준다.', k:'bond', dc:24, wake:1,
      ok:`불씨 네 점을 네 사람 손바닥에 하나씩 올렸다. 식지 않게 숨 고르는 법을 짧게 일렀다.<br><br>
        다섯 숨이 네 점을 지켰다. 어둠의 것들이 네 방향 네 불씨 앞에서 갈피를 못 잡았다.<br>
        새벽에 네 점을 다시 모아 불을 세웠다. 한 점도 안 죽었다.<br><br>
        불은 혼자 지키는 게 아니었다. 나눠 쥔 불씨가 대형이 된다. 그걸 이 밤이 가르쳤다.`,
      ng:`셋째 사람 손에서 불씨가 식었다. 쥐는 법을 제대로 못 일렀다.<br><br>
        그쪽 방향 어둠이 먼저 밀고 들어왔다. 남은 불씨를 급히 모아 불을 세웠다. 반쪽짜리 불.<br>
        밀고 들어온 놈은 쫓았다. 불씨를 쥐었다 식힌 동료가 밤새 제 손바닥만 들여다봤다. 네 탓이 아니라고 말해 줬다. 가르친 쪽 탓이라고.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-15, spirit:-17 } }
  ] },

{ at:'S', t:'검은 피 웅덩이 — 태워서 막는다',
  x:`일행 무기가 큰 놈을 넘어뜨렸다. 좋다. 검은 피가 바닥을 먹으며 번져 간다. 안 좋다.<br><br>
    피 웅덩이가 번지는 방향에 유일한 출구가 있다. 웅덩이가 문턱을 먹으면 문도 못 쓴다.<br>
    쇠도 돌도 녹이는 피다. 막을 수 있는 건 — 태워서 굳히는 것뿐이다.<br><br>
    피 끓는 냄새가 벌써 복도 저쪽 기척들을 당기고 있다.`,
  o:[
    { l:'① 웅덩이 가장자리를 돌아가며 지져 둑을 만든다.', k:'break', dc:25, cost:{ mana:32 },
      ok:`가장자리를 따라 불줄을 둘렀다. 검은 피가 불에 닿으며 숯빛 딱지로 굳었다. 딱지가 둑이 됐다.<br><br>
        둑 안에서 피가 제 자리만 파먹다 멎었다. 문턱은 지켰다.<br>
        굳은 딱지 위로 한 사람씩 건넜다. 발밑에서 바삭거리는 소리가 났다. 밟고 지나가도 되는 건 불이 먼저 밟아 준 자리뿐이다.`,
      ng:`둑이 반쯤 돌았을 때 피가 바닥 틈으로 스며 둑 밑을 지났다.<br><br>
        문턱 모서리가 연기를 내며 주저앉기 시작했다. 서둘러 문턱째 지져 굳혔다.<br>
        문은 살았다. 다만 반쯤 녹은 문턱이 안 닫히는 문이 됐다. 닫히지 않는 문을 등지고 걷는 기분은 설명이 어렵다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-15, spirit:-16 } },
    { l:'② 피째 통째로 태운다 — 웅덩이 한가운데 불을 박는다.', k:'break', dc:26,
      ok:`웅덩이 한복판에 불덩이를 박았다. 검은 피가 한꺼번에 끓어오르며 — 탔다.<br><br>
        독한 연기가 기둥으로 섰다. 일행은 입을 막고 벽에 붙었다. 연기는 천장 환기구가 삼켰다.<br>
        바닥에는 유리처럼 굳은 검은 판만 남았다. 지나온 기척들이 그 냄새에 멈칫하는 사이 복도를 벗어났다.<br>
        녹이는 것은 타는 것을 못 이긴다. 적어도 오늘은 그랬다.`,
      ng:`피가 타며 튀었다. 끓는 검은 방울들이 사방으로.<br><br>
        한 방울이 소매에 앉아 천과 살갗을 같이 파고들었다. 급히 소매째 태워 떨궜다.<br>
        팔뚝에 동전만 한 흉이 남았다. 연기 기둥은 등대처럼 이쪽 자리를 알렸다. 급히 떴다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-14 } }
  ] },

{ at:'S', t:'불을 아는 놈',
  x:`이 놈은 다르다. 불덩이를 던지면 피하는 게 아니라 — 기다린다. 불이 사그라드는 끝을.<br><br>
    두 번 봤다. 불꽃이 주먹에서 떠나는 순간 놈의 눈이 불이 아니라 이쪽 손을 본다.<br>
    불을 배운 것이다. 어디서 배웠는지는 생각하고 싶지 않다.<br><br>
    놈이 반원을 그리며 거리를 잰다. 불 없는 쪽 — 이쪽 왼편으로.`,
  o:[
    { l:'① 손을 속인다 — 오른손에 헛불, 진짜 불은 바닥을 기어가게.', k:'break', dc:26, wake:1, cost:{ mana:38 },
      ok:`오른손에 큰 불을 피웠다. 놈의 눈이 그 손에 묶였다. 그사이 왼손 끝에서 풀어 둔 불이 바닥을 기었다. 얇고 낮게, 뱀처럼.<br><br>
        바닥불이 놈의 발밑에 닿는 순간 세웠다. 아래에서 위로 — 놈이 배운 적 없는 방향.<br>
        불을 배운 놈은 불의 버릇을 배웠을 뿐이다. 버릇을 버리면 불은 다시 처음 보는 것이 된다.<br><br>
        불에 버릇을 안 들이는 법 — 그게 이번에 이쪽이 배운 것이다.`,
      ng:`바닥불이 기는 사이 놈이 움직였다. 불이 아니라 처음부터 이쪽 몸을 보고 있었다.<br><br>
        왼편 — 불 없는 쪽에서 들어왔다. 헛불 든 오른손으로 막느라 손등이 발톱에 긁혔다.<br>
        일행 창이 사이를 벌려 줬다. 놈은 물러나며 끝까지 이쪽 두 손을 번갈아 봤다. 다음 수업 준비를 하는 눈이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 불을 끈다 — 전부. 놈이 아는 판을 치운다.', k:'steady', dc:25,
      ok:`손끝 불을 다 죽였다. 어둠. 놈이 아는 싸움은 불 있는 싸움이다.<br><br>
        어둠 속에서 셋을 셌다. 놈의 발소리가 혼란스럽게 왼쪽, 오른쪽. 판이 사라진 것이다.<br>
        발소리가 가까워진 순간 — 그 콧등 바로 앞에서 — 불을 한꺼번에 돌려세웠다. 눈이 어둠에 열린 놈한테 그 빛은 대낮이 아니라 벼락이다.<br>
        놈은 눈을 감싸듯 고개를 틀며 물러나 사라졌다. 불은 끌 줄 아는 자의 것이다.`,
      ng:`어둠 속에서 발소리를 놓쳤다. 저쪽 눈이 이쪽 귀보다 빨랐다.<br><br>
        어깨를 치고 지나갔다. 넘어지며 급히 불을 세웠다. 놈은 벌써 어둠 밖이다.<br>
        어깨에 발톱 자국 셋. 끈 불값으로는 비쌌다. 끄는 법이 틀린 게 아니라 켜는 때가 늦었다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S', t:'젖은 길 — 불이 싫어하는 복도',
  x:`천장에서 물이 줄줄 새는 복도다. 벽도 바닥도 젖었다. 공기까지 무겁다.<br><br>
    손끝 불꽃이 자꾸 주저앉는다. 여기서 불은 평소의 반값이다.<br>
    그걸 아는 것들이 이 복도에 산다. 젖은 어둠 속에서 눈들이 떠 있다. 불 쓰는 사람이 약해지는 자리를 골라 사는 것들.<br><br>
    복도는 길다. 그리고 눈들이 하나둘 늘고 있다.`,
  o:[
    { l:'① 물을 끓인다 — 불 대신 김으로 복도를 채운다.', k:'break', dc:25, wake:1, cost:{ mana:35 },
      ok:`바닥 물웅덩이에 열을 들이부었다. 불꽃은 반값이어도 열은 열이다. 복도가 김으로 하얗게 찼다.<br><br>
        젖은 데 사는 것들은 찬 물 것들이다. 끓는 김이 저것들한테는 이쪽의 불보다 넓은 불이다.<br>
        눈들이 김 뒤로 밀려났다. 김을 앞세워 복도를 다 건넜다.<br><br>
        불이 반값인 곳에서는 불을 팔지 말고 열을 팔면 된다. 물이 많으면 물을 무기로 빌리면 된다. 장부가 하나 늘었다.`,
      ng:`웅덩이가 생각보다 깊었다. 김이 복도를 채우기 전에 마력이 먼저 바닥을 보였다.<br><br>
        어중간한 안개만 섰다. 이쪽 눈도 가리는 안개.<br>
        안개 속에서 찬 것이 종아리를 스치고 지나갔다. 두 번. 세 번째 전에 복도를 뛰어 벗어났다. 끓이다 만 물은 양쪽 다 못 쓰는 패였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 마른 길을 읽는다 — 물길 피해 천장 배관 위로.', k:'sense', dc:25,
      ok:`물이 새는 데는 규칙이 있다. 배관 이음매. 그 사이사이 마른 등뼈 길이 천장 가까이 나 있다.<br><br>
        배관 위로 올라 마른 길만 디뎠다. 불꽃이 제값을 되찾았다.<br>
        아래 젖은 바닥에서 눈들이 올려다봤다. 물 밖은 저것들 판이 아니다.<br>
        마른 불꽃 하나를 아래로 툭 떨궈 줬다. 인사였다. 눈들이 흩어졌다.`,
      ng:`배관 하나가 무게에 꺾이며 물을 쏟았다. 머리부터 다 젖었다.<br><br>
        손끝 불이 피식 죽었다. 어둠, 젖은 바닥, 그리고 반기는 기척들.<br>
        일행 등불 하나에 의지해 남은 복도를 건넜다. 불 쓰는 사람이 젖은 생쥐 꼴로 걷는 걸 눈들이 끝까지 구경했다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S', t:'온기를 세는 알들',
  x:`길목에 알들이 쌓여 있다. 가죽질 알. 몇 개는 속에서 꿈틀거린다.<br><br>
    손을 대 보지 않아도 안다 — 불 쓰는 손은 열을 읽는다. 알마다 온도가 다르다. 뜨거운 것일수록 깨기 직전이다.<br>
    제일 뜨거운 세 개가 하필 길목 한가운데 있다. 발소리 진동이면 깬다. 체온이 스쳐도 깬다.<br><br>
    어미 기척은 없다. 알이 깨면 생길 것이다.`,
  o:[
    { l:'① 온도를 훔친다 — 뜨거운 알 셋의 열을 빨아내 재운다.', k:'break', dc:26, cost:{ mana:37 },
      ok:`불을 넣는 대신 뺐다. 알 세 개의 열을 손바닥으로 끌어왔다. 천천히, 알이 놀라지 않을 속도로.<br><br>
        꿈틀거림이 느려지다 멎었다. 죽인 게 아니다. 겨울인 줄 알게 한 것이다. 깨어날 날이 몇 밤 미뤄졌을 뿐.<br>
        식은 알 사이를 지났다. 훔친 열은 손바닥에 남아 밤새 따뜻했다. 남의 봄으로 덥힌 손이라 생각하면 묘했지만, 따뜻한 건 따뜻한 거다.`,
      ng:`둘째 알에서 속도를 넘겼다. 갑자기 식는 건 겨울이 아니라 위험이다.<br><br>
        알이 안에서 터지듯 깨졌다. 깨다 만 것이 반쯤 나와 울었다. 덜 여문 울음인데 멀리 갔다.<br>
        셋째 알을 마저 재우고 뛰었다. 등 뒤 멀리서 큰 것이 우는 대답이 왔다. 몇 밤 치 빚을 진 기분이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 가장 먼 알 하나만 데운다 — 깨어날 자리를 저쪽으로 정해 준다.', k:'gaze', dc:25,
      ok:`길목 반대쪽 끝, 제일 찬 알 하나를 골라 천천히 데웠다. 깨기 직전 온도까지.<br><br>
        그 알이 먼저 울기 시작했다. 안에서. 길목의 뜨거운 알들이 일제히 그 소리에 귀 기울이듯 잠잠해졌다. 형제가 먼저 나오는 걸 기다리는 것이다.<br>
        모두의 주의가 저쪽에 가 있는 사이 길목을 지났다. 등 뒤에서 알 깨지는 소리와 — 멀리서 달려오는 어미 발소리가 겹쳤다. 어미는 이쪽을 지나쳐 갔다. 제 새끼 소리 쪽으로.`,
      ng:`데우는 양이 모자랐다. 알이 울다 말았다.<br><br>
        대신 길목의 뜨거운 알 하나가 그 어중간한 소리에 깼다. 제일 나쁜 자리에서.<br>
        갓 깬 것은 느리다. 그게 유일한 다행이었다. 뛰어 지나는 발뒤꿈치를 덜 여문 이빨이 한 번 스쳤다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'불의 금 — 넘어 들어온 것',
  x:`야영 자리에 불의 금을 둘렀다. 허리 높이 불벽. 밤의 것들은 금 밖을 돌기만 했다.<br><br>
    새벽녘, 금 안쪽 흙에 발자국이 찍혀 있다. 긴 발가락 셋. 들어왔다 나간 자국.<br>
    불벽은 밤새 안 꺼졌다. 넘은 게 아니라 — 지나온 것이다. 불을.<br>
    일행 짐 하나가 뒤집혀 있고, 말린 고기 꾸러미가 사라졌다. 맛을 봤다. 다음에는 맛보기가 아닐 것이다.`,
  o:[
    { l:'① 불의 금을 다시 설계한다 — 높이가 아니라 깊이로.', k:'fix', dc:25, wake:1,
      ok:`불벽을 허리 높이에서 무릎 깊이로 바꿨다. 높은 커튼이 아니라 넓은 강. 지나는 데 세 걸음이 걸리는 불.<br><br>
        한 호흡에 뚫는 불은 지나도, 세 걸음 내내 타는 불은 못 지난다. 발바닥이 버티지 못한다.<br>
        다음 밤, 금 밖에서 그것이 강 폭을 재며 오래 서성였다. 발자국은 끝내 금 밖에만 남았다.<br><br>
        불은 벽이 아니라 땅이 될 때 더 세다. 금 긋는 법이 하나 늘었다.`,
      ng:`깊이를 벌리니 기름이 배로 든다. 새벽 전에 강 한 귀퉁이가 여울처럼 얕아졌다.<br><br>
        그 여울로 그것이 들어왔다. 이번엔 고기 꾸러미가 아니라 고기 꾸러미를 베고 자던 동료 어깨를 긁었다.<br>
        비명에 다 깼고, 그것은 여울로 되돌아 나갔다. 깊이는 맞았다. 양이 틀렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 미끼 자리를 만든다 — 금 한 곳만 얇게, 그 앞에 이쪽이 선다.', k:'break', dc:26,
      doom:{ title:'불을 지나는 것', what:'불의 금 밖으로 끌려 나갑니다', dc:19, sec:44,
        text:`얇은 자리로 그것이 왔다. 계산대로. 계산 밖이었던 건 속도다.<br><br>
          불을 지나는 동안 보이리라 했다. 안 보였다. 불이 눌리듯 갈라지고, 다음 순간 그것 턱이 이쪽 팔을 물고 있었다.<br>
          금 밖으로 끌린다. 제가 지나온 불 위로 이쪽을 끌고 — 불이 이쪽 옷자락만 태운다. 저것 가죽은 멀쩡하다. 불 쓰는 사람이 불에 끌려 나가는 꼴이라니.`,
        dieText:`불의 금이 새벽까지 멀쩡히 탔다. 지킬 사람 없는 금이.<br><br>
          금 밖 어둠에서 긴 발가락 자국이 끌린 자국과 나란히 이어졌다. 일행은 자국이 끝나는 데까지는 따라가지 못했다.<br>
          다음 야영부터 불의 금은 둘이 지켰다. 금은 긋는 것보다 지키는 쪽이 어렵다는 걸 모두가 알게 됐다.`,
      },
      ok:`얇은 자리 앞에 숨을 죽이고 섰다. 왔다 — 불이 눌리듯 갈라지는 순간, 기다리던 불을 그 자리에 쏟았다.<br><br>
        얇은 금이 한순간 기둥이 됐다. 지나던 것이 기둥 한가운데 갇혔다.<br>
        비명이 짧았다. 불을 지나는 재주는 불이 얇을 때 재주다.<br>
        재가 가라앉고, 긴 발가락 발자국은 더 안 생겼다. 고기 꾸러미 값은 받은 셈 쳤다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'연기 읽기 — 숨은 길',
  x:`막다른 방이다. 문은 들어온 것 하나. 그 문 너머로 쫓아오는 것들 소리가 가깝다.<br><br>
    공기가 돈다. 막힌 방에서 공기가 돌면 어딘가 숨구멍이 있다는 뜻이다. 눈에는 안 보인다.<br>
    손끝에서 가는 연기 한 줄을 피워 올렸다. 연기는 바람의 글씨다.<br><br>
    연기가 천천히 허리를 꺾는다. 어디로든 — 빨리 읽어야 한다.`,
  o:[
    { l:'① 연기 끝을 따라간다 — 글씨를 끝까지 읽는다.', k:'sense', dc:25,
      ok:`연기가 벽 아래 선반 뒤로 기어들었다. 선반을 당기니 바람구멍 — 아니, 옛 배관 통로가 입을 벌렸다.<br><br>
        사람 하나 기어갈 폭. 연기를 앞세워 들여보냈다. 연기가 곧게 뻗어 나갔다. 막힌 데 없다는 글씨다.<br>
        마지막 사람이 들어가고 선반을 당겨 닫는 순간 방문이 터졌다. 통로 안에서 그 소리를 들으며 기었다. 글씨는 끝까지 맞았다.`,
      ng:`연기가 두 갈래로 갈렸다. 숨구멍이 둘이다. 고를 시간에 문이 먼저 터졌다.<br><br>
        가까운 쪽 구멍으로 무작정 들어갔다. 반은 맞았다 — 통로는 통로였다. 반은 틀렸다 — 좁아지다 꺾이는 통로였다.<br>
        어깨가 긁히며 꺾임을 억지로 지났다. 뒤에서 그것들이 구멍에 머리를 박는 소리가 쿵쿵 따라왔다. 못 들어오는 소리이기도 했다. 그것만 들었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 연기를 역으로 쓴다 — 문틈으로 짙은 연기를 밀어 보낸다.', k:'break', dc:25, cost:{ mana:31 },
      ok:`기름걸레에 불을 묻혀 매운 연기를 만들고, 열로 밀어 문틈으로 보냈다. 문 너머가 연기로 찼다.<br><br>
        코로 쫓는 것들한테 매운 연기는 눈 가리개가 아니라 코 가리개다. 문 너머 발소리들이 엉키기 시작했다.<br>
        그사이 연기 글씨가 가리킨 선반 뒤 통로로 다 빠졌다. 쫓던 것들은 빈 방의 매운 공기만 다 마셨을 것이다. 고소하다.`,
      ng:`바람이 변덕을 부렸다. 민 연기가 문틈에서 되밀려 이쪽 방을 채웠다.<br><br>
        제 연기에 제가 눈물 바람이 됐다. 기침 소리가 문 너머까지 갔다.<br>
        눈물범벅으로 통로를 찾아 기었다. 매운 연기는 저쪽 코도 막았는지 추격은 흐지부지해졌다. 본전치기였다. 눈은 밤새 쓰렸다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S', t:'열 그림자 — 안 보이는 것의 윤곽',
  x:`일행 하나가 말했다. 방금 뭐가 스쳤다고. 아무것도 안 보인다. 그런데 바닥 먼지가 두 줄로 눌려 있다.<br><br>
    보이지 않는 게 아니라 비치는 것이다. 유리처럼 제 뒤 풍경을 입는 가죽. 눈은 못 잡는다.<br>
    하지만 숨 쉬는 것은 열이 있다. 열은 못 입는다.<br><br>
    손끝 불을 끄고, 손바닥을 폈다. 방 안의 온도를 읽는다. 저기 — 벽 앞에, 벽보다 두 도 따뜻한 윤곽.`,
  o:[
    { l:'① 윤곽째 태운다 — 보이기 전에 끝낸다.', k:'break', dc:26, wake:1, cost:{ mana:39 },
      ok:`눈을 감았다. 눈은 거짓말에 약하다. 손바닥이 읽는 온도만으로 겨눴다.<br><br>
        두 도 따뜻한 윤곽 한가운데에 불을 던졌다. 비명 — 그리고 불이 붙은 것은 더 못 비친다. 타는 제 모습을 입을 수는 없으니까.<br>
        불덩이 모양 그대로 날뛰는 윤곽을 일행 창들이 마무리했다.<br><br>
        눈을 감고 맞힌 첫 불이었다. 보는 것과 겨누는 것이 다른 일이라는 걸 손이 먼저 알았다.`,
      ng:`던지는 순간 윤곽이 움직였다. 열 그림자가 번진 자리 — 방금까지 있던 자리를 태웠다.<br><br>
        빈 벽만 그을렸다. 그리고 등 뒤에서 일행의 비명.<br>
        돌아서 두 번째 불로는 맞혔다. 동료 등에 긁힌 자국 넷이 난 뒤였다. 열 그림자는 자국이 아니라 지금이어야 했다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 방 전체를 데운다 — 온도 차를 지워 저것의 가죽을 망가뜨린다.', k:'gaze', dc:26,
      ok:`벽이고 바닥이고 한꺼번에 미지근하게 데웠다. 방 안 온도가 고르게 올라갔다.<br><br>
        비치는 가죽은 뒤 풍경을 입는다. 풍경이 전부 한 온도로 이글거리자 가죽이 갈피를 잃었다 — 윤곽이 물결처럼 일렁이며 드러났다.<br>
        모두의 눈에 보였다. 보이면 끝난 싸움이다.<br>
        그것이 문으로 도망치는 걸 아무도 안 쫓았다. 쫓을 필요가 없었다. 일렁이는 등짝이 복도 끝까지 보였으니까.`,
      ng:`방이 넓었다. 데우다 마력이 바닥났다. 미지근한 방에 지친 술사 하나.<br><br>
        윤곽은 반만 드러났다 다시 녹아들었다. 그 반 — 꼬리 끝이 일행 하나의 발목을 치고 사라졌다.<br>
        문을 등지고 다 같이 물러 나왔다. 방 안 어딘가에서 비치는 것이 식기를 기다리는 기척이 오래 남아 있었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-18, spirit:-19 } }
  ] },

{ at:'S', t:'태울 것이 없는 밤',
  x:`기름이 떨어졌다. 마른 나무도 없다. 젖은 뼈와 쇠와 돌 뿐인 밤.<br><br>
    맨 마력으로 세우는 불은 밑 빠진 독이다. 새벽까지 못 간다.<br>
    일행 짐을 뒤졌다. 태울 만한 것 — 여분 옷 한 벌, 기록 수첩, 그리고 죽은 동료의 나무 지팡이. 지난달에 묻은 동료 것이다. 버리지 못해 들고 다녔다.<br><br>
    어둠 가장자리에서 기척들이 불이 작아지기를 기다린다.`,
  o:[
    { l:'① 지팡이를 태운다 — 들고 다닌 건 이런 밤을 위해서였다고 믿기로 한다.', k:'steady', dc:25, wake:1,
      ok:`지팡이를 두 토막 내 불에 얹었다. 잘 마른 나무였다. 불이 환하게 올라섰다.<br><br>
        그 불로 새벽까지 갔다. 기척들은 끝내 금을 못 넘었다.<br>
        다 타고 남은 재를 아침에 한 줌 묻었다. 두 번째 장례 같았다. 아무도 뭐라 안 했다.<br><br>
        짐과 유품의 차이를 그 밤에 배웠다. 산 사람을 지키는 것은 유품이 아니라 쓰임이다. 그 동료라면 먼저 태우라 했을 것이다. 그런 사람이었다.`,
      ng:`반 토막을 얹고 반 토막은 차마 못 얹었다. 어중간한 불이 어중간하게 탔다.<br><br>
        새벽 전에 불이 잦아들었고, 기척 하나가 금을 넘어 짐을 뒤지다 쫓겨 갔다.<br>
        날이 밝고 보니 남긴 반 토막을 그놈이 물어 갔다. 유품은 결국 어둠 속 것의 이빨 자국이 됐다. 어느 쪽에게도 미안한 밤이었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-20 } },
    { l:'② 쇠를 달군다 — 타는 불 대신 달아오른 쇠로 밤을 난다.', k:'break', dc:25, cost:{ mana:33 },
      ok:`부서진 쇠창살 세 토막을 모아 벌겋게 달궜다. 불꽃은 없다. 대신 쇠는 오래 식는다.<br><br>
        달군 쇠를 삼각으로 박아 두르고 그 안에서 밤을 났다. 마력은 식을 때마다 한 번씩만 부으면 됐다. 밑 빠진 독이 아니라 아궁이가 됐다.<br>
        기척들이 불빛 없는 열 앞에서 갈피를 못 잡았다. 빛을 보고 오는 것들한테 어둠 속 열은 수수께끼다. 수수께끼는 건드리지 않는 법이다.`,
      ng:`둘째 쇠가 무쇠가 아니라 겉만 쇠인 합금이었다. 달구다 터졌다.<br><br>
        튄 조각이 정강이를 지졌다. 남은 쇠 둘로 반쪽 아궁이를 만들어 등을 벽에 대고 버텼다.<br>
        새벽까지 번갈아 눈을 붙였다. 정강이 덴 자리가 욱신거릴 때마다 잠이 깼다. 덕분에 불침번은 잘 섰다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, mind:-14 } }
  ] },

// ---------- S1 『표본실 — 착륙 이후』 ----------

{ at:'S1', t:'표본 선반 — 알코올의 방',
  x:`표본실 안쪽 방이다. 선반마다 단지, 단지마다 보존액. 코가 아리다 — 전부 독한 알코올이다.<br><br>
    방 전체가 불씨 하나면 터지는 통이다. 불 쓰는 손이 제일 조심해야 하는 방.<br>
    그런데 방 저쪽 어둠에 그것이 있다. 단지 깨진 자리에서 나온 것. 보존액을 뒤집어쓴 채 이쪽을 보고 있다.<br><br>
    젖은 저것과 이 방 — 둘 다 불 한 점이면 끝난다. 이쪽까지 셋이라는 게 문제다.`,
  o:[
    { l:'① 문까지 물러난 다음, 문턱에서 한 점을 던진다.', k:'break', dc:26, cost:{ mana:36 },
      ok:`불씨를 쥔 채 뒷걸음으로 물러났다. 그것이 따라왔다 — 보존액 발자국을 줄줄 흘리며. 제가 심지를 끌고 오는 줄도 모르고.<br><br>
        문턱을 넘자마자 그 발자국 줄에 한 점을 떨궜다. 불이 젖은 길을 거슬러 달렸다.<br>
        방이 통째로 한 번 울었다. 문짝이 등을 밀었다. 문틈으로 새어 나온 열기가 지나가고 — 조용해졌다.<br>
        방 안의 표본들에게는 미안하게 됐다. 어차피 깨어날 것들이었다고 믿기로 했다.`,
      doom:{ title:'보존액을 쓴 것', what:'표본 선반 안쪽 어둠으로 끌려 들어갑니다', dc:19, sec:42,
        text:`물러나는 발이 깨진 유리를 밟았다. 소리에 그것이 달렸다. 네 발로.<br><br>
          문턱 두 걸음 앞에서 발목이 붙들렸다. 젖은 손. 불 한 점이면 둘 다 — 방까지 셋 다 끝나는 방이라, 불을 못 쥔다.<br>
          선반 사이 어둠으로 끌려 들어간다. 보존액 냄새가 짙어진다. 빈 단지들이 지나간다. 이쪽이 들어갈 만큼 큰 단지도 하나 있었다.`,
        dieText:`방은 끝내 터지지 않았다. 그것은 제 방에서 불을 안 낸다.<br><br>
          일행은 문을 봉하고 물러났다. 문틈으로 알코올 냄새와 함께 느리게 무엇을 재우는 듯한 소리가 샜다.<br>
          표본실 단지가 하나 늘었는지는 아무도 확인하러 들어가지 않았다.`,
      } },
    { l:'② 불을 봉인한다 — 맨손과 지혜로만 지나간다.', k:'steady', dc:25,
      ok:`손끝 불을 완전히 재웠다. 불 쓰는 사람이 불을 재우는 건 무기를 거꾸로 메는 일이다.<br><br>
        대신 선반 하나를 밀어 통로를 막고, 보존액 한 통을 그것 쪽 바닥에 부어 두었다 — 저것이 미끄러지는 사이 방을 가로질렀다.<br>
        문을 닫고 나서야 불씨를 깨웠다. 손끝이 근질거렸다고, 나중에야 말했다.<br>
        불을 안 쓰는 판단도 불 쓰는 사람 기술이다. 그 방에서는 그게 전부였다.`,
      ng:`보존액 통이 미끄러져 엉뚱한 데 쏟아졌다. 이쪽 길에.<br><br>
        젖은 바닥에 이쪽 발이 미끄러지고, 그것이 그 위로 덮쳤다. 불 없이 받아 내는 수밖에 없었다.<br>
        선반 두 줄이 넘어가는 난장 끝에 문을 넘었다. 알코올에 전 옷 때문에 그날 밤 불가에도 못 앉았다. 불 쓰는 사람이.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-16 } }
  ] },

{ at:'S1', t:'통풍구의 숨 — 역류',
  x:`벽의 통풍구가 숨을 쉰다. 들이쉬고 내쉰다. 기계 소리가 아니다. 안에 사는 것들의 숨이 관을 타고 밀려오는 것이다.<br><br>
    이 구역 통풍구는 전부 한 관으로 모인다고 배관도가 말한다. 그 관 어디쯤에 둥지가 있다.<br>
    관을 타고 다니며 밤마다 하나씩 사라진다 — 벽에 그렇게 긁혀 써 있다. 먼저 온 사람들 글씨다.<br><br>
    통풍구 바람이 이쪽 냄새를 실어 나르고 있다. 둥지 쪽으로.`,
  o:[
    { l:'① 불을 바람에 태워 보낸다 — 관을 거슬러 둥지까지.', k:'break', dc:26, wake:1, cost:{ mana:40 },
      ok:`통풍구가 들이쉬는 박자에 맞춰 불을 흘려 넣었다. 빨아들이는 숨이 불을 제 집까지 데려간다.<br><br>
        한 호흡. 두 호흡. 관 깊은 데서 북 치는 소리가 연달아 울리고 — 벽 속에서 비명들이 사방으로 흩어졌다.<br>
        통풍구 숨이 멎었다. 탄내가 한 줄 흘러나왔다.<br><br>
        불은 던지는 것만이 아니다. 바람이 배달을 해 준다. 받는 주소만 정확하면. 배관도 읽는 눈이 불 쓰는 손만큼 중요해졌다.`,
      ng:`불을 넣는 박자가 내쉬는 숨과 겹쳤다. 불이 관을 거슬러 가다 되밀려 나왔다.<br><br>
        통풍구가 불을 뱉었다. 이쪽 얼굴 앞으로. 눈썹이 그을렸다.<br>
        그리고 관 전체가 성난 숨으로 울렸다. 그날 밤 통풍구란 통풍구는 다 긁는 소리를 냈다. 주소를 틀린 배달의 값이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, mind:-16 } },
    { l:'② 냄새를 끊는다 — 통풍구 앞에 탄막을 피워 이쪽 냄새를 태운다.', k:'fix', dc:25,
      ok:`통풍구 앞에 작은 화로를 즉석으로 짰다. 매캐한 것들 — 녹슨 약품 라벨, 기름걸레 — 을 태워 그 연기만 관으로 들여보냈다.<br><br>
        이쪽 냄새가 탄내에 묻혔다. 관 저쪽에서 킁킁대던 숨이 재채기 비슷한 소리를 내고는 물러갔다.<br>
        그 방에서 자는 동안 통풍구는 조용했다. 밤마다 하나씩 — 이라던 벽의 글씨 옆에, 오늘은 아무도, 라고 한 줄 보탰다.`,
      ng:`태운 연기가 역풍에 방으로 되돌아왔다. 밤새 매운 방에서 눈물로 잤다.<br><br>
        그리고 탄내는 냄새를 가리지만 소리는 못 가린다. 기침 소리가 관을 탔다.<br>
        새벽에 통풍구 덮개가 덜컹거렸다. 다 같이 깨서 쇠지레로 덮개를 눌러 버텼다. 안에서 미는 힘은 아침 빛과 함께 사라졌다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-17, spirit:-18 } }
  ] },

{ at:'S1', t:'얼굴에 뛰는 것 — 한 뼘의 불',
  x:`천장에서 그것이 떨어졌다. 손바닥만 하고 다리가 여덟. 노리는 건 얼굴이다. 숨구멍에 꼬리를 꽂고 둥지를 트는 것들 — 단지 라벨에 그렇게 적혀 있었다.<br><br>
    일행 하나의 얼굴 한 뼘 앞에서 다른 동료 손이 그것을 간신히 붙들고 있다. 다리 여덟이 그 손을 거꾸로 감아 온다.<br>
    놓치면 얼굴이다. 쥐고 있으면 손이 먼저 뚫린다.<br><br>
    불을 쓸 자리는 손과 얼굴 사이 — 한 뼘이다.`,
  o:[
    { l:'① 한 뼘 안에 불의 씨를 꽂는다 — 사람 살갗 바로 옆에서.', k:'break', dc:26, cost:{ mana:38 },
      ok:`불을 크게 만들 자리가 아니다. 겨자씨만 한 흰 불 — 제일 뜨겁고 제일 작은 불을 그것 배 한가운데 꽂았다.<br><br>
        다리 여덟이 한꺼번에 펴졌다. 움켜쥐는 것들은 속이 타면 편다.<br>
        동료 손에서 그것이 툭 떨어졌고, 바닥에서 마저 태웠다. 동료 손바닥에는 다리 자국 여덟 줄과 — 데인 자국은 없었다.<br>
        한 뼘 안의 불. 오늘 쓴 불 중에 제일 작고 제일 무거웠다.`,
      doom:{ title:'여덟 개의 다리', what:'얼굴에 그것이 들러붙었습니다', dc:20, sec:36,
        text:`흰 불이 서는 데 반 호흡이 걸렸다. 그 반 호흡에 그것이 동료 손을 박차고 — 이쪽으로 뛰었다.<br><br>
          가까운 얼굴 순이었다. 불을 들이대던 이쪽 얼굴이 제일 가까웠다.<br>
          다리 여덟이 뒤통수에서 맞물린다. 꼬리가 입가를 더듬는다. 제 얼굴에는 제 불을 못 쓴다. 숨이 뜨겁고 어둡다.`,
        dieText:`그것을 떼어 냈을 때는 꼬리가 벌써 들어간 뒤였다.<br><br>
          숨은 붙어 있었다. 그게 더 나빴다. 단지 라벨이 말한 다음 단계를 일행 모두 읽었기 때문이다.<br>
          잠들기 전에 본인이 고르게 해 줬다. 무엇을 골랐는지는 적지 않는다.`,
      } },
    { l:'② 찬 쪽을 만든다 — 얼굴 반대편에 열 미끼를 띄운다.', k:'gaze', dc:25, wake:1,
      ok:`저것이 얼굴을 노리는 건 숨 때문이다 — 따뜻하고 축축한 바람. 그렇다면 더 좋은 숨을 만들어 주면 된다.<br><br>
        손바닥 위에 사람 숨 온도의 공기 뭉치를 띄웠다. 축축하게, 후끈하게. 저것 머리가 홱 돌았다.<br>
        다리 여덟이 동료 손을 놓고 열 미끼로 뛰었다 — 허공의 숨을 문 순간 불로 바꿨다.<br><br>
        잡는 불에서 꾀는 불로. 저것들 눈에 세상이 어떻게 보이는지 알면, 불로 가짜 세상을 그려 줄 수 있다.`,
      ng:`미끼 온도가 반 도 모자랐다. 저것이 진짜와 가짜를 가렸다.<br><br>
        동료 손을 놓기는 했다 — 얼굴 쪽으로 뛰었다. 얼굴 주인이 몸을 던져 굴렀고, 그것은 빈 바닥에 떨어졌다.<br>
        바닥에서 태웠다. 모두 숨을 몰아쉬었다. 가짜 숨을 만들던 이쪽 숨이 제일 거칠었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'살균실 — 불의 방을 거꾸로 쓴다',
  x:`복도 끝 방 문패 — 살균실. 천장에 노즐이 줄지어 있고, 벽의 레버에는 소각 살균이라고 적혀 있다.<br><br>
    방 전체를 불로 채우는 방이다. 시설이 멀쩡하던 시절, 오염된 것을 넣고 태우던 방.<br>
    지금 그 방 안쪽 벽에 뚫린 구멍으로 그것들이 드나든다. 둥지와 복도 사이 지름길로 쓰는 중이다.<br><br>
    레버는 살아 있다. 비상 전원 눈금이 딱 한 번 칠 만큼 남았다.`,
  o:[
    { l:'① 지나다니는 때를 읽어 레버를 당긴다 — 방이 덫이 된다.', k:'gaze', dc:26,
      ok:`구멍 둘레의 긁힌 자국과 바닥 기름기를 읽었다. 드나드는 시간이 몰리는 때 — 교대처럼 몰려 지나는 박자가 있다.<br><br>
        그 박자에 맞춰 방 밖에서 레버를 당겼다. 노즐이 일제히 울고 문틈이 주황빛으로 샜다.<br>
        비명은 셌다. 넷 또는 다섯. 소각이 끝나고 들여다본 방은 — 깨끗했다. 문패 값을 했다.<br>
        그 지름길은 그날로 폐쇄됐다. 저쪽 사정으로.`,
      ng:`박자를 반 시간 잘못 읽었다. 레버를 당긴 방은 비어 있었다.<br><br>
        마지막 전원이 빈 방만 데웠다. 노즐이 식어 가는 소리를 들으며 서 있었다.<br>
        그리고 달궈진 방의 열기가 — 둥지의 것들을 불렀다. 저것들한테 따뜻한 방은 초대장이다. 서둘러 그 구역을 벗어났다. 덫을 놓으려다 난로를 놔 준 셈이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-16 } },
    { l:'② 전원을 아낀다 — 노즐 기름만 받아 내 불 기름으로 쓴다.', k:'fix', dc:25,
      ok:`레버 대신 노즐 배관을 땄다. 소각용 기름 — 불 쓰는 사람한테는 보물이다. 통 두 개를 받았다.<br><br>
        그 기름이면 열 밤 치 불의 금이다. 방 하나 태우는 것보다 길게 쓰는 셈법.<br>
        나오는 길에 구멍 둘레에 그 기름을 한 줄 발라 두었다. 다음에 지나는 놈 발에 묻을 것이다. 불 쓰는 사람 근처에서 발에 기름을 묻히고 다니는 건 — 저쪽 사정이 될 것이다.`,
      ng:`배관을 따다 압력을 잘못 건드렸다. 기름이 뿜어져 이쪽이 뒤집어썼다.<br><br>
        불 쓰는 사람이 기름에 전 채로는 제 불도 못 쓴다. 벗고 닦는 반나절 동안 불꽃 한 점 못 올렸다.<br>
        받은 기름은 한 통. 뒤집어쓴 기름이 반 통. 셈은 맞는데 꼴이 말이 아니었다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-25, spirit:-15 } }
  ] },

{ at:'S1', t:'여왕의 온도',
  x:`아래층으로 내려갈수록 더워진다. 벽이 미지근하다. 시설 보일러는 죽은 지 오래인데.<br><br>
    이 열은 여왕의 것이다. 알들을 품는 방이 시설 심장부에 있고, 그 온기가 건물 뼈대를 타고 오르는 것이다.<br>
    문제는 저것들이 열로 길을 찾는다는 점이다. 이쪽 체온도, 손끝 불도 — 여왕의 온도 안에서는 전부 두드러진다.<br>
    여기서 불 쓰는 사람은 등불이 아니라 봉화다.`,
  o:[
    { l:'① 체온을 벽에 맞춘다 — 일행 다섯의 겉온도를 벽 온도로 입힌다.', k:'break', dc:26, wake:1, cost:{ mana:40 },
      ok:`다섯 사람 겉에 얇은 열막을 입혔다. 벽과 같은 온도의 막. 속은 사람 온도, 겉은 건물 온도.<br><br>
        열로 보는 저것들 눈에 일행은 벽이 걸어 다니는 것처럼 — 아니, 아예 안 보였을 것이다. 순찰 도는 것 둘과 복도에서 마주 지나쳤다. 저것들은 비켜 주기까지 했다. 벽끼리는 안 부딪치는 법이니까.<br><br>
        불로 숨는 법을 배웠다. 불은 드러내는 것인 줄만 알았다. 열막을 입히는 손놀림이 밤새 손끝에 남았다.`,
      ng:`넷까지는 입혔다. 다섯째 막이 반쯤에서 마력이 떨렸다.<br><br>
        복도에서 마주친 순찰 것이 그 다섯째 앞에서 멈췄다. 반쪽만 벽인 것을 보는 눈.<br>
        싸움이 났다. 짧게 끝냈지만 소리는 퍼졌다. 그 구역을 뛰어서 벗어나는 동안 등 뒤 복도가 계속 더워졌다. 몰려오는 체온들로.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 가짜 봉화 — 멀리 빈 방 하나를 여왕 온도보다 뜨겁게 달군다.', k:'break', dc:26,
      doom:{ title:'온도를 지키는 것들', what:'뜨거운 아래층으로 끌려 내려갑니다', dc:20, sec:38,
        text:`빈 방이 달아오르자 복도의 것들이 그리로 몰렸다 — 계산대로. 계산 밖은, 여왕 온도보다 뜨거운 것을 저것들이 침입이 아니라 도전으로 읽는다는 것.<br><br>
          도전자를 찾아 거슬러 온 큰 놈 둘이 열 자국을 따라 — 이쪽 손끝까지 왔다.<br>
          양팔이 각각 물렸다. 들린다. 아래로. 계단이 아니라 뚫린 바닥 구멍으로. 더운 바람이 밑에서 올라온다. 여왕의 방은 생각보다 가까웠다.`,
        dieText:`아래층에서 올라오던 온기가 그날 밤 잠깐 더 뜨거워졌다.<br><br>
          일행은 그 뜻을 생각하지 않기로 했다. 생각하면 걸을 수 없는 뜻이었다.<br>
          남은 넷은 체온을 죽이는 쪽을 골랐다. 불 쓰는 사람 없이 열막도 없이 — 찬 물에 젖은 담요를 쓰고 기어서 그 층을 지났다.`,
      },
      ok:`비상 전원이 남은 빈 방 하나를 골라 전열판을 터뜨리듯 달궜다. 여왕 온도보다 반 도만 높게 — 도전이 아니라 고장으로 보이게.<br><br>
        복도의 것들이 고장 난 열을 살피러 몰려갔다. 열로 보는 것들은 열이 이상하면 못 참는다.<br>
        빈 길로 그 층을 다 건넜다. 등 뒤에서 저것들이 빈 방 전열판을 두드리는 소리가 오래 났다. 수리반 노릇은 오늘 밤 내내 하게 될 것이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S1', t:'산성 안개 — 녹는 공기',
  x:`아래층 복도에 안개가 깔려 있다. 흰 안개가 아니다. 노랗다. 벽 아래쪽 페인트가 안개 높이까지 벗겨져 있다.<br><br>
    죽은 큰 놈의 피가 웅덩이째 증발하며 만든 안개다. 숨으로 마시면 폐가 — 생각을 멈췄다.<br>
    안개는 무릎 높이. 기면 못 지나고, 서서 걸으면 발이 안 보인다. 발밑에 뭐가 사는지도.<br><br>
    안개 밑에서 무언가 첨벙거리는 소리가 났다. 녹는 공기 속에서 사는 것도 있다.`,
  o:[
    { l:'① 열로 안개를 가른다 — 홍해처럼, 지나는 동안만.', k:'break', dc:26, cost:{ mana:37 },
      ok:`안개 한가운데에 열의 벽 두 장을 세웠다. 뜨거운 공기가 오르며 노란 안개를 양쪽으로 밀어 올렸다.<br><br>
        바닥까지 보이는 맨길이 복도 폭 절반으로 열렸다. 발밑에 살던 것들 — 손가락만 한 벌레 떼 — 이 열을 피해 안개째 물러났다.<br>
        일행이 맨길로 건넜다. 마지막 사람 뒤에서 열벽을 거뒀다. 안개가 제자리로 닫히는 소리는, 커튼 치는 소리와 비슷했다.`,
      ng:`열벽 한 장이 중간에서 주저앉았다. 밀려 올라갔던 안개가 그쪽으로 쏟아져 내렸다.<br><br>
        뒷줄 둘이 노란 것을 한 모금씩 마셨다. 기침이 피 맛이 난다고 했다.<br>
        나머지 길은 젖은 천으로 입을 막고 뛰었다. 두 사람 기침은 사흘 갔다. 열벽은 두 장 다 설 때만 벽이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 바람을 만든다 — 복도 끝까지 안개를 통째로 밀어 치운다.', k:'fix', dc:25,
      ok:`복도 이쪽 끝 공기를 크게 데웠다. 더운 공기가 흐르며 복도에 바람이 섰다. 한 방향으로.<br><br>
        노란 안개가 바람에 밀려 복도 저쪽 계단 아래로 흘러 내려갔다. 폐수 버리듯.<br>
        마른 복도를 걸어 건넜다. 계단 아래쪽에서 첨벙대던 것들이 안개를 따라 내려가는 소리가 들렸다. 제 세간 따라 이사 가는 것이다. 잘 가라.`,
      ng:`바람이 서다 말았다. 복도 중간쯤 안개가 소용돌이로 뭉쳤다.<br><br>
        뭉친 노란 기둥이 이쪽으로 천천히 밀려왔다. 바람을 거꾸로 맞은 것이다.<br>
        왔던 길로 물러나 반나절을 돌았다. 돌아가는 길 내내 목이 칼칼했다. 반 모금쯤은 마신 모양이었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S1', t:'알 방 — 품는 온기 흉내',
  x:`지나야 하는 방이 하필 알 방이다. 벽이고 바닥이고 주먹만 한 알집이 다닥다닥하다.<br><br>
    알집들이 일제히 같은 박자로 오르내린다. 방 전체가 숨 쉬듯. 방 한가운데 온기 기둥 — 여왕의 온기가 지나는 배관 — 이 그 박자를 정해 주고 있다.<br>
    온기가 흔들리면 알들이 깬다. 차가운 것이 지나가도 깬다.<br>
    이 방에서 다섯 사람은 다섯 개의 찬 바람이다.`,
  o:[
    { l:'① 배관의 박자를 읽어, 다섯 몸을 그 온기로 감싸 지난다.', k:'break', dc:26, wake:1, cost:{ mana:39 },
      ok:`배관 온기의 박자 — 둥, 하고 더워졌다 반 호흡 식는 결 — 을 읽어, 같은 박자로 뛰는 열막을 다섯에게 입혔다.<br><br>
        알집들 사이를 지나는 다섯은 알집들한테 여왕 온기의 일부였다. 방이 다섯 덩이 온기를 제 숨으로 받아들였다.<br>
        방을 다 건너 열막을 거둘 때까지 알 하나 안 깼다.<br><br>
        남의 심장 박자로 불을 뛰게 하는 법 — 제일 어려운 불이었다. 손끝이 아직 그 박자로 뛴다.`,
      ng:`박자는 맞았는데 넷째 열막이 반 호흡 어긋났다. 방 전체의 숨이 한순간 멈칫했다.<br><br>
        가장 가까운 알집 세 개가 깨어 터졌다. 갓 깬 것들은 작고 느렸다 — 그게 전부였던 건, 이쪽이 쉬지 않고 뛰었기 때문이다.<br>
        방 반대쪽 문을 닫을 때 뒤에서 방 전체가 깨어나는 소리가 시작됐다. 반 호흡 값으로는 컸다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 배관을 먼저 지난다 — 온기 기둥 바로 밑, 제일 더운 길로.', k:'hide', dc:25,
      ok:`제일 더운 자리는 배관 바로 밑이다. 찬 바람 다섯이 숨기에는 그 그늘 — 아니, 그 양지가 제일이다.<br><br>
        배관 밑에 바짝 붙어 한 줄로 지났다. 땀이 비 오듯 했지만 알집들은 다섯 체온을 배관 온기로 읽었다.<br>
        문턱을 넘으며 돌아본 방은 여전히 한 박자로 숨 쉬고 있었다. 모르고 자는 방. 그대로 두고 왔다.`,
      ng:`배관 밑 한가운데서 땀에 전 등짐이 미끄러져 떨어졌다. 알집 하나 위로.<br><br>
        눌린 알집이 울었다. 주변 알집들이 박자를 흩뜨리며 꿈틀댔다.<br>
        등짐을 버려 두고 남은 반을 뛰었다. 방이 반쯤 깨어났지만 갓 깬 것들 걸음보다 이쪽 걸음이 빨랐다. 등짐 속 사흘 치 식량은 저 방의 첫 끼니가 됐을 것이다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-17, spirit:-19 } }
  ] },

// ---------- S2 『백악기 정원』 ----------

{ at:'S2', t:'젖은 정원 — 불이 모르는 땅',
  x:`정원은 온통 젖어 있다. 스프링클러가 고장 난 채 백 년째 비를 뿌리는 땅. 마른 장작 같은 건 없다.<br><br>
    고사리는 젖어서 안 타고, 이끼는 물을 머금어 김만 낸다. 불 쓰는 사람한테 이 정원은 통째로 적지다.<br>
    그런데 풀숲의 것들은 불을 모른다. 수십 년 동안 이 안에서 불이란 걸 본 적이 없는 짐승들이다.<br><br>
    불을 모르는 것들 앞에서 첫 불을 어떻게 보여 주느냐 — 그게 앞으로 이 정원 전체의 규칙이 된다.`,
  o:[
    { l:'① 첫 불을 크게 보여 준다 — 무리 앞에서 마른 덤불 하나를 통째로.', k:'break', dc:26, wake:1, cost:{ mana:38 },
      ok:`담장 안쪽 처마 밑 — 정원에서 유일하게 마른 덤불을 아껴 뒀다가, 무리가 담장을 시험하러 모인 저녁에 통째로 세웠다.<br><br>
        불기둥이 빗속에 섰다. 불을 처음 보는 것들이 일제히 굳었다. 타닥거리는 소리, 열, 빛 — 저것들 몸속 아주 오래된 기억이 깨어나는 게 보였다. 하늘에서 떨어지던 불의 기억.<br>
        무리가 물러났다. 그날부터 이 정원에서 불꽃 한 점은 백 마디 경고였다.<br><br>
        첫인상은 못 고친다. 그래서 첫 불에 전부를 걸었다. 걸 줄 아는 게 기술이다.`,
      ng:`덤불이 겉만 마르고 속이 젖어 있었다. 불기둥이 서다 말고 — 피시식, 연기만 토했다.<br><br>
        불을 처음 본 것들이 고개를 갸웃하더니, 한 놈이 다가와 연기 나는 덤불을 발로 쳐 봤다. 그리고 아무 일도 없자 — 기억했다. 불이란 건 별것 아니라고.<br>
        최악의 첫인상이었다. 이 정원에서 불의 금은 한동안 반값이 됐다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 첫 불을 아낀다 — 보여 주지 않고, 필요한 밤을 위해 숨겨 둔다.', k:'steady', dc:24,
      ok:`불을 안 보여 줬다. 젖은 정원에서 불 쓰는 사람이라는 패는 한 번 까면 끝이다.<br><br>
        대신 손끝 온기로 젖은 이끼 밑 마른 심 — 쓰러진 고목 속살 — 을 찾아 조금씩 모았다. 품 안에 마른 것 한 꾸러미.<br>
        무리는 일행을 그냥 느린 짐승 다섯으로 셈하고 있다. 그 셈이 틀렸다는 걸 알게 되는 밤은 — 이쪽이 고른다.<br>
        패는 숨길수록 비싸진다. 품속 꾸러미가 든든했다.`,
      ng:`마른 심을 찾느라 고목을 쪼개는 소리가 너무 컸다. 무리 하나가 소리를 듣고 왔다.<br><br>
        불 없이 쫓느라 일행 전원이 비에 젖은 채 창을 들었다. 놈은 간을 보고 물러갔다.<br>
        모은 마른 것은 반 꾸러미. 소리 값으로 반을 치렀다. 젖은 정원은 소리마저 적 편이었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'S2', t:'물 위의 불 — 기름막',
  x:`물에 잠긴 고사리밭. 건너야 한다. 수면 밑에서 등줄기들이 금을 그으며 돈다. 하나가 아니다.<br><br>
    물가에 뒤집힌 관리선 — 작은 보트 — 이 반쯤 묻혀 있다. 연료통이 아직 달려 있다. 흔들어 보니 반 통.<br>
    기름은 물에 뜬다. 그리고 뜬 기름은 — 탄다.<br><br>
    물 밑 것들 위에 불의 천장을 깔 수 있다. 딱 반 통 어치만.`,
  o:[
    { l:'① 건널 물길에만 기름을 흘려 띄우고, 건너며 등 뒤로 불을 깐다.', k:'break', dc:26, cost:{ mana:36 },
      ok:`물길 폭만큼 기름을 띄웠다. 무지개막이 수면에 섰다. 일행이 허리 물을 가르며 건너기 시작했다.<br><br>
        등줄기 하나가 속도를 올려 따라붙는 순간 — 등 뒤 기름막에 불을 깔았다. 수면이 불의 천장이 됐다.<br>
        물 밑 것들한테 머리 위가 불이 된 세상은 처음이었을 것이다. 등줄기들이 물밑 깊이 가라앉아 흩어졌다.<br>
        마지막 사람이 마른 땅을 밟을 때까지 수면이 탔다. 불 밑으로는 아무것도 안 올라왔다.`,
      doom:{ title:'물밑의 등줄기', what:'검은 물 밑으로 끌려 들어갑니다', dc:19, sec:38,
        text:`기름이 물살에 밀려 비스듬히 흘렀다. 불을 깔자 물길 반만 천장이 서고 — 반은 뚫렸다.<br><br>
          뚫린 쪽을 막아서던 이쪽 허리를 등줄기가 감았다. 이빨이 아니라 몸통째.<br>
          물이 머리를 덮는다. 바로 위에서 제가 깐 불의 천장이 주황빛으로 일렁인다. 불 밑의 물속 — 불 쓰는 사람이 있을 자리 중 제일 나쁜 자리로 가라앉는다.`,
        dieText:`수면의 불이 다 타고 꺼질 때까지 물밑에서는 아무것도 올라오지 않았다.<br><br>
          기름막이 걷힌 물은 아무 일 없다는 듯 검었다. 일행은 남은 물길을 말없이 건넜다.<br>
          건너편에서 누군가 물 위에 마른 불씨 하나를 띄워 보냈다. 흘러가다 꺼졌다. 그런 배웅도 있다.`,
      } },
    { l:'② 기름을 아껴 두고, 얕은 물길을 찾아 돌아간다.', k:'sense', dc:25,
      ok:`수면 색을 읽었다. 짙은 데가 깊고 고사리가 성긴 데가 얕다. 무릎 물로만 이어지는 갈지자 길이 보였다.<br><br>
        무릎 물에서는 등줄기들이 못 논다. 배가 긁히는 깊이다.<br>
        갈지자로 멀리 돌아 건넜다. 기름 반 통은 고스란히 등에 멨다. 이 정원에서 기름 반 통은 — 두고두고 쓸 패다.<br>
        깊은 물 쪽에서 등줄기들이 아쉽게 금을 긋는 걸 끝까지 봤다. 오늘은 셈이 안 맞았을 것이다, 저쪽.`,
      ng:`얕은 길이 중간에 끊겼다. 지도에 없던 물구덩이 — 옛 연못 자리다.<br><br>
        허리까지 빠지는 구간을 두 걸음 — 그 두 걸음에 등줄기 하나가 번개처럼 왔다.<br>
        기름통을 방패처럼 내밀었다. 이빨이 통을 물고 흔들었다. 통을 내주고 몸을 뺐다. 기름 반 통이 물 밑으로 사라졌다. 아껴 둔 패를 물고기가 먹었다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S2', t:'큰 것과 연기 기둥',
  x:`큰 것이 이쪽 방향으로 온다. 아직 멀다 — 물결 가락지가 반 뼘일 때 소리가 닿는 거리. 하지만 길이 겹친다. 이대로면 백 걸음 앞에서 만난다.<br><br>
    숨을 데가 없다. 이 구역은 허리 높이 고사리뿐이다. 큰 것 눈높이에서 다섯 사람은 접시 위 콩이다.<br>
    바람이 이쪽에서 저쪽으로 분다.<br><br>
    접시 위 콩이 할 수 있는 일 — 접시에 다른 볼거리를 놓는 것뿐이다.`,
  o:[
    { l:'① 연기 기둥을 멀리 세운다 — 젖은 이끼 더미를 한 무더기 태워서.', k:'break', dc:26, cost:{ mana:35 },
      ok:`길 밖 멀리 젖은 이끼 둔덕에 불을 박았다. 젖은 것은 불꽃 대신 연기를 낸다 — 굵고 흰 기둥이 하늘로 섰다.<br><br>
        큰 것이 멈췄다. 저 크기가 되도록 살아남은 짐승은 모르는 것을 먼저 살피러 간다.<br>
        기둥 쪽으로 돌아서는 큰 것의 걸음이 땅을 울렸다. 멀어지는 울림이었다.<br>
        연기가 다 삭기 전에 겹치던 길을 벗어났다. 콩은 접시에서 무사히 굴러 내려왔다.`,
      ng:`젖은 이끼가 생각보다 더 젖어 있었다. 연기가 서다 말고 흩어졌다.<br><br>
        큰 것은 멈추지 않았다. 길이 겹치기 전에 이쪽이 길을 버리고 가시덤불로 들어가는 수밖에 없었다.<br>
        덤불에서 큰 것이 지나가기를 기다린 한나절 — 가시에 긁힌 자리가 스물몇 군데. 콩 신세도 서러운데 고슴도치 꼴까지 됐다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 바람을 거슬러 비킨다 — 냄새가 앞서 가지 않는 쪽으로.', k:'evade', dc:25,
      ok:`바람이 이쪽 냄새를 큰 것한테 실어 나르는 중이다. 길을 버리고 바람을 마주 보는 쪽으로 꺾었다.<br><br>
        냄새가 등 뒤로 흐르자 큰 것 콧등이 길 위에서 갈피를 잃었다. 방금까지 있던 냄새가 끊긴 자리.<br>
        큰 것은 한참 코를 땅에 대고 돌다가 제 갈 길로 갔다. 이쪽은 바람 속에 서서 그 등성이 같은 등이 멀어지는 걸 봤다.<br>
        불 없이 넘긴 판이었다. 불 쓰는 사람도 바람부터 읽어야 한다는 걸 — 연기가 아니라 몸으로 배웠다.`,
      ng:`바람이 변덕을 부렸다. 꺾은 방향으로 한 번 크게 되불었다.<br><br>
        냄새 다발이 통째로 큰 것 콧등에 닿는 게 보이는 듯했다. 고개가 이쪽으로 돌았다.<br>
        전원이 엎드려 진흙에 몸을 발랐다. 큰 것이 백 걸음 거리까지 와 코를 땅에 대고 — 진흙 냄새만 맡고 돌아갔다. 엎드린 채 아무도 반나절을 못 일어났다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S2', t:'무리의 눈 — 불을 배우는 중',
  x:`담장 무리가 요즘 불의 금에서 물러나는 거리가 짧아졌다. 처음엔 백 걸음, 지난밤엔 서른 걸음.<br><br>
    저것들이 배우는 중이다. 불이 닿는 금, 불이 식는 시간, 불 쓰는 사람이 지치는 박자까지.<br>
    오늘 밤 금 밖에 셋이 앉아 있다. 가운데 놈은 아예 턱을 땅에 괴고 — 구경하는 자세다.<br><br>
    배우는 것들한테는 교과서를 바꿔 줘야 한다.`,
  o:[
    { l:'① 오늘 밤 불은 어제와 다르게 — 금을 당겼다 늦췄다, 규칙을 없앤다.', k:'break', dc:26, wake:1, cost:{ mana:37 },
      ok:`불의 금을 숨 쉬게 했다. 넓어졌다 좁아졌다, 꺼질 듯하다 벌컥 일어서게. 박자 없이. 이쪽도 모르는 박자로 — 주사위를 굴려 가며.<br><br>
        구경하던 셋의 자세가 밤새 무너졌다. 외울 수 없는 것 앞에서 배우는 짐승은 지친다.<br>
        새벽에 셋이 일어나 돌아갔다. 수업을 포기한 걸음이었다.<br><br>
        규칙 없는 불은 불 쓰는 쪽도 피곤하다. 하지만 외워지는 불은 이미 불이 아니다. 금은 살아 있어야 금이다.`,
      ng:`박자를 없앤다는 게 쉽지 않았다. 새벽녘 이쪽 손이 지치자 불이 제 편한 박자로 돌아갔다.<br><br>
        그 박자를 기다린 가운데 놈이 금이 좁아지는 호흡에 맞춰 — 들어왔다 나갔다. 시험 답안을 맞춰 보듯.<br>
        물린 사람은 없었다. 하지만 저것은 답을 알았다는 걸 이쪽도 알았다. 다음 밤부터 불침번이 배로 늘었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-19, spirit:-16 } },
    { l:'② 구경꾼 가운데 놈에게만 — 금 밖까지 닿는 불화살 한 발을 가르친다.', k:'break', dc:26,
      doom:{ title:'배운 것들', what:'어둠 속 무리에게 물려 가 수풀로 끌려갑니다', dc:20, sec:37,
        text:`불화살이 가운데 놈 앞 땅에 박혔다. 경고로는 완벽했다 — 저것들이 경고를 경고로 받는 짐승이었다면.<br><br>
          셋이 흩어졌다. 도망이 아니라 — 산개. 불화살이 한 번에 한 발이라는 걸 셋이 동시에 배운 것이다.<br>
          두 번째 화살을 재우기 전에 왼쪽 놈이 금을 뚫었다. 이빨이 어깨에 닿고, 몸이 들리고, 금의 불빛이 뒤로 멀어진다. 마지막으로 보인 건 남은 둘이 금 안 일행을 묶어 두는 광경이었다. 분업까지 배웠다.`,
        dieText:`불의 금은 밤새 탔다. 주인 없이.<br><br>
          새벽에 금이 식자 셋이 와서 식은 재를 코로 뒤적이고 갔다. 복습이었다.<br>
          일행은 그날로 야영 규칙을 바꿨다. 불은 금이 아니라 미끼로만 쓴다 — 불 쓰는 사람의 빈자리가 정한 규칙이었다.`,
      },
      ok:`불화살을 가운데 놈 턱 바로 앞 — 괸 턱 밑의 땅에 박았다. 수염이 그을리는 거리.<br><br>
        놈이 뒤로 자빠지듯 물러났다. 금 밖도 금이라는 수업.<br>
        셋이 어둠으로 물러났다. 서른 걸음이 아니라 소리가 안 닿는 데까지.<br>
        교과서 개정판은 한 발이면 충분했다. 그 한 발을 아무 때나 쏘지 않는 것까지가 개정판이다.`,
      win:{ exp:23, dream:3 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 젖은 전선',
  x:`정원을 나가는 낡은 엘리베이터. 비상 권양기는 녹아 떨어져 나갔고, 남은 건 전동기뿐이다.<br><br>
    전동기는 돌 수 있다 — 배선함 눈금이 산다. 문제는 배선이다. 백 년 묵은 전선이 반은 젖고 반은 삭았다. 이대로 전원을 올리면 승강로가 통째로 불꽃놀이다.<br>
    젖은 구간을 말리고 삭은 구간을 잇는 일 — 열을 다루는 손이 할 일이다.<br><br>
    수풀에서 쇠 냄새를 맡은 기척들이 모여들기 시작했다. 시간은 저쪽 편이다.`,
  o:[
    { l:'① 전선을 따라 손끝 열로 한 뼘씩 말린다 — 태우지 않고, 꼭 말리기만.', k:'break', dc:26, wake:1, cost:{ mana:40 },
      ok:`물기가 증발하는 온도와 피복이 타는 온도 사이 — 그 좁은 틈의 열을 손끝에 쥐고 전선을 훑었다. 한 뼘, 한 뼘.<br><br>
        스무 뼘째에서 수풀 첫 놈이 나왔다. 손은 전선에서 안 뗐다. 일행이 창으로 시간을 사는 소리를 등으로 들으며 — 마지막 뼘.<br>
        전원이 올라갔다. 전동기가 백 년 만에 기침을 하고 돌았다. 승강기가 떠오르는 바닥 밑으로 발톱들이 긁고 지나갔다.<br><br>
        제일 급한 순간에 제일 느린 열을 쥐는 것 — 불 다루는 손의 끝판이 그것이었다.`,
      ng:`열아홉 뼘까지는 완벽했다. 스무 뼘째에서 수풀이 터지는 소리에 손끝이 반 도 흔들렸다.<br><br>
        피복에 불이 붙었다. 한 뼘 태우고 껐다 — 그 한 뼘을 삭은 예비선으로 잇느라 또 한참.<br>
        승강기는 떴다. 반 층 오르다 한 번 덜컥 멎었다 다시 올랐다. 그 덜컥, 에 다섯 심장도 같이 멎었다 뛰었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 말릴 시간이 없다 — 젖은 구간을 끊어 내고 마른 선끼리 바로 잇는다.', k:'fix', dc:25,
      ok:`젖은 구간을 통째로 포기했다. 끊고, 마른 토막끼리 당겨 잇고, 모자라는 길이는 창날 쇠를 덧대 때웠다.<br><br>
        누더기 배선이지만 전기는 길만 있으면 간다. 전원이 올라가고 전동기가 돌았다.<br>
        딱 한 번 오를 만큼만 버텨 달라고 빌었다. 버텼다. 위층 문턱에 닿는 순간 어디선가 퍽, 하고 눈금이 죽었다.<br>
        뒤는 없다. 뒤가 없어도 되는 때를 골라 쓰는 게 누더기의 쓰임이다.`,
      ng:`이은 자리 하나가 무게를 못 버텼다. 반 층에서 불꽃이 튀고 전동기가 멎었다.<br><br>
        허공에 매달린 승강기. 밑에서 기척들이 모이는 소리.<br>
        창살 문을 열고 위층 문턱까지 사람 사다리로 기어올랐다. 마지막 사람이 올라온 창살을 — 밑에서 뛰어오른 것이 물고 흔드는 걸 다 같이 내려다봤다. 반 층이 이렇게 먼 거리인 줄 몰랐다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S2', t:'둥지의 밤 — 온기 도둑',
  x:`비가 억수로 쏟아지는 밤. 피할 데가 하필 — 빈 둥지다. 진흙과 가지로 지은 지붕 있는 둥지. 주인은 사냥을 나간 모양이다.<br><br>
    둥지 안쪽에 알이 셋. 따뜻하다. 주인이 돌아올 둥지라는 뜻이다.<br>
    밖은 번개와 물벼락. 안은 알 셋과 남의 온기.<br>
    주인이 비를 뚫고 돌아오기 전에 비가 그치기를 비는 것 말고 — 불 쓰는 손이 할 수 있는 일이 있을 것이다.`,
  o:[
    { l:'① 알의 온기를 그대로 지킨다 — 이쪽 열로 알을 품으며 밤을 난다.', k:'steady', dc:25, wake:1,
      ok:`비에 식어 가는 알 셋에 손바닥 열을 나눠 줬다. 주인이 품는 온도 그대로 — 아까 만졌을 때의 온도를 손이 기억했다.<br><br>
        새벽에 주인이 돌아왔다. 둥지 앞에서 — 멈췄다. 코를 들이밀고 알을 살폈다. 따뜻하다. 제 온도로.<br>
        일행은 둥지 뒤편으로 빠져나가는 중이었다. 주인은 쫓아오지 않았다. 알이 식지 않은 둥지에서는 급할 게 없는 것이다.<br><br>
        빌린 지붕 값을 온기로 치렀다. 셈이 통하는 상대가 아닌데 셈이 통했다. 그런 밤도 있다.`,
      ng:`셋째 알에 준 열이 반 도 넘쳤다. 알이 — 울기 시작했다. 안에서. 예정보다 이른 울음.<br><br>
        그 울음이 빗소리를 뚫었다. 주인의 대답이 생각보다 가까운 데서 왔다.<br>
        빗속으로 뛰어나와 밤새 걸었다. 뒤에서 둥지 쪽 수풀이 갈라지는 소리. 쫓는 소리가 아니라 돌아가는 소리였던 걸 한참 뒤에야 알았다. 젖은 밤길 반나절이 벌이었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 둥지 밖 가짜 온기 — 주인 돌아오는 길목에 따뜻한 바위를 만들어 둔다.', k:'break', dc:26, cost:{ mana:34 },
      ok:`길목 바위 하나를 짐승 체온으로 데워 뒀다. 빗속에서 김이 모락모락 — 다친 먹이처럼 보이는 온기.<br><br>
        돌아오던 주인이 바위 앞에 멈춰 코를 대고 한참 수색했다. 그 한참 동안 일행은 둥지에서 빠져나와 반대쪽 어둠으로.<br>
        주인은 끝내 바위의 정체를 못 풀었을 것이다. 세상에는 따뜻한 바위도 있다고 치고 살아갈 것이다. 그 정도 거짓말은 서로 눈감아 주기로 했다.`,
      ng:`빗줄기가 바위를 너무 빨리 식혔다. 주인이 길목을 그냥 지나쳐 — 둥지로 직행했다.<br><br>
        둥지 반대편 벽을 뚫다시피 빠져나왔다. 가지와 진흙을 뒤집어쓴 채.<br>
        등 뒤에서 주인이 둥지 안 낯선 냄새에 우는 소리가 길게 울렸다. 밤새 추적을 따돌리느라 비보다 땀에 더 젖었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-27, mind:-15 } }
  ] },

{ at:'S2', t:'마지막 성냥 — 엘리베이터 앞 공터',
  x:`낡은 엘리베이터가 보이는 마지막 공터. 그리고 무리가 그 앞을 안다. 나가는 것들이 꼭 거치는 자리라는 걸.<br><br>
    여섯이 공터를 반원으로 막고 있다. 여태 본 무리 중 제일 많다. 마지막 길목에는 제일 큰 판돈이 걸리는 법이다.<br>
    이쪽 마력은 바닥이 보인다. 크게 한 번 — 그게 전부다.<br><br>
    한 번으로 여섯을 쫓거나, 못 쫓거나.`,
  o:[
    { l:'① 여섯 한가운데가 아니라 — 여섯 발밑의 마른 뿌리층을 태운다.', k:'break', dc:26, cost:{ mana:40 },
      ok:`공터 흙 밑 — 백 년 묵은 고사리 뿌리층은 지붕 밑이라 말라 있다. 남은 마력을 전부 땅속 한 뼘 깊이에 부었다.<br><br>
        여섯 발밑에서 땅이 연기를 올리며 갈라졌다. 발바닥이 뜨거워지는 공포는 눈앞의 불과 다르다 — 피할 방향이 없다.<br>
        여섯이 사방으로 흩어졌다. 반원이 무너진 가운데로 일행이 내달렸다.<br>
        승강기 창살 문이 닫힐 때까지 아무것도 못 따라붙었다. 땅은 한나절 더 연기를 냈다고 한다. 좋은 배웅이었다.`,
      ng:`뿌리층이 생각보다 깊었다. 마력이 땅속에서 길을 잃었다.<br><br>
        연기 몇 줄만 올라왔다. 여섯은 콧방귀도 안 뀌었다.<br>
        빈손이 된 불 쓰는 사람과 창 넷으로 공터를 뚫었다. 둘이 물리고 하나가 밟혔다. 다 승강기에 탔다는 것만이 그 판의 유일한 자랑이다.`,
      win:{ exp:24, dream:4 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 한 번을 아예 안 쓴다 — 동트기를 기다려, 저것들 교대 시간에 지난다.', k:'sense', dc:25,
      ok:`무리에도 밤낮이 있다. 사흘을 지켜본 일행 기록에 — 동틀 녘 여섯이 넷이 되는 반 시진이 있었다.<br><br>
        그 반 시진에 공터를 가로질렀다. 넷은 졸음과 교대 인수인계에 바빴다.<br>
        승강기가 뜨는 소리에 넷이 달려왔지만 창살 너머였다. 마지막 마력 한 줌은 — 쓰지 않은 채 가지고 나왔다.<br>
        쓰지 않은 불이 제일 싼 불이다. 장부 마지막 줄에 그렇게 적었다.`,
      ng:`교대 시간이 하필 그날 어긋났다. 무리 쪽에도 변덕이 있었다.<br><br>
        공터 한가운데서 여섯과 마주쳤다. 마지막 마력으로 불벽 한 장 — 반 호흡짜리 — 을 세워 거리를 벌고 내달렸다.<br>
        승강기 문이 닫히는 틈으로 발톱 하나가 들어와 바닥을 긁고 빠졌다. 그 긁힌 자국을 다들 한참 내려다봤다. 반 호흡이 가른 자국이었다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-28, spirit:-16 } }
  ] }

]);

// ------------------------------------------
// 권사 · 내공
// ------------------------------------------
kJob('fist', 'S', [

{ at:'S', t:'껍질 — 주먹이 묻는 것',
  x:`한 대 쳤다. 제대로 들어간 주먹이었다. 놈은 반 걸음 밀렸을 뿐이다.<br><br>
    주먹이 먼저 안다 — 이건 껍질이다. 통짜 껍질. 두드려서 깨지는 종류가 아니다.<br>
    놈이 고개를 갸웃한다. 방금 그게 공격이었느냐는 투다.<br><br>
    하지만 통짜로 움직이는 몸은 없다. 움직이려면 틈이 있어야 한다. 틈은 접히는 데 있다.`,
  o:[
    { l:'① 접히는 데를 친다 — 놈이 디디는 순간, 뒷무릎 안쪽.', k:'break', dc:25, cost:{ qi:30 },
      ok:`놈이 앞발을 디디는 순간 뒷무릎이 접혔다. 접히는 껍질 틈 — 그 안쪽에 반 뼘 주먹을 꽂았다.<br><br>
        껍질 안에서 무엇이 어긋나는 느낌이 주먹으로 전해졌다. 놈이 주저앉았다. 세 발로 일어나려다 다시 주저앉았다.<br>
        마무리는 일행 창이 했다. 주먹은 틈을 여는 데까지다.<br><br>
        껍질은 두드리는 게 아니라 접어서 여는 것이다. 손등이 그 각도를 외웠다.`,
      ng:`무릎을 노리는 걸 놈이 알았다. 디디는 척 — 디디지 않았다.<br><br>
        허공을 친 주먹 위로 꼬리가 떨어졌다. 어깨로 받으며 굴렀다.<br>
        어깨가 한동안 들리지 않았다. 접히는 데를 아는 놈은 제 접히는 데도 지킬 줄 안다.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 치지 않는다 — 민다. 통짜 몸을 통째로 비탈로.', k:'break', dc:26,
      ok:`껍질에 주먹이 안 들어가면 껍질째 옮기면 된다. 놈이 덮치는 힘을 어깨로 받아 흘리며 — 방향만 보탰다.<br><br>
        통짜 몸이 제 무게에 밀려 비탈 아래 배수구로 미끄러졌다. 껍질이 쇠 바닥을 긁는 소리가 길게 내려갔다.<br>
        올라오는 데 한참 걸릴 비탈이다. 그 한참이면 충분했다.`,
      ng:`미는 각이 반 뼘 얕았다. 놈이 비탈 끝에 발톱을 걸고 버텼다.<br><br>
        버틴 놈과 민 이쪽이 비탈 가장자리에서 엉겼다. 같이 구를 뻔한 걸 일행이 허리를 잡아 세웠다.<br>
        놈만 굴러 내려갔다. 숨을 고르는데 무릎이 떨렸다. 몸무게 싸움은 이기든 지든 비싸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'심장 소리 — 들키는 박자',
  x:`벽 하나를 사이에 두고 그것이 있다. 소리로 찾는 것. 발소리는 다 죽였다. 숨소리도 죽였다.<br><br>
    그런데 벽 너머 그것이 이쪽 벽 앞에서 멈췄다. 고개를 기울이는 기척.<br>
    듣고 있는 건 발도 숨도 아니다. 심장이다. 쿵, 쿵 — 이것만은 못 멈춘다.<br><br>
    못 멈춘다. 하지만 내공을 도는 피는 — 느리게 할 수는 있다.`,
  o:[
    { l:'① 심장을 늦춘다 — 내공으로 박동을 바위 밑 물소리까지 낮춘다.', k:'steady', dc:26, wake:1, cost:{ qi:35 },
      ok:`숨을 아랫배에 가라앉히고 내공으로 피를 느리게 돌렸다. 쿵, 쿵 — 이 둥... 둥... 이 됐다.<br><br>
        벽 너머 기척이 갸웃거렸다. 방금까지 있던 심장이 바위가 됐다. 바위는 먹이가 아니다.<br>
        그것이 지나갔다. 박동을 평소로 되돌리는 데 한참 걸렸다. 급히 돌리면 그 소리가 또 들린다.<br><br>
        심장도 다스리는 근육이라는 걸 배웠다. 제일 깊은 데 있는 주먹.`,
      ng:`박동을 낮추다 아찔해졌다. 너무 낮췄다. 눈앞이 좁아지며 몸이 벽에 기댔다 — 쿵.<br><br>
        벽 치는 소리에 벽 너머 것이 돌았다. 심장이 놀라 제멋대로 뛰었다. 북을 울리는 꼴.<br>
        그 방을 전력으로 벗어났다. 심장은 다스리되 정신 줄과 바꾸면 안 된다는 것까지가 수업이었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 박자를 숨긴다 — 벽의 배관을 쳐서 더 큰 박동을 만든다.', k:'fix', dc:24,
      ok:`옆 배관을 주먹 옆면으로 눌러 울렸다. 쿵 — 쿵 — 건물 심장 같은 저음이 벽을 타고 퍼졌다.<br><br>
        그 큰 박동 밑에 다섯 심장이 숨었다. 그것이 배관 소리를 따라 반대쪽으로 멀어졌다.<br>
        배관 끝까지 가서 거기 사는 큰 심장을 찾아낼 때까지 — 저것은 한참 바쁠 것이다.`,
      ng:`배관이 두 번째 울림에서 삭은 이음매가 빠지며 바닥에 떨어졌다. 요란하게.<br><br>
        벽 너머 것이 벽을 부수기 시작했다. 소리의 정체를 알아낸 것이다.<br>
        벽이 뚫리기 전에 방을 빠져나왔다. 복도 끝에서 돌아보니 뚫린 벽 구멍으로 머리 하나가 나와 이쪽을 보고 있었다. 눈이 마주쳤다. 그날 밤 꿈에도 마주쳤다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'발바닥 — 바닥이 전하는 말',
  x:`불빛이 못 가는 어둠이 앞에 있다. 눈은 여기서부터 소용없다.<br><br>
    신을 벗었다. 맨발바닥을 바닥에 붙이면 바닥이 말을 한다. 멀리서 디디는 무게, 그 무게가 네 발인지 두 발인지, 오는지 가는지.<br>
    지금 바닥이 말하는 것 — 왼쪽 앞, 네 발, 무겁다, 멎어 있다. 기다리는 무게다.<br><br>
    일행은 이쪽 손짓만 보고 있다.`,
  o:[
    { l:'① 바닥 소리로 길을 그린다 — 기다리는 무게를 크게 돌아서.', k:'sense', dc:25, wake:1,
      ok:`발바닥이 읽은 지도를 손짓으로 옮겼다. 왼쪽 금지. 오른쪽 벽 따라. 느리게.<br><br>
        돌아가는 내내 왼쪽의 무게는 같은 자리에 멎어 있었다. 길목만 지키는 무게. 돌아가는 먹이는 셈에 없는 무게.<br>
        어둠을 다 지나 불빛에 들어서고도 한참, 발바닥에 바닥의 말이 남아 있었다.<br><br>
        눈 감고도 걷는 발이 됐다. 눈보다 바닥이 정직하다. 바닥은 숨을 줄 모른다.`,
      ng:`바닥 말을 반쯤 잘못 들었다. 무게는 하나가 아니라 둘이었다. 포개 선 둘.<br><br>
        돌아가는 길이 둘째 무게의 길목이었다. 어둠 속에서 더운 숨이 목에 닿았다.<br>
        주먹이 눈보다 먼저 나갔고, 맞은 것이 물러났다. 일행이 불을 당겨 왔을 때 어둠에는 아무것도 없었다. 발바닥만 아직 둘, 이라고 말하고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 무게에게 먼저 간다 — 기다리는 것은 기다림이 깨지면 약하다.', k:'break', dc:26, cost:{ qi:32 },
      ok:`기다리는 것의 셈은 이쪽이 모르고 지나가는 것까지다. 셈을 깼다 — 어둠으로 먼저 걸어 들어갔다. 곧장, 그 무게를 향해.<br><br>
        발바닥이 전하는 무게의 떨림 — 당황이 바닥을 타고 왔다. 매복이 들키면 매복꾼은 반 박자 늦는다.<br>
        그 반 박자에 들어가 쳤다. 어둠 속에서 주먹은 눈이 필요 없다. 거리와 방향은 발바닥이 줬다.<br>
        무게가 바닥에서 사라졌다 — 쓰러진 것은 무게가 아니라 소리로 남는다.`,
      ng:`걸어 들어가는 사이 무게가 움직였다. 기다리는 것인 줄 알았는데 — 재는 것이었다.<br><br>
        위에서 왔다. 바닥은 위를 못 읽는다.<br>
        어깨에 발톱 두 줄을 받고 구르며 쳐 냈다. 일행 불빛이 닿자 그것은 천장으로 돌아가 사라졌다. 바닥 공부 다음은 천장 공부라는 뜻으로 받아들였다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S', t:'발톱을 잡는 손',
  x:`놈의 앞발이 빠르다. 눈으로 좇으면 늦고, 피하기만 하면 뒤의 일행에게 간다.<br><br>
    권사의 답은 하나 남는다 — 발톱을 손으로 잡는 것. 베이자고 잡는 게 아니다. 발톱 위 발목, 털이 끝나는 매끈한 마디를 잡는 것이다.<br>
    한 번 잡으면 놈의 가장 빠른 무기가 이쪽 손잡이가 된다.<br><br>
    못 잡으면 — 손이 발톱 밑이다.`,
  o:[
    { l:'① 발톱 위 발목을 마중 잡는다.', k:'break', dc:26,
      doom:{ title:'마주 잡은 것', what:'앞발에 손목이 물려 어둠으로 끌려갑니다', dc:19, sec:40,
        text:`발목을 잡았다. 잡는 데까지는 맞았다. 놈이 앞발을 — 거둬들였다. 이쪽 손목째.<br><br>
          발톱 아래 손가락 같은 마디가 있다는 건 아무도 몰랐다. 그 마디가 이쪽 손목을 마주 잡았다.<br>
          한 팔이 통째로 놈의 것이다. 놈이 세 발로 달리기 시작했다. 어둠 쪽으로. 끌려가며 바닥의 말을 들었다 — 마중 나오는 무게가 둘 더 있다고.`,
        dieText:`어둠 속에서 바닥을 끄는 소리가 한참 이어지다 멎었다.<br><br>
          일행이 따라 들어간 자리에는 벗겨진 신 한 짝이 놓여 있었다. 맨발로 바닥을 읽던 사람의 신이.<br>
          그 복도를 지날 때마다 바닥이 낮게 우는 것 같다고, 일행은 오래 말했다.`,
      },
      ok:`앞발이 뻗는 금 안쪽으로 먼저 들어가 발목 마디를 잡았다. 잡자마자 비틀며 당겼다.<br><br>
        제일 빠른 무기가 손잡이가 되는 순간 — 놈의 몸 전체가 그 손잡이에 끌려 돌았다. 돌아간 옆구리에 무릎을 박았다.<br>
        놈이 앞발을 빼고 절뚝이며 물러났다. 다시는 그 발을 먼저 내밀지 않았다.<br><br>
        잡는 손은 치는 손보다 한 수 위라는 옛말이 몸에 들어왔다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 잡지 않는다 — 발톱이 뻗을 때마다 반 보씩, 금 밖에서 지치게 한다.', k:'evade', dc:25,
      ok:`앞발이 닿는 금에서 꼭 반 보 밖 — 거기만 디뎠다. 놈이 뻗고, 비고, 뻗고, 비고.<br><br>
        빠른 무기는 빗나갈 때마다 비싸다. 스무 번째쯤 앞발이 눈에 띄게 늦어졌다.<br>
        그때 들어갔다. 늦어진 발은 길잡이일 뿐이다. 주먹이 그 안쪽을 쳤다.<br>
        지치게 해서 이기는 건 제일 오래 걸리고 제일 안 다치는 길이다. 오늘은 그 길이 맞았다.`,
      ng:`열다섯 번째에서 이쪽 다리가 먼저 느려졌다. 반 보가 반의반 보가 됐다.<br><br>
        발톱 끝이 가슴팍을 긁고 지나갔다. 옷과 살갗 한 겹.<br>
        일행이 사이에 들어 번갈아 받았다. 지치기 싸움은 이쪽도 거는 판돈이 같다는 걸 잊고 있었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S', t:'숨 거리 — 눈 감은 반 보',
  x:`등불이 꺼졌다. 다시 붙일 틈은 없다 — 어둠 속에서 그것이 이미 숨 거리 안에 있다.<br><br>
    숨 거리. 서로의 숨이 닿는 거리. 이 거리에서는 눈이 멀쩡해도 소용없다. 보고 움직이면 늦는 거리다.<br>
    권사는 이 거리를 배운다. 숨이 닿는 방향, 숨의 높이, 들숨과 날숨 사이의 빈틈.<br><br>
    그것의 숨이 날숨으로 바뀌었다. 덮치기 전의 숨이다.`,
  o:[
    { l:'① 날숨에 맞춰 반 보 들어가 턱 밑을 친다.', k:'break', dc:26, wake:1, cost:{ qi:36 },
      ok:`날숨은 몸이 쏟아지기 반 호흡 전이다. 그 반 호흡에 이쪽이 먼저 반 보 — 숨의 뿌리, 턱 밑으로 주먹을 올려 꽂았다.<br><br>
        덮치려던 무게가 제 턱을 통해 멎었다. 어둠 속에서 큰 것이 무릎부터 무너지는 소리.<br>
        불을 다시 켰을 때 일행은 쓰러진 그것과 그 옆에 선 이쪽을 번갈아 봤다. 뭘 봤느냐고 물었다. 아무것도. 들었을 뿐이다.<br><br>
        눈 감고 치는 주먹이 완성됐다. 숨 거리 안에서는 이쪽이 주인이다.`,
      ng:`날숨을 읽었는데 그것이 숨을 — 멈췄다. 숨을 끊고 덮치는 법을 아는 것이었다.<br><br>
        어깨와 어깨가 어둠 속에서 부딪쳤다. 뒹굴며 팔꿈치와 이빨이 오갔다.<br>
        일행이 불을 켜자 그것이 빛을 싫어하며 떨어져 나갔다. 입안에 피 맛. 이쪽 것인지 저쪽 것인지 모를 피 맛이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 반 보 물러나 숨을 흘린다 — 빈자리를 덮치게 한다.', k:'evade', dc:25,
      ok:`날숨이 닿는 순간 반 보 — 숨은 그대로 그 자리에 뱉어 두고 몸만 비켰다.<br><br>
        그것이 숨 냄새가 남은 빈자리를 덮쳤다. 바닥을 긁는 소리.<br>
        엎드린 등은 숨 거리의 제일 큰 빈틈이다. 팔꿈치를 등뼈 위로 떨어뜨렸다.<br>
        어둠 속 싸움은 그걸로 끝났다. 숨은 미끼도 된다. 하나 배웠다.`,
      ng:`몸은 비켰는데 발끝이 바닥 틈에 걸렸다. 반 보가 한 보가 됐다.<br><br>
        그것의 어깨가 이쪽 옆구리를 스치며 지나갔다. 스친 것만으로 갈비뼈가 울렸다.<br>
        구르며 거리를 벌리고, 일행 불빛 안으로 물러났다. 숨 거리 수업은 바닥 상태 확인부터라고 적어 뒀다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S', t:'가시 돋친 것',
  x:`놈의 등과 어깨에 가시가 돋았다. 끝이 젖어 번들거린다. 스친 자리부터 감각이 죽는다고 — 먼저 스쳐 본 일행 손등이 벌써 말을 안 듣는다.<br><br>
    맨손 싸움꾼한테는 고약한 상대다. 잡을 데가 없다.<br>
    아니 — 잡을 데가 없게 보이는 것뿐이다. 가시는 등과 어깨. 배와 턱 밑은 민살이다.<br><br>
    민살을 치려면 가시 밑으로 들어가야 한다. 들어가는 길이 전부 가시 곁이다.`,
  o:[
    { l:'① 가시 밑으로 미끄러져 들어가 배를 친다 — 바닥에 등을 대고.', k:'break', dc:26, cost:{ qi:34 },
      ok:`놈이 덮치는 순간 맞서지 않고 — 바닥으로 미끄러졌다. 등을 바닥에, 얼굴 위로 가시 돋친 배가 아니라 민살 배가 지나간다.<br><br>
        그 배에 두 주먹을 연달아 박았다. 바닥이 등을 받쳐 주는 주먹은 평소의 배로 무겁다.<br>
        놈이 이쪽을 넘어가다 꼬꾸라졌다. 일어나기 전에 일행 창이 끝냈다.<br>
        바닥은 적이 아니라 발판이라는 것 — 누운 자세도 자세다.`,
      ng:`미끄러지는 바닥에 기름기가 있었다. 반 뼘 더 미끄러졌다.<br><br>
        주먹이 배가 아니라 뒷다리에 닿았다. 그리고 뒷다리 안쪽에도 잔가시가 있었다.<br>
        주먹등이 얼얼하다가 — 멍해졌다. 한나절 동안 왼손이 남의 손이었다. 민살 지도는 다 그린 뒤에 믿어야 했다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 가시를 뽑을 물건을 만든다 — 놈을 좁은 문틀로 꾄다.', k:'gaze', dc:25,
      ok:`가시 돋친 몸의 약점은 가시다 — 걸린다. 놈을 문틀 쪽으로 물러서며 꾀었다.<br><br>
        덮치던 놈의 어깨 가시가 문틀에 박혔다. 세 대가 깊이. 뽑으려 버둥댈수록 더 박혔다.<br>
        걸린 놈의 턱 밑 민살은 이제 그냥 과녁이었다.<br>
        가시는 무기이자 덫이다. 어느 쪽이 되느냐는 싸움터가 정한다. 싸움터는 이쪽이 골랐다.`,
      ng:`문틀이 삭아 있었다. 가시가 박히는 대신 문틀째 뜯겨 나왔다.<br><br>
        문틀을 어깨에 단 놈이 더 성이 나서 몰아붙였다. 부서진 나무 조각과 가시가 같이 날았다.<br>
        방을 하나 내주고 물러나서야 놈이 문틀을 떼어 내느라 멈췄다. 그 틈에 다 빠져나왔다. 덫 설계는 덫 재료 검사부터다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S', t:'멎은 숨 — 돌려주는 손',
  x:`동료가 숨을 안 쉰다. 목을 조르던 것은 떼어 냈는데 — 숨이 돌아오지 않는다.<br><br>
    심장은 뛴다. 약하게. 숨길이 눌려 닫힌 것이다.<br>
    치유사는 두 방 건너에 있다. 부를 시간에 숨이 끝난다.<br><br>
    내공은 제 몸만 도는 게 아니다. 손바닥을 통해 남의 몸에도 길을 낸다 — 배우기는 했다. 산 사람에게 해 보는 건 처음이다.`,
  o:[
    { l:'① 가슴에 손바닥을 얹고 내공으로 숨길을 쓸어 연다.', k:'bond', dc:26, wake:1, cost:{ qi:38 },
      ok:`손바닥을 명치에 얹고 내공을 가늘게 흘렸다. 급류가 아니라 실개천으로 — 눌려 닫힌 숨길을 안에서 쓸어내리듯.<br><br>
        한 번. 두 번. 세 번째에 동료가 크게 숨을 토했다. 켁켁대며 눈을 떴다.<br>
        왜 네 손바닥이 여기 있느냐는 얼굴이었다. 설명은 치유사가 와서 대신했다.<br><br>
        부수는 내공과 살리는 내공이 같은 길을 쓴다는 걸 손바닥이 배웠다. 세기만 다를 뿐.`,
      ng:`실개천이어야 할 것이 급류로 들어갔다. 동료 몸이 활처럼 휘었다.<br><br>
        숨은 — 돌아왔다. 거칠게. 같이 돌아온 건 가슴 안쪽의 멍이다.<br>
        치유사가 도착해 마무리하며 이쪽을 한 번 봤다. 야단도 칭찬도 아닌 눈. 숨을 살린 손이 멍도 낸 손이라는 눈이었다. 둘 다 맞다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 몸을 옆으로 뉘고 등의 혈 자리를 두드려 깨운다.', k:'heal', dc:25,
      ok:`몸을 옆으로 뉘었다. 등 — 날개뼈 사이 혈 자리를 손바닥 밑동으로 세 번, 박자 있게 두드렸다.<br><br>
        둘째 박에 목에서 걸린 것이 풀리는 소리. 셋째 박에 숨이 터졌다.<br>
        기침과 함께 동료가 일어나 앉았다. 등이 얼얼하다고 투덜댔다. 숨 값으로는 싸다.<br>
        권사의 손은 급소를 아는 손이다. 급소는 죽이는 자리이자 살리는 자리다. 같은 지도의 양면.`,
      ng:`첫 박이 혈 자리에서 손가락 하나 비껴났다. 둘째 박도.<br><br>
        그 사이 동료 입술이 파래졌다. 셋째 박을 포기하고 숨길에 직접 손가락을 넣어 눌린 것을 당겼다.<br>
        숨은 돌아왔다. 거친 방법이었다. 동료는 목이 쉬어 이틀 말을 못 했다. 지도는 외웠는데 실전 축척이 달랐다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'S', t:'좁은 관 — 주먹만 들어가는 길',
  x:`무너진 길을 피해 가는 유일한 샛길이 — 기어가는 관이다. 어깨가 끼는 폭. 무기는 못 들고 들어간다.<br><br>
    권사만 온전한 싸움꾼으로 들어가는 길이라는 뜻이다. 앞장은 정해졌다.<br>
    관 중간쯤에서 맞은편 어둠에 숨소리가 있다. 이 관을 집으로 쓰는 것. 몸집은 이쪽만 하거나 — 좁은 데 사는 것치고 크다.<br><br>
    물러서는 것도 기어서다. 앞으로 가는 것도 기어서다. 어느 쪽이든 등은 못 돌린다.`,
  o:[
    { l:'① 기어가며 싸운다 — 팔꿈치와 이마로, 관 전체를 내 편으로.', k:'break', dc:26, wake:1,
      ok:`좁은 관에서는 큰 동작이 없다. 팔꿈치 반 뼘, 이마 반 뼘 — 대신 벽이 사방에 있다. 벽을 등지는 게 아니라 벽 네 개를 다 쓰는 싸움.<br><br>
        그것이 덮치는 순간 몸을 비틀어 관 벽에 어깨를 걸고, 올라오는 턱을 팔꿈치로 내리찍었다. 관이 울렸다.<br>
        그것이 뒷걸음으로 — 기어서 — 물러났다. 제 집에서 제가 좁아진 것이다.<br><br>
        좁은 데 싸움은 몸집 싸움이 아니라 각도 싸움이다. 팔꿈치가 그 각도들을 다 외웠다.`,
      ng:`팔꿈치를 거는 벽 모서리가 미끄러웠다. 반 뼘이 안 나갔다.<br><br>
        그것 이빨이 어깨를 물었다 놓쳤다. 옷깃째.<br>
        서로 반 몸씩 물리고 긁힌 채 그것이 먼저 옆 가지관으로 빠졌다. 남은 관 길이를 피 냄새 속에서 기었다. 뒤에 오는 일행한테는 좁아서 다행이었다고만 말했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-15 } },
    { l:'② 관을 울려 내쫓는다 — 들어가기 전에, 양 주먹으로 관 입구를 친다.', k:'break', dc:25, cost:{ qi:29 },
      ok:`관 입구에 두 주먹을 대고 내공을 실어 쳤다. 관 전체가 종처럼 울었다 — 안에 사는 것한테는 집 전체가 우는 소리다.<br><br>
        반대쪽 끝에서 그것이 튀어나가는 소리가 났다. 집이 우는 날은 이사하는 날이다.<br>
        빈 관을 기어서 지났다. 그래도 반대쪽 출구 앞에서는 한참 바닥 말을 듣고 나갔다. 이사 간 집에 돌아오는 놈도 있는 법이라.`,
      ng:`관을 울렸는데 — 반대쪽에서 마주 울렸다. 쿵. 쿵. 그것이 안쪽 벽을 마주 치고 있다.<br><br>
        나가라는 소리에 나가겠다고 대답한 게 아니다. 들어오라는 대답이다.<br>
        관은 포기했다. 무너진 길을 반나절 걸려 돌았다. 돌아가는 내내 관 쪽에서 쿵, 쿵, 초대장이 계속 왔다.`,
      win:{ exp:19, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'벽 너머 — 주먹으로 여는 길',
  x:`뒤가 막혔다. 쫓아오는 것들의 발소리가 복도를 채운다. 앞은 벽돌 벽 — 지도에는 이 너머에 계단이 있다.<br><br>
    벽돌 반 장 두께. 망치가 있으면 열 번 칠 벽.<br>
    망치는 없다. 주먹이 있다.<br><br>
    벽을 치는 주먹은 벽을 이기는 게 아니다. 벽의 삭은 줄눈을 찾아 — 거기만 치는 것이다.`,
  o:[
    { l:'① 줄눈을 읽고 한 점에 전부를 싣는다.', k:'break', dc:26, cost:{ qi:37 },
      ok:`손바닥으로 벽을 쓸었다. 줄눈 — 삭아서 가루가 묻어나는 금이 열십자로 지나는 점 하나.<br><br>
        그 점에 내공을 실은 주먹을 박았다. 한 번. 벽 저쪽까지 금이 뻗는 울림이 손목으로 돌아왔다. 두 번째에 벽돌 네 장이 통째로 저쪽으로 빠졌다.<br>
        구멍을 어깨로 넓히며 다섯이 빠져나갔다. 쫓아온 것들은 제 몸집 때문에 그 구멍 앞에서 한참 막혔다.<br>
        벽은 두께로 버티고 주먹은 한 점으로 이긴다.`,
      ng:`줄눈을 찾았는데 그 밑이 하필 철근이었다. 주먹이 철근을 치는 소리가 복도에 울렸다.<br><br>
        손등이 찢어졌다. 두 점째를 찾아 다시 쳤고, 이번엔 뚫렸다 — 쫓는 것들이 모퉁이를 도는 게 보이는 거리에서.<br>
        마지막 사람 발뒤꿈치가 빠져나오는 순간 첫 놈이 구멍에 머리를 박았다. 피 묻은 주먹으로 그 콧등을 한 대 보태 줬다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-34, mind:-14 } },
    { l:'② 벽 대신 천장을 본다 — 환기 덮개를 뜯어 위로 돌린다.', k:'sense', dc:25,
      ok:`벽을 치려다 손바닥에 느껴진 바람 — 천장 구석 환기 덮개에서 샌다. 덮개 나사는 녹이 먹었다. 비트는 손에는 안 버틴다.<br><br>
        덮개를 뜯고 한 사람씩 밀어 올렸다. 위 통로는 계단실 천장으로 이어졌다.<br>
        마지막으로 올라가 덮개를 제자리에 끼웠다. 밑에서 쫓던 것들이 막힌 복도를 긁는 소리가 덮개 틈으로 올라왔다. 벽은 안 깨도 됐다. 바람이 먼저 길을 알고 있었다.`,
      ng:`덮개는 뜯었는데 통로가 중간에서 어긋나 있었다. 건물이 내려앉으며 접힌 것이다.<br><br>
        도로 내려와 결국 벽을 쳤다. 준비 자세도 숨 고를 틈도 없이.<br>
        뚫기는 뚫었다. 손목이 시큰거리는 걸 참으며 마지막으로 빠져나왔다. 지름길 찾다 늦어진 만큼 주먹이 비싸게 치렀다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S', t:'부르는 소리 앞에서 — 움직이지 않는 수련',
  x:`야영 중 어둠에서 이름이 불린다. 죽은 동료 목소리로. 하룻밤에 몇 번씩.<br><br>
    새로 온 일행들이 흔들린다. 한 번 대답하면, 한 번 돌아보면 — 그걸로 저것의 밤 장사가 시작된다.<br>
    권사의 수련 중에 부동심이 있다. 몸을 멈추는 게 아니라 마음이 몸보다 먼저 안 움직이는 것.<br><br>
    오늘 밤은 그 수련을 일행 전체가 해야 한다. 가르칠 사람은 이쪽뿐이다.`,
  o:[
    { l:'① 둘러앉혀 숨 고르는 법부터 — 부르는 소리를 숨으로 흘려보내게 한다.', k:'steady', dc:25, wake:1,
      ok:`불가에 둘러앉혔다. 들숨 넷, 멈춤 둘, 날숨 여섯. 소리가 오면 — 쫓지도 막지도 말고 날숨에 실어 보낼 것.<br><br>
        밤새 목소리가 돌았다. 이름들을 차례로 불렀다. 여섯 숨이 박자를 안 잃었다.<br>
        새벽녘, 목소리가 처음으로 — 제 이름을 댔다. 아무도 모르는 이름. 대답이 없자 그 이름도 조용해졌다.<br><br>
        부동심은 혼자 닦는 것인 줄 알았다. 둘러앉으면 서로의 숨이 벽이 된다. 가르치며 배웠다.`,
      ng:`셋째 숨 박자에서 막내가 흐느꼈다. 불린 이름이 하필 어머니 목소리로 바뀐 참이었다.<br><br>
        흐느낌은 대답으로 쳐 주는 모양이다. 목소리가 금 바로 밖까지 왔다.<br>
        밤새 막내를 가운데 두고 등을 맞댔다. 아침까지 아무도 못 잤다. 수련은 벽이 되기 전에 뚫리면 처음부터다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 부르는 것의 자리를 숨으로 찾아 — 소리 한가운데로 주먹을 보낸다.', k:'break', dc:26,
      ok:`목소리는 가짜여도 소리는 진짜다. 소리에는 자리가 있다. 눈을 감고 귀로 거리를 쟀다 — 금 밖 돌무더기 뒤, 가슴 높이.<br><br>
        돌무더기까지 세 걸음에 닿아 소리 한가운데를 쳤다. 이름을 부르다 만 소리가 꺾이는 다른 소리로 변했다.<br>
        그것이 다리 여럿으로 어둠을 긁으며 달아났다. 그 뒤로 밤 목소리는 이 일행을 피해 갔다.<br>
        목소리에 주먹이 닿는다는 걸 모두가 봤다. 그게 제일 큰 약이었다.`,
      ng:`소리 자리를 쟀는데 — 소리가 두 자리였다. 부르는 놈과 기다리는 놈.<br><br>
        부르는 쪽을 치러 나간 금 밖에서 기다리던 쪽이 덮쳤다. 어깨를 물려 금 안까지 구르며 돌아왔다.<br>
        일행 창들이 어둠을 찔러 쫓았다. 그날 밤 목소리는 신이 나서 더 불렀다. 이름에 웃음기를 섞어서.`,
      win:{ exp:21, dream:3 }, lose:{ hp:-31, mind:-16 } }
  ] },

{ at:'S', t:'급소가 없는 것',
  x:`쳤다. 들어갔다. 분명 꺾일 자리였다 — 안 꺾인다.<br><br>
    턱 밑을 쳐도, 관자놀이를 쳐도, 명치를 쳐도 같은 반응이다. 반 걸음 밀리고, 다시 온다.<br>
    급소가 없다. 아니 — 급소가 사람 지도와 다른 데 있다.<br>
    남은 방법은 지도를 새로 그리는 것이다. 맞아 가면서.`,
  o:[
    { l:'① 지도를 새로 그린다 — 치는 자리마다 반응을 읽으며.', k:'gaze', dc:26, wake:1, cost:{ qi:33 },
      ok:`급소 찾기를 버리고 반응 읽기로 바꿨다. 어깨 — 무반응. 옆구리 — 무반응. 뒷목 아래 — 움찔.<br><br>
        움찔한 자리 한 치 밑을 파듯 두 번 쳤다. 그것이 처음으로 소리를 냈다.<br>
        세 번째에 무너졌다. 뒷목 아래 — 사람으로 치면 아무것도 없는 자리에 저것의 심줄이 모여 있었다.<br><br>
        급소는 외우는 게 아니라 찾는 것이다. 맞은 자리마다 금을 긋던 버릇이 — 지도 그리는 손이 됐다.`,
      ng:`읽는 동안 맞는 수업료가 비쌌다. 세 자리를 확인하는 사이 이쪽 갈비에 금이 갔다.<br><br>
        지도 반 장을 그리고 물러났다. 일행이 번갈아 막아 주는 뒤에서 숨을 골랐다.<br>
        결국 수로 눌러 잡았다. 지도 반 장은 다음 놈한테 쓰기로 했다. 같은 종이라면.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-35, mind:-14 } },
    { l:'② 급소를 포기한다 — 균형만 부순다. 설 수 없으면 급소도 소용없다.', k:'break', dc:25,
      ok:`어디를 쳐도 안 죽는 몸이면 — 안 죽여도 된다. 세우지만 않으면 된다.<br><br>
        디디는 발목만 노렸다. 왼쪽 앞, 오른쪽 뒤, 번갈아. 꺾이지는 않아도 디딤은 흐트러진다.<br>
        네 번째에 그것이 제 발에 걸려 넘어졌다. 넘어진 것 위로는 일행의 쇠가 알아서 했다.<br>
        죽이는 길이 안 보이면 넘어뜨리는 길로. 싸움의 답이 꼭 급소일 필요는 없다.`,
      ng:`발목을 노리는 걸 두 번째부터 눈치챘다. 발 대신 꼬리로 디디기 시작했다.<br><br>
        다리 넷에 꼬리까지 — 다섯 발이 됐다. 균형 부수기 셈이 더 복잡해졌다.<br>
        결국 벽까지 몰아 일행과 함께 눌러 잡았다. 혼자 그린 셈법이 모자라면 머릿수로 채우면 된다. 그것도 답이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-29, spirit:-15 } }
  ] },

// ---------- S1 『표본실 — 착륙 이후』 ----------

{ at:'S1', t:'숙주의 가슴 — 사람을 안 치는 주먹',
  x:`쓰러진 연구원이 복도에 누워 있다. 숨이 있다. 그런데 가슴이 — 숨과 다른 박자로 들썩인다.<br><br>
    안에 있다. 자리 잡는 중이다. 자리를 다 잡으면 겉사람은 끝난다고, 표본실 기록이 말했다.<br>
    째고 꺼낼 시간도 사람도 없다. 하지만 권사의 주먹은 칼이 못 하는 걸 한다 — 겉을 안 부수고 속만 치는 침투경.<br><br>
    사람 가슴 위에서 그 주먹을 쓰는 건 — 처음이다.`,
  o:[
    { l:'① 침투경 — 겉가슴은 두고, 안의 것만 꿰뚫어 친다.', k:'break', dc:26, wake:1, cost:{ qi:40 },
      ok:`손바닥을 가슴에 밀착하고, 울림을 안으로만 보냈다. 갈비뼈는 지나가고 — 그 밑에 자리 잡던 것에만 닿는 깊이로.<br><br>
        가슴 밑에서 무언가 움츠러드는 떨림이 손바닥으로 돌아왔다. 한 번 더. 떨림이 멎었다.<br>
        연구원이 켁, 하고 제 박자의 숨을 토했다. 들썩임이 하나로 돌아왔다.<br><br>
        겉을 안 다치게 속을 치는 것 — 수련장에서는 나무통 속 항아리로 연습했다. 사람으로 완성하게 될 줄은 몰랐다.`,
      ng:`울림이 반 치 얕았다. 갈비 안쪽을 울리고 그 밑에는 못 닿았다.<br><br>
        안의 것이 놀라 — 더 깊이 파고들었다. 연구원이 경련했다.<br>
        두 번째는 닿았다. 멎었다. 하지만 깊이 들어간 것은 죽어서도 숙주를 상하게 한다. 연구원은 숨은 돌아왔지만 깨어나지는 못한 채였다. 업고 걸었다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-18, spirit:-18 } },
    { l:'② 치지 않는다 — 혈을 눌러 안의 것 먹이인 숙주의 기를 재운다.', k:'heal', dc:25,
      ok:`안의 것은 숙주의 기를 먹고 자란다. 그렇다면 밥상을 치우면 된다.<br><br>
        목과 명치의 혈을 눌러 연구원의 기를 겨울잠처럼 낮췄다. 가슴의 다른 박자가 — 느려졌다. 굶기 시작한 것이다.<br>
        그대로 업고 치유사한테까지 달렸다. 치유사가 째고 꺼낸 것은 반쯤 말라 있었다.<br>
        연구원은 사흘 만에 깼다. 누가 업어 왔느냐고 물었다고 한다. 밥상 치운 손이라고 전해 달라 했다.`,
      ng:`기를 낮추는 깊이가 어긋나 숙주 숨까지 같이 낮아졌다. 입술이 파래졌다.<br><br>
        급히 혈을 풀고 숨부터 돌렸다. 안의 것도 같이 깨어나 들썩임이 거칠어졌다.<br>
        결국 업고 뛰는 수밖에 없었다. 치유사 방문을 발로 차다시피 열었다. 늦지는 않았다 — 늦을 뻔한 것과 늦은 것 사이가 종이 한 장이었다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-17, spirit:-19 } }
  ] },

{ at:'S1', t:'산성 피 — 스치지 않는 주먹',
  x:`이 시설의 것들은 벨 수 없다. 베면 검은 피가 날과 손을 같이 먹는다.<br><br>
    권사라고 다를 게 없다 — 맨주먹은 더하다. 터뜨리면 주먹이 녹는다.<br>
    하지만 터뜨리지 않고 부수는 길이 있다. 겉가죽을 안 찢는 타격 — 속만 울려 끊는 것.<br>
    피 한 방울 안 흘리고 잡는 싸움. 여기서는 그게 멋이 아니라 생존이다.`,
  o:[
    { l:'① 울림으로만 끝낸다 — 겉가죽을 안 찢고 속심줄만 끊는다.', k:'break', dc:26, cost:{ qi:39 },
      ok:`주먹 끝을 세우지 않고 손바닥 밑동으로 — 닿는 순간 비틀지 않고 밀어 넣듯 울렸다.<br><br>
        겉가죽은 멀쩡하다. 속에서 둔하게 끊어지는 느낌 두 번. 그것이 선 채로 — 접혔다.<br>
        피 한 방울 바닥에 안 떨어졌다. 일행이 돌아보고 물었다. 왜 안 죽이느냐고. 죽었다. 겉만 모를 뿐.<br>
        이 시설에서 제일 안전한 시체를 만드는 법이다. 물도 안 새는.`,
      ng:`둘째 울림에서 그것이 몸을 틀었다. 손바닥 밑동이 비껴 미끄러지며 — 어깨 가시에 손목이 긁혔다.<br><br>
        상처에서가 아니라 가시에 묻어 있던 저쪽 피에서 연기가 났다. 급히 소매를 찢어 닦았다.<br>
        그것은 일행이 맡았다. 손목에 지렁이 같은 흉이 남았다. 피를 안 내는 싸움은 저쪽 피가 어디 묻어 있는지부터 보는 싸움이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 피가 안 나오는 자리만 — 관절을 꺾어 산 채로 묶는다.', k:'steady', dc:25,
      ok:`죽이면 피가 샌다. 그러면 안 죽이면 된다. 뒤로 돌아 들어가 앞다리 둘을 등 뒤로 꺾어 몰았다.<br><br>
        꺾인 관절은 피가 안 난다. 버둥대는 것을 일행이 배관 철사로 묶었다.<br>
        묶인 채 남겨진 그것이 복도에서 오래 울었다. 그 울음이 — 뜻밖의 덤이었다. 동족 소리가 나는 복도를 다른 것들이 피해 다녔다.<br>
        산 채로 이기는 법이 이 시설에서는 제일 깨끗한 법이다.`,
      ng:`앞다리 하나는 꺾었는데 둘째가 생각보다 길었다. 꺾인 채로 몸을 돌려 물어 왔다.<br><br>
        놓고 물러날 수밖에 없었다. 반쯤 꺾인 것이 벽을 타고 도망갔다.<br>
        피는 안 났다. 다만 반만 꺾인 원한 하나가 이 시설 어딘가를 돌아다니게 됐다. 다음에 만나면 알은척을 할 것이다, 서로.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S1', t:'함석 너머 — 벽을 읽는 손바닥',
  x:`통풍구가 사방으로 지나는 구역이다. 벽 속 함석관으로 그것들이 다닌다. 소리로는 늦다 — 소리가 들릴 때는 이미 머리 위다.<br><br>
    손바닥을 벽에 대면 소리보다 빠른 게 온다. 떨림. 기는 다리들이 함석을 누르는 미세한 떨림.<br>
    지금 왼쪽 벽에서 그 떨림이 온다. 둘. 이쪽으로. 벽에 뚫린 통풍구 입은 세 걸음 앞에 하나.<br><br>
    일행은 아직 모른다. 알리면 발소리가 바뀌고, 발소리가 바뀌면 저쪽도 안다.`,
  o:[
    { l:'① 통풍구 입 옆에 붙어 — 나오는 순서대로 받아 친다.', k:'break', dc:26,
      ok:`걸음 박자를 안 바꾸고 통풍구 옆까지 가 벽에 붙었다. 떨림이 입 바로 안쪽까지 왔다.<br><br>
        첫 놈 머리가 나오는 순간 손바닥 밑동이 마중했다. 둔탁한 소리와 함께 머리가 함석 모서리에 끼었다.<br>
        둘째 놈은 첫째에 막혀 못 나왔다. 끼인 첫째를 마저 끝내자 둘째가 물러나는 떨림이 손바닥에 느껴졌다.<br>
        일행은 그제야 알았다. 알리지 않은 것을 뭐라 하는 사람은 없었다. 발소리가 안 바뀐 덕에 산 줄은 다들 아니까.`,
      ng:`첫 놈이 머리가 아니라 꼬리부터 나왔다. 거꾸로 기어 나오는 종류였다.<br><br>
        꼬리 가시가 마중 나간 손바닥을 긁었다. 놀란 둘째가 다른 출구로 빠져 — 천장 쪽에서 나왔다.<br>
        복도가 잠깐 난장이 됐다. 둘 다 잡기는 했다. 손바닥 붕대를 감으며 생각했다. 떨림은 방향까지만 알려 준다. 앞뒤는 안 알려 준다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 벽을 먼저 울린다 — 함석 속 둘을 입구 반대쪽으로 몰아 보낸다.', k:'fix', dc:25,
      ok:`벽에 손바닥을 대고 내공을 넣어 울렸다. 함석관 전체가 낮게 웅, 하고 떨렸다 — 관 속에 있는 것들한테는 지진이다.<br><br>
        떨림 둘이 급히 방향을 돌려 멀어졌다. 지진 나는 굴에 남는 짐승은 없다.<br>
        일행이 왜 벽에 손을 대고 있느냐고 물었다. 벽 점검. 틀린 말은 아니었다.<br>
        그 구역을 지나는 동안 벽을 두 번 더 울렸다. 지진 소식은 멀리 갈수록 좋다.`,
      ng:`울림이 과했다. 삭은 함석 이음매가 복도 천장에서 통째로 내려앉았다.<br><br>
        관 속에 있던 둘도 같이 떨어졌다. 지진을 피하려다 지진에 깔린 꼴로 — 화는 저쪽이 더 났다.<br>
        바닥에서 붙었다. 이기긴 이겼다. 천장에 뚫린 구멍은 그 구역 내내 머리 위 걱정거리로 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, mind:-14 } }
  ] },

{ at:'S1', t:'뛰는 것 — 허공에서 잡는 손',
  x:`천장 구석에 그것이 붙어 있다. 손바닥만 한 것. 다리 여덟을 접고 — 조준 중이다.<br><br>
    저것들은 얼굴로 뛴다. 뛰는 속도는 눈으로 좇을 수 있는 게 아니다.<br>
    하지만 뛰기 전에 다리가 눌리는 순간이 있다. 활시위가 당겨지는 순간. 그걸 보면 — 날아오는 건 못 봐도 날아올 길은 안다.<br><br>
    권사의 손이 허공에서 무언가를 잡는 건 그 길목에서다.`,
  o:[
    { l:'① 길목에 손을 먼저 둔다 — 날아오는 것을 허공에서 움켜잡는다.', k:'break', dc:26,
      doom:{ title:'얼굴로 뛰는 것', what:'얼굴에 그것이 들러붙었습니다', dc:20, sec:35,
        text:`다리가 눌렸다 — 손을 길목에 뻗었다. 길이 틀렸다. 저것은 곧장 뛰지 않고 벽을 한 번 차고 꺾어 들어왔다.<br><br>
          뻗은 손 옆을 지나 얼굴에 닿았다. 다리 여덟이 뒤통수에서 맞물리는 소리가 뼈로 울린다.<br>
          숨이 막힌다. 손가락을 다리 밑에 넣어 보지만 — 당길수록 제 살이 당겨진다. 꼬리가 입술을 더듬는 게 느껴진다.`,
        dieText:`떼어 냈을 때는 반 호흡 늦어 있었다.<br><br>
          일행은 표본실 기록이 말하는 다음 단계를 알고 있었다. 숙주의 가슴이 다른 박자로 뛰기 시작하는 단계.<br>
          권사는 그 단계를 남에게 맡기지 않았다. 마지막 내공으로 제 가슴에 — 침투경은 밖으로만 쓰는 것이 아니었다. 그 선택만은 제 주먹으로 했다.`,
      },
      ok:`다리 여덟이 눌리는 순간 — 길목이 보였다. 손바닥을 그 허공에 먼저 펴 두었다.<br><br>
        퍽, 하고 손안에 들어왔다. 날아오는 것을 잡는 게 아니라 날아올 자리에 손이 기다리는 것.<br>
        움켜쥔 채 바닥에 메쳤다. 다리 여덟이 한 번 오그라들고 끝났다.<br>
        일행이 입을 벌리고 봤다. 손바닥에는 긁힌 자국 하나. 잡는 손의 값으로는 싸다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 조준을 흩뜨린다 — 겉옷을 벗어 얼굴 높이에 펼쳐 든다.', k:'evade', dc:25,
      ok:`저것의 조준은 얼굴 — 숨과 열이 나는 자리다. 겉옷을 벗어 머리 위 비스듬히 펼쳤다. 가짜 윤곽.<br><br>
        그것이 뛰었다. 겉옷 한가운데에 박혀 다리가 천에 엉켰다.<br>
        엉킨 채로 둘둘 말아 바닥에 놓고 발로 끝냈다. 겉옷에는 구멍 여덟 개.<br>
        구멍 난 옷을 도로 입었다. 얼굴에 날 뻔한 구멍보다는 보기 좋다.`,
      ng:`겉옷을 펼치는 반 호흡 — 그 사이에 뛰었다. 저것의 활시위가 더 빨랐다.<br><br>
        천 모서리에 걸려 방향만 빗나갔다. 어깨에 붙은 것을 일행이 창대로 쳐 떨궜다.<br>
        어깨 위 옷이 다리 자국대로 찢겼다. 살은 안 닿았다. 반 호흡 차이가 어깨와 얼굴의 차이였다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'여왕의 방 앞 — 심장 둘을 재우고',
  x:`큰 문 앞 홀을 지켜 선 것들은 소리와 열로 본다. 그리고 — 심장 박동으로 센다.<br><br>
    이 홀을 지나려면 다섯 심장을 전부 바위 밑 물소리로 낮춰야 한다. 권사 혼자면 쉽다. 문제는 나머지 넷이다. 내공 없는 심장은 제가 못 낮춘다.<br>
    손바닥으로 남의 박동을 고르는 법 — 스승이 보여 준 적은 있다. 한 번에 한 사람이었다.<br><br>
    홀을 건너는 동안 넷을 번갈아 고르며 가야 한다.`,
  o:[
    { l:'① 둘씩 어깨를 짚고 — 박동을 이쪽 느린 박자에 업어 간다.', k:'bond', dc:26, wake:1, cost:{ qi:40 },
      ok:`양손을 양옆 둘의 어깨에 얹고, 이쪽 느린 박동을 손바닥으로 흘려보냈다. 박자는 옮는다 — 느린 심장 곁에서 빠른 심장이 순해지듯. 두 걸음마다 손을 옮겨 넷을 번갈아 업었다.<br><br>
        지켜 선 것들의 고개가 다섯 사람을 훑고 — 그냥 지나갔다. 바위 다섯이 굴러가는 걸로 센 모양이다.<br>
        작은 문을 넘고 손을 뗐다. 넷의 심장이 제 박자로 돌아오며 다들 한꺼번에 어지럼을 호소했다.<br><br>
        내 숨을 고르는 손이 남의 숨도 고른다. 손바닥이 북채가 아니라 — 북 가죽을 쓰다듬는 손이 됐다.`,
      ng:`셋째까지는 업었다. 넷째 — 제일 겁 많은 — 심장이 손바닥 밑에서 요동을 쳤다. 겁은 내공보다 힘이 세다.<br><br>
        지켜 선 것 하나가 그 요동을 세었다. 고개가 꺾이고, 홀이 움직이기 시작했다.<br>
        전원이 작은 문까지 내달렸다. 문을 닫고 빗장을 거는 손들이 다 떨렸다. 다섯 심장이 북 다섯이 되어 한참 울렸다. 문 밖에서도 들었을 것이다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 심장을 못 숨기면 — 가짜 심장을 하나 만든다. 홀 반대편 배관을 울려서.', k:'break', dc:26,
      ok:`홀 반대편으로 내공을 실은 돌을 던져 배관을 맞혔다. 배관이 쿵 — 쿵 — 심장 박자로 울리게, 두 번째 돌로 박자를 보탰다.<br><br>
        지켜 선 것들이 일제히 그 큰 심장 쪽으로 고개를 꺾었다. 바위만 한 심장이면 바위만 한 먹이다.<br>
        저것들이 배관을 뜯는 동안 다섯 작은 심장이 반대편 작은 문을 지났다.<br>
        문 너머에서 배관 뜯기는 소리를 들으며 생각했다. 심장 소리란 참 — 서로에게 약점이다.`,
      ng:`둘째 돌이 배관을 빗나가 바닥에 떨어졌다. 박자가 끊긴 가짜 심장은 — 가짜 티가 난다.<br><br>
        지켜 선 것들이 소리의 출처가 아니라 소리를 던진 쪽을 돌아봤다. 영리한 것들.<br>
        홀 가장자리를 전력으로 돌아 문을 넘었다. 마지막 사람 등 뒤로 문이 긁혔다. 가짜는 박자가 생명이라는 걸 돌 두 개 값으로 배웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'배양조 유리 — 한 치 주먹',
  x:`갈림길을 막은 건 배양조다 — 넘어져 통로를 가로막은 거대한 유리통. 안은 비었다. 다행히.<br><br>
    돌아가는 길은 그것들 순찰로다. 뚫고 가는 게 맞다. 문제는 이 유리 — 강화유리다. 망치로 때리면 튕기는 종류.<br>
    강화유리는 겉이 아니라 속이 당겨져 있는 유리다. 겉을 때리면 버티고, 속을 울리면 — 전체가 한 번에 간다.<br><br>
    속을 울리는 주먹. 한 치 거리에서 미는 주먹이 그 일을 한다.`,
  o:[
    { l:'① 한 치 주먹 — 주먹을 유리에 댄 채로, 속만 민다.', k:'break', dc:26, wake:1, cost:{ qi:38 },
      ok:`주먹을 유리면에 가볍게 대고 — 몸통부터 어깨, 팔꿈치, 손목 순으로 힘을 포개 한 치를 밀었다.<br><br>
        유리 전체가 한순간 뿌옇게 — 수만 조각 금이 속에서 피며 통째로 주저앉았다. 와르르가 아니라 사르르.<br>
        가루가 된 유리 더미를 밟고 넘었다. 발밑에서 눈 밟는 소리가 났다.<br><br>
        치지 않고 미는 주먹. 거리가 없을수록 깊이 가는 힘. 스승이 평생 말로만 하던 걸 유리가 한 번에 가르쳤다.`,
      ng:`첫 밀기가 반 치에 그쳤다. 유리는 속금 대신 겉금만 한 줄 갔다.<br><br>
        두 번째 준비 중에 순찰로 쪽에서 발소리 — 결국 유리는 두 번째에 갔지만, 깨지는 소리가 발소리들을 불렀다.<br>
        유리 가루 위를 뛰어 넘으며 쫓기는 꼴이 됐다. 눈 밟는 소리가 뒤에서도 났다. 여러 겹으로.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 유리 밑 받침대를 본다 — 통째로 굴려 길을 연다.', k:'sense', dc:25,
      ok:`유리는 둥글다. 둥근 것은 깨는 게 아니라 굴리는 것이다. 받침대 잔해를 치우고 바닥 기름때를 읽어 구를 방향을 쟀다.<br><br>
        다섯이 한쪽에 붙어 밀었다. 배양조가 묵직하게 — 구르기 시작하자 제 무게로 복도 벽감까지 굴러가 안착했다.<br>
        통로가 열렸다. 유리는 멀쩡한 채다. 깨지 않은 유리는 소리도 없다.<br>
        소리 없이 연 길로 소리 없이 지났다. 순찰은 끝까지 몰랐을 것이다.`,
      ng:`구르던 배양조가 바닥 턱에 걸려 — 벽을 쳤다. 유리가 그제야 깨졌다. 제일 크고 제일 나쁜 박자로.<br><br>
        순찰 발소리가 꺾여 들어왔다. 유리 조각 깔린 복도에서 한바탕.<br>
        이기고 지났지만 다들 신발 밑에 유리 조각을 한 움큼씩 달고 걸었다. 조용히 열자던 길이 제일 시끄러운 길이 됐다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S1', t:'격벽 틈 — 손가락의 힘',
  x:`격벽이 잘못 내려왔다. 동료 하나가 저쪽에 남았다. 문과 바닥 사이 틈은 한 뼘 — 그 틈으로 저쪽 복도가 보인다.<br><br>
    보이는 게 문제다. 복도 끝에서 그것이 오고 있다. 동료는 문을 두드리고, 기계실은 세 층 위다.<br>
    쇠지레는 틈에 안 들어간다. 들어가는 건 — 손가락뿐이다.<br>
    한 뼘 틈에 손가락 여덟 개를 걸고 격벽을 드는 일. 기계가 누르는 무게를 손가락 마디가 받는 일이다.`,
  o:[
    { l:'① 손가락을 틈에 걸고 — 내공을 마디마디에 채워 격벽째 든다.', k:'break', dc:26, wake:1,
      ok:`여덟 손가락을 틈에 밀어 넣고 — 내공을 손끝 마디부터 손목, 팔꿈치, 허리 순으로 기둥처럼 세웠다. 드는 건 손가락이 아니다. 손가락은 고리일 뿐, 드는 건 온몸이다.<br><br>
        격벽이 끼익 — 반 자 올라왔다. 동료가 그 틈으로 굴러 들어왔다. 복도 끝 발소리가 뛰기 시작하는 소리를 들으며 손을 뺐다. 격벽이 쾅.<br>
        문 너머에서 그것이 부딪는 소리가 두 번 났다.<br><br>
        손가락이 고리가 되고 몸이 기중기가 되는 법 — 마디 여덟 개가 그 순서를 외웠다.`,
      ng:`반 자까지는 들었다. 동료 어깨가 틈을 반쯤 지났을 때 — 왼손 넷째 마디가 울며 꺾였다.<br><br>
        격벽이 한 치 내려앉았다. 동료가 비명을 삼키며 마저 기어 나왔고, 손가락을 뺐다.<br>
        넷째 손가락이 퉁퉁 부었다. 부목을 대고 생각했다. 여덟 고리 중 하나가 약하면 그 하나로 다 무너진다. 약한 마디부터 단련할 것.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 이쪽이 틈으로 기어 들어간다 — 저쪽에서 동료를 지키며 함께 길을 찾는다.', k:'steady', dc:26,
      doom:{ title:'격벽 저쪽의 것', what:'격벽 너머 어두운 복도로 끌려갑니다', dc:20, sec:39,
        text:`한 뼘 틈에 어깨를 비틀어 넣고 반쯤 지났을 때 — 저쪽에서 그것이 도착했다. 계산보다 빨랐다.<br><br>
          틈에 낀 몸은 권사가 아니라 그냥 끼인 것이다. 발목이 물렸다.<br>
          동료가 팔을 붙들고 이쪽 일행이 틈으로 손을 뻗는다 — 문 밑에 낀 몸을 사이에 두고 양쪽이 당긴다. 격벽 모서리가 갈비를 긁는다. 저쪽 힘이 더 세다. 어두운 복도 쪽으로, 한 치씩.`,
        dieText:`틈 저쪽에서 동료가 끝까지 손을 놓지 않았다 — 손만 남을 때까지, 라고는 쓰지 않겠다.<br><br>
          격벽은 다음 날 기계실을 돌려 열었다. 저쪽 복도는 비어 있었다. 끌린 자국이 모퉁이 너머까지 이어져 있었다.<br>
          동료는 그 뒤로 닫히는 문을 못 봤다. 어느 문이든 끝까지 손으로 받치고 서 있곤 했다.`,
      },
      ok:`틈으로 몸을 비틀어 넘어가 — 동료를 등 뒤 벽감에 밀어 넣고 복도를 마주 섰다.<br><br>
        그것이 왔다. 좁은 문가는 이쪽 판이다. 들이미는 콧등에 팔꿈치, 발톱 위 발목 잡아 비틀기 — 두 합에 그것이 물러나 거리를 쟀다.<br>
        재는 동안 위층 일행이 기계실에 닿았다. 격벽이 올라가고, 둘이 함께 돌아왔다.<br>
        혼자 남는 쪽의 무게를 아는 사람이 하나 늘었다. 그래서 간 것이다.`,
      win:{ exp:23, dream:3 } }
  ] },

// ---------- S2 『백악기 정원』 ----------

{ at:'S2', t:'담장을 미는 것 — 맞미는 어깨',
  x:`담장 기둥 하나가 오늘 밤을 못 넘긴다. 받침 콘크리트가 바스러져 — 다음 몸통박치기 한 번이면 뽑힌다.<br><br>
    보강할 철근도, 시간도 없다. 풀숲에서 그놈이 거리를 재는 숨소리가 벌써 온다.<br>
    권사가 할 수 있는 일은 하나 — 기둥 안쪽에 어깨를 대고, 부딪치는 순간 맞미는 것.<br><br>
    쇠그물 너머의 몸통과 이쪽 어깨 사이에, 삭은 기둥 하나.`,
  o:[
    { l:'① 부딪치는 순간에 맞춰 — 어깨로 기둥째 되민다.', k:'break', dc:26,
      doom:{ title:'담장 너머의 무리', what:'뚫린 담장 틈으로 물려 가 풀숲으로 끌려갑니다', dc:20, sec:36,
        text:`박자가 반 호흡 어긋났다. 놈이 부딪치기 직전 멈췄다 — 두 번 치는 척하는 수까지 익힌 놈이었다.<br><br>
          헛민 어깨가 앞으로 쏠린 순간 진짜 박치기가 왔다. 기둥이 뽑히고 그물이 이쪽을 감으며 넘어갔다.<br>
          그물에 말린 채 풀숲으로 끌린다. 쇠그물 코가 등을 긁고, 풀이 얼굴을 때리고 — 끄는 놈 말고도 마중 나오는 발소리들이 보태진다.`,
        dieText:`아침에 담장 틈 밖으로 그물 반 장이 풀숲까지 끌려 나가 있었다.<br><br>
          일행은 그물을 거두고 기둥을 새로 박았다. 아무도 그 일을 입에 올리지 않고 — 다만 밤마다 기둥마다 돌아가며 어깨를 대 보는 버릇이 생겼다.<br>
          맞미는 어깨가 비어서, 담장은 그 뒤로 두 명이 지켰다.`,
      },
      ok:`놈의 발이 땅을 차는 떨림이 발바닥으로 왔다 — 부딪치기 반 호흡 전. 그 반 호흡에 어깨와 내공을 기둥에 포갰다.<br><br>
        쿵. 기둥이 아니라 이쪽 어깨가 받았다. 되미는 힘에 놈이 제 박치기째 튕겨 나자빠졌다.<br>
        기둥은 삭은 채로 살았다. 자빠진 놈이 일어나 콧등을 땅에 비비며 물러갔다. 벽이 되받아친 것은 처음 겪었을 것이다.<br>
        아침에 받침을 새로 다졌다. 어깨의 멍은 기둥 값이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 기둥을 포기한다 — 뽑힐 기둥 안쪽에 함정 구덩이를 판다.', k:'fix', dc:25,
      ok:`못 지킬 기둥이면 뚫릴 자리를 이쪽이 정하면 된다. 기둥 안쪽에 무릎 깊이 구덩이를 파고 삭은 가지로 덮었다.<br><br>
        밤에 예정대로 기둥이 뽑혔다. 돌진하던 놈의 앞다리 둘이 구덩이에 꽂혔다.<br>
        고꾸라진 놈 콧등을 일행 창대가 두드려 돌려보냈다. 절뚝이며 돌아간 놈은 담장 뚫기의 값을 새로 배웠을 것이다.<br>
        기둥은 아침에 다시 세웠다. 구덩이는 — 그대로 뒀다. 쓸 만한 문지기다.`,
      ng:`구덩이 깊이가 모자랐다. 놈이 꽂히는 대신 밟고 — 넘어 들어왔다.<br><br>
        야영지 가장자리에서 한바탕이 벌어졌다. 다섯이 달라붙어 도로 밀어냈다.<br>
        뚫린 담장을 밤새 등으로 막았다. 함정은 반 자 차이로 문턱이 된다. 다음 구덩이는 허리 깊이로 팠다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S2', t:'물속의 주먹 — 반 박자 느린 세상',
  x:`허리까지 잠긴 고사리밭. 물속에서 주먹은 반 박자 느리다. 그걸 아는 것이 물밑으로 돈다.<br><br>
    젖은 소매가 무겁다. 헛친 주먹이 물을 밀 때마다 몸이 반대로 흔들린다.<br>
    물속 싸움의 답은 주먹 끝이 아니다 — 물에 잠기지 않은 데, 팔꿈치와 무릎. 짧은 것들은 물을 덜 민다.<br><br>
    등줄기가 다시 금을 그으며 온다. 이번엔 피하지 않고 받기로 했다.`,
  o:[
    { l:'① 짧게 받는다 — 스치는 순간 팔꿈치를 수면에 내리꽂는다.', k:'break', dc:26, wake:1, cost:{ qi:35 },
      ok:`등줄기가 닿는 거리 — 주먹이면 반 박자 늦는 거리에서 팔꿈치는 제때다. 수면을 가르는 콧등 위로 팔꿈치를 짧게 떨어뜨렸다.<br><br>
        물이 둔탁하게 울리고 그것이 뒤집혔다. 흰 배가 수면에 떴다.<br>
        물속 세상의 박자를 손에 넣었다. 긴 것은 버리고 짧은 것만 쓴다 — 물이 가르쳐 준 수련이다.<br><br>
        마른 땅에 올라와서도 한동안 팔꿈치가 먼저 나가려 했다. 몸은 배운 걸 금방 못 놓는다.`,
      ng:`팔꿈치는 제때 떨어졌는데 — 그것이 수면 한 뼘 밑으로 지나갔다. 물이 깊이를 속였다.<br><br>
        헛친 팔꿈치 밑으로 꼬리가 다리를 후렸다. 물속에 한 바퀴 — 코로 물이 들어왔다.<br>
        일행이 세워 줬다. 그것은 멀찍이서 다시 금을 그었다. 물은 거리도 깊이도 다 거짓말을 한다. 눈을 빼고 발바닥으로 다시 쟀다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 바닥을 쓴다 — 물 바닥에 두 발을 심고, 오는 길목에서 무릎을 세운다.', k:'steady', dc:25,
      ok:`물속에서 유일하게 안 느린 것 — 심어 둔 발이다. 바닥 뻘에 두 발을 반 뼘 묻고 길목에 섰다.<br><br>
        등줄기가 다리 사이로 지나려는 순간 무릎을 세웠다. 물을 미는 게 아니라 길을 막는 것은 느려질 게 없다.<br>
        콧등이 무릎뼈를 들이받고 그것이 제풀에 비틀거렸다. 그 위로 일행 창들이 꽂혔다.<br>
        움직여서 이기는 물싸움이 아니라 안 움직여서 이기는 물싸움도 있다.`,
      ng:`뻘이 발을 너무 깊이 물었다. 무릎을 세우는 박자에 발이 안 빠졌다.<br><br>
        콧등 대신 옆구리로 받았다. 물속으로 반 바퀴.<br>
        뻘에서 발을 뽑는 데 일행 둘이 당겼다. 심는 것과 묶이는 것은 반 뼘 차이였다. 신 한 짝은 뻘이 가졌다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S2', t:'큰 것의 발소리 — 무릎으로 받는 땅',
  x:`큰 것이 지나가는 길목에 숨을 자리라고는 쓰러진 고목 밑동 하나뿐이다. 다섯이 그 뒤에 엎드렸다.<br><br>
    문제는 발소리다. 쿵 — 땅이 뛸 때마다 엎드린 몸이 들썩인다. 들썩이는 윤곽을 저 눈이 잡는다.<br>
    땅의 울림은 못 멈춘다. 하지만 받을 수는 있다 — 무릎과 손바닥으로, 울림이 몸을 치기 전에 흘려보내는 법.<br><br>
    권사는 그 법을 안다. 나머지 넷은 모른다. 알려 줄 시간은 — 발소리 세 번.`,
  o:[
    { l:'① 세 번 안에 가르친다 — 손바닥 짚는 자리와 무릎 각도만.', k:'bond', dc:26, wake:1,
      ok:`말은 버리고 손으로 가르쳤다. 옆 사람 손바닥을 바닥에 눌러 짚어 주고, 무릎을 당겨 세워 주고 — 한 사람에 발소리 하나.<br><br>
        네 번째 쿵부터 다섯 몸이 바닥 울림을 타고 흘렸다. 들썩임이 사라졌다.<br>
        큰 것이 고목 옆을 지나갔다. 눈이 한 번 이쪽을 쓸었지만 — 움직이지 않는 것은 고목의 일부다.<br><br>
        몸으로 가르치는 게 말보다 빠르다는 걸 배웠다. 급할수록 입을 닫고 손을 쓸 것.`,
      ng:`셋은 배웠다. 넷째가 — 무릎 각도를 반대로 꺾었다. 다섯 번째 쿵에 그 몸만 통, 하고 튀었다.<br><br>
        큰 것의 걸음이 멎었다. 콧김이 고목 위를 훑었다.<br>
        모두 숨을 죽인 채 — 억겁 같은 시간이 지나고 걸음이 다시 멀어졌다. 넷째는 그날 밤부터 자청해서 무릎 수련을 했다. 말리지 않았다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 가르칠 시간이 없다 — 넷을 이쪽 몸 위에 겹쳐 엎드리게 한다.', k:'steady', dc:26, cost:{ qi:37 },
      ok:`울림을 흘리는 몸 하나가 바닥이 되면 된다. 고목에 등을 대고 비스듬히 엎드려 — 넷을 이쪽 등과 다리에 겹치게 했다.<br><br>
        쿵. 울림이 이쪽 손바닥과 무릎으로 들어와 — 거기서 끝났다. 위에 겹친 넷은 물 위의 배처럼 잔잔했다.<br>
        큰 것이 지나가는 열두 걸음 동안 사람 바닥 노릇을 했다. 지나고 나서 넷이 내려오자 팔다리가 한꺼번에 저렸다.<br>
        바닥이 되는 수련은 없었다. 오늘부로 생겼다.`,
      ng:`여덟 걸음까지는 바닥 노릇이 됐다. 아홉 걸음째 — 무릎 밑 돌이 깨지며 반 뼘 내려앉았다.<br><br>
        위에 겹친 넷이 한꺼번에 들썩였다. 큰 것 고개가 돌았다.<br>
        콧김이 고목을 두 번 훑고 — 갔다. 돌 하나가 다섯 목숨 값을 할 뻔했다. 바닥 노릇도 바닥 검사부터다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S2', t:'무리의 시험 — 맨 앞의 맨손',
  x:`사냥 무리 셋이 길을 막았다. 싸우자는 반원이 아니다 — 재는 반원이다. 다섯 중 누가 제일 무른지.<br><br>
    저것들 눈이 차례로 훑는다. 창. 창. 지팡이. 칼. 그리고 — 맨손.<br>
    맨손에서 눈들이 멎었다. 무기 없는 것이 제일 무르다는 계산. 가운데 놈이 맨손 쪽으로 반 걸음 디뎠다.<br><br>
    계산을 고쳐 줄 시간이다.`,
  o:[
    { l:'① 계산을 고쳐 준다 — 디딘 반 걸음에 마중 나가 콧등을 꺾는다.', k:'break', dc:26,
      doom:{ title:'재던 것들', what:'무리에게 물려 가 풀숲으로 끌려갑니다', dc:20, sec:37,
        text:`마중 나간 주먹이 콧등에 닿기 반 뼘 전 — 가운데 놈이 고개를 틀었다. 디딘 반 걸음은 미끼였다.<br><br>
          빈 주먹이 지나간 겨드랑이 밑을 어깨째 물렸다. 양옆 둘이 다리를 하나씩 맡았다.<br>
          셋이 번갈아 물며 끈다. 풀숲이 닫힌다. 무기 없는 게 무른 게 아니라 — 혼자 나온 게 무른 거였다. 계산이 틀린 건 이쪽이었다.`,
        dieText:`풀숲 어귀에 신발 한 짝과 감아 둔 주먹 붕대가 풀린 채 떨어져 있었다.<br><br>
          일행은 창을 세우고 밤을 샜다. 무리는 그날 밤 다시 오지 않았다. 올 필요가 없었다.<br>
          남은 넷은 그 뒤로 누구도 반원 앞에 혼자 나서지 않았다. 그 규칙에는 이름이 붙었다. 맨손의 값.`,
      },
      ok:`반 걸음 디딘 앞발이 땅에 앉는 순간 — 그 콧등 위로 마중 나갔다. 재는 중인 놈은 아직 싸울 몸이 아니다.<br><br>
        콧등이 옆으로 꺾이는 소리가 반원 전체에 들렸다. 가운데 놈이 주저앉아 뒷걸음질쳤다.<br>
        눈들이 다시 훑었다. 창. 창. 지팡이. 칼. 그리고 — 제일 위험한 것.<br>
        반원이 풀숲으로 녹아 사라졌다. 고쳐진 계산은 무리 전체에 퍼진다. 그게 무리의 좋은 점이다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 계산을 역이용한다 — 무른 척 뒤로 빠져, 따라 들어온 놈을 좁은 바위틈에서 받는다.', k:'hide', dc:25,
      ok:`겁먹은 척 뒷걸음질로 바위틈까지 물러났다. 가운데 놈이 신이 나서 따라 들어왔다 — 어깨가 겨우 드는 틈으로.<br><br>
        좁은 데서는 몸집이 짐이다. 끼인 어깨 위 콧등에 팔꿈치를 내리찍었다.<br>
        놈이 뒷걸음으로 빠져 달아나자 남은 둘도 물러났다. 무른 먹이가 덫이었다는 소문도 무리 전체에 퍼질 것이다.<br>
        권사의 맨손은 무기가 아니라서 — 숨길 수 있는 무기다.`,
      ng:`바위틈이 생각보다 넓었다. 놈이 끼지 않고 들어왔다.<br><br>
        좁은 데 싸움은 됐지만 덫은 못 됐다. 틈 안에서 정면으로 받았다.<br>
        밀어내긴 했다. 바위에 쓸린 등과 물린 팔뚝 — 덫 설계는 제 몸 치수가 아니라 저쪽 치수로 하는 거였다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 맨손의 권양기',
  x:`권양기 손잡이가 부러져 있다. 남은 건 톱니바퀴 축 — 쇠막대가 끼워졌던 네모 구멍뿐이다.<br><br>
    쇠막대는 없다. 손으로 축을 감아쥐고 돌리는 수밖에.<br>
    축을 돌리면 승강기가 오른다. 놓치면 — 탄 사람들째 바닥까지 떨어진다. 중간에 쉬는 수가 없는 일이다.<br><br>
    수풀의 기척들이 모여들고 있다. 두 번에 나눠 탈 시간은 없다. 넷을 태우고, 축은 이쪽이 잡는다.`,
  o:[
    { l:'① 내공을 손아귀에 모아 — 축째 감아쥐고 끝까지 돌린다.', k:'break', dc:26, wake:1, cost:{ qi:40 },
      ok:`손바닥에 침을 뱉고 축을 감아쥐었다. 내공을 손아귀와 허리에 반반 — 돌리는 건 팔이 아니라 허리다.<br><br>
        한 바퀴. 열 바퀴. 서른 바퀴째에 손바닥이 쇠에 눌어붙는 것 같았지만 놓지 않았다. 마흔두 바퀴에 위에서 닿았다는 외침.<br>
        축을 고정 고리에 걸고 — 수풀에서 나온 첫 놈의 콧등을 남은 손으로 한 대 치고 — 사다리 쪽 배관을 타고 올랐다.<br><br>
        손바닥 가죽이 반은 벗겨졌다. 대신 알았다. 쥐는 힘의 바닥이 어딘지. 생각보다 훨씬 깊었다.`,
      ng:`서른 바퀴째에 땀이 축으로 흘렀다. 손아귀가 반 뼘 미끄러지며 — 승강기가 반 층 떨어졌다. 비명.<br><br>
        이를 악물고 다시 감아쥐었다. 떨어진 반 층을 도로 감는 동안 수풀 첫 놈이 나왔다.<br>
        위에 닿자마자 축을 걸고 발길질로 놈을 밀어내며 배관을 탔다. 손바닥에 쇠 네모 자국이 도장처럼 찍혀 한동안 안 지워졌다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, mind:-15 } },
    { l:'② 축을 돌리지 않는다 — 승강기 밑에 들어가 어깨로 밀어 올린다.', k:'steady', dc:26,
      ok:`권양기가 못 미더우면 직접 드는 수가 있다. 승강로 벽의 가로 보를 디딤 삼아 — 승강기 바닥을 어깨로 받치며 한 단씩 밀어 올렸다.<br><br>
        어깨로 한 단, 보를 바꿔 디디고 또 한 단. 위에서 넷이 창살을 붙들고 숨을 죽였다.<br>
        아홉 단. 위 문턱에 걸리는 소리가 나자 넷이 기어 나갔고, 이쪽도 보를 타고 올랐다.<br>
        밑에서 올려다보던 것들은 끝내 승강로에 안 들어왔다. 쇠 상자가 혼자 올라가는 광경이 저것들 눈에는 — 큰 것의 짓으로 보였을지도 모른다.`,
      ng:`여섯 단째에 디딘 보가 삭아 부러졌다. 승강기 무게가 통째로 어깨에 얹혔다.<br><br>
        무릎이 꺾이기 직전 옆 보로 발을 옮겼다. 반 단을 도로 내려 보내고 — 거기서부터 다시.<br>
        다 올리고 나서 어깨를 보니 창살 자국이 깊게 패여 있었다. 쇠 상자 하나 무게를 어깨가 다 외웠다. 잊고 싶은 암기였다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S2', t:'새끼 입 — 벌리는 손',
  x:`막내 발목을 갓 깬 새끼가 물었다. 주먹만 한 것 — 그런데 턱이 안 열린다. 태어나며 처음 문 것은 안 놓는 턱이라고 한다.<br><br>
    잡아떼면 발목 살이 한 움큼 같이 떨어진다. 칼을 대면 새끼 피가 — 이 종은 새끼 피 냄새가 어미를 부른다.<br>
    남은 길은 턱을 여는 것이다. 부수지 않고, 피 내지 않고.<br><br>
    턱에는 무는 근육과 벌리는 근육이 따로 있다. 무는 쪽은 쇠 같고, 벌리는 쪽은 — 어느 짐승이나 종잇장이다.`,
  o:[
    { l:'① 턱 관절 뒤 벌리는 근을 눌러 — 스스로 벌리게 한다.', k:'break', dc:25, wake:1,
      ok:`새끼 턱 관절 뒤 — 귀밑 옴폭한 자리를 엄지 두 개로 지그시 눌렀다. 무는 힘과 싸우지 않고, 벌리는 쪽 문만 두드렸다.<br><br>
        턱이 하품하듯 열렸다. 발목이 빠졌다. 새끼는 영문을 모르고 허공을 두 번 더 물었다.<br>
        피 한 방울 없이 끝났다. 새끼는 둥지 쪽으로 던져 돌려보냈다.<br><br>
        제일 센 근육과는 싸우지 않는다. 그 옆의 제일 약한 근육을 찾는다 — 이 손버릇은 사람 아닌 것한테도 통한다는 걸 확인했다.`,
      ng:`누르는 자리가 손가락 하나 비껴났다. 새끼가 아파서 — 더 물었다.<br><br>
        막내 비명이 커졌다. 두 번째에 자리를 찾아 열었지만, 이빨이 들어갔다 나온 자리가 깊어졌다.<br>
        발목을 싸매고 업었다. 새끼 울음에 멀리서 대답이 오기 전에 그 자리를 떴다. 반 박자 급했던 엄지 값이다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 새끼 코를 막는다 — 숨 쉬려면 입을 열어야 한다.', k:'gaze', dc:25,
      ok:`새끼를 관찰했다 — 콧구멍이 턱 위에 둘. 물고 있는 동안 숨은 코로만 쉰다.<br><br>
        콧구멍 둘을 손가락으로 막았다. 셋을 세기 전에 턱이 벌컥 열렸다. 숨과 고집 중에 숨이 이겼다.<br>
        발목이 빠지자 손을 뗐다. 새끼가 켁켁대며 이쪽을 노려봤다. 노려보는 건 공짜다.<br>
        막내가 절뚝이며 물었다. 어떻게 알았느냐고. 무는 것들은 다 그렇다. 입이 바쁘면 코가 목숨줄이다.`,
      ng:`콧구멍인 줄 눌렀던 것이 — 콧구멍이 아니라 독샘 구멍이었다. 손끝이 얼얼해졌다.<br><br>
        손가락 둘이 한나절 곱았다. 새끼는 둘째 시도 — 진짜 콧구멍 — 에 입을 열었다.<br>
        막내는 빠졌고 이쪽 손가락이 값을 치렀다. 남의 얼굴 지도는 함부로 믿지 말 것. 특히 백악기 얼굴은.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S2', t:'진흙 구덩이 — 끄는 힘과 버티는 힘',
  x:`마른 땅인 줄 밟은 자리가 — 진흙이다. 무릎까지 한 번에. 그리고 진흙 밑에서 발목을 감는 것이 있다.<br><br>
    이 구덩이에 사는 것이다. 빠진 것을 밑에서 당겨 재우는 사냥법.<br>
    당기는 힘이 일정하다. 서두르지 않는다. 빠진 쪽이 버둥댈수록 깊어지는 걸 아는 힘이다.<br><br>
    버둥대지 않고 이기는 법을 아는 쪽이 이긴다.`,
  o:[
    { l:'① 버티지 않고 — 당기는 힘을 타고 내려가 발목 감은 것을 발로 찍는다.', k:'break', dc:26, cost:{ qi:36 },
      doom:{ title:'진흙 밑의 것', what:'진흙 밑으로 끌려 들어갑니다', dc:19, sec:38,
        text:`당기는 힘을 타고 반 길 내려가 — 감은 것의 몸통을 발꿈치로 찍었다. 찍었다. 분명 찍었는데, 몸통이 하나가 아니었다.<br><br>
          둘째 몸통이 허리를 감았다. 셋째가 가슴을. 구덩이 하나에 한 마리라는 법은 없었다.<br>
          진흙이 턱까지 온다. 위에서 일행 손들이 어깨를 붙들었다 — 당기는 힘과 붙드는 힘 사이에서 몸이 밧줄이 된다. 진흙이 귀를 덮으며 소리가 멀어진다.`,
        dieText:`진흙이 잠잠해진 뒤에도 일행은 한참 구덩이 가장자리를 붙들고 있었다.<br><br>
          해 질 녘 구덩이 한가운데 거품이 한 번 크게 올라왔다 꺼졌다.<br>
          그 길에는 돌아올 때 돌무더기 표지를 세웠다. 마른 땅처럼 보이는 것 — 이라고 새길 줄 아는 사람이 없어, 그냥 돌을 높이 쌓았다.`,
      },
      ok:`당기는 힘에 맞버티는 대신 — 그 힘을 타고 몸을 접어 내려갔다. 저쪽 계산에 없는 방향.<br><br>
        발목을 감은 몸통이 손에 잡혔다. 미끈한 관 같은 것 — 내공 실은 발꿈치로 그 한가운데를 찍었다.<br>
        감은 것이 풀리며 진흙 깊은 데로 움츠러들었다. 일행이 내민 창대를 잡고 빠져나왔다.<br>
        온몸이 진흙 반 사람 반이었다. 씻을 물이 아깝지 않은 하루였다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 둘이 한 몸으로 — 일행과 팔을 걸어 사다리가 되어 빠져나온다.', k:'bond', dc:25,
      ok:`버둥대면 둘 다 빠진다. 가장 가까운 일행과 팔꿈치를 서로 걸어 — 한쪽이 당길 때 한쪽은 바닥 노릇을 하는 두 박자를 맞췄다.<br><br>
        당기고, 버티고. 당기고, 버티고. 발목 감은 것이 두 박자 힘을 못 이기고 놓았다.<br>
        마른 땅에 둘이 한 덩이로 굴러 나왔다.<br>
        혼자면 힘이고 둘이면 박자다. 진흙 묻은 팔꿈치 인사를 나눴다.`,
      ng:`두 박자가 세 번째에서 어긋났다. 당길 사람이 같이 당겨져 — 둘 다 허리까지 빠졌다.<br><br>
        남은 일행 셋이 창대 두 개를 걸쳐 주고서야 차례로 나왔다.<br>
        발목의 것은 끝까지 얼굴을 안 보여 줬다. 진흙 속에서 뭔가가 아쉬워하는 거품만 올라왔다. 박자 연습은 마른 땅에서 미리 해 둘 것.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] }

]);

// ------------------------------------------
// 폭파공 · (자원 없음)
// ------------------------------------------
kJob('blaster', 'S', [

{ at:'S', t:'소리의 값 — 눌러 터뜨리는 법',
  x:`여기서 폭음 한 번은 저녁 종이다. 울리는 순간 이 구역 모든 것이 이쪽 자리를 안다.<br><br>
    그래도 벽은 깨야 한다. 뒤가 막혔고 앞은 벽돌 한 장 반.<br>
    장약을 벽에 그냥 붙이면 소리 반, 일 반이다. 소리를 일로 바꾸는 법 — 덮는 것이다. 젖은 흙과 짐으로 장약을 눌러, 터지는 힘이 벽으로만 가게.<br><br>
    덮을 것이 마땅치 않다. 일행 배낭과 벗은 겉옷들, 그리고 물통의 물이 전부다.`,
  o:[
    { l:'① 배낭과 젖은 옷으로 장약을 눌러 — 소리를 벽에 삼키게 한다.', k:'break', dc:25, wake:1,
      ok:`장약을 벽 아랫단 줄눈에 붙이고, 물 먹인 겉옷 세 벌과 배낭으로 겹겹이 눌렀다. 다지는 손끝에 장약이 숨죽는 게 느껴진다.<br><br>
        터졌다 — 폭음이 아니라 둔한 기침 소리. 벽돌이 저쪽으로 한 아름 빠졌다.<br>
        어둠 속 기척들이 움찔하고는 — 자리를 못 잡았다. 기침 소리는 방향이 없다.<br><br>
        소리는 낭비된 힘이다. 조용한 폭파일수록 좋은 폭파다. 스승 말이 여기서는 목숨 값이었다.`,
      ng:`덮는 짐이 반 뼘 모자랐다. 터지는 힘이 덮개 틈으로 소리가 되어 샜다.<br><br>
        벽은 뚫렸다. 소리도 났다. 반값 소리지만 — 들을 귀들한테는 충분했다.<br>
        뚫린 구멍으로 서둘러 빠지며 뒤로 접근하는 발소리들을 들었다. 못 덮은 반 뼘이 쫓기는 반나절이 됐다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } },
    { l:'② 소리를 아예 판다 — 벽 말고 반대쪽 멀리에 헛폭음을 하나 심는다.', k:'break', dc:26,
      ok:`작은 장약 하나를 긴 심지에 달아 들어온 길 끝으로 굴려 보냈다. 그리고 벽 장약에 불을 붙였다.<br><br>
        헛폭음이 먼저 — 쾅. 기척들이 일제히 그쪽으로 쏠리는 소리. 세 호흡 뒤 이쪽 벽이 둔하게 뚫렸다.<br>
        모든 귀가 첫 소리를 기억한다. 둘째 소리는 메아리로 치는 법이다.<br>
        기척들이 헛폭음 자리에서 서로를 의심하는 동안 구멍을 넘었다.`,
      ng:`헛폭음 심지가 중간에 죽었다. 굴러가다 물웅덩이를 지난 모양이다.<br><br>
        벽 폭파만 외로이 울렸다. 위치가 그대로 찍혔다.<br>
        구멍을 넘어 한참을 달렸다. 심지는 굴리기 전에 길바닥부터 봐야 한다는 걸 — 물값으로 배웠다.`,
      win:{ exp:21, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'심지 — 세 호흡짜리',
  x:`놈이 길목을 지킨다. 영리한 종류다. 던진 돌에는 꿈쩍도 안 하고, 사람 걸음에만 몸을 낮춘다.<br><br>
    장약을 던져 넣을 틈은 놈이 고개를 돌리는 순간 — 길어야 세 호흡.<br>
    심지 한 치면 다섯 호흡. 세 호흡이면 반 치가 넘고 반의반 치는 모자란다. 그 사이 어딘가를 — 손끝과 가위가 정해야 한다.<br><br>
    길게 자르면 놈이 장약을 보고 피한다. 짧게 자르면 이쪽 손에서 터진다.`,
  o:[
    { l:'① 세 호흡에 맞춰 자른다 — 손이 기억하는 그 길이로.', k:'break', dc:26,
      doom:{ title:'손안의 불', what:'불붙은 장약과 함께 길목에 고립됩니다', dc:19, sec:35,
        text:`심지가 생각보다 빨리 탔다 — 속심이 삭아 불길이 안으로 먼저 달린 것이다. 던질 손이 반 호흡 늦었다.<br><br>
          장약은 손을 떠났다. 떠난 자리가 문제다 — 놈과 이쪽 사이 한가운데. 피아 구분 없는 자리.<br>
          몸을 던진 바위 뒤가 얕다. 놈도 같은 바위 반대편에 몸을 붙였다. 장약 하나를 사이에 두고 — 터지면 바위째 둘 다다. 심지 타는 소리만 또렷하다.`,
        dieText:`폭음 뒤 바위는 두 쪽이 나 있었다.<br><br>
          놈은 제 쪽 반 토막 밑에서, 폭파공은 — 일행은 그쪽 반 토막을 사흘은 못 봤다.<br>
          남긴 장약통은 막내가 물려받았다. 통 안쪽 뚜껑에 손글씨가 있었다. 심지는 눈으로 믿지 말고 태워 보고 믿을 것. 물려받은 막내가 평생 지킨 한 줄이 됐다.`,
      },
      ok:`출발 전에 같은 두름 심지 한 토막을 태워 속도를 쟀다 — 오늘 심지는 평소보다 빠르다. 그만큼 길게 잡고 세 호흡 길이로 잘랐다.<br><br>
        놈이 고개를 돌리는 순간 — 하나, 던지고. 둘, 구르고. 셋에 터졌다. 놈 발밑 정중앙.<br>
        길목이 열렸다. 심지는 눈대중이 아니라 그날그날 재는 것. 화약은 날씨를 탄다.<br>
        지나가며 놈이 있던 자리를 봤다. 안 봤으면 좋았을 것까지는 아니고 — 일이 깔끔했다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 심지를 안 쓴다 — 돌 밑에 장약을 깔고, 놈이 밟게 길을 몬다.', k:'gaze', dc:25,
      ok:`놈이 몸을 낮출 때 디디는 발자리 — 세 번 다 같은 돌이었다. 버릇 있는 짐승이다.<br><br>
        그 돌 밑에 충격식 뇌관을 깔고, 일행 하나가 걸음 소리를 내 줬다.<br>
        놈이 몸을 낮췄다. 버릇대로. 돌이 울었다.<br>
        심지 없는 폭파는 때를 저쪽이 정한다 — 저쪽 버릇이 심지인 셈이다. 버릇 없는 놈한테는 못 쓰는 수라, 버릇부터 읽는 눈이 먼저다.`,
      ng:`뇌관을 까는 사이 바람이 바뀌었다. 화약 냄새가 길목으로 흘렀다.<br><br>
        놈이 돌을 안 밟고 — 돌을 피해 크게 돌았다. 화약 냄새를 아는 놈이었다.<br>
        깔아 둔 돌만 아깝게 됐다. 회수는 못 한다. 깔아 둔 자리를 지도에 그려 두고 다른 길로 돌았다. 이 구역 어딘가에 이쪽 화약 버릇도 읽혔을 것이다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-17 } }
  ] },

{ at:'S', t:'등 뒤를 끊는 일',
  x:`따돌릴 수 없는 무리다. 속도도 코도 저쪽이 위다. 남은 수는 길 자체를 끊는 것.<br><br>
    지나온 복도 천장 — 보가 셋. 가운데 보가 금 간 채 매달려 있다. 저것 하나면 복도가 메워진다.<br>
    문제는 무너지는 방향과 양이다. 적게 무너지면 틈이 남고, 많이 무너지면 이쪽 천장까지 온다.<br><br>
    발소리들이 복도 어귀에 닿았다. 셈할 시간은 심지 하나 길이.`,
  o:[
    { l:'① 가운데 보 뿌리에만 — 꼭 복도 폭만큼만 내려앉힌다.', k:'break', dc:26, wake:1,
      ok:`금 간 보의 뿌리 — 벽에 물린 자리에 장약 반 줌을 붙였다. 많이도 말고 — 보가 제 무게로 꺾일 만큼만.<br><br>
        터지자 보가 꺾이고, 천장이 복도 폭 꼭 그만큼 주저앉았다. 흙과 벽돌의 마개.<br>
        마개 너머에서 발소리들이 긁고 파는 소리가 밤새 났다. 파는 속도보다 이쪽 걷는 속도가 빨랐다.<br><br>
        무너뜨리는 일은 많이가 아니라 — 꼭 맞게다. 반 줌의 셈이 손에 남았다.`,
      ng:`반 줌이 한 줌에 가까웠다. 보가 꺾이며 옆 보까지 끌고 내려왔다.<br><br>
        무너짐이 이쪽으로 세 걸음 넘어왔다. 막내가 발목까지 묻혀 — 셋이 파냈다.<br>
        길은 끊었다. 이쪽 천장에도 금이 새로 갔다. 그 밑을 지나는 동안 아무도 천장에서 눈을 못 뗐다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 길을 안 끊고 — 어귀에 발 걸리는 실폭약 한 줄만 치고 간다.', k:'fix', dc:25,
      ok:`복도 어귀 무릎 높이에 가는 실을 매고 작은 장약을 걸었다. 죽이는 양이 아니라 — 놀라는 양.<br><br>
        반 시진 뒤 등 뒤 멀리서 퍽, 하고 울렸다. 그리고 무리가 멎는 기척.<br>
        한 번 걸린 길은 저것들한테 전부 의심길이 된다. 걸음마다 바닥을 보느라 추격 속도가 반으로 줄었다.<br>
        죽이지 못해도 늦출 수는 있다. 늦추는 게 이기는 길일 때가 있다.`,
      ng:`실을 너무 낮게 쳤다. 선두 놈이 실 밑으로 — 코를 땅에 붙이고 다니는 놈이었다.<br><br>
        장약은 셋째 놈 발에 터졌다. 무리가 멎기는 했는데, 성난 쪽으로 멎었다.<br>
        추격이 빨라졌다. 결국 좁은 틈을 골라 몸으로 막아서며 밤을 샜다. 덫은 저쪽 걸음버릇에 맞춰 치는 것 — 높이부터.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S', t:'화약 장부 — 남은 것의 셈',
  x:`장약 주머니를 털어 셌다. 벽 깰 분량 둘, 길 끊을 분량 하나, 놀래킬 분량 넷.<br><br>
    남은 길은 짐작도 안 되는데 장부는 이게 전부다. 여기서부터는 터뜨릴 자리를 고르는 게 아니라 — 안 터뜨릴 자리를 고르는 일이다.<br>
    일행이 막힌 문 앞에서 이쪽을 본다. 문은 두껍지 않다. 장약이면 금방이다.<br><br>
    금방이지. 금방이 문제가 아니다.`,
  o:[
    { l:'① 장부를 지킨다 — 문은 경첩을 갈아 딴다. 화약은 화약만 할 수 있는 일에.', k:'steady', dc:25, wake:1,
      ok:`문 경첩 핀을 줄로 갈아 뽑았다. 반 시진 — 장약이면 세 호흡인 일이다.<br><br>
        일행이 답답해했다. 참았다. 문이 열리고, 그 너머 통로에서 — 쇠문 세 개와 내려앉은 천장 하나를 더 만났다. 전부 화약 일이었다.<br>
        장부가 꼭 맞게 비었다. 마지막 통로가 열렸을 때 주머니에는 놀래킬 분량 하나가 남아 있었다.<br><br>
        폭파공의 반은 화약이고 반은 장부다. 안 쓰는 셈이 제일 어려운 셈이라는 걸 — 문 네 개가 가르쳤다.`,
      ng:`경첩을 반쯤 갈았을 때 복도 끝에서 기척이 왔다. 반 시진이 사치가 됐다.<br><br>
        결국 장약을 붙였다. 벽 깰 분량 하나가 문 하나에 나갔다.<br>
        나중에 진짜 벽을 만났을 때 그 분량이 모자랐다. 벽 반 장을 손과 쇠지레로 마저 허무는 데 밤이 샜다. 장부는 어긋난 자리에서 꼭 이자를 받는다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 장부를 늘린다 — 이 구역 어딘가의 옛 공사장 화약고를 찾는다.', k:'luck', dc:25,
      ok:`벽의 배선과 바닥 레일 자국 — 여기는 지은 지 얼마 안 돼 버려진 구역이다. 짓다 만 데는 공사 화약이 남는다.<br><br>
        레일을 거슬러 반 층 아래 — 자물쇠 달린 철궤를 찾았다. 자물쇠는 녹이 먼저 땄다.<br>
        공업 뇌관 한 묶음과 방수포에 싸인 화약 두 덩이. 장부가 배로 늘었다.<br>
        궤 바닥에 먼저 다녀간 이의 쪽지가 있었다. 반은 두고 감. 다음 사람 몫. — 그래서 이쪽도 반만 챙겼다.`,
      ng:`레일을 거슬러 간 반 층 아래는 화약고가 아니라 — 둥지였다. 뭔가의.<br><br>
        마른 풀과 뼈 무더기. 그리고 주인이 마침 들어오는 길이었다.<br>
        좁은 계단을 거꾸로 뛰어 올라오며 놀래킬 분량 하나를 계단에 깔았다. 퍽, 소리에 주인이 멈칫한 덕에 따돌렸다. 장부를 늘리려다 한 줄 더 썼다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'던질 수 없는 거리',
  x:`덮쳐 오는 놈과의 거리가 — 던지기엔 가깝고 버리고 뛰기엔 늦다.<br><br>
    장약은 손안에 있다. 심지는 이미 탄다. 폭파공이 제일 싫어하는 그림이다. 불붙은 장약과 적과 내가 한 호흡 안에 있는 그림.<br>
    교본에는 이럴 때의 답이 없다. 교본 쓴 사람은 여기 안 와 봤다.<br><br>
    놈의 입이 벌어진다. 크게. 통째로 삼키는 종류다.`,
  o:[
    { l:'① 입 안으로 — 던지는 게 아니라 먹인다.', k:'break', dc:26,
      ok:`벌어진 입에 장약을 — 던지지 않고 들이밀었다. 삼키는 종류는 입에 든 걸 거절 못 한다.<br><br>
        놈이 덥석 물고 — 이쪽은 뒤로 굴렀다. 두 바퀴 반.<br>
        둔한 폭음이 놈의 몸속에서 났다. 밖으로 샐 소리까지 놈이 다 삼켰다. 가장 조용한 폭파가 됐다.<br>
        일어나 먼지를 털며 생각했다. 교본에 한 줄 보태야 한다. 거리가 없으면 거리를 버려라.`,
      ng:`들이미는 손보다 놈의 고개가 빨랐다. 장약이 입을 스쳐 바닥에 굴렀다.<br><br>
        놈과 이쪽이 동시에 장약을 봤다. 동시에 반대로 뛰었다.<br>
        폭음 — 둘 다 무사했다. 바닥만 움푹 패었다. 놈은 그 소리에 물러갔으니 본전은 넘었는데, 손이 한동안 떨려 심지를 못 잘랐다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-16 } },
    { l:'② 장약을 발밑에 놓고 — 놈과 장약 사이에서 몸만 비킨다.', k:'evade', dc:26,
      ok:`심지 타는 장약을 발밑에 — 두고, 덮치는 놈의 코앞에서 옆으로 몸을 던졌다.<br><br>
        놈의 눈은 몸을 좇았다. 발은 장약 위를 디뎠다.<br>
        폭음과 함께 놈이 모로 넘어갔다. 이쪽은 구른 어깨만 털었다.<br>
        미끼가 몸이고 덫이 발밑인 싸움 — 다시는 안 하고 싶지만, 다시 하면 또 이렇게 할 것이다.`,
      ng:`몸을 던지는 쪽을 놈이 반 박자 먼저 읽었다. 덮치는 방향이 꺾였다.<br><br>
        장약은 빈 데서 터지고, 놈의 앞발이 구르는 이쪽 등을 긁었다.<br>
        폭음에 놀란 놈이 물러난 게 그나마의 수확이다. 등의 세 줄 긁힌 자국은 — 반 박자의 값이다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-33, spirit:-15 } }
  ] },

{ at:'S', t:'버티는 벽, 버리는 벽',
  x:`무너진 홀이다. 지나가려면 기운 벽 하나를 마저 허물어야 한다. 문제는 그 벽이 — 뭘 받치고 있느냐다.<br><br>
    폭파공 눈에 벽은 두 종류다. 버티는 벽과 그냥 선 벽. 잘못 읽고 허물면 천장이 통째로 온다.<br>
    벽을 짚어 보고, 금 간 결을 보고, 천장 보가 어디서 내려와 어디에 앉는지 — 눈으로 하중의 길을 그린다.<br><br>
    이 벽은… 양쪽 다다. 반은 버티고 반은 그냥 섰다.`,
  o:[
    { l:'① 하중의 길을 그려 — 그냥 선 반쪽만 도려 허문다.', k:'gaze', dc:26, wake:1,
      ok:`천장 보의 무게가 벽 왼쪽 어깨로 내려오는 게 보였다. 오른쪽 반은 짐을 안 진 벽이다.<br><br>
        오른쪽 아랫단 세 자리에만 장약을 콩알로 나눠 붙였다. 터지자 오른쪽 반이 주저앉고 — 왼쪽 반은 어깨에 짐을 진 채 그대로 섰다.<br>
        사람 하나 지날 아치가 남았다. 일행이 그 밑을 지나며 벽을 올려다봤다. 안 무너진다. 짐 진 벽은 쉽게 안 죽는다.<br><br>
        부수는 눈의 반은 안 부술 데를 보는 눈이다. 하중의 길이 지도처럼 보이기 시작했다.`,
      ng:`하중의 길을 하나 놓쳤다 — 벽 속에 숨은 덧기둥. 오른쪽 반이 주저앉으며 그 덧기둥을 쳤다.<br><br>
        천장 모서리가 한 귀퉁이 내려왔다. 전원이 먼지 속에서 뒹굴었다.<br>
        구멍은 났고 다 지나긴 했다. 벽 속까지 보는 눈은 아직이라는 것 — 두드려 보는 손이 눈을 보완해야 한다는 것을 먼지째 삼켰다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 허물지 않는다 — 벽 밑동에 사람 하나 구멍만 조심히 딴다.', k:'fix', dc:25,
      ok:`버티는 벽은 건드리지 않는 게 일급이다. 밑동 벽돌을 줄눈 따라 한 장씩 — 화약 없이 정과 손으로 땄다.<br><br>
        여덟 장을 빼내자 배로 기는 구멍이 났다. 하중의 길에서 가장 먼 구석이라 벽은 끄떡없다.<br>
        한 사람씩 기어 지났다. 느리고, 조용하고, 안전한 길.<br>
        화약 없이 지난 벽도 폭파공의 일이다. 쓴 화약보다 아낀 화약이 실력일 때가 있다.`,
      ng:`여섯 장째에서 벽돌이 부서지며 손이 미끄러졌다. 안쪽 벽돌 한 장이 홀 바닥에 떨어져 — 크게 울렸다.<br><br>
        홀 건너 어둠에서 대답이 왔다. 남은 두 장을 급히 따고 구멍으로 밀어 넣듯 일행을 통과시켰다.<br>
        마지막 사람 발이 빠지는 순간 구멍 밖에서 콧김이 닿았다. 조용한 길도 끝까지 조용해야 조용한 길이다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S', t:'알 무더기 앞에서 — 쓰지 않는 손',
  x:`길목의 알 무더기. 치우자면 장약 반 줌이면 된다. 손이 벌써 주머니로 간다.<br><br>
    가다가 멈췄다. 폭음은 알을 치우고 — 어미를 부른다. 그리고 알 무더기 밑이 비었으면 길까지 꺼진다.<br>
    폭파공의 손버릇은 여기서 독이다. 모든 문제가 못이면 손에 든 게 망치라서다.<br><br>
    망치를 주머니에 도로 넣는 손이 — 오늘의 기술이다.`,
  o:[
    { l:'① 장약 대신 지렛대 — 알 밑에 판자를 넣어 무더기째 옆으로 민다.', k:'steady', dc:25, wake:1,
      ok:`부서진 문짝을 알 무더기 밑에 비집어 넣고 — 무더기째 천천히 길 옆으로 밀었다. 알끼리 부딪치지 않는 속도로.<br><br>
        길이 났다. 알은 하나도 안 깨졌다. 폭음도 없다. 어미가 와도 — 알이 무사하니 쫓을 이유가 반으로 준다.<br>
        지나고 나서 판자를 도로 빼 줬다. 왜 그러느냐는 일행 물음에 — 글쎄. 무사한 알한테는 무사한 받침이 어울려서.<br><br>
        장약 없이 푼 문제를 장부 뒷장에 적었다. 그 장이 제일 빨리 채워지는 폭파공이 좋은 폭파공이다.`,
      ng:`무더기가 반쯤 밀렸을 때 판자가 삭아 부러졌다. 알 둘이 굴러 — 하나가 금 갔다.<br><br>
        금 간 알에서 냄새가 샜다. 멀리서 우는 대답.<br>
        남은 알들을 급히 밀어 길을 내고 뛰었다. 어미는 금 간 알 앞에 멈춰 이쪽을 오래 봤다고, 맨 뒤 일행이 말했다. 쫓아오지는 않았다. 그게 더 무거웠다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-17, spirit:-17 } },
    { l:'② 꼭 치울 알만 — 무더기 꼭대기 세 알만 실로 걷어 내린다.', k:'luck', dc:25,
      ok:`길을 막는 건 사실 꼭대기 세 알이다. 나머지는 몸을 숙이면 지난다.<br><br>
        갈고리 실을 던져 세 알을 하나씩 걸어 — 굴리지 않고 들어 내렸다. 옆 움푹한 자리에 차곡차곡.<br>
        몸을 숙여 하나씩 지났다. 알 무더기는 거의 그대로다. 지나간 자국도 거의 없다.<br>
        제일 작은 일로 푸는 버릇 — 화약쟁이가 제일 늦게 배우고 제일 오래 쓰는 버릇이다.`,
      ng:`둘째 알이 실에서 미끄러졌다. 무더기 허리에 떨어져 — 둔한 소리.<br><br>
        깨지진 않았다. 대신 무더기 전체가 낮게 울렁였다. 안의 것들이 깨는 울렁임.<br>
        숙일 틈 없이 무더기 옆을 뛰어 지났다. 등 뒤에서 젖은 것 깨지는 소리가 둘, 셋. 어미 몫의 숙제를 두고 온 셈이다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'빛의 폭파 — 눈을 치는 장약',
  x:`어둠 속의 것들은 어둠에 눈이 열려 있다. 열린 눈은 — 약점이다.<br><br>
    장약 중에 섬광제가 반 줌 있다. 터지는 힘은 콩알이고 빛은 대낮인 물건.<br>
    문제는 이쪽 눈도 눈이라는 것. 터지는 순간 눈을 감는 쪽과 뜨고 있는 쪽의 싸움이 된다.<br><br>
    포위되기 반 걸음 전이다. 쓸 거면 지금이다.`,
  o:[
    { l:'① 전원 눈 감아 — 신호에 맞춰 섬광을 바닥에 때린다.', k:'break', dc:25, wake:1,
      ok:`감아! — 외침과 동시에 섬광제를 바닥에 때렸다. 감은 눈꺼풀 너머로도 세상이 하얘지는 빛.<br><br>
        뜨고 있던 눈들의 비명이 사방에서 났다. 어둠에 열린 눈일수록 깊이 베이는 빛이다.<br>
        눈을 뜨고 — 더듬대는 것들 사이를 질러 포위를 나왔다. 저것들 눈이 돌아오기까지 백 걸음은 벌었다.<br><br>
        빛도 장약이다. 다치는 자리가 살이 아니라 눈일 뿐. 장부에 섬광제 칸을 새로 팠다.`,
      ng:`외침과 때리는 손이 반 호흡 어긋났다. 일행 둘이 눈을 덜 감았다.<br><br>
        포위는 뚫었는데 — 둘이 앞이 안 보여 이쪽 어깨를 잡고 뛰었다. 세 사람 눈으로 다섯이 뛰는 길.<br>
        반나절 뒤에야 둘의 눈이 돌아왔다. 신호는 외침보다 어깨 두드림 — 소리는 급할 때 꼭 반 호흡 늦는다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 섬광을 아끼고 — 포위 반대편에 소리 장약을 까 길을 연다.', k:'break', dc:26,
      ok:`포위라는 건 머릿수가 금인 그림이다. 금 제일 얇은 데 — 반대편 구석에 소리 장약을 던졌다.<br><br>
        쾅. 저것들 머리가 일제히 그쪽으로 돌았다. 포위가 한쪽으로 쏠리며 이쪽 금이 터졌다.<br>
        터진 금으로 다섯이 빠졌다. 섬광제 반 줌은 주머니에 그대로다.<br>
        소리로 풀리는 판에 빛까지 쓸 건 없다. 비싼 패는 비싼 판에.`,
      ng:`던진 장약이 기둥에 맞고 가까이 떨어졌다. 소리가 이쪽 반 포위 쪽에서 났다.<br><br>
        저것들이 소리와 이쪽을 한 그림으로 읽었다. 포위가 되레 좁혀졌다.<br>
        결국 섬광제까지 마저 썼다. 패 두 장으로 풀 판을 석 장 쓴 셈 — 살아 나온 게 남는 장사라고 치기로 했다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'S', t:'젖은 화약 — 품는 밤',
  x:`물길을 건너다 미끄러졌다. 몸은 건졌는데 — 화약 주머니가 반이나 젖었다.<br><br>
    젖은 화약은 돌덩이다. 말리면 돌아온다. 불에 말리면 — 말리다 다 같이 하늘로 간다.<br>
    남은 방법은 하나다. 몸. 품에 안고 체온으로 밤새 말리는 것. 폭파공들이 웃으면서 하는 말이 있다. 화약은 애인처럼 품어야 돌아온다고.<br><br>
    웃을 일이 아닌 게, 오늘 밤 불침번 교대 중에도 품고 있어야 한다.`,
  o:[
    { l:'① 밤새 품는다 — 뒤척이지 않는 잠을 자며.', k:'steady', dc:25, wake:1,
      ok:`가슴과 배에 화약 꾸러미를 나눠 붙이고 겉옷을 여몄다. 눕는 각도를 정하고 — 그 각도로만 잤다.<br><br>
        새벽에 꾸러미를 열었다. 보슬보슬. 돌덩이가 가루로 돌아왔다.<br>
        일행이 신기해했다. 잠버릇까지 고치는 직업이냐고. 고쳐진다. 품은 게 화약이면.<br><br>
        화약을 품는 밤이 폭파공을 만든다던 스승 말 — 농담인 줄 알았는데 수련법이었다. 몸이 화약 시중드는 법을 배웠다.`,
      ng:`새벽녘에 — 뒤척였다. 꿈에 뭐가 나와서.<br><br>
        꾸러미 하나가 등 밑에 깔려 눌렸다. 눌린 화약은 덩이로 굳는다. 반 줌이 못 쓰게 됐다.<br>
        남은 반 줌은 살렸다. 못 쓰게 된 덩이는 — 버리지 않고 챙겼다. 굳은 화약도 불쏘시개는 된다. 폭파공 장부에 버리는 칸은 없다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 밤을 안 기다린다 — 달군 돌 위 함석판에 펴서 저녁 안에 말린다.', k:'fix', dc:26,
      ok:`불가의 달군 돌을 꺼내 식기를 기다렸다 — 손을 대고 셋을 셀 수 있는 온도까지. 그 위에 함석판, 그 위에 화약을 종잇장처럼 얇게 폈다.<br><br>
        뒤집개로 저어 가며 반 시진. 돌이 식으면 다음 돌. 불과 화약 사이에 돌과 함석 — 두 겹의 거리를 끝까지 지켰다.<br>
        저녁 안에 전부 말랐다. 품는 밤보다 빠르고, 자는 동안 장부 걱정이 없다.<br>
        일행은 그 반 시진 동안 저만치 가 있었다. 서운하지 않았다. 그게 예의다.`,
      ng:`셋째 돌이 — 겉만 식은 돌이었다. 함석판 가운데가 달아올랐다.<br><br>
        화약이 쉭, 하고 한 귀퉁이 타올랐다. 판째 뒤집어 흙을 덮었다.<br>
        터지지는 않았다. 판 위의 반 줌이 연기가 됐을 뿐. 돌 온도는 가운데를 재야 한다 — 눈썹 반쪽 값으로 배웠다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-25, mind:-15 } }
  ] },

{ at:'S', t:'무너짐의 소리 — 먼저 듣는 귀',
  x:`천장에서 모래가 한 줄 흘렀다. 일행은 아무도 못 봤다. 폭파공 눈에만 걸렸다.<br><br>
    무너지는 건물은 무너지기 전에 말을 한다. 모래 한 줄, 삐걱 소리의 간격, 문틀이 문을 무는 정도.<br>
    이 홀은 — 말이 많다. 너무 많다. 들보가 울고 기둥 셋 중 하나가 어깨를 틀었다.<br>
    쫓아오는 것들이 홀 입구에 닿기 전에, 다섯이 홀을 건너야 한다. 건물의 말을 들으면서.`,
  o:[
    { l:'① 건물의 말을 통역한다 — 디딜 데와 디디면 안 될 데를 외치며 선두로.', k:'sense', dc:26, wake:1,
      ok:`왼쪽 벽 붙어! 가운데 금지! 들보 밑 셋씩 끊어서! — 건물이 하는 말을 사람 말로 바꿔 외치며 앞장섰다.<br><br>
        다섯이 홀을 건넜다. 건너는 동안 가운데 바닥이 — 디디지 말라던 그 자리가 — 혼자 내려앉았다.<br>
        입구에 닿은 것들은 그 구멍 앞에서 멈췄다. 건너올 길을 저쪽은 모른다. 건물 말을 못 알아듣는 것들이라.<br><br>
        폭파공은 무너뜨리는 사람이기 전에 무너짐을 듣는 사람이다. 귀가 한 급 올라갔다.`,
      ng:`통역 하나가 틀렸다. 괜찮다던 왼쪽 벽 밑에서 바닥이 울었다.<br><br>
        막내 발밑이 꺼지는 걸 둘이 낚아챘다. 꺼진 구멍이 홀의 다른 말들을 다 깨웠다 — 사방에서 모래가 흘렀다.<br>
        마지막 열 걸음은 통역이고 뭐고 전력으로 뛰었다. 건물 말은 끝까지 존댓말로 들어야 한다. 반말로 들은 값이었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 아예 뒤로 무너뜨린다 — 홀을 건넌 뒤 트는 기둥을 밀어 입구를 닫는다.', k:'break', dc:26,
      ok:`홀을 건너자마자 어깨 튼 기둥으로 갔다. 이미 갈 마음이 반인 기둥은 콩알 장약이면 넘어간다.<br><br>
        입구 쪽으로 넘어가게 — 밑동 바깥쪽에 콩알 하나. 기둥이 천천히, 그러나 돌이킬 수 없이 입구 위 들보를 끌고 넘어갔다.<br>
        홀 입구가 통째로 닫혔다. 쫓던 발소리들이 벽이 된 입구를 긁었다.<br>
        건물이 어차피 할 일을 — 때와 방향만 이쪽이 정해 준 것이다. 그게 폭파의 반이다.`,
      ng:`기둥이 넘어가다 — 중간에 걸렸다. 옆 들보에 어깨를 걸치고 비스듬히.<br><br>
        입구가 반만 닫혔다. 반 틈으로 날랜 놈 하나가 비집고 들어왔다.<br>
        홀 안에서 한바탕 치르고서야 조용해졌다. 걸린 기둥은 그 뒤로도 삐걱대며 — 언제 마저 넘어갈지 모르는 숙제로 남았다. 넘어가는 길까지 봐 줘야 폭파다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S', t:'마지막 한 발 — 품 안의 패',
  x:`폭파공들 사이에 말 안 하는 규칙이 있다. 마지막 장약 하나는 장부에 안 적는다. 그건 길 뚫는 용도가 아니라서.<br><br>
    오늘 그 패를 생각하게 되는 밤이다. 다섯이 막다른 창고에 몰렸고, 문은 하나, 문 밖에는 여럿.<br>
    마지막 패는 품 안에 있다. 쓰면 문과 문 밖 것들과 — 어쩌면 창고 천장까지.<br>
    쓰는 패가 아니라 쥐고 버티는 패다. 쥔 손이 떨리지 않는 동안은.`,
  o:[
    { l:'① 패를 보여 주지 않고 — 창고 안의 것들로 문틀만 무너뜨려 문을 봉한다.', k:'break', dc:26,
      ok:`창고 선반과 쇠궤짝을 문 안쪽에 쌓고 — 문틀 위 인방돌을 쇠지레로 쳐 떨궜다. 문이 돌과 궤짝에 물려 영영 닫혔다.<br><br>
        문 밖 것들이 밤새 긁었다. 문은 이제 벽이다.<br>
        창고 뒤쪽 환기창을 넓혀 새벽에 빠져나갔다. 품 안의 패는 품 안에 그대로.<br>
        마지막 패는 안 쓰고 이기는 데 쓰는 패다. 쥐고 있다는 사실이 손을 차분하게 했다. 그거면 제값을 한 것이다.`,
      ng:`인방돌이 반만 떨어졌다. 문이 반봉인 — 긁는 소리가 밤새 문짝을 얇게 깎았다.<br><br>
        뜬눈으로 교대하며 환기창을 넓혔다. 새벽에 문 아래 귀퉁이가 뚫려 — 코 하나가 들어왔다 나갔다.<br>
        마지막 사람이 환기창을 빠질 때 문이 버티는 소리가 한계였다. 돌 반쪽 차이가 밤 하나 차이였다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-18 } },
    { l:'② 패의 값만 빌린다 — 문틈으로 심지 타는 냄새만 흘려보낸다.', k:'gaze', dc:25,
      ok:`문 밖 것들은 이 구역에서 폭음을 겪은 것들이다 — 아까 낮의 폭파 때 흩어지던 꼴이 그랬다.<br><br>
        심지 한 토막에 불을 붙여 — 장약 없이 — 문틈 앞에서 태웠다. 타들어 가는 그 냄새만 밖으로.<br>
        긁던 소리가 멎었다. 냄새의 뜻을 아는 것들이 하나둘 물러나는 기척.<br>
        빈 심지 하나로 산 밤이었다. 패는 보여 주지 않아도 — 패 냄새만으로 판이 접힐 때가 있다.`,
      ng:`문 밖 것들 중에 그 냄새를 모르는 신참이 있었다. 긁는 소리가 하나만 — 끈질기게 남았다.<br><br>
        결국 그 하나가 문 아래를 파기 시작했다. 파는 놈 코앞 문틈에 놀래킬 분량을 터뜨려서야 물러갔다.<br>
        냄새 수는 겪은 놈한테만 통한다. 신참은 폭음으로 가르치는 수밖에. 교육비가 들었다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-15, spirit:-16 } }
  ] },

// ---------- S1 『표본실 — 착륙 이후』 ----------

{ at:'S1', t:'격벽 — 열리지 않는 문의 급소',
  x:`내려앉은 격벽이 길을 막았다. 기계실은 침수, 수동 크랭크는 뜯겨 나갔다. 두께 세 치의 강철 문.<br><br>
    통째로 깨자면 가진 화약 전부로도 모자란다. 하지만 문에도 급소가 있다 — 잠금쇠가 문틀에 물리는 자리. 거기는 강철이 아니라 주물이다.<br>
    문틈에 귀를 대고 두드려 — 잠금쇠 위치를 소리로 찾는다. 속이 찬 소리, 빈 소리, 그리고 주물 특유의 둔한 소리.<br><br>
    복도 저쪽 어둠에서 이쪽 두드림에 — 마주 두드리는 소리가 왔다. 서두르라는 뜻으로 듣기로 했다.`,
  o:[
    { l:'① 주물 소리 나는 두 점에만 — 콩알 장약으로 잠금쇠를 끊는다.', k:'break', dc:26, wake:1,
      ok:`둔한 소리 두 점 — 위 잠금쇠, 아래 잠금쇠. 콩알 장약을 점토로 눌러 붙이고 심지를 한 가닥으로 이었다.<br><br>
        퍽, 퍽 — 폭음이라기엔 작은 소리 둘. 격벽이 제 무게로 반 뼘 미끄러져 내렸다. 잠긴 문이 그냥 무거운 문이 됐다.<br>
        쇠지레 둘을 걸어 다섯이 밀어 올렸다. 열렸다.<br><br>
        세 치 강철을 콩알 둘로 이겼다. 문은 두께로 버티고 폭파공은 급소로 이긴다 — 벽이든 문이든 같은 법이다.`,
      ng:`아래 점이 잠금쇠가 아니라 — 경첩 기름통이었다. 콩알에 기름이 튀며 불이 붙었다.<br><br>
        문틈으로 연기가 복도 저쪽까지 흘렀다. 마주 두드리던 소리가 — 뛰는 소리로 바뀌었다.<br>
        위 잠금쇠는 끊겼다. 아래는 쇠지레로 비틀어 뜯었다. 문이 열리는 순간과 어둠 속 눈이 모퉁이를 도는 순간이 겹쳤다. 먼저 지나가 문을 되눌렀다. 간발이었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 문을 포기하고 — 격벽 옆 벽체를 소리로 재 얇은 데를 딴다.', k:'sense', dc:25,
      ok:`격벽은 강철이어도 벽은 벽이다. 주먹으로 벽을 짚어 가며 두드렸다 — 배관 지나는 자리는 속이 비어 소리가 높다.<br><br>
        배관 통로 덮개벽 — 한 뼘 두께 — 를 찾았다. 콩알 하나 반이면 되는 두께.<br>
        둔한 기침 소리와 함께 사람 폭 구멍이 났다. 배관 사이로 격벽 너머까지 기어 지났다.<br>
        강한 문 옆에는 꼭 약한 벽이 있다. 문만 보는 눈에는 안 보일 뿐이다.`,
      ng:`높은 소리 자리를 땄는데 — 배관 통로가 아니라 약품 배관 그 자체였다. 깨진 관에서 시큼한 것이 흘렀다.<br><br>
        바닥을 태우는 약품이었다. 구멍은 났지만 지나는 발밑이 연기 나는 길이 됐다.<br>
        장화 밑창 두 켤레가 녹아 반나절을 절뚝였다. 빈 소리에도 종류가 있다 — 바람 빈 소리와 물 찬 소리. 귀 공부가 하나 늘었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S1', t:'통풍구 — 관을 타는 장약',
  x:`둥지가 통풍관 분기점에 있다 — 배관도가 가리키는 자리는 벽 속 깊이, 사람은 못 가는 데다.<br><br>
    장약은 갈 수 있다. 관은 기울어 있고, 장약은 구른다. 분기점까지 — 배관도 눈금으로 스물다섯 자. 심지가 타는 시간과 구르는 시간이 분기점에서 만나야 한다.<br>
    관 속에서 미리 터지면 벽만 울리고, 늦게 터지면 — 저것들이 먼저 밀어 되돌려 보낸다. 그런 일이 있었다고, 선배 폭파공의 수기에 적혀 있다.<br><br>
    수기의 그 장에는 얼룩이 있었다.`,
  o:[
    { l:'① 구르는 시간을 잰다 — 돌멩이 하나 먼저 굴려 소리로 스물다섯 자를 듣는다.', k:'break', dc:26,
      doom:{ title:'관 속의 마중', what:'통풍구 안으로 끌려 들어갑니다', dc:20, sec:36,
        text:`돌멩이는 아홉을 세고 분기점 소리를 냈다. 심지를 아홉에 맞춰 장약을 굴렸다 — 다섯째에서 구르는 소리가 멎었다.<br><br>
          관 속에서 무엇이 장약을 받아 들었다. 그리고 거꾸로 — 미는 게 아니라 들고 — 관 입구로 달려 나왔다.<br>
          입구에서 장약을 든 그것과 눈이 마주쳤다. 손을 뻗어 장약을 쳐내는 순간 다른 손 — 저것의 — 이 이쪽 손목을 잡았다. 관 속으로. 심지는 아직 탄다. 어느 쪽 손에 있는지도 모를 어둠 속에서.`,
        dieText:`폭음은 관 속 깊은 데서 났다. 벽이 한 번 울고 먼지가 가라앉았다.<br><br>
          분기점 둥지는 조용해졌다. 그 값을 누가 치렀는지도 벽은 말해 주지 않았다.<br>
          남은 일행은 수기의 얼룩진 장 옆에 한 줄을 보탰다. 관에 굴린 것은 돌아올 수 있다. 사람도. — 쓰고 나서 마지막 두 글자는 지웠다.`,
      },
      ok:`돌멩이 먼저 — 굴러가는 소리가 아홉을 세고 분기점 턱에 닿았다. 둘째 돌로 한 번 더 — 아홉. 됐다.<br><br>
        심지를 아홉 반에 맞춰 잘라 장약을 굴렸다. 여덟… 아홉… 반 — 벽 속 깊은 데서 둔한 북소리.<br>
        분기점 둥지가 내려앉는 소리가 관을 타고 사방으로 퍼졌다. 벽 속을 긁던 소리들이 그날로 끊겼다.<br>
        못 가는 데는 못 가는 게 아니다. 손 대신 구르는 것을 보내는 데다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 관을 안 쓴다 — 분기점 바로 밑 벽을 재서, 벽 너머로 바로 때린다.', k:'gaze', dc:26,
      ok:`배관도와 벽을 번갈아 읽었다 — 분기점은 이 벽 뒤 두 자, 높이는 어깨.<br><br>
        벽 두께 반 장 — 벽 깰 분량 하나를 어깨 높이에 붙이고 전원 모퉁이 뒤로.<br>
        폭음과 함께 벽이 뚫리며 분기점 둥지가 통째로 복도 바닥에 쏟아졌다. 쏟아진 것들은 일행 쇠붙이들이 바닥에서 정리했다.<br>
        관 타는 꾀 대신 벽 너머 직격 — 꾀보다 측량이 나을 때가 있다. 배관도가 정확하다면. 오늘은 정확했다.`,
      ng:`배관도가 낡았다. 분기점은 두 자가 아니라 넉 자 뒤 — 폭파는 벽만 뚫고 둥지는 반만 다쳤다.<br><br>
        뚫린 구멍으로 성난 것들이 쏟아져 나왔다. 반쯤 다친 것들이라 — 반만 다행이었다.<br>
        복도에서 한바탕 치르고 둥지는 둘째 장약으로 마저 끝냈다. 낡은 도면은 반만 믿을 것. 나머지 반은 제 귀와 돌멩이로 잴 것.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-32, mind:-14 } }
  ] },

{ at:'S1', t:'피를 흘리게 하면 안 되는 자리',
  x:`큰 놈이 배양 설비 위에 올라앉아 있다. 저 설비 아래로 — 이 구역 유일한 통로가 지난다.<br><br>
    쏘든 베든 터뜨리든, 저 자리에서 피를 흘리게 하면 검은 피가 설비와 통로를 통째로 먹는다. 통로가 녹으면 돌아갈 길도 없다.<br>
    피 없이 치우는 법 — 폭파공의 답은 충격이다. 터지는 힘이 아니라 미는 힘. 찢지 않고 떠미는 폭파.<br><br>
    설비 옆 허공에서 터뜨리면 — 폭풍만 저놈을 민다. 파편 없이. 그 거리 셈이 오늘의 일이다.`,
  o:[
    { l:'① 허공 폭파 — 파편 없는 민폭약을 놈의 옆 허공에서 터뜨려 떠민다.', k:'break', dc:26, wake:1,
      ok:`쇠붙이 없는 민폭약 — 화약과 점토만 — 을 끈에 묶어 설비 옆 배관에 걸었다. 놈과 두 자 거리의 허공.<br><br>
        터지는 건 바람이다. 폭풍이 놈의 옆구리를 통째로 밀었다 — 피 한 방울 없이, 놈이 설비에서 떨어져 통로 반대편 바닥으로.<br>
        떨어진 자리는 녹아도 되는 자리다. 일행 쇠붙이들이 그 자리에서 일을 끝냈다. 바닥 한 뼘이 녹는 것으로 장부가 닫혔다.<br><br>
        찢는 폭파와 미는 폭파를 가르는 건 파편이다. 센 것만 폭파가 아니라는 것 — 바람으로 이긴 첫 판이었다.`,
      ng:`끈이 반 자 길었다. 터진 바람이 놈을 미는 대신 — 설비를 밀었다.<br><br>
        설비가 기울며 배양액이 통로 쪽으로 샜다. 녹는 건 아니었지만 미끄럽기가 기름 저리 가라였다.<br>
        놈은 제 발로 내려와 덤볐고, 미끄러운 통로 위에서 다 같이 엉켰다. 이기긴 이겼다. 피는 — 다행히 통로 밖에서 흘리게 했다. 반 자 셈이 사람 잡을 뻔했다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 놈을 안 건드린다 — 설비 반대편에 먹이 소리 나는 깡통 장치를 단다.', k:'fix', dc:25,
      ok:`빈 깡통 속에 돌을 넣고 — 긴 심지 끝 콩알이 깡통을 때려 구르게 만들었다. 작은 것이 바닥을 긁으며 달아나는 소리.<br><br>
        심지에 불을 붙이고 전원 통로 어귀에 엎드렸다. 때가 되자 저쪽에서 깡통이 달그락 — 놈의 고개가 돌고, 몸이 설비에서 미끄러져 내려 그쪽으로.<br>
        빈 통로 밑을 다섯이 지났다. 놈은 깡통을 앞발로 굴리며 한참 놀고 있었다.<br>
        화약 한 콩알로 사냥 본능 하나를 산 셈이다. 폭파공 장부에서 제일 싼 줄이었다.`,
      ng:`깡통이 구르다 설비 다리에 걸렸다. 소리가 두 번 나고 멎었다.<br><br>
        놈이 소리 자리가 아니라 — 소리가 시작된 자리를 봤다. 심지 연기가 오르는 이쪽 어귀를.<br>
        통로 밑을 뛰어 지나는 수밖에 없었다. 놈이 설비에서 내려오는 사이 넷은 지났고 막내는 꼬리바람에 넘어졌다 일어나 지났다. 깡통 수는 바닥 검사부터 — 오늘도 바닥이 문제였다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S1', t:'연료고 — 화약이 독이 되는 방',
  x:`지나야 하는 방이 연료 저장고다. 바닥에 샌 연료가 발목 깊이 — 냄새만으로 머리가 어질하다.<br><br>
    이 방에서 화약은 전부 독이다. 불꽃은 물론 부싯돌 긁는 소리까지. 심지 한 가닥도 품에서 꺼내면 안 된다.<br>
    그리고 방 한가운데 — 그것이 연료 위를 미끄러지듯 돌고 있다. 연료가 안 묻는 가죽. 여기 사는 것이다.<br><br>
    폭파공이 폭파 없이, 제일 폭파 같은 일을 해야 하는 방이다.`,
  o:[
    { l:'① 압력으로 민다 — 빈 연료통 뚜껑을 밟아 터뜨려 공기 포를 쏜다.', k:'break', dc:26,
      ok:`빈 철제 연료통 — 속에 공기만 찬 것 — 을 눕혀 놈 쪽으로 겨누고, 바닥을 두 발로 내리밟았다. 뚜껑이 공기압에 포탄처럼 날았다.<br><br>
        불꽃 한 점 없는 발사다. 뚜껑이 놈의 옆머리를 치고, 놈이 연료 바닥에 미끄러져 뒹굴었다.<br>
        그 틈에 다섯이 가장자리 마른 턱을 밟고 건넜다. 놈은 머리를 흔들며 일어나다 두 번 더 미끄러졌다.<br>
        화약 없이 쏜 첫 포였다. 폭파는 불이 아니라 — 결국 압력이라는 걸, 이 방이 시험 문제로 냈다.`,
      ng:`뚜껑이 빗나가 연료통 더미를 맞혔다. 통들이 와르르 — 쇠가 쇠를 치는 소리가 방을 채웠다.<br><br>
        불꽃은 안 났다. 그게 유일한 다행이었다.<br>
        놀란 놈이 사방으로 미끄러지며 날뛰는 방을 — 벽에 붙어 게걸음으로 건넜다. 연료에 전 바지가 마를 때까지 반나절, 불가에 못 가는 폭파공 꼴이 됐다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 놈의 가죽을 쓴다 — 연료가 안 묻는 놈을 겁줘 앞세워 길을 낸다.', k:'gaze', dc:26,
      ok:`놈이 도는 길을 봤다 — 연료 깊은 데를 피해 도는 길. 저 길이 이 방의 마른 길이다.<br><br>
        놈 뒤에서 쇠통 두 개를 맞부딪쳤다. 불꽃 없는 소리 — 놈이 놀라 제 길로 내뺐다.<br>
        그 발자국 길 — 연료가 얕은 길 — 을 따라 다섯이 건넜다. 길잡이 삯은 안 줬다. 겁이 삯이었다.<br>
        이 방에서 제일 밝은 지도는 여기 사는 놈 발바닥이었다. 지도는 훔쳐 보는 것이다.`,
      ng:`놈이 놀라 내빼긴 했는데 — 방향이 이쪽이었다. 겁먹은 것은 길을 안 가린다.<br><br>
        미끄러지며 돌진해 오는 놈을 — 전원이 연료통 뒤로 흩어져 피했다. 둘이 연료에 통째로 젖었다.<br>
        놈이 나간 문으로 따라 나갔다. 젖은 둘은 그날 밤 불가에서 멀찍이 — 폭파공까지 셋이 나란히 유배였다. 겁은 방향을 못 고른다. 다음엔 몰 방향부터 막고 겁줄 것.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S1', t:'여왕의 방 입구 — 무너뜨리는 셈',
  x:`큰 문은 못 연다. 열 일도 없다. 할 일은 반대다 — 이 입구를 영영 닫는 것.<br><br>
    문 위 벽체에 보가 둘, 그 위에 바위 같은 콘크리트 덩이. 셈은 선다. 보 둘을 끊으면 덩이가 입구를 막는다.<br>
    문제는 문 안쪽이다. 깊은 숨소리 — 여왕. 그리고 폭음이 나는 순간 문이 안에서 열릴 것이다. 심지가 타는 동안 그 문 앞에 서 있어야 한다는 뜻이다.<br><br>
    심지를 길게 잡으면 열고 나온다. 짧게 잡으면 — 이쪽이 못 피한다.`,
  o:[
    { l:'① 두 보 동시 기폭 — 심지 둘의 길이를 한 치 오차 없이 맞춘다.', k:'break', dc:26, wake:1,
      doom:{ title:'열리는 큰 문', what:'큰 문 안쪽으로 끌려 들어갑니다', dc:20, sec:35,
        text:`왼쪽 심지가 먼저 탔다 — 한 치의 오차. 보 하나만 끊기고 덩이가 비스듬히 걸렸다.<br><br>
          그리고 폭음 쪽이 아니라 — 문이 먼저 반응했다. 안에서 열렸다. 반쯤.<br>
          문틈에서 나온 긴 것이 가장 가까운 — 둘째 심지에 불을 대던 — 이쪽 발목을 감았다. 걸린 덩이 밑, 반쯤 열린 문 안으로. 둘째 폭음이 등 뒤에서 울렸다. 덩이가 마저 내려앉는 소리가 — 문이 닫히는 소리이기도 했다. 안쪽에서 들었다.`,
        dieText:`입구는 막혔다. 셈대로. 셈에 없던 것 하나만 빼고.<br><br>
          막힌 벽 너머에서 깊은 숨이 한 번 길게 — 만족스럽게 — 뒤척였다.<br>
          일행은 벽 앞에 심지 한 토막을 태워 꽂고 물러났다. 폭파공 무덤에는 향 대신 심지를 꽂는다. 그 법도를 처음 치르는 날이었다.`,
      },
      ok:`심지 둘을 나란히 놓고 한 자로 재 — 같은 두름에서 잇달아 잘랐다. 불도 한 손에 쥔 관솔 하나로 동시에.<br><br>
        물러나 엎드린 등 뒤에서 — 퍽, 퍽. 반 호흡 안의 둘. 보 둘이 같이 끊기고 콘크리트 덩이가 문 앞에 통째로 앉았다.<br>
        문이 안에서 밀리는 소리가 — 덩이에 막혀 둔하게 끝났다. 깊은 숨이 벽 너머에서 길게, 성나게 울렸다.<br>
        울려도 벽은 벽이다. 폭파공이 만든 벽은 폭파공만 연다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 심지를 안 믿는다 — 보 하나를 미리 반만 끊어 두고, 멀리서 줄로 당겨 마무리한다.', k:'fix', dc:26,
      ok:`왼 보를 장약으로 먼저 — 반만 — 끊었다. 문이 들썩했지만 덩이는 아직이라 안 열렸다. 남은 반에는 갈고리와 줄.<br><br>
        복도 끝까지 물러나 다섯이 줄을 당겼다. 반 끊긴 보가 꺾이고 — 덩이가 입구에 앉았다.<br>
        폭음은 한 번, 마무리는 사람 힘. 문 앞에 서 있던 시간은 — 없음.<br>
        심지는 좋은 하인이고 나쁜 주인이다. 맡길 일과 안 맡길 일을 가르는 게 폭파공의 셈이다.`,
      ng:`줄을 당기는데 갈고리가 — 빠졌다. 반 끊긴 보와 걸린 덩이가 어중간하게 매달린 채 멎었다.<br><br>
        누가 다시 가서 걸어야 했다. 문 앞까지. 제일 빠른 막내가 아니라 — 셈을 틀린 이쪽이 갔다.<br>
        갈고리를 다시 걸고 돌아서는 등 뒤에서 문이 한 번 들썩였다. 뛰었다. 둘째 당김에 덩이가 앉았다. 앉는 소리를 문 앞이 아니라 복도 끝에서 들은 것만으로 — 오늘 셈은 반타작이다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'장약 띠를 무는 것',
  x:`허리의 장약 띠가 — 당겨졌다. 돌아보니 손바닥만 한 것이 띠에 매달려 있다. 다리 여덟. 그리고 그 입이 지금 뇌관 묶음을 물고 있다.<br><br>
    쳐서 떨구면 — 뇌관째 터진다. 허리에서. 띠를 풀어 던지면 장부의 반이 날아간다.<br>
    그것은 쇠 냄새 나는 것을 무는 습성이다. 물고 — 제 둥지로 가져간다. 지금도 다리 넷은 띠를, 넷은 이쪽 허리를 쥐고 당기는 중이다.<br><br>
    숨을 멈추고, 셈을 시작한다. 뇌관은 물려서 안 터진다. 긁혀야 터진다. 아직은.`,
  o:[
    { l:'① 뇌관 묶음만 — 띠에서 소리 없이 풀어 그것에게 통째로 준다.', k:'break', dc:26,
      doom:{ title:'띠를 무는 것', what:'장약 띠째 벽 틈으로 끌려 들어갑니다', dc:19, sec:37,
        text:`묶음 매듭을 푸는 손가락이 — 반 박자 늦었다. 그것이 당기는 다리에 힘을 보탰다.<br><br>
          띠가 허리에서 안 풀린 채 — 몸째 끌린다. 벽 아래 틈으로. 손바닥만 한 것의 힘이 아니다. 틈 안쪽에서 더 큰 무엇이 줄다리기를 넘겨받았다.<br>
          틈에 어깨가 걸려 버틴다. 품 안의 장부가 — 화약 전부가 — 틈 안쪽 어둠과 함께 당긴다. 띠 버클이 녹슬어 안 풀린다. 하필 오늘, 안 풀린다.`,
        dieText:`틈 앞에 버클 반쪽이 떨어져 있었다.<br><br>
          그날 밤 벽 속 깊은 데서 둔한 폭음이 한 번 울렸다. 긁는 이빨이 뇌관을 만난 소리였을 것이다.<br>
          일행은 그 폭음을 폭파공의 마지막 일로 치기로 했다. 장부는 그렇게 닫혔다 — 벽 속에서, 주인과 함께, 크게 한 번.`,
      },
      ok:`매듭 셋을 — 숨 한 번에 하나씩 — 풀었다. 뇌관 묶음이 띠에서 떨어져 그것 입에 온전히 넘어갔다.<br><br>
        그것이 전리품을 안고 벽 틈으로 사라졌다. 뇌관은 긁히지만 않으면 쇳덩이다. 둥지 바닥에서 녹슬 것이다.<br>
        장부에서 뇌관 한 줄이 지워졌다. 허리와 화약과 목숨 — 셋이 남았으니 남는 장사다.<br>
        그날부터 띠에 방울을 달았다. 다음 도둑은 소리부터 낼 것이다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 그것의 습성을 쓴다 — 더 반짝이는 쇠, 빈 기폭통을 꺼내 흔든다.', k:'luck', dc:25,
      ok:`주머니의 빈 기폭통 — 놋쇠 반짝이는 — 을 그것 눈앞에서 천천히 흔들었다. 쇠 무는 것한테는 보석이다.<br><br>
        다리 여덟이 셈을 했다. 물고 있는 둔한 쇠와 눈앞의 반짝이는 쇠. 입이 뇌관을 놓고 기폭통으로 건너뛰었다.<br>
        통째로 쥐여 줬다. 그것이 전리품을 안고 벽 틈으로 — 빈 통이니 둥지에서 천년을 긁어도 소리만 날 것이다.<br>
        도둑한테는 싸우지 말고 더 좋은 장물을 — 폭파공 수첩에 적을 줄은 몰랐던 한 줄이다.`,
      ng:`기폭통을 꺼내는 부스럭 소리에 그것이 — 서둘렀다. 뇌관을 문 채 띠에서 뛰어내려 바닥을 긁으며 내뺐다.<br><br>
        뇌관이 바닥에 긁혔다. 퍽 — 작은 폭음이 그것째 복도에 울렸다.<br>
        그것은 그걸로 끝났는데, 소리가 문제였다. 복도 양끝에서 오는 기척들 사이로 반 시진을 내뺐다. 뇌관 한 묶음과 조용한 오후의 값이었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'S1', t:'표본 벽 — 떨림의 한계선',
  x:`지나야 할 벽의 저쪽은 복도, 이쪽은 — 표본실이다. 벽 양옆 선반에 단지가 빼곡하다. 탁한 단지가 여럿.<br><br>
    폭파의 힘은 벽만 치지 않는다. 떨림이 방 전체로 간다. 단지 속에서 자는 것들은 떨림에 깬다 — 금 간 단지라면 떨림에 나온다.<br>
    벽을 깨되 방을 안 깨우는 폭파 — 콩알을 쪼개 여러 번, 떨림의 한계선 밑으로만.<br>
    한 번이라도 선을 넘으면, 이 방의 단지 수만큼의 일이 생긴다.`,
  o:[
    { l:'① 콩알을 넷으로 쪼개 — 네 번에 나눠, 떨림을 선 밑으로 누른다.', k:'break', dc:26,
      doom:{ title:'깨어난 선반', what:'표본실 안쪽으로 끌려 들어갑니다', dc:20, sec:38,
        text:`셋째 조각까지는 선 밑이었다. 넷째 — 벽이 뚫리며 뚫린 쪽이 아니라 벽 속 떨림이 선반 기둥을 타고 올라갔다.<br><br>
          탁한 단지 여섯이 — 한 박자로 — 안에서 깨졌다. 젖은 것들이 선반에서 쏟아져 내렸다.<br>
          뚫은 구멍으로 일행을 밀어 넣는 사이 발목과 허리에 젖은 손들이 감겼다. 여섯이 한 사람을 나눠 쥐고 — 방 안쪽, 제일 큰 빈 단지가 있는 쪽으로 끈다. 보존액 냄새가 코를 채운다.`,
        dieText:`구멍 저쪽에서 일행이 되부르는 소리가 한참 울렸다.<br><br>
          표본실은 다시 조용해졌다. 너무 조용해서 — 아무도 구멍으로 고개를 되넣지 못했다.<br>
          다음 날 그 벽 앞을 지난 다른 조가 말했다. 선반의 탁한 단지가 하나 — 유난히 큰 것이 하나 — 늘어 있더라고.`,
      },
      ok:`콩알을 넷으로 쪼개 벽 네 귀에 — 한 번 터뜨리고, 단지들 가라앉기를 기다렸다 다음. 떨림이 선을 넘보면 반 호흡 더 기다렸다.<br><br>
        네 번째에 벽돌이 소리 죽여 내려앉았다. 사람 폭 구멍 — 단지 하나 안 울었다.<br>
        하나씩 구멍을 넘는 동안 탁한 단지들은 제 꿈을 꿨다.<br>
        폭파를 네 조각으로 나누는 법 — 힘이 아니라 떨림을 장부에 적는 법을 이 방이 가르쳤다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 폭파를 접는다 — 벽돌 줄눈을 식초로 삭혀 손으로 뺀다.', k:'fix', dc:25,
      ok:`선반 약품 중에 산성 세정액이 남아 있었다. 줄눈에 붓고 기다리니 — 모르타르가 치즈처럼 물렀다.<br><br>
        벽돌을 한 장씩 소리 없이 뺐다. 여덟 장 — 기는 구멍.<br>
        시간은 폭파의 세 배가 들었다. 떨림은 — 영. 단지들은 끝까지 몰랐다.<br>
        폭파공 연장에 약품 한 줄이 추가됐다. 벽을 이기는 게 꼭 힘일 필요는 없다. 벽의 이 사이를 삭히는 수도 있다.`,
      ng:`세정액이 줄눈 틈으로 — 벽 저쪽 복도 바닥까지 흘렀다. 바닥에서 연기가 올랐다.<br><br>
        그 냄새가 복도의 것을 불렀다. 벽돌 네 장을 뺀 구멍 너머로 — 코 하나가 들이밀어졌다.<br>
        남은 네 장을 급히 안쪽에서 도로 쌓고 반 시진을 숨죽였다. 코가 가고 나서야 마저 뺐다. 흘리는 약은 쓰는 약보다 멀리 간다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

// ---------- S2 『백악기 정원』 ----------

{ at:'S2', t:'담장의 종 — 소리로 치는 울타리',
  x:`담장이 길다. 지킬 사람은 다섯. 무리는 밤마다 자리를 바꿔 가며 민다.<br><br>
    폭파공의 답 — 화약은 꼭 터뜨리라고 있는 게 아니다. 콩알 장약 여섯 개, 실 여섯 가닥. 담장 여섯 구간에 소리 덫을 심는다.<br>
    밀면 울린다. 울리면 — 저쪽은 놀라고 이쪽은 안다. 어느 구간인지까지.<br><br>
    화약으로 만드는 건 구멍만이 아니다. 종도 만든다.`,
  o:[
    { l:'① 여섯 구간에 소리 덫을 — 울림 간격으로 어디가 밀리는지 들리게 심는다.', k:'fix', dc:25, wake:1,
      ok:`구간마다 실 높이를 달리하고 — 장약 크기도 조금씩 다르게. 첫째 구간은 퍽, 여섯째는 팡. 소리만 듣고 자리를 아는 종렬.<br><br>
        그 밤 — 팡. 여섯째다. 전원이 눈 감고도 그리로 뛰었다. 뚫리기 전에 닿았다.<br>
        사흘 밤 동안 종이 네 번 울렸고 네 번 다 선수를 쳤다. 무리가 담장 밀기를 — 셈이 안 맞는 장사로 치기 시작했다.<br><br>
        지키는 폭파라는 게 있다. 터뜨린 화약보다 울린 화약이 많아지는 날 — 폭파공은 파수꾼이 된다.`,
      ng:`넷째 구간 실을 — 밤새 이슬 먹은 실이 늘어져 — 바람이 건드렸다. 헛종이 울렸다.<br><br>
        전원이 헛걸음. 그리고 그 틈에 둘째 구간이 진짜로 밀렸다.<br>
        간신히 막았지만 밤잠을 통으로 바쳤다. 종은 거짓말을 하면 안 된다 — 실은 날마다 당겨 고르는 것으로 규칙이 늘었다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-26, mind:-14 } },
    { l:'② 종 말고 겁 — 제일 자주 밀리는 기둥 앞에 밟으면 튀는 흙폭죽을 묻는다.', k:'break', dc:26,
      ok:`제일 녹슨 기둥 앞 땅에 콩알 장약을 묻고 흙과 자갈을 덮었다 — 밟으면 흙기둥이 튀는 폭죽.<br><br>
        그 밤 쿵 소리 대신 — 퍽, 하고 흙기둥이 섰다. 담장을 밀러 온 놈이 제 발밑에서 솟은 흙벼락에 공중제비를 돌았다.<br>
        그 놈은 다시 안 왔다. 무리에 소문이 돈 모양이다 — 그 기둥 앞 땅은 문다고.<br>
        땅이 무는 담장. 폭파공이 담장에게 줄 수 있는 제일 좋은 선물이다.`,
      ng:`묻은 자리가 — 하필 빗물 길이었다. 밤비에 화약이 젖어 그 밤 폭죽은 침묵.<br><br>
        기둥이 밀렸다. 녹슨 기둥은 두 번째 박치기에 꺾였고, 새벽까지 뚫린 틈을 지키는 밤이 됐다.<br>
        젖은 폭죽을 파내 품에 넣으며 적었다. 묻는 자리는 물길부터 볼 것. 화약의 적은 짐승보다 비다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, mind:-15 } }
  ] },

{ at:'S2', t:'물밑 폭파 — 초로 봉한 장약',
  x:`물에 잠긴 고사리밭 — 물길 한가운데 등줄기들이 돈다. 둘. 돌아가는 길은 없고, 물속 싸움은 저쪽 판이다.<br><br>
    폭파공은 물속에서도 폭파공이다. 장약을 초 녹인 것으로 겹겹이 봉하면 물을 먹지 않는다. 심지 대신 — 길게 뺀 유선. 물가에서 부싯돌 기폭.<br>
    물속 폭음은 공기보다 세게 멀리 간다. 물에 잠긴 것들한테는 — 하늘이 무너지는 소리다.<br><br>
    초가 손가락 두 마디만큼 남았다. 봉할 수 있는 건 장약 하나.`,
  o:[
    { l:'① 하나면 된다 — 등줄기들이 겹쳐 도는 길목 물밑에 가라앉혀 때린다.', k:'break', dc:26, wake:1,
      ok:`등줄기 둘이 도는 길 — 겹치는 점이 있다. 물때 낀 말뚝 옆. 초 봉한 장약에 돌을 달아 그 점에 가라앉혔다.<br><br>
        둘이 겹치는 순간 — 물가에서 유선을 당겼다. 물이 통째로 한 번 부풀고, 수면이 하얗게 뒤집혔다.<br>
        등줄기 둘이 배를 뒤집고 떠올랐다. 물속 폭음은 비늘 속까지 때린다.<br><br>
        젖어서 못 쓰는 화약은 없다. 봉하는 법을 모르는 폭파공이 있을 뿐 — 스승의 그 말을 물속에서 증명했다.`,
      ng:`가라앉히는 돌이 가벼웠다. 장약이 물살에 밀려 겹치는 점에서 두 자 비껴 앉았다.<br><br>
        폭음에 하나는 떠올랐는데 하나는 — 성나서 더 빨라졌다.<br>
        남은 하나를 피해 물길을 반은 걷고 반은 뛰어 건넜다. 마지막 사람 뒤꿈치 물보라를 등줄기가 스쳤다. 물속 측량은 물살까지 셈에 넣을 것.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 폭파 없이 — 빈 통 두 개를 띄워 등줄기들을 물길 끝으로 꾄다.', k:'luck', dc:25,
      ok:`빈 통 둘에 돌을 반쯤 넣어 — 물살에 뒤뚱대며 떠가게 띄웠다. 허우적대는 것 소리.<br><br>
        등줄기 둘이 통을 따라갔다. 물속 것들 눈에 뒤뚱대는 것은 다친 것이고, 다친 것은 공짜 밥이다.<br>
        둘이 물길 끝에서 통과 씨름하는 동안 — 다섯이 빈 물길을 건넜다.<br>
        초 두 마디와 장약 하나가 고스란히 남았다. 공짜로 건넌 물은 두고두고 자랑이 된다.`,
      ng:`통 하나가 물풀에 걸려 멎었다. 등줄기 하나만 따라가고 — 하나는 남았다.<br><br>
        남은 하나를 사이에 두고 물길을 갈지자로 건넜다. 막내가 미끄러져 물을 먹었고, 등줄기가 그 물보라로 꺾어 들었다.<br>
        창 둘이 물을 때려 쫓는 사이 끌어냈다. 미끼는 둘 다 걸려야 미끼다. 반만 걸린 미끼는 반만 산 셈이다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-15 } }
  ] },

{ at:'S2', t:'큰 것 앞의 금기',
  x:`폭파공 장부 맨 앞장에 이 정원의 금기를 적어 뒀다. 큰 것 곁에서는 터뜨리지 않는다.<br><br>
    폭음에 놀란 큰 것은 — 도망치지 않는다. 밟는다. 소리 난 쪽을. 둘레 백 걸음을 통째로.<br>
    그런데 지금, 큰 것이 하필 야영지와 물길 사이에 자리를 잡고 누웠다. 지나가려면 곁을 스쳐야 하고 — 하필 오늘 옮겨야 한다. 어제 깬 알 냄새가 야영지에 배어, 밤이면 무리가 온다.<br><br>
    화약쟁이가 화약을 봉인하고 치르는 시험이다.`,
  o:[
    { l:'① 장비 전부를 소리 안 나게 묶는다 — 쇠는 천으로, 통은 품으로. 그리고 곁을 지난다.', k:'steady', dc:26, wake:1,
      ok:`버클마다 천을 물리고, 통끼리 닿는 자리마다 이끼를 끼웠다. 장비 점검 — 폭파공이 제일 잘하는 일의 거꾸로 판이다. 소리 나는 데를 찾아 — 죽이는 점검.<br><br>
        다섯이 큰 것의 숨소리 박자에 걸음을 묻고 곁을 지났다. 쉰 걸음. 쇳소리 한 번 없이.<br>
        큰 것의 눈꺼풀이 한 번 들렸다 — 내려왔다. 지나가는 바람 다섯으로 친 것이다.<br><br>
        화약 없이도, 소리 없이도 — 점검하는 손은 같은 손이다. 조이는 일과 죽이는 일이 한 기술이라는 걸 배웠다.`,
      ng:`마흔 걸음까지 완벽했다. 마흔한 걸음 — 품의 빈 기폭통 둘이 서로 닿아 — 땡.<br><br>
        작은 소리였다. 큰 것한테는 충분했다. 머리가 들리고 콧김이 돌았다.<br>
        전원 풀숲에 엎드려 반 시진 — 큰 것이 도로 눕고도 한참을 기다렸다 기어서 지났다. 빈 통도 통이다. 빈 것일수록 소리가 맑다는 걸 잊고 있었다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-17, spirit:-17 } },
    { l:'② 금기를 거꾸로 쓴다 — 멀리 무리 쪽 숲에 소리 장약을 던져, 큰 것이 그쪽을 밟게 한다.', k:'break', dc:26,
      ok:`금기의 뒷장 — 큰 것은 소리 난 쪽을 밟는다. 그렇다면 소리를 무리의 숲에 내면 된다.<br><br>
        제일 긴 심지에 소리 장약을 달아 무리 쪽 숲 깊이 던져 두고, 전원 물길 쪽에 대기. 쾅 — 큰 것이 일어나 그쪽으로 걸음을 옮겼다. 땅이 북처럼 울렸다.<br>
        큰 것이 숲을 밟는 소리와 무리가 흩어지는 비명을 등 뒤로 — 다섯이 빈 길을 지났다. 오늘 밤 무리는 야영지 올 형편이 아닐 것이다.<br>
        금기는 외우라고 있는 게 아니라 — 셈에 넣으라고 있는 것이다.`,
      ng:`던진 장약이 나뭇가지에 걸렸다. 숲 바닥이 아니라 — 허공에서 터졌다.<br><br>
        소리가 사방으로 퍼져 방향이 뭉개졌다. 큰 것이 일어나 — 제자리에서 돌며 둘레를 다 노려봤다.<br>
        반나절을 엎드려 기다렸다 지났다. 소리의 방향은 터지는 높이가 정한다 — 장부 금기 장에 한 줄이 늘었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S2', t:'반원을 깨는 한 점',
  x:`사냥 무리 넷이 반원으로 좁혀 온다. 등 뒤는 바위벽. 창 둘로 넷을 — 셈이 안 선다.<br><br>
    폭파공의 눈이 바닥을 읽는다. 반원이 좁혀 오는 길목 — 넷의 발이 모이는 조임점이 있다. 반원이 원이 되기 직전, 꼭 한 번 넷이 한 걸음 안에 드는 점.<br>
    장약 하나를 그 점에 — 지금 굴려 두면, 터뜨리는 때는 저쪽 걸음이 정해 준다.<br><br>
    심지 길이가 곧 그 때다. 반원의 속도를 읽는 눈이 곧 자다.`,
  o:[
    { l:'① 조임점에 굴려 두고 — 반원의 속도로 심지를 잰다.', k:'break', dc:26,
      doom:{ title:'반원의 끝', what:'무리에게 물려 가 풀숲으로 끌려갑니다', dc:20, sec:37,
        text:`반원의 속도를 읽었다 — 읽은 속도가 틀렸다. 저것들이 굴러온 장약을 보고 — 걸음을 늦췄다. 화약을 아는 무리였다.<br><br>
          장약이 빈 점에서 터졌다. 흙만 튀었다. 그리고 반원이 — 원이 됐다.<br>
          바위벽 쪽 틈으로 셋은 올렸다. 마지막 둘 중 — 민 쪽이 이쪽이었고, 남은 쪽도 이쪽이었다. 네 입이 팔다리를 나눠 물고 풀숲으로 — 장약 띠가 바위에 걸려 벗겨지는 것까지는 셈에 있었다. 띠라도 남게.`,
        dieText:`바위벽 밑에 장약 띠가 걸려 있었다. 장부도 그 안에.<br><br>
          일행은 띠를 거뒀다. 장부 마지막 장 — 반원 속도 셈 — 에 틀린 숫자가 그대로 있었다.<br>
          아무도 그 숫자를 안 고쳤다. 고치는 대신 그 장을 접어 표시했다. 접힌 장이 있는 장부가 — 산 폭파공들의 교본이 됐다.`,
      },
      ok:`반원의 속도 — 열 걸음에 세 호흡. 조임점까지 다섯 걸음 — 심지 한 호흡 반. 잘랐다. 굴렸다.<br><br>
        장약이 멎는 점과 넷의 발이 모이는 점과 심지의 끝 — 셋이 한 순간에 만났다.<br>
        흙기둥이 서고 반원이 공중에서 해체됐다. 넷 중 둘은 그대로 눕고 둘은 절며 풀숲으로.<br>
        창 한 번 안 섞고 끝난 포위전이다. 폭파공의 창은 땅 밑에서 올라온다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 조임점이 아니라 — 등 뒤 바위벽에 콩알을 때려 바위 우는 소리를 낸다.', k:'gaze', dc:25,
      ok:`바위벽 움푹한 데 콩알 장약 — 터지는 소리가 바위에 울려 몇 배로 컸다. 벽 전체가 우는 소리.<br><br>
        반원이 멈칫했다. 저것들 귀에는 — 등 뒤 바위가 큰 것의 발소리를 낸 것이다.<br>
        큰 것 곁은 무리도 피한다. 반원이 풀숲으로 녹았다.<br>
        바위는 폭파공의 북이다. 어디를 때리면 무슨 소리가 나는지 — 그 지도가 머리에 한 장 늘었다.`,
      ng:`콩알이 움푹한 데를 빗나가 모서리에서 터졌다. 울림 대신 — 바위 조각이 튀었다.<br><br>
        조각 하나가 이쪽 정강이를 때리고, 반원은 소리의 정체를 금방 알았다. 흙 튀는 화약 소리를 아는 무리였다.<br>
        결국 창으로 치렀다. 밀어내긴 했는데 둘이 물렸다. 북 치는 자리는 평소에 봐 둘 것 — 급할 때 고르면 모서리를 고른다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 녹슨 추의 걸쇠',
  x:`균형추가 녹슨 걸쇠에 물려 있다. 걸쇠를 깨야 승강기가 산다 — 문제는 걸쇠 바로 옆이 추를 매단 줄이라는 것.<br><br>
    장약이 크면 줄까지 끊는다. 줄이 끊기면 추가 떨어지고 — 승강기는 영영 고철이다.<br>
    걸쇠만 깨고 줄은 스치지도 않는 양 — 콩알의 반의반. 폭파공 평생 가장 작은 폭파가 될 것이다.<br>
    수풀의 기척들이 모여든다. 저울질할 시간은 한 번 치다.`,
  o:[
    { l:'① 반의반 콩알 — 점토로 줄 쪽을 막고 걸쇠 쪽으로만 힘을 틔운다.', k:'break', dc:26, wake:1,
      ok:`화약을 손톱만큼 덜어 — 점토로 삼면을 봉하고 걸쇠 쪽 한 면만 틔웠다. 힘에게 문을 하나만 열어 주는 것.<br><br>
        틱 — 폭음이랄 것도 없는 소리. 걸쇠가 가루로 떨어지고 줄은 실오라기 하나 안 상했다.<br>
        추가 내려앉고 권양기가 팽팽해졌다. 일행이 감아올리는 사이 수풀 첫 놈의 콧등을 빈 화약통으로 한 대 — 그리고 탑승.<br><br>
        평생 제일 작은 폭파가 제일 어려운 폭파였다. 힘은 키우는 것보다 줄이는 쪽이 공부다.`,
      ng:`점토 봉인 한 귀퉁이가 눌리다 터졌다. 힘이 샜다 — 걸쇠가 반만 깨졌다.<br><br>
        반 깨진 걸쇠를 쇠지레로 마저 꺾는 데 세 사람 반 시진 — 아니, 수풀에서 첫 놈이 나오기까지였으니 반의반 시진.<br>
        꺾이자마자 전원이 매달리듯 탔다. 올라가는 창살 밑으로 발톱 긁는 소리. 샌 힘은 꼭 시간으로 갚게 된다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 폭파를 아낀다 — 걸쇠에 기름을 먹이고 추의 제 무게로 비틀리게 한다.', k:'fix', dc:25,
      ok:`녹은 기름의 반대말이다. 걸쇠 물린 자리에 연료 기름을 먹이고 — 추를 지렛대로 반 뼘 들썩여 줬다.<br><br>
        끼익 — 녹이 기름을 먹으며 걸쇠가 제물에 돌아 빠졌다. 백 년 치 녹이 반 시진 기름에 풀린 것이다.<br>
        화약 장부는 한 줄도 안 줄었다. 수풀 기척들이 어귀에 닿기 전에 승강기가 떴다.<br>
        폭파공의 연장 주머니에서 제일 센 건 가끔 — 기름통이다.`,
      ng:`기름이 녹에 스미기 전에 수풀이 먼저 터졌다. 반 시진이 없었다.<br><br>
        결국 콩알을 급히 — 봉인도 대충 — 붙여 깼다. 걸쇠는 갔는데 줄도 가닥 반이 끊겼다.<br>
        남은 가닥 반에 다섯 목숨을 걸고 올랐다. 줄이 우는 소리를 다 같이 들으며. 문턱에 닿는 순간까지 아무도 숨을 안 쉬었다. 급한 폭파가 제일 비싼 폭파다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-28, spirit:-16 } }
  ] },

{ at:'S2', t:'옛 관리동 — 남의 장부',
  x:`무너진 관리동 지하에서 철문 하나 — 화기고 표지가 반쯤 녹아 붙어 있다. 정원 관리인들의 화약고다.<br><br>
    백 년 묵은 화약은 두 얼굴이다. 삭아서 먹통이거나 — 삭아서 건드리면 우는 것이거나. 열기 전엔 모른다.<br>
    폭파공한테 남의 화약고는 보물창고이자 — 남이 쓰다 만 장부다. 어느 줄이 틀렸는지 모르는 장부.<br><br>
    문틈으로 바람이 드나든 흔적. 안에 뭐가 사는지도 — 열기 전엔 모른다.`,
  o:[
    { l:'① 장부 검수하듯 연다 — 문밖에서 줄로 당겨 열고, 반 시진 바람을 쐰 뒤 든다.', k:'steady', dc:25, wake:1,
      ok:`문고리에 줄을 걸고 모퉁이 뒤에서 당겼다. 끼익 — 아무 일 없음. 반 시진 바람을 쐬어 백 년 묵은 공기를 빼고 들어갔다.<br><br>
        선반 위 — 반은 먹통, 반은 쓸 만했다. 쓸 만한 쪽에서도 땀 흘린 것들 — 겉에 기름방울 맺힌 위험한 놈들 — 은 손도 안 댔다.<br>
        방수포 화약 두 덩이와 공업 심지 한 두름. 장부가 넉넉해졌다.<br><br>
        남의 화약은 남의 장부다. 검수 없이 쓰는 놈은 남의 실수까지 물려받는다 — 스승의 이 말을 오늘은 글자 그대로 지켰다.`,
      ng:`반 시진을 못 참았다 — 수풀 기척에 쫓겨 서둘러 들었다. 서두른 손이 선반의 땀 흘린 놈을 스쳤다.<br><br>
        쉭, 하고 한 귀퉁이가 끓었다. 통째로 문밖에 던지고 엎드렸다. 퍽 — 흙비.<br>
        건진 건 심지 한 두름뿐. 화기고는 그 소리에 몰린 기척들 때문에 다시 못 들어갔다. 남의 실수를 반만 물려받은 걸 다행으로 쳤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 화기고를 통째로 — 둥지 삼은 것이 있나 문을 두드려 소리부터 듣는다.', k:'sense', dc:25,
      ok:`철문을 세 번 두드리고 귀를 댔다. 빈 울림이어야 할 안쪽에서 — 부스럭. 작은 것들. 여럿.<br><br>
        문틈 아래로 연기 나는 걸레 한 장을 밀어 넣고 기다렸다. 작은 것들이 반대쪽 바람구멍으로 줄줄이 빠져나가는 소리.<br>
        비운 뒤에 들어가 챙겼다. 작은 것들이 쏠다 만 화약 상자 — 쏠린 놈은 버리고 성한 놈만.<br>
        화약고 문은 귀부터 대는 것. 보물창고와 둥지는 문 하나 차이다.`,
      ng:`두드린 소리에 안쪽 것들이 — 조용해졌다. 빈 줄 알고 열었다.<br><br>
        조용했던 건 숨은 것이었다. 발치로 쏟아져 나온 작은 것들에게 장화와 바지를 물어뜯겼다.<br>
        털어 내고 챙길 건 챙겼다. 성한 화약 한 덩이 — 와 물린 자국 한 다스. 조용한 둥지가 빈 둥지보다 나쁘다는 걸 바지가 배웠다.`,
      win:{ exp:19, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S2', t:'먹이대 공터 — 해 지기 전의 철거',
  x:`해 질 녘이면 것들이 모이는 먹이대 — 오늘 밤 야영지가 하필 그 바람 아래다. 공터를 지나는 김에 먹이대를 철거하면 밤이 편해진다.<br><br>
    쇠기둥 넷에 평상 하나. 화약이면 금방인데 — 해 질 녘까지 소리를 내면 안 되는 자리이기도 하다.<br>
    폭파공의 철거에는 두 길이 있다. 소리 나는 길과 — 시간이 드는 길.<br><br>
    해가 손가락 네 개 남았다.`,
  o:[
    { l:'① 무소리 철거 — 기둥 볼트를 기름 먹여 풀고, 평상을 눕혀 해체한다.', k:'break', dc:25, wake:1,
      ok:`볼트마다 기름 한 방울 — 스미는 동안 다음 볼트. 돌아오며 하나씩 풀었다. 손가락 두 개 해에 기둥 둘, 세 개째에 넷 다.<br><br>
        평상을 넷이 받아 소리 없이 눕혔다. 먹이대가 — 없던 것이 됐다.<br>
        해 질 녘, 모여든 것들이 빈 공터를 돌며 어리둥절해했다. 약속 장소가 사라진 저녁 — 그것들은 바람 위로는 코도 안 돌리고 흩어졌다.<br><br>
        폭파 없는 철거도 철거다. 볼트 스물넷을 푼 손목이 — 콩알 하나보다 조용히 같은 일을 했다.`,
      ng:`셋째 기둥 볼트가 — 녹아 붙어 안 돌았다. 해가 손가락 하나 남을 때까지 씨름하다 결국 평상이 비스듬히 걸렸다.<br><br>
        반 철거. 기운 평상이 바람에 끼익대는 소리가 밤새 났다.<br>
        모여든 것들이 기운 평상 둘레를 돌며 울었고, 그 소리에 야영지의 밤도 설잠이 됐다. 반만 한 철거는 안 한 것만 못할 때가 있다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 철거 대신 이사 — 평상 위 묵은 뼈와 기름때를 걷어 바람 반대쪽 숲에 옮겨 둔다.', k:'luck', dc:25,
      ok:`것들이 오는 건 먹이대가 아니라 — 먹이대 냄새다. 평상의 묵은 기름때 판자 두 장과 뼈 무더기를 걷어 바람 반대쪽 숲에 부렸다.<br><br>
        해 질 녘, 것들이 냄새를 따라 — 그 숲으로 갔다. 공터도 야영지도 빈 바람.<br>
        덤으로 뼈 무더기에서 성한 소금 덩이 하나를 건졌다. 옛 사육사 짐에서 구른 것이다.<br>
        냄새의 지도를 다시 그려 준 셈이다. 철거보다 싸고 — 것들도 저녁을 굶지 않았다. 셈이 두 쪽 다 맞는 날은 드물다.`,
      ng:`기름때 판자를 옮기다 — 한 장을 야영지 쪽 덤불에 떨어뜨린 걸 몰랐다.<br><br>
        해 질 녘 것들 반은 숲으로, 반은 — 그 덤불로 왔다. 야영지 코앞.<br>
        밤새 불을 키우고 교대로 지켰다. 새벽에 그 판자를 찾아 태웠다. 냄새 지도는 한 장만 흘려도 길이 두 갈래가 된다.`,
      win:{ exp:19, dream:2, item:'소금 덩이' }, lose:{ hp:-25, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 대검사 · 무력
// ------------------------------------------
kJob('greatsword', 'S', [

{ at:'S', t:'좁은 복도 — 휘두를 수 없는 칼',
  x:`복도 폭이 어깨 둘. 등의 대검은 복도보다 길다. 여기서 이 칼은 — 휘두르는 물건이 아니다.<br><br>
    어둠 저쪽에서 발소리가 온다. 하나. 거침없다. 좁은 데 싸움을 아는 걸음이다.<br>
    칼을 뽑아 봤자 벽에 걸린다. 그걸 저쪽도 아는 것이다. 큰 칼 든 먹이는 좁은 데서 잡는다 — 그게 저것들 교본일 것이다.<br><br>
    교본을 찢어 줄 차례다. 대검은 휘두르지 못하면 — 찌르고, 밀고, 벽이 된다.`,
  o:[
    { l:'① 칼끝을 복도 한가운데 두고 — 창처럼 겨눠 마중한다.', k:'break', dc:25, wake:1,
      ok:`칼을 어깨 위로 눕혀 끝만 앞으로 — 복도가 좁다는 건 저쪽도 비킬 데가 없다는 뜻이다.<br><br>
        달려온 것이 멈추지 못하고 칼끝을 제 가슴으로 받았다. 대검의 무게는 찌름에서도 무게다.<br>
        빼내고 보니 날이 아니라 끝 한 뼘만 쓴 싸움이었다.<br><br>
        대검의 전부를 쓰는 자리가 있고 한 뼘만 쓰는 자리가 있다. 좁은 복도는 한 뼘짜리 — 그 한 뼘이 창 한 자루 몫을 한다는 걸 배웠다.`,
      ng:`칼끝을 겨눈 높이가 가슴 — 저것은 바닥에 배를 붙이고 달려왔다.<br><br>
        칼 밑으로 파고든 것이 정강이를 물었다. 좁은 복도에서 칼을 버리고 뒹굴었다.<br>
        뒤의 일행 창이 끝냈다. 칼을 주워 메며 생각했다. 좁은 데서는 높이도 좁혀야 한다. 칼끝은 무릎 높이부터.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 칼집째 가로 세운다 — 복도를 이쪽 금 앞에서 끊는 문빗장으로.', k:'steady', dc:24,
      ok:`칼집째 복도에 가로로 — 양 벽 틈에 끼워 허리 높이 빗장을 질렀다.<br><br>
        달려온 것이 빗장 앞에서 멎었다. 넘자니 배를 보이고 기자니 목을 보이는 높이다.<br>
        빗장 너머에서 으르렁대는 것을 두고 일행이 등 뒤 갈림길로 다 빠질 때까지 — 버텼다. 마지막에 칼집째 뽑아 메고 물러났다.<br>
        대검은 뽑기 전에도 한 가지 일을 한다. 길을 끊는 일.`,
      ng:`벽 틈이 삭아 빗장이 반 박자에 내려앉았다. 저것이 그 위를 밟고 넘어왔다.<br><br>
        좁은 데서 엉겨 붙어 — 칼자루 머리로 때려 밀어냈다.<br>
        빗장은 걸 자리부터 보고 거는 것. 삭은 벽은 빗장도 삭게 만든다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S', t:'한 번의 값 — 두 번은 없는 칼',
  x:`대검의 셈은 단순하다. 한 번 휘두르면 한 호흡이 빈다. 빗나가면 그 한 호흡이 — 저쪽 것이다.<br><br>
    눈앞의 놈은 그 셈을 안다. 두 번 봤다. 칼이 오르면 물러나고, 내려와 박히면 들어온다.<br>
    세 번째 칼을 올리기 전에 정해야 한다. 이번 한 번은 — 언제, 어디서, 무엇과 바꿀 것인가.<br><br>
    대검사의 평생 숙제가 이 한 줄이다. 한 번의 값을 정하는 것.`,
  o:[
    { l:'① 빈 호흡을 판다 — 일부러 헛치고, 들어오는 놈 위로 되올려 벤다.', k:'break', dc:26, cost:{ might:34 }, wake:1,
      ok:`세 번째 칼을 — 일부러 반 뼘 앞에 헛쳤다. 박힌 칼, 빈 호흡. 놈이 교본대로 들어왔다.<br><br>
        박힌 칼은 빼는 게 아니라 — 박힌 자리를 축으로 되올리는 것이다. 바닥을 차고 오르는 날이 들어오던 놈의 턱 밑을 지났다.<br>
        한 번의 값으로 — 끝났다.<br><br>
        빈 호흡도 파는 물건이라는 걸 배웠다. 대검의 틈은 틈이 아니라 미끼 값이다.`,
      ng:`헛친 것까지는 팔렸다. 되올리는 길에 — 칼이 바닥 틈에 물렸다.<br><br>
        진짜 빈 호흡이 됐다. 들어온 놈의 발톱을 어깨로 받으며 칼자루째 몸으로 밀어 떼냈다.<br>
        일행이 사이를 벌려 줬다. 미끼 장사도 바닥을 보고 벌일 것 — 어깨 세 줄 값의 수업이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 한 번을 안 쓴다 — 칼을 세워 둔 채 놈이 지치도록 돌기만 한다.', k:'evade', dc:25,
      ok:`칼끝을 바닥에, 두 손을 자루에 — 탑처럼 서서 놈을 축으로만 돌았다. 칼은 들리지 않는다. 들리지 않는 칼은 셈이 안 된다.<br><br>
        놈이 칼 오르기를 기다리다 — 기다리다 — 제가 먼저 들어왔다. 기다림에 진 것이다.<br>
        들어온 그때 칼이 올랐다. 기다리게 한 쪽이 정한 순간에.<br>
        대검은 무거워서 느린 게 아니다. 아무 때나 안 들어서 느려 보일 뿐이다.`,
      ng:`돌기 싸움 반 각 — 이쪽 종아리가 먼저 저렸다. 칼 무게는 서 있어도 무게다.<br><br>
        축이 흔들린 반 박자에 놈이 들어와 허벅지를 긁고 나갔다.<br>
        결국 일행과 둘이서 몰아 잡았다. 기다림 싸움은 다리 힘 싸움이기도 하다. 종아리도 수련 장부에 올렸다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, spirit:-15 } }
  ] },

{ at:'S', t:'강철 지붕 — 받아 내는 칼',
  x:`위에서 떨어지는 것들이 있는 통로다. 천장 배관 사이 어둠에서 — 소리도 없이.<br><br>
    방패는 없다. 대신 폭 한 자짜리 강철판이 등에 있다.<br>
    대검을 머리 위로 눕혀 들면 — 한 사람 반 폭의 지붕이 된다. 팔이 버티는 동안은.<br>
    통로는 서른 걸음. 일행은 다섯.`,
  o:[
    { l:'① 칼지붕을 이고 맨 뒤에서 — 일행을 처마 밑처럼 지나게 한다.', k:'steady', dc:26, wake:1,
      ok:`칼을 두 손으로 머리 위에 눕혀 들고 일행을 바짝 앞세웠다. 처마 밑으로 병아리 꿰듯.<br><br>
        열두 걸음째 — 쿵. 지붕 위로 떨어진 것이 날 위에서 미끄러져 바닥에 나뒹굴었다. 일행 창 둘이 그걸 받았다.<br>
        스물네 걸음째 또 하나. 같은 순서.<br>
        서른 걸음을 다 내고 칼을 내렸다. 팔이 떨렸다 — 지붕 노릇 서른 걸음의 값. 싸게 산 다섯 목숨이다.`,
      ng:`스무 걸음째 떨어진 놈이 — 미끄러지지 않고 날을 움켜잡았다. 지붕 위에 올라탄 무게.<br><br>
        무릎이 꺾였다. 칼째 주저앉으며 옆으로 쏟아 냈다.<br>
        일행이 바닥에서 처리했다. 어깨가 한동안 안 올라갔다. 지붕은 미끄러워야 지붕이다 — 날 위에 기름을 발라 두는 버릇이 생겼다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-14 } },
    { l:'② 지붕 대신 — 천장을 먼저 찌른다. 배관 어둠을 칼끝으로 쓸며 간다.', k:'break', dc:26,
      ok:`머리 위 어둠을 믿지 않기로 했다. 세 걸음마다 칼끝으로 배관 사이를 — 휘젓지 않고 찔러 올렸다.<br><br>
        아홉 걸음째 칼끝에 물컹한 것이 닿았고, 비명과 함께 배관을 타고 달아나는 소리가 멀어졌다.<br>
        그 소리가 통로의 다른 어둠들한테도 소문이 된 모양이다. 남은 걸음은 조용했다.<br>
        기다렸다 받는 것보다 먼저 찔러 묻는 쪽이 — 팔도 덜 아프다.`,
      ng:`찔러 올린 칼끝이 배관을 때렸다. 쇳소리가 통로 전체에 울렸다.<br><br>
        어둠들이 일제히 움직였다. 떨어지는 대신 — 앞질러 가 통로 끝에서 기다리는 쪽으로.<br>
        통로 끝에서 한바탕 치르고 나왔다. 소리를 낸 수색은 수색이 아니라 예고다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S', t:'삭은 다리 — 무게의 셈',
  x:`골짜기 같은 배수로 위에 삭은 철제 발판 다리. 한 사람씩 — 이라고 다리가 삐걱대며 말한다.<br><br>
    문제는 이쪽 등의 쇳덩이다. 사람 하나 반 무게. 다리 셈에 이쪽은 두 사람이다.<br>
    버리고 건널 수는 없다. 이 어둠에서 대검을 버리는 건 손을 버리는 것이다.<br><br>
    다리 밑 어둠에서 물 아닌 것이 뒤척이는 소리가 난다. 떨어지는 것을 받는 일을 하는 어둠이다.`,
  o:[
    { l:'① 칼과 몸을 나눈다 — 칼에 줄을 매 먼저 밀어 보내고, 몸만 건넌다.', k:'fix', dc:25, wake:1,
      ok:`칼집에 줄을 매 다리 발판 위에 눕히고 — 건너편에서 일행이 줄을 당겨 칼만 먼저 미끄러뜨려 보냈다. 끄는 무게는 디디는 무게의 반이다.<br><br>
        칼이 건너고, 몸이 건넜다. 다리는 두 번 다 한 사람 셈으로 삐걱이고 말았다.<br>
        건너편에서 칼을 도로 멨다. 등이 허전했던 서른 걸음 — 그게 제일 길었다.<br><br>
        칼과 몸이 꼭 한 덩이일 필요는 없다. 떨어져도 줄 하나로 이어져 있으면 — 그것도 쥐는 법의 하나다.`,
      ng:`칼이 반쯤 건넜을 때 발판 틈에 칼집 모서리가 — 물렸다. 당길수록 깊이.<br><br>
        결국 이쪽이 다리 중간까지 가 빼내야 했다. 몸 더하기 칼 — 두 사람 반 셈.<br>
        다리가 비명을 질렀고 발판 하나가 떨어져 아래 어둠이 그걸 받는 소리가 났다. 나머지는 빨리 건넜다는 말로 줄인다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-15 } },
    { l:'② 다리를 안 믿는다 — 배수로 좁은 목을 찾아 칼을 걸쳐 외나무다리를 만든다.', k:'break', dc:26,
      ok:`배수로가 어깨너비로 좁아지는 목 — 칼집째 걸치니 꼭 맞는 외나무다리가 됐다.<br><br>
        강철 다리는 삐걱대지 않는다. 다섯이 차례로 칼등을 밟고 건넜다. 밑의 어둠이 뒤척였지만 — 떨어지는 것이 없는 다리는 그 어둠한테 빈 식탁이다.<br>
        마지막으로 건너며 칼을 거둬 멨다. 제 칼을 밟고 건너는 기분은 — 묘하게 떳떳했다.`,
      ng:`좁은 목의 저쪽 턱이 — 삭은 콘크리트였다. 셋째 사람 때 턱이 부스러지며 칼이 기울었다.<br><br>
        셋째가 미끄러지는 걸 양쪽에서 손목을 낚아챘다. 칼은 배수로 반 길 아래 턱에 걸렸다.<br>
        줄을 타고 내려가 칼을 건져 올리는 동안 — 아래 어둠과 눈이 마주쳤다고, 내려간 이쪽만 안다. 다리 공사는 양쪽 지반부터.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-29, spirit:-16 } }
  ] },

{ at:'S', t:'낮은 천장 — 눕힌 베기',
  x:`천장이 이마 높이다. 대검을 세로로 드는 순간 날이 천장을 문다.<br><br>
    그걸 아는 것이 이 방에 산다. 낮은 방에서만 사냥하는 놈 — 큰 칼이 못 서는 방을 제 우리로 고른 놈이다.<br>
    세로가 안 되면 가로다. 허리 높이로 눕힌 칼이 도는 금 — 방 전체가 그 금 안이다.<br><br>
    놈이 벽을 타고 돈다. 세로 버릇이 나오기를 기다리며.`,
  o:[
    { l:'① 눕힌 채로 돈다 — 허리의 회전만으로 방 폭 전체를 벤다.', k:'break', dc:26, wake:1, cost:{ might:35 },
      ok:`칼을 허리에 눕혀 붙이고 — 팔이 아니라 허리를 돌렸다. 눕힌 날이 방 폭을 수평으로 쓸었다.<br><br>
        벽을 타던 놈이 그 금 높이를 못 넘고 — 바닥으로 내려선 순간을 둘째 회전이 받았다.<br>
        천장은 긁히지 않았다. 바닥도. 그 사이 허리 높이만 — 깨끗하게 비었다.<br><br>
        세로를 빼앗기면 가로가 있다. 대검의 금은 긋는 방향이 정하는 게 아니라 — 허리가 정한다는 걸 몸이 알았다.`,
      ng:`첫 회전은 좋았다. 둘째 회전에 — 등짐이 벽을 긁으며 박자가 밀렸다.<br><br>
        놈이 그 반 박자에 바닥을 기어 들어와 발목을 쳤다. 한 바퀴 구르며 칼을 놓칠 뻔했다.<br>
        일행 창이 놈을 벽으로 몰아 준 덕에 셋째 회전으로 끝냈다. 도는 싸움은 등부터 비울 것 — 짐은 싸움 전에 내려놓는다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 놈의 우리를 바꾼다 — 천장 가운데 보를 쳐서 방 반쪽을 높인다.', k:'break', dc:26,
      ok:`천장이 낮은 건 — 내려앉은 가벽 때문이다. 그 가벽을 받친 썩은 보 하나를 칼자루 머리로 올려쳤다.<br><br>
        가벽 반쪽이 우수수 내려앉고 — 그 위 원래 천장이 드러났다. 방 반쪽의 하늘이 두 자 높아졌다.<br>
        높아진 반쪽으로 물러서 칼을 세웠다. 세로 금을 되찾은 대검 앞에서 — 낮은 방 사냥꾼은 제 우리 반쪽을 잃었다.<br>
        놈은 남은 낮은 반쪽에서 끝내 안 나왔다. 나올 수 없는 금이 그어진 것이다.`,
      ng:`보를 치자 가벽이 — 이쪽 머리 위까지 같이 내려왔다. 먼지와 판자 비.<br><br>
        뒤집어쓴 채 물러나는 등으로 놈이 덮쳤다. 판자 조각을 사이에 두고 뒹굴었다.<br>
        일행이 떼어 냈다. 천장 공사는 서 있을 자리부터 정하고 — 공사판 금언이 싸움판에서도 금언이었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S', t:'칼을 심는 밤',
  x:`바람이 칼날 같은 벼랑길 — 야영할 자리는 바위 턱 하나뿐이다. 묶을 기둥이 없다.<br><br>
    대검사의 해답은 등에 있다. 바위 틈에 대검을 — 심는 것이다. 뿌리 깊이 박아 다섯 목숨 줄을 묶을 기둥으로.<br>
    칼에게 밤새 맡기는 것이다. 다섯 목숨을.<br><br>
    심는 깊이가 모자라면 — 바람이 먼저 안다.`,
  o:[
    { l:'① 틈을 골라 세 번에 나눠 박는다 — 돌이 물고 칼이 버티게.', k:'break', dc:25, wake:1,
      ok:`바위 틈 중에 — 아래로 좁아지는 틈을 골랐다. 한 번에 깊이 아니라 세 번에 나눠, 돌이 날을 무는 소리가 바뀔 때까지.<br><br>
        목숨 줄 다섯을 자루에 묶고 밤을 났다. 바람이 밤새 줄을 당겼고 칼은 — 한 치도 안 밀렸다.<br>
        새벽에 뽑는 데 둘이 매달렸다. 그만큼 물려 있었다는 뜻이라 반가운 수고였다.<br><br>
        칼이 무기만이 아니라는 건 알았다. 기둥이고 말뚝이고 — 믿고 맡기는 물건이라는 건 이 밤에 처음 알았다.`,
      ng:`틈이 — 속에서 넓어지는 틈이었다. 밤중 바람에 칼이 반 뼘 들썩였다.<br><br>
        줄의 떨림에 모두 깼다. 어둠 속에서 칼을 도로 박고 — 교대로 자루를 붙들고 밤을 났다.<br>
        사람이 칼을 지키는 밤이 됐다. 거꾸로 된 밤. 틈은 겉이 아니라 속을 보고 고를 것.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-16, spirit:-17 } },
    { l:'② 칼을 눕혀 심는다 — 바위 턱을 가로질러 다섯 줄의 난간으로.', k:'fix', dc:25,
      ok:`세워 심을 깊이가 안 나오는 바위라면 — 눕히는 수다. 턱을 가로질러 양끝을 돌무더기로 눌러 묻었다.<br><br>
        허리 높이 강철 난간 하나가 생겼다. 다섯이 그 안쪽에 줄을 걸고 잤다.<br>
        밤중에 무엇이 벼랑을 타고 올라와 — 난간에 닿고, 쇠 맛을 보고, 도로 내려갔다. 이빨 자국 둘이 아침에 남아 있었다.<br>
        난간은 바람도 막고 이빨도 막았다. 눕힌 칼도 칼이다.`,
      ng:`돌무더기 한쪽이 밤사이 바람에 — 흘러내렸다. 난간 한끝이 벼랑 쪽으로 처졌다.<br><br>
        줄 하나가 그쪽으로 쏠리며 막내가 반 자 미끄러졌다. 비명에 다 깼다.<br>
        끌어올리고, 돌을 다시 쌓고, 남은 밤은 눈으로 지켰다. 누름돌은 바람 부는 쪽에 배로 — 산의 법을 벼랑이 가르쳤다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-15 } }
  ] },

{ at:'S', t:'칼을 보는 눈들',
  x:`야영 금 밖 어둠에 눈들이 모였다. 사람을 보는 게 아니다 — 불빛에 번뜩이는 대검을 본다.<br><br>
    이 어둠의 것들은 영리하다. 큰 이빨을 가진 짐승을 피하듯 큰 칼을 피한다. 그런데 오늘 눈들은 피하지 않고 — 재고 있다. 칼이 몇 번 오르는지, 오르고 나서 몇 호흡 늦는지.<br>
    내일이면 저 눈들은 교본 한 장을 다 쓸 것이다.<br><br>
    교본에 거짓을 적어 줄 기회이기도 하다. 보고 있을 때만 쓸 수 있는 기회.`,
  o:[
    { l:'① 가짜 버릇을 보여 준다 — 셋 셀 때마다 같은 쪽으로 드는 칼을, 밤새.', k:'gaze', dc:26,
      ok:`불가에서 칼 손질을 핑계로 — 셋을 셀 때마다 왼쪽 어깨로 올리는 버릇을 꾸며 보였다. 밤새. 눈들이 세는 걸 느끼면서.<br><br>
        이튿날 길목에서 그중 둘이 덮쳤다 — 왼쪽을 비우고. 교본대로.<br>
        칼은 오른쪽에서 나왔다. 교본의 거짓 장이 펼쳐지는 자리가 — 저것들 마지막 자리가 됐다.<br>
        보여 주는 것도 무기다. 적의 공부에 거짓 교재를 꽂는 법 — 대검사의 밤 수업이 하나 늘었다.`,
      ng:`꾸민 버릇이 — 과했다. 너무 고른 박자는 꾸민 티가 난다.<br><br>
        눈들이 밤중에 흩어졌다. 공부를 접은 게 아니라 — 꾸민 것을 꾸민 것으로 적어 간 것이다.<br>
        이튿날 길목의 둘은 어느 쪽도 안 믿고 — 양쪽에서 왔다. 치르긴 치렀는데 셈이 비쌌다. 거짓말은 박자까지 흐트러뜨려야 거짓말이다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-31, mind:-15 } },
    { l:'② 재는 값을 올린다 — 금 밖 제일 가까운 눈 하나를, 재는 도중에 끊는다.', k:'break', dc:26,
      doom:{ title:'재던 눈들', what:'어둠 속 눈들에게 물려 가 금 밖으로 끌려갑니다', dc:20, sec:38,
        text:`제일 가까운 눈을 향해 금 밖으로 — 한 걸음이 과했다. 눈 하나가 미끼고 나머지가 금 바로 밖에 엎드려 있었다.<br><br>
          칼이 오른 빈 호흡을 — 밤새 잰 그 호흡을 — 세 방향이 한꺼번에 샀다.<br>
          팔과 다리에 무게가 하나씩 붙고, 몸이 금 밖 어둠으로 끌린다. 불빛이 멀어진다. 등의 칼이 땅에 금을 그으며 따라온다. 그 금이 — 일행이 쫓아올 길이 되기를.`,
        dieText:`땅에 끌린 칼금이 어둠 속으로 서른 걸음 — 거기서 칼만 남아 있었다.<br><br>
          일행은 칼을 세워 그 자리에 박았다. 뽑아 갈 사람이 돌아오지 않는 칼은 비석이 된다.<br>
          그 뒤로 그 길목의 눈들은 박힌 대검 둘레를 크게 돌아 다녔다. 주인 없는 칼을 — 여전히 재지 못하는 것이다.`,
      },
      ok:`재는 공부에는 수업료를 매기는 법이다. 금 바로 밖 제일 가까운 눈 — 거기까지 한 걸음, 칼은 들지 않고 낮게 눕혀 나갔다.<br><br>
        눈이 칼 오르기를 기다렸다. 칼은 안 오르고 — 눕힌 채로 쓸었다. 잰 적 없는 각도.<br>
        비명 한 번에 눈들이 일제히 꺼졌다. 공부하던 책상을 뒤엎은 셈이다.<br>
        그날 밤부터 눈들은 이 일행의 불빛을 멀리서만 봤다. 수업료가 비싸다고 소문이 난 것이다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'S', t:'두 손이 못 되는 날 — 빌리는 손',
  x:`왼팔이 어제 물렸다. 오늘 칼이 — 반만 든다. 대검은 두 손의 칼이다. 한 손의 대검은 한숨이다.<br><br>
    어둠의 것들은 다친 쪽을 안다. 벌써 왼쪽으로만 간을 보고 들어온다.<br>
    일행 중 힘 좋은 막내가 곁에 선다. 창을 쥐어 본 손이지만 — 대검 자루는 두 사람 손이 같이 쥘 만큼 길다.<br><br>
    둘이 드는 대검. 교본에 없는 장이다. 오늘 쓰는 수밖에.`,
  o:[
    { l:'① 자루를 나눠 쥔다 — 이쪽이 길을, 막내가 힘을.', k:'bond', dc:26, wake:1,
      ok:`자루 위는 이쪽 오른손 — 길을 긋는 손. 자루 끝은 막내 두 손 — 미는 손. 구령은 숨으로 맞췄다.<br><br>
        왼쪽으로 들어온 놈이 — 두 사람 무게가 실린 날에 받혔다. 한 손 대검이 아니라 세 손 대검이었다.<br>
        놈이 물러나고, 막내가 떨리는 숨으로 물었다. 또 오면요. 또 하면 된다.<br><br>
        대검은 두 손의 칼이 아니라 — 두 손 몫의 칼이다. 누구 손이든. 그걸 다친 팔이 가르쳤다.`,
      ng:`길 긋는 손과 미는 손의 숨이 — 세 번째에 어긋났다. 날이 바닥을 치며 둘 다 앞으로 쏠렸다.<br><br>
        그 틈에 놈이 막내의 등짐을 찢고 지나갔다. 짐이었기 망정이지.<br>
        물러나 숨 구령부터 다시 맞췄다. 넷째부터는 맞았다. 빌린 손은 손보다 숨을 먼저 빌릴 것.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 칼을 바꾼다 — 대검을 막내 창 대신 거치대에 눕혀 두고, 이쪽은 한 손 단검으로.', k:'steady', dc:25,
      ok:`칼에 대한 고집을 하루 접었다. 대검은 바위에 눕혀 — 길목을 겨눈 거치 쇠뇌처럼 두고, 이쪽은 단검과 성한 오른팔로 금을 지켰다.<br><br>
        왼쪽을 간 보던 놈이 들어온 순간 — 바위의 대검을 오른손 하나로 밀어 떨어뜨렸다. 드는 게 아니라 떨어뜨리는 건 한 손으로도 된다.<br>
        제 무게로 떨어진 날 아래 놈이 깔렸다.<br>
        칼의 무게는 빌릴 수 있다 — 중력한테. 오늘의 두 번째 손은 중력이었다.`,
      ng:`거치한 대검이 — 바위 위에서 반 뼘 미끄러져 각이 틀어졌다. 떨어뜨린 날이 빈 땅을 쳤다.<br><br>
        놈이 그 쇳소리에 놀라 물러난 게 그나마 수확이다.<br>
        단검 하나로 남은 밤을 지켰다. 거치도 거치 나름 — 받침 돌부터 평평한 놈으로 고를 것. 한 손 수업은 끝이 없다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S', t:'피를 안 쏟게 베는 법',
  x:`이 어둠의 것들은 동족 피 냄새에 모인다. 한 놈을 베면 그 피가 — 다음 열 놈의 초대장이다.<br><br>
    대검사의 베기는 크고 깊다. 크고 깊은 상처는 피도 크고 깊다.<br>
    오늘은 거꾸로 벼려야 한다. 피가 적게 나는 큰 칼질 — 날이 아니라 칼의 무게와 넓이로 치는 법.<br><br>
    길목의 한 놈. 이놈을 조용히 눕혀야 뒤의 길이 조용하다.`,
  o:[
    { l:'① 칼배로 친다 — 날을 눕혀, 베지 않고 통째로 때려 눕힌다.', k:'break', dc:26, cost:{ might:33 },
      ok:`날을 수평으로 눕혀 — 베는 금이 아니라 때리는 면으로 들어갔다. 강철판 한 자 폭이 놈의 관자놀이를 쳤다.<br><br>
        피 한 방울 없이 — 놈이 접혔다. 소리도 둔탁한 한 번뿐.<br>
        길목을 지나는 동안 초대장은 돌지 않았다. 조용한 길.<br>
        대검의 날은 반쪽이다. 나머지 반은 — 무게. 무게만 쓰는 법을 오늘 한 장 적었다.`,
      ng:`칼배로 쳤는데 놈의 목 비늘이 — 날을 비틀었다. 눕힌 날이 반 바퀴 돌아 모서리가 섰다.<br><br>
        피가 났다. 적게 — 그러나 났다.<br>
        길목은 지났지만 반 시진 뒤부터 뒤가 소란해졌다. 초대장이 늦게 돈 것이다. 밤길을 서둘렀다. 무게로 치는 법은 쥐는 손목부터 다시 — 비틀리지 않게.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 베지 않는다 — 칼을 지렛대로 길목 바위를 굴려 길 자체를 막는다.', k:'fix', dc:25,
      ok:`놈을 치우는 대신 — 놈과 이쪽 사이를 막기로 했다. 비탈의 바위 밑에 칼끝을 꽂고 자루를 눌렀다.<br><br>
        바위가 구르며 길목에 — 꼭 맞게 앉았다. 놈의 길과 이쪽 길이 바위 하나로 갈렸다.<br>
        바위 너머에서 놈이 한참 긁는 소리를 냈다. 피 한 방울, 칼질 한 번 없는 밤.<br>
        대검은 지렛대 중에 제일 튼튼한 지렛대다. 날만 아깝지 않다면 — 그리고 오늘 밤 날은 하나도 안 아깝다.`,
      ng:`바위가 구르다 — 반 바퀴 모자라게 섰다. 길목 반이 열린 채다.<br><br>
        그 반 틈으로 놈이 어깨를 비집었다. 결국 칼배로 한 대 — 피는 안 났지만 소리가 났다.<br>
        바위를 마저 미는 데 다섯이 붙었다. 지렛대 셈은 끝까지 — 반 바퀴는 안 구른 것과 같다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-15 } }
  ] },

{ at:'S', t:'칼끝이 읽는 어둠',
  x:`불을 쓸 수 없는 구간이다 — 불빛을 보면 모이는 것들의 영역. 완전한 어둠 쉰 걸음.<br><br>
    대검이 앞장선다. 칼끝을 낮게 앞으로 — 지팡이처럼. 강철 두 자 반이 손보다 먼저 어둠을 더듬는다.<br>
    칼끝에 닿는 것의 결 — 돌, 쇠, 나무, 그리고 물컹한 것 — 이 자루를 타고 손바닥까지 온다.<br><br>
    쉰 걸음의 눈이 칼끝 한 점이다.`,
  o:[
    { l:'① 칼끝을 눈 삼아 — 결을 읽으며 한 걸음씩 줄을 이끈다.', k:'sense', dc:25, wake:1,
      ok:`돌. 돌. 쇠턱 — 왼쪽으로. 칼끝이 읽는 결을 낮은 소리로 뒤에 전하며 걸었다.<br><br>
        서른 걸음째 칼끝에 — 물컹한 것. 숨을 멈추고 결을 더 읽었다. 오르내린다. 자는 숨이다.<br>
        잠든 것의 둘레를 칼끝으로 그려 — 그 금 밖으로 넷을 돌렸다. 깨우지 않고 쉰 걸음을 다 냈다.<br><br>
        칼끝에도 눈이 생긴다. 쓰는 만큼. 오늘 쉰 걸음어치 눈이 밝아졌다.`,
      ng:`마흔 걸음째 — 물컹한 것을 돌로 읽었다. 이끼 낀 돌인 줄.<br><br>
        칼끝에 눌린 그것이 깨어 비명을 질렀다. 어둠 전체가 그 비명에 대답했다.<br>
        남은 열 걸음을 끌고 뛰다시피 나왔다. 물컹한 것과 이끼 낀 돌 — 칼끝 공부의 다음 장이 정해졌다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-27, mind:-16 } },
    { l:'② 어둠에 금을 긋는다 — 칼끝으로 바닥을 그어, 뒤 사람들의 길 홈을 판다.', k:'break', dc:25,
      ok:`칼끝에 체중 반을 실어 — 바닥에 홈을 그으며 걸었다. 발끝으로 더듬을 수 있는 금.<br><br>
        뒤의 넷이 그 홈에 발끝을 걸고 줄줄이 따라왔다. 어둠 속의 철로.<br>
        갈림길마다 홈을 꺾어 줬다. 쉰 걸음이 끝나고 불빛에 들자 — 마지막 사람까지 한 번도 손을 안 잡고 건너온 걸 알았다.<br>
        지나간 자리에 길을 새기는 칼. 베는 것 말고도 새기는 일이 칼의 일이다.`,
      ng:`홈을 긋는 쇳소리가 — 바닥 울림 좋은 구간에서 생각보다 멀리 갔다.<br><br>
        어둠 속에서 무엇이 그 소리를 따라 나란히 걷기 시작했다. 홈 긋는 소리와 네 발 소리의 이중주.<br>
        홈을 끊고 숨을 죽인 채 더듬어 나왔다. 철로는 좋은 수지만 — 까는 소리까지 셈에 넣을 것.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-17 } }
  ] },

{ at:'S', t:'돌진 — 창이 되는 대검',
  x:`들소만 한 것이 통로 저쪽에서 흙을 긁는다. 돌진 전의 버릇. 피할 옆 공간은 — 없다.<br><br>
    피할 수 없는 돌진은 받는 수밖에 없다. 대검사의 교본 마지막 장 — 칼끝을 돌진에 맞춰 세우고, 자루 끝을 땅에 묻는다. 창병의 수를 칼로 쓰는 것.<br>
    버티는 건 팔이 아니다. 땅이다. 팔은 각도만 지킨다.<br><br>
    흙 긁는 소리가 멎었다. 온다.`,
  o:[
    { l:'① 자루를 땅에 묻고 — 각도 하나로 돌진을 받는다.', k:'break', dc:26, cost:{ might:38 },
      doom:{ title:'돌진하는 것', what:'돌진에 떠밀려 어둠 속으로 실려 갑니다', dc:20, sec:36,
        text:`각도는 맞았다. 땅이 — 틀렸다. 자루 끝이 묻힌 자리가 겉만 단단한 빈 흙이었다.<br><br>
          칼끝이 가슴 비늘에 박히고도 자루가 뒤로 밀렸다. 박힌 칼째 — 이쪽까지 — 돌진이 그대로 안고 달린다.<br>
          칼자루를 놓지 못한 손이 문제인지 덕인지 — 들소만 한 것의 가슴에 칼과 함께 매달려 어둠 속으로 실려 간다. 놈이 멈출 때가 — 어디일지, 무엇 앞일지.`,
        dieText:`통로 끝 어둠에서 쿵 — 무엇이 벽을 들이받는 소리가 났다. 한 번. 그리고 조용.<br><br>
          따라간 일행은 벽 밑에서 칼을 찾았다. 칼은 제 일을 했다 — 놈도 거기 있었다.<br>
          사람은 칼과 놈 사이에 — 있던 자리만 있었다. 대검은 그날부터 막내가 이어 멨다. 자루에 묻은 흙을 — 빈 흙을 — 막내는 평생 안 잊었다.`,
      },
      ok:`발꿈치로 땅을 세 번 찍어 — 속까지 단단한 자리를 골라 자루를 묻었다. 무릎을 낮추고 각도 하나에 전부를 걸었다.<br><br>
        부딪치는 순간은 소리가 먼저였다. 칼끝이 돌진의 한가운데를 — 돌진의 제 무게로 — 꿰었다.<br>
        밀린 건 반 걸음. 땅이 받고, 각도가 이겼다.<br>
        들소만 한 것이 칼 위에서 식었다. 교본 마지막 장에 오늘 날짜를 적었다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 받지 않는다 — 통로 천장 보를 미리 반 베어, 돌진이 제 지붕을 무너뜨리게 한다.', k:'gaze', dc:26,
      ok:`돌진은 직선이다. 직선 위의 천장 보 — 썩은 놈 하나 — 를 미리 반만 베어 두고, 그 밑으로 저쪽을 꾀었다.<br><br>
        돌진의 발굽 울림이 반 벤 보를 마저 흔들었다. 보와 천장 반 칸이 돌진 위로 — 저쪽 무게가 저쪽 지붕을 당긴 셈이다.<br>
        먼지가 가라앉자 길은 막혔지만 돌진도 멎어 있었다.<br>
        받을 수 없는 힘은 제 힘으로 지게 한다. 베는 자리가 꼭 적의 몸일 필요는 없다.`,
      ng:`보를 반 베다 — 톱질 소리에 돌진이 예정보다 일찍 왔다.<br><br>
        반의반만 벤 보는 안 무너졌다. 통로 벽에 붙어 돌진을 흘려보내며 옷깃이 비늘에 쓸렸다.<br>
        되돌아 나가는 놈을 보내 주고 — 보를 마저 베어 길을 막았다. 늦은 공사는 공사 소리부터 숨길 것.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-14 } }
  ] },

// ---------- S1 『표본실 — 착륙 이후』 ----------

{ at:'S1', t:'검은 피와 바꾸는 날',
  x:`이 시설의 것들을 베면 날이 녹는다. 대검의 날은 두 자 반 — 녹을 자리도 두 자 반이다.<br><br>
    피할 수 없는 큰 놈이 복도를 막았다. 베어야 한다. 베면 날이 상한다. 안 베면 사람이 상한다.<br>
    대검사의 셈 — 날의 어느 한 뼘과 이 싸움을 바꿀 것인가. 날 전체를 적시는 깊은 베기 대신, 한 뼘만 쓰는 꿰기와 — 피가 쏟아지는 방향을 정해 주는 각도.<br><br>
    날은 소모품이고 목숨은 아니다. 다만 소모의 값은 정하고 쓴다.`,
  o:[
    { l:'① 끝 한 뼘만 판다 — 꿰고, 비틀지 않고, 피가 저쪽으로 쏟아지게 뽑는다.', k:'break', dc:26, wake:1, cost:{ might:36 },
      ok:`찌름의 각도를 — 아래에서 위로 — 잡았다. 꿰뚫린 자리가 저쪽으로 기울게. 끝 한 뼘이 들어가고, 비틀지 않고, 그대로 당겨 뽑았다.<br><br>
        검은 피가 등 뒤 — 놈의 등 뒤 — 로 쏟아졌다. 날에 묻은 건 한 뼘 치.<br>
        그 한 뼘을 바닥에 세 번 긁어 벗겼다. 홈이 파였지만 날은 살았다.<br><br>
        날의 값을 정하고 쓰는 법 — 한 뼘의 장부. 대검사의 장부는 화약쟁이 것보다 짧지만 — 있다는 걸 오늘 알았다.`,
      ng:`꿰는 각이 반 치 얕았다. 뽑는 길에 놈이 몸을 틀어 — 피가 날을 타고 흘렀다.<br><br>
        반 자가 녹았다. 끝 한 뼘이 아니라.<br>
        싸움은 이겼다. 숫돌 앞에서 밤을 새웠다. 반 자 홈을 고르며 — 각도 반 치의 값을 손가락이 외우도록.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 날을 아예 안 쓴다 — 복도의 캐비닛을 칼로 밀어 놈째 벽에 눌러 둔다.', k:'fix', dc:25,
      ok:`복도 양쪽의 강철 캐비닛 — 칼을 지렛대 삼아 둘을 넘어뜨려 놈을 벽과 캐비닛 사이에 끼웠다.<br><br>
        눌린 놈이 버둥댔지만 강철 가구는 녹는 피가 안 나온다. 끼인 채 두고 — 다섯이 그 옆을 줄지어 지났다.<br>
        지나며 보니 놈이 캐비닛을 — 천천히 — 밀어내고 있었다. 서둘렀다. 뒤에서 쿵 소리가 났을 때는 모퉁이 둘을 돈 뒤였다.<br>
        벤 적 없는 승리. 날은 오늘도 두 자 반 그대로다.`,
      ng:`첫 캐비닛이 넘어가며 — 놈이 아니라 복도 쪽으로 기울었다. 일행 둘이 뛰어 피했다.<br><br>
        놈은 그 소동에 이쪽 셈을 다 봤다. 둘째 캐비닛 뒤로 도는 놈과 복도에서 정면으로 — 결국 끝 한 뼘을 썼다.<br>
        가구 싸움은 기울 방향부터 — 무게 중심은 밀기 전에 읽는 것. 벤 한 뼘은 바닥에 긁어 벗겼다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-31, mind:-15 } }
  ] },

{ at:'S1', t:'격벽 밑의 지렛대',
  x:`격벽이 사람 하나를 — 다리를 — 물고 멎었다. 비상 정지에 걸린 것이다. 다시 움직이면 마저 내려온다.<br><br>
    들어 올릴 기계는 죽었다. 사람 손으로는 어림없는 무게.<br>
    대검이 있다. 두 자 반 강철 — 세상에서 제일 튼튼한 지렛대. 문 밑에 꽂고 받침돌에 걸어 — 들어 올리는 것이다.<br>
    날이 버틸지 휠지는 — 해 보면 안다. 다리가 기다려 주는 동안.`,
  o:[
    { l:'① 칼을 꽂고 받침을 괴어 — 다섯 체중으로 자루를 누른다.', k:'break', dc:26, wake:1,
      ok:`날을 문 밑 틈에 — 날 방향이 아니라 옆면이 받게 — 꽂고, 캐비닛 문짝을 받침으로 괴었다. 다섯이 자루에 매달렸다.<br><br>
        격벽이 끼익 — 한 뼘 올랐다. 물린 다리가 빠지고, 칼을 뽑자 문이 도로 앉았다.<br>
        날을 살폈다. 휘지 않았다. 옆면으로 받은 덕이다 — 날로 받았으면 두 동강이었다.<br><br>
        지렛대 일에는 지렛대의 결이 있다. 베는 결과 미는 결 — 강철에도 결이 있다는 걸, 대검을 십 년 메고 처음 알았다.`,
      ng:`받침 문짝이 — 무게에 쪼개졌다. 격벽이 반 뼘 올랐다가 도로 떨어지며 물린 다리가 비명을 보탰다.<br><br>
        둘째 받침은 바닥 벽돌을 모아 쌓았다. 이번엔 올랐다.<br>
        다리는 빠졌다 — 부러진 채로. 부목을 대고 업었다. 받침부터 돌로 — 급한 지렛대일수록 받침이 반이다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, mind:-15 } },
    { l:'② 문을 안 든다 — 바닥을 판다. 다리 밑 바닥 타일을 깨서 빼낼 틈을.', k:'gaze', dc:25,
      ok:`문은 강철이지만 바닥은 타일이다. 싸울 상대를 바꿨다 — 다리 밑 타일 석 장을 칼끝으로 쪼아 깼다.<br><br>
        타일 밑 모래층이 드러나자 다리가 — 아래로 — 빠질 틈이 생겼다. 조심히 끌어냈다.<br>
        격벽은 손도 안 댔다. 비상 정지도 안 풀렸다.<br>
        센 놈과 싸우지 말고 무른 놈을 찾을 것 — 문과 바닥 중에 바닥이 물렀다. 늘 둘 다 봐야 한다.`,
      ng:`타일이 — 두 겹이었다. 밑장이 콘크리트. 쪼는 동안 물린 다리의 숨이 가빠졌다.<br><br>
        결국 칼을 문 밑에 꽂는 수로 돌아갔다. 돌아가는 데 쓴 시간만큼 다리가 상했다.<br>
        빼내긴 했다. 업고 걸으며 적었다. 무른 놈을 찾는 것도 좋지만 — 찾는 시간의 값부터 셈할 것.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S1', t:'통풍구 사잇길 — 두 손이 묶인 서른 걸음',
  x:`복도 양쪽 벽에 통풍구가 번갈아 — 왼쪽 셋, 오른쪽 넷. 저 안의 것들은 지나가는 것의 — 들고 있는 것부터 잡아챈다. 먼저 간 조의 등불이 그렇게 사라졌다 한다.<br><br>
    대검을 등에 메면 등이 과녁이다. 손에 들면 손이 과녁이다.<br>
    서른 걸음 — 칼과 몸이 같이 지나가는 법을 정해야 한다.<br><br>
    통풍구 일곱 개가 숨을 쉰다. 들이쉬고, 내쉬고.`,
  o:[
    { l:'① 칼을 몸 앞에 세워 안고 — 벽에서 제일 먼 한가운데로 걷는다.', k:'steady', dc:26,
      doom:{ title:'통풍구의 손들', what:'통풍구 안으로 끌려 들어갑니다', dc:20, sec:37,
        text:`한가운데 — 양쪽에서 똑같이 먼 길 — 이 양쪽에서 똑같이 가까운 길이기도 하다는 걸, 열다섯 걸음째에 배웠다.<br><br>
          왼쪽 둘째와 오른쪽 셋째가 — 동시에 — 열렸다. 긴 것 둘이 양팔을 하나씩 감았다.<br>
          칼을 안은 두 손이 — 칼 때문에 — 늦었다. 몸이 오른쪽 통풍구 입에 어깨까지 들어간다. 안은 칼이 입 테두리에 가로로 걸렸다. 걸린 동안만 — 이 자세가 버티는 동안만 — 사람이다.`,
        dieText:`통풍구 입에 대검이 가로로 걸려 있었다. 안쪽으로 당긴 자국이 자루에 깊었다.<br><br>
          일행은 칼을 — 뽑지 않고 그대로 두었다. 그 입을 막는 빗장으로.<br>
          그 복도를 나중에 지난 조들은 통풍구 하나가 대검에 봉해진 걸 보고 — 사연을 묻지 않았다 한다. 묻지 않아도 아는 모양이었다.`,
      },
      ok:`칼을 칼집째 가슴에 세워 안고 — 양 벽에서 똑같이 먼 한가운데를 걸었다. 어느 쪽 손이 뻗어도 반 뼘 모자라는 금.<br><br>
        왼쪽 둘째에서 긴 것이 뻗었다 — 반 뼘 앞에서 허공을 긁었다. 오른쪽 셋째도 — 같은 반 뼘.<br>
        서른 걸음 내내 반 뼘의 금 위를 걸었다. 칼은 품 안에서 한 번도 안 흔들렸다.<br>
        금을 긋는 건 칼만이 아니다. 걸음도 금을 긋는다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 칼로 먼저 묻는다 — 통풍구마다 칼끝을 들이밀어, 잡아채게 하고 비웠을 때 지난다.', k:'break', dc:26,
      ok:`첫 통풍구 앞에서 — 칼끝을 입구에 들이밀었다. 안의 것이 덥석 — 강철을 물었다. 이가 갈리는 소리.<br><br>
        문 것이 질려 놓을 때까지 밀어붙였다 빼냈다. 그 통풍구는 — 한동안 조용했다. 문 자리가 아픈 동안.<br>
        일곱 입에 일곱 번 — 쇠 맛을 돌렸다. 쇠 맛 본 입들은 그 뒤를 지나는 살 맛을 — 의심부터 했다.<br>
        서른 걸음이 느긋해졌다. 묻고 지나가는 길은 늦어도 — 통째로 이쪽 길이다.`,
      ng:`다섯째 입이 — 칼끝을 물고 놓지 않았다. 당기기 싸움.<br><br>
        안쪽 힘이 생각보다 컸다. 셋이 자루에 매달려서야 뽑혔다 — 끝 반 뼘이 이빨 자국투성이로.<br>
        소동 중에 일곱째 입에서 뻗은 것이 막내 등짐을 채 갔다. 짐 하나 값 — 묻는 것도 좋지만 답이 길어지면 끊고 지날 것.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

{ at:'S1', t:'숙주 앞의 칼 — 쓰지 않을 수 있는 무게',
  x:`복도 끝에 연구원이었던 것이 서 있다. 가슴의 다른 박자 — 이미 늦은 몸이라는 걸 모두 안다.<br><br>
    일행의 눈이 대검으로 온다. 제일 큰 칼이 제일 빨리 끝낼 수 있다는 눈.<br>
    대검사는 안다 — 이 칼은 끝내는 칼이지, 끝내는 것밖에 못 하는 칼이 아니라는 걸.<br>
    칼을 쓰는 결정과 안 쓰는 결정 — 무게는 같은 손에 있다.`,
  o:[
    { l:'① 한 번에, 돌아서기 전에 — 제일 큰 칼의 책임을 진다.', k:'break', dc:26, cost:{ might:37 },
      ok:`맡겠다고 — 말로 하지 않고 한 걸음 앞으로 나서는 걸로 말했다. 일행이 물러서 길을 냈다.<br><br>
        한 번이었다. 크고, 깊고, 되돌아볼 것 없는 한 번. 겉사람과 안의 것이 같이 끝났다 — 안의 것이 빠져나올 틈도 없는 속도가 대검의 자비다.<br>
        명찰을 거둬 주머니에 넣었다. 시설 끝의 명단 벽에 걸어 줄 것이다.<br><br>
        제일 큰 칼을 메는 값이 이런 날이라는 걸 — 메던 첫날의 자신은 몰랐다. 알고도 메는 게 지금의 자신이다.`,
      ng:`한 번이 — 반 번이 됐다. 마지막 순간 그것이 사람 목소리를 냈다. 추워요, 라고.<br><br>
        흔들린 반 뼘에 안의 것이 가운을 찢고 튀어 천장으로 붙었다. 겉사람만 바닥에 남았다.<br>
        천장의 것은 일행과 함께 쫓아 끝냈다. 명찰은 거뒀다. 반 번의 값 — 목소리는 귀로 듣지 말고 박자로 들을 것. 알면서도 또 흔들릴 것이다. 사람이라서.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-19, spirit:-18 } },
    { l:'② 칼을 세워 길만 막는다 — 끝내는 건 시설의 격벽에 맡긴다.', k:'steady', dc:25,
      ok:`그것의 걸음은 느리다. 칼을 복도 한가운데 세워 — 이쪽으로 못 오는 금을 긋고, 일행을 격벽 구간 너머로 물렸다.<br><br>
        그것이 금 앞에서 서성이는 동안 마지막 사람이 비상 레버를 당겼다. 격벽이 내려와 — 그것과 이쪽 사이를 영구히 갈랐다.<br>
        칼에는 아무것도 안 묻었다.<br>
        끝내지 않고 가르는 길이 있으면 — 가르는 길이 먼저다. 큰 칼일수록 그 순서가 무겁다.`,
      ng:`격벽 레버가 — 반쯤 내려오다 멎었다. 비상 전원이 모자랐다.<br><br>
        반 열린 틈으로 그것이 몸을 숙여 들어왔다. 결국 칼이 나섰다 — 준비 없이, 좁은 틈 앞에서.<br>
        끝냈다. 깔끔하지 못했다는 것만 적는다. 기계에 맡기는 길은 기계 상태부터 — 레버는 당기기 전에 전원 눈금을 볼 것.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'S1', t:'여왕의 홀 — 긴 칼의 금',
  x:`큰 문 앞 홀 — 줄지어 선 호위들 앞을 다섯이 지나야 한다. 작은 문까지 스무 걸음.<br><br>
    숨고 속이는 수는 다른 조들의 것이다. 대검사에게는 대검사의 수가 있다 — 금을 긋고, 금을 보이고, 금의 값을 저쪽이 셈하게 하는 것.<br>
    두 자 반의 날이 닿는 금 — 그 금을 저것들 눈앞에 그어 보이며, 금과 벽 사이로 일행을 지나게 한다.<br><br>
    선 것들의 고개가 일제히 돈다. 금의 값을 재는 눈 여섯.`,
  o:[
    { l:'① 금을 보여 준다 — 바닥에 날끝으로 한 줄을 그으며, 그 금을 등지고 걷는다.', k:'break', dc:26, wake:1, cost:{ might:40 },
      ok:`날끝으로 바닥 철판에 — 끼이익 — 스무 걸음의 금을 그으며 옆걸음으로 지났다. 일행은 금과 벽 사이로.<br><br>
        호위들의 눈이 금 긋는 날을 따라왔다. 소리와 불꽃과 두 자 반의 강철 — 값을 재는 눈들이 재기를 끝내지 못했다.<br>
        재는 동안은 안 온다. 저것들은 셈이 끝나야 움직인다 — 셈이 안 끝나는 금을 그어 주면 된다.<br><br>
        작은 문이 닫히고, 홀 바닥에는 금 하나가 남았다. 다음 조가 그 금을 보고 길을 알았다 한다. 금은 그런 것이다.`,
      ng:`열다섯 걸음째 — 바닥 철판이 끝나고 콘크리트. 금 긋는 소리가 바뀌자 재던 눈들의 셈이 끝났다.<br><br>
        맨 끝 호위가 금을 넘어 들어왔다. 눕힌 날로 받아 밀며 — 남은 다섯 걸음은 금이고 뭐고 내달렸다.<br>
        문이 닫히고 나서야 숨을 쉬었다. 금은 소리까지 금이다 — 바닥 재질까지 읽고 그을 것.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 금을 안 긋는다 — 칼을 등에 세워 메고, 제일 큰 짐승처럼 느리게 지난다.', k:'hide', dc:25,
      ok:`저것들의 셈은 크기와 속도다. 칼을 세워 메 윤곽을 키우고 — 느리게, 아주 느리게 걸었다. 크고 느린 것 — 저것들 셈에서 그건 센 것이다.<br><br>
        여섯 고개가 따라 돌았지만 아무도 금을 안 넘었다. 센 것은 먼저 안 건드린다 — 특히 주인 숨소리가 들리는 홀에서는.<br>
        다섯이 그 그림자 폭에 묻어 지났다.<br>
        대검의 윤곽이 하는 일이 또 하나 늘었다. 뽑지 않은 칼의 일이.`,
      ng:`열 걸음째 — 뒤의 막내가 서두르며 그림자 밖으로 반 발 나갔다. 작고 빠른 것 하나가 셈에 잡혔다.<br><br>
        끝 호위 하나가 막내 쪽으로 미끄러져 왔다. 칼을 뽑는 소리 — 그 쇳소리 하나로 멈춰 세웠다.<br>
        마주 선 반 호흡 뒤 — 저쪽이 줄로 돌아갔다. 문까지 남은 걸음을 모두 그림자 안에서 걸었다. 이번엔 아무도 안 나갔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-17 } }
  ] },

{ at:'S1', t:'배양조 거치대 — 베어서 옮기는 것',
  x:`막힌 통로 — 이번에는 배양조가 선 채로 길을 막았다. 안에 든 것이 — 깨어 있다. 유리 너머로 이쪽을 본다.<br><br>
    유리를 깨면 그것과 보존액이 한꺼번에 쏟아진다. 통로에서 — 최악의 자리에서.<br>
    대검사의 눈이 유리가 아니라 — 거치대를 본다. 배양조를 받친 강철 다리 넷. 셋을 베면 조는 벽 쪽으로 기운다. 유리는 벽에 기대 안 깨지고, 길은 열린다.<br><br>
    베는 순서가 전부다. 틀린 순서는 조를 이쪽으로 눕힌다.`,
  o:[
    { l:'① 다리 셋을 — 벽 반대쪽부터 — 순서대로 벤다.', k:'break', dc:26,
      ok:`기울 방향의 반대 — 통로 쪽 다리부터. 하나. 둘. 조가 벽 쪽으로 기우는 걸 확인하고 — 셋.<br><br>
        배양조가 벽에 어깨를 기대듯 천천히 누웠다. 유리는 안 깨졌다. 안의 것이 기운 액체 속에서 — 어리둥절해했다.<br>
        열린 길로 다섯이 지났다. 안의 것과 유리 한 장 거리로 스치며 — 눈이 마주쳤지만, 유리는 유리다.<br>
        베는 순서가 일의 전부인 날이 있다. 오늘 세 번의 순서는 — 교본에 적을 만했다.`,
      ng:`둘째 다리가 — 속이 빈 가짜 기둥이었다. 벤 순간 조가 예정보다 빨리, 비스듬히 틀어지며 기울었다.<br><br>
        유리 모서리가 벽 돌출부를 쳐 — 금이 갔다. 보존액이 실금으로 새기 시작했다.<br>
        새는 속도보다 빨리 지났다. 등 뒤에서 유리가 마저 갈라지는 소리와 — 젖은 것이 바닥을 치는 소리. 뛰었다. 다리도 두드려 보고 벨 것 — 강철에도 가짜가 있다.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-29, mind:-15 } },
    { l:'② 베지 않고 — 조 꼭대기 배액 밸브를 칼끝으로 돌려 보존액만 뽑는다.', k:'fix', dc:25,
      ok:`배양조 어깨의 배액 밸브 — 손은 안 닿지만 칼끝은 닿는다. 날끝을 밸브 홈에 걸어 반 바퀴.<br><br>
        보존액이 바닥 배수구로 — 조 안의 수위가 내려가자 안의 것이 액체를 잃고 바닥에 — 잠들 듯 — 가라앉았다. 저것들은 마른 데서 반 박자 느려지고, 액을 다 잃으면 — 움직임을 접는다.<br>
        잠잠해진 조의 옆구리 공간으로 지났다. 유리도, 피도, 칼질도 없이.<br>
        칼끝이 밸브를 돌린 날 — 대검의 섬세한 일 목록에 한 줄이 늘었다.`,
      ng:`밸브가 반 바퀴에 — 부러졌다. 백 년 묵은 놋쇠.<br><br>
        보존액이 졸졸이 아니라 — 꼭지째 뿜었다. 수위가 한 번에 떨어지자 안의 것이 놀라 유리를 쳤다.<br>
        금 가는 소리를 들으며 뛰어 지났다. 깨지는 소리는 모퉁이 너머에서 들었다. 백 년 묵은 꼭지는 반의반 바퀴씩 — 급할수록.`,
      win:{ exp:21, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'S1', t:'천장의 고치들 — 숙인 걸음',
  x:`복도 천장에 고치들이 매달려 있다. 사람 하나씩 들어갈 크기 — 안 들여다보는 게 서로를 위한 일이다.<br><br>
    고치 밑단이 — 하필 — 등에 멘 대검 꼭대기 높이다. 스치면 찢어지고, 찢어지면 안의 것이 깬다.<br>
    서른 걸음의 고치 복도. 칼을 눕혀 안고 허리를 숙이면 지나는 높이다.<br>
    고치 몇 개가 — 숨 쉬듯 — 천천히 오르내린다. 찬 것은 죽은 고치, 오르내리는 것은 — 익는 고치다.`,
  o:[
    { l:'① 칼을 안고 허리를 숙여 — 오르내리는 고치 밑만 골라 짚으며 지난다.', k:'steady', dc:26,
      doom:{ title:'익은 고치', what:'고치 속으로 끌려 올라갑니다', dc:20, sec:36,
        text:`스물두 걸음째 — 바로 위 고치가 오르내림을 멈췄다. 익은 고치가 익기를 끝내는 순간이 하필.<br><br>
          밑단이 — 아래로 — 열렸다. 긴 것들이 쏟아져 내려 어깨와 안은 칼을 한꺼번에 감았다.<br>
          발이 바닥에서 뜬다. 고치 입이 어깨를 넘어온다. 안은 안온하고 축축하고 — 숨 쉬듯 오르내린다. 이제 이 고치도 오르내리는 쪽이 되는 것이다. 안은 칼이 입에 가로 걸려 — 그 한 뼘이 아직 바깥이다.`,
        dieText:`서른 걸음 복도의 스물두 걸음째 고치가 — 다음 날부터 다른 고치들보다 크게 오르내렸다.<br><br>
          일행은 그 복도를 다시 지나지 않았다. 반 층을 돌아 다녔다.<br>
          돌아 다니는 길목에서 막내가 물었다. 꺼낼 수는 없느냐고. 아무도 대답하지 않은 것이 대답이었다.`,
      },
      ok:`오르내리는 고치는 — 박자가 있다. 내려올 때 멈추고 오를 때 걸었다. 허리는 숙이고 칼은 가슴에.<br><br>
        스물두 걸음째 — 바로 위 고치가 박자를 멈췄다. 멈춘 고치 밑에서는 — 이쪽도 멈춘다. 세 호흡 — 고치가 도로 오르내렸다. 마저 걸었다.<br>
        서른 걸음 끝 — 허리를 펴는 소리가 다섯 번. 아무 고치도 안 울었다.<br>
        익는 것들 밑을 지나는 법 — 익는 박자부터 읽을 것. 등의 칼이 오늘은 끝까지 얌전했다.`,
      win:{ exp:23, dream:3 } },
    { l:'② 못 믿을 복도다 — 입구 쪽 죽은 고치 둘을 베어 내려, 길과 높이를 먼저 확인한다.', k:'break', dc:26,
      ok:`입구의 찬 고치 둘 — 죽은 것 — 을 베어 내렸다. 떨어진 고치는 빈 껍질 — 안의 것이 제 발로 나간 지 오래였다.<br><br>
        빈 껍질로 두 가지를 배웠다. 고치 줄기는 한 번에 베어지는 굵기라는 것 — 그리고 천장 줄기 자국으로 — 안 나간 고치와 나간 고치가 구분된다는 것.<br>
        나간 자리 밑으로만 길을 그려 — 서른 걸음을 유유히 지났다.<br>
        베어 본 둘이 지도값을 했다. 모르는 복도는 — 죽은 것부터 물어볼 것.`,
      ng:`둘째 고치가 — 죽은 게 아니라 식은 거였다. 베어 내린 껍질 안에서 마른 것이 — 반쯤 산 것이 — 기어 나왔다.<br><br>
        느렸다. 그게 다행이었다. 칼배로 눌러 끝냈다.<br>
        그 소동의 떨림에 복도 안쪽 고치 둘이 박자를 흩뜨렸다. 서른 걸음을 — 숨을 쪼개 가며 — 두 배의 시간으로 지났다. 죽은 것과 식은 것 — 그 구분이 오늘의 숙제로 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-15 } }
  ] },

// ---------- S2 『백악기 정원』 ----------

{ at:'S2', t:'담장의 새 기둥',
  x:`밤새 밀린 담장 — 기둥 하나가 부러져 누웠다. 대신 세울 쇠기둥은 없다.<br><br>
    있다. 등에. 두 자 반 강철.<br>
    칼을 기둥으로 심는 것 — 벼랑의 밤에 해 봤다. 이번에는 하룻밤이 아니라 — 이 구간을 지나는 내내다. 칼 없는 등으로 백악기 정원을 걷는다는 뜻이다.<br><br>
    담장이냐 등이냐. 다섯 목숨의 울타리냐 한 손의 무기냐.`,
  o:[
    { l:'① 심는다 — 부러진 기둥 자리에 칼을 박고, 그물을 걸어 맨다.', k:'break', dc:26, wake:1,
      ok:`부러진 기둥을 뽑고 그 구멍에 — 대검을 거꾸로, 자루가 위로 오게 박았다. 어깨까지 묻히게 세 번에 나눠.<br><br>
        그물을 자루에 걸어 매자 담장이 다시 한 줄이 됐다. 그 밤 — 쿵. 시험하러 온 놈이 새 기둥을 받았다. 강철 기둥은 — 안 운다. 받은 쪽이 울었다.<br>
        구간을 다 지나는 사흘 — 등이 가벼웠고 잠이 깊었다. 떠나는 날 칼을 뽑아 도로 멨다.<br><br>
        칼을 놓아 보니 알겠다. 대검사의 일은 칼을 쥐는 게 아니라 — 어디에 둘지 아는 것까지다.`,
      ng:`박은 자리가 — 밤새 빗물에 물렀다. 새벽 시험에 기둥이 — 칼이 — 반 뼘 기울었다.<br><br>
        뽑히지는 않았다. 기운 채 버텼고, 아침에 돌을 날라 밑동을 다졌다.<br>
        사흘 내내 비 올 때마다 밑동부터 봤다. 심는 땅은 마른 날 골라 — 아니, 비 올 셈까지 하고 고를 것.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-27, mind:-14 } },
    { l:'② 안 심는다 — 부러진 기둥 둘을 칼로 깎아 잇고, 칼은 등에 남긴다.', k:'fix', dc:25,
      ok:`부러진 기둥과 예비 각목 — 칼로 양쪽 끝을 어긋나게 깎아 겹치고, 철사로 감아 이었다. 목수의 이음을 대검이 했다.<br><br>
        이은 기둥은 새것만 못하다 — 그래서 그 앞에 돌무더기를 보태 쌓았다. 기둥 반, 돌 반.<br>
        그 밤의 시험을 — 버텼다. 삐걱댔지만 버텼다.<br>
        칼은 등에 있다. 담장도 서 있다. 두 마리 토끼의 밤 — 이음과 돌무더기의 값이다.`,
      ng:`깎아 이은 자리가 — 둘째 밤 시험에 우지끈 갈라졌다.<br><br>
        결국 한밤에 칼을 뽑아 들고 뚫린 틈을 몸으로 막는 당번이 됐다. 새벽까지.<br>
        아침에 다시 — 이번에는 세 겹으로 — 이었다. 이음은 시험 한 번 버틴 걸로 믿지 말 것. 두 번째 시험이 진짜 시험이다.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-28, spirit:-15 } }
  ] },

{ at:'S2', t:'물밭의 다리 — 눕는 칼',
  x:`물에 잠긴 고사리밭 — 한 군데, 물밑 두 바위 사이가 배꼽 깊이로 패인 물목이 있다. 등줄기들이 그 물목에서 기다린다. 건너는 것들의 다리가 깊이 잠기는 자리라서.<br><br>
    두 바위 사이 — 두 자 반이다. 대검의 길이다.<br>
    칼집째 바위 사이에 걸치면 물 위 한 뼘의 다리가 된다. 균형 잡고 세 걸음이면 건너는 폭.<br><br>
    등줄기들이 기다리는 물목 위로 — 저것들 머리 위로 — 마른 발이 지나가는 그림이다.`,
  o:[
    { l:'① 칼다리를 놓고 — 한 사람씩, 등줄기들 머리 위로 건넌다.', k:'fix', dc:26, wake:1,
      ok:`칼집째 두 바위에 걸치고 양 끝을 돌로 괴었다. 물 위 한 뼘 — 폭 반 뼘의 다리.<br><br>
        첫 사람이 세 걸음에 건넜다. 물밑 등줄기가 그 발 — 물에 안 닿는 발 — 밑을 두 번 지났다. 셈이 안 맞는 먹이.<br>
        다섯이 다 건너고 칼을 거뒀다. 물목의 것들은 끝까지 한 입도 못 벌었다.<br><br>
        대검의 두 자 반이 — 오늘은 길이로 일했다. 날도 무게도 아니고 길이로. 칼의 쓸모 목록이 또 한 줄 늘었다.`,
      ng:`넷째 사람 — 제일 무거운 — 때 괸 돌 하나가 물러났다. 다리가 기울며 그 발이 물목에 — 첨벙.<br><br>
        등줄기가 번개같이 꺾어 들어왔다. 양쪽에서 손을 뻗어 낚아채고, 이쪽은 기운 칼을 눌러 버텼다.<br>
        물린 데 없이 건넜다 — 장화 한 짝만 물목에 바쳤다. 다리 괴는 돌은 제일 무거운 사람 셈으로 괼 것.`,
      win:{ exp:23, dream:3 }, lose:{ hp:-28, mind:-14 } },
    { l:'② 다리를 안 놓는다 — 물목에 미리 칼을 꽂아 등줄기들의 길부터 끊는다.', k:'break', dc:26, cost:{ might:36 },
      ok:`물목은 등줄기들의 길이기도 하다 — 깊은 물끼리 잇는 유일한 목. 그 목 한가운데 칼을 — 날을 물길과 직각으로 — 꽂았다.<br><br>
        물밑에 강철 벽이 섰다. 등줄기 하나가 길을 쓰려다 — 콧등으로 벽을 읽고 돌아갔다. 둘째도.<br>
        목이 끊긴 물목은 그냥 얕은 물이다. 다섯이 바지만 적시고 건넜다.<br>
        칼을 뽑아 메며 — 물에게 금을 그은 첫날로 적었다. 물에도 길이 있고, 길이 있으면 끊을 수도 있다.`,
      doom:{ title:'물목의 것', what:'물목 깊은 물로 끌려 들어갑니다', dc:19, sec:38,
        text:`꽂은 자리 물밑이 — 뻘이었다. 콧등으로 벽을 읽은 첫 놈이 벽을 — 밀었다. 칼이 기울었다.<br><br>
          기운 칼을 붙들러 물목에 들어간 그림이 — 저쪽이 기다린 그림이었다.<br>
          칼자루를 쥔 손 위로 긴 몸통이 감겼다. 발밑 뻘이 꺼지고, 깊은 물 쪽으로 — 칼째 — 끌린다. 칼을 놓으면 손이 비고, 안 놓으면 몸이 간다. 대검사의 손은 — 이럴 때 안 놓는 쪽으로 굳어 있다. 그게 문제다.`,
        dieText:`물목이 잠잠해진 뒤 — 고사리 사이로 칼자루 끝이 반 뼘 솟아 있었다.<br><br>
          물속의 칼은 아무도 못 건졌다. 뻘이 칼째 물고 있었다.<br>
          일행은 상류로 돌아 건넜다. 그 물목에는 이제 강철 벽이 하나 서 있다 — 세운 사람 없이. 등줄기들이 그 벽을 아직도 피해 돈다는 것만이 — 위로라면 위로였다.`,
      } }
  ] },

{ at:'S2', t:'큰 것 아래의 강철 지붕',
  x:`트인 진흙벌 한가운데서 — 큰 것과 마주쳤다. 숨을 데가 없다. 엎드릴 풀도 없다.<br><br>
    큰 것의 눈은 움직임을 본다. 콧등은 살 냄새를 읽는다. 그리고 지금 — 다섯은 진흙투성이다. 냄새는 진흙이 반쯤 가려 준다. 남는 건 윤곽과 움직임.<br>
    대검을 진흙에 비스듬히 꽂고 다섯이 그 그늘에 — 날 뒤에 — 포개 엎드리면, 윤곽은 바위 하나다.<br><br>
    큰 것이 오는 길이 — 하필 이 바위 곁이다.`,
  o:[
    { l:'① 바위가 된다 — 칼을 꽂고, 날 뒤에 다섯이 포개 엎드린다.', k:'steady', dc:26, wake:1,
      doom:{ title:'큰 것의 콧등', what:'큰 것에게 물려 올려져 실려 갑니다', dc:20, sec:35,
        text:`콧등이 — 바위를 의심했다. 어제까지 없던 바위라서인지, 진흙 밑 냄새가 샜는지.<br><br>
          콧김이 칼날을 넘어 들어오고 — 제일 바깥에 엎드린 이쪽 등짐 끈을 이빨이 걸었다.<br>
          끈째 들어 올려진다. 발밑에서 벌판이 — 꽂힌 칼과 엎드린 넷이 — 점이 된다. 큰 것은 문 것을 바로 안 삼킨다. 새끼들 있는 데로 가져간다. 그 걸음이 시작됐다.`,
        dieText:`벌판의 칼은 그대로 서 있었다. 그 뒤에 넷.<br><br>
          큰 것의 발소리가 멀어진 뒤에도 한참 — 아무도 일어나지 못했다.<br>
          칼을 뽑아 멘 것은 막내였다. 메 본 사람은 안다 — 그 무게의 반은 강철이고 반은 — 그날부터 막내의 등이 조금 굽은 이유다.`,
      },
      ok:`칼을 꽂고 — 다섯이 날 뒤에 지붕 기와처럼 포개 엎드렸다. 숨은 길게, 움직임은 영.<br><br>
        큰 것이 곁을 지났다. 발 하나가 세 걸음 거리에 — 진흙이 파도처럼 밀려와 몸을 반쯤 덮었다. 그게 오히려 윤곽을 지웠다.<br>
        콧등이 한 번 바위 쪽으로 기울었다 — 쇠 냄새는 먹이 냄새가 아니다. 지나갔다.<br>
        일어나 보니 다섯 다 진흙 바위 반쪽이 돼 있었다. 칼은 — 늠름하게 서 있었다. 오늘의 공로자는 서 있던 쪽이다.`,
      win:{ exp:24, dream:4 } },
    { l:'② 바위가 아니라 — 죽은 것이 된다. 진흙에 눕고 칼을 제 위에 얹는다.', k:'hide', dc:26,
      ok:`큰 것은 산 것을 본다 — 죽어 널린 것은 밟지 않고 돌아간다. 벌판의 법.<br><br>
        다섯이 진흙에 아무렇게나 — 죽은 그림으로 — 눕고, 칼을 그 위에 쓰러진 나무처럼 얹었다.<br>
        큰 것이 곁에서 한 번 멈췄다. 죽은 것 다섯과 쇠 하나 — 셈이 끝나는 데 세 호흡. 돌아서 갔다.<br>
        일어나며 다들 말이 없었다. 죽은 척은 — 이기는 수인데 이긴 기분이 안 나는 수다. 그래도 적어 둔다. 벌판에서는 죽은 그림이 산 그림보다 오래 산다.`,
      ng:`죽은 그림 — 넷은 완벽했다. 다섯째의 발끝이 — 모기인지 뭔지에 — 움찔했다.<br><br>
        죽은 것은 움찔하지 않는다. 큰 것의 머리가 내려왔다.<br>
        콧김 두 번 — 영겁 — 그리고 흥미를 잃고 갔다. 산 것치고는 너무 가만있고 죽은 것치고는 — 뭐 그런 셈이었기를. 일어난 다섯 중 셋이 다리가 풀려 도로 앉았다.`,
      win:{ exp:21, dream:3 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'S2', t:'반원 앞의 큰 호 — 한 번에 네 개의 금',
  x:`사냥 무리 넷이 반원으로 — 이번에는 트인 길에서. 벽도 덤불도 없다. 다섯 대 넷의 정면.<br><br>
    대검이 제값을 하는 판이다. 두 자 반의 호 — 한 번의 휘두름이 긋는 금이 반원 전체에 닿는 넓이.<br>
    창은 하나를 찌른다. 대검은 넷 앞에 한꺼번에 금을 긋는다. 베지 못해도 — 금이 보인다는 게 값이다.<br><br>
    반원이 좁혀 온다. 호를 그릴 자리와 때 — 그걸 정하는 게 대검사다.`,
  o:[
    { l:'① 큰 호 — 반원이 금에 드는 순간, 지면 한 뼘 위로 수평의 호를 긋는다.', k:'break', dc:26, cost:{ might:39 },
      ok:`반원 넷의 앞발이 — 한 걸음 안에 드는 순간을 쟀다. 그 순간 — 무릎을 낮추고 지면 한 뼘 위 수평으로, 왼 끝에서 오른 끝까지.<br><br>
        두 자 반의 호가 넷의 앞발 높이를 — 한 번에 — 지났다. 둘은 물러서다 뒤엉키고, 하나는 앞발을 스쳐 절고, 하나는 호 안쪽에서 — 호 안쪽은 대검의 집이다.<br>
        반원이 깨졌다. 깨진 반원은 각자다 — 각자가 된 것들은 일행 창들의 셈이다.<br>
        큰 호 한 번의 값 — 오늘은 넷이었다.`,
      ng:`호를 긋는 순간 — 가운데 놈이 뛰었다. 수평의 금 위로.<br><br>
        금을 넘은 무게가 어깨로 떨어졌다. 깔린 채 자루 머리로 턱을 밀어 올리며 버텼다.<br>
        일행 창 둘이 꿰고서야 치웠다. 수평의 호는 — 뛰는 놈 셈을 빼먹으면 반쪽이다. 다음 호에는 비스듬한 각을 섞을 것.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-33, mind:-14 } },
    { l:'② 호를 아낀다 — 칼을 땅에 꽂고 그 뒤에 서서, 반원이 제풀에 풀리기를 기다린다.', k:'gaze', dc:25,
      ok:`반원은 — 좁히는 동안만 반원이다. 칼을 꽂고 그 뒤에 다섯이 뭉쳐 서서 — 아무 짓도 안 했다.<br><br>
        좁히던 넷이 — 꽂힌 강철과 그 뒤의 다섯 앞에서 걸음 셈이 흐트러졌다. 좁혀도 깨지지 않는 먹이는 먹이 셈이 안 선다.<br>
        반 각을 서로 버티다 — 반원이 먼저 풀렸다. 넷이 풀숲으로.<br>
        안 휘두른 대검이 이긴 판 — 꽂힌 칼의 위압도 대검의 무공이다. 수련 목록에 없는 무공이지만.`,
      ng:`버티기 반 각 — 넷 중 막내 격인 놈이 셈을 못 참고 들어왔다. 젊은 놈은 셈이 짧다.<br><br>
        꽂힌 칼을 뽑는 반 호흡이 — 급했다. 뽑다가 균형이 흔들려 첫 합을 어깨로 받았다.<br>
        둘째 합은 칼이 받았고 놈은 물러갔다. 꽂은 칼 뒤에 설 때는 — 뽑는 반 호흡까지 셈에 넣고 설 것.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'낡은 엘리베이터 — 멈추지 않는 추락',
  x:`승강기가 오르다 — 권양기 톱니가 이 하나를 잃었다. 줄이 역회전으로 풀리며 승강기가 미끄러져 내리기 시작한다. 안에 넷.<br><br>
    권양기는 잡을 수 없다 — 손잡이가 역회전으로 미쳐 돈다. 잡으면 팔이 간다.<br>
    대검사의 눈이 승강로를 — 내려가는 승강기 바닥과 승강로 벽 사이 한 뼘 틈을 본다.<br>
    저 틈에 두 자 반 강철을 — 꽂으면 멎는다. 꽂는 팔이 버티면.`,
  o:[
    { l:'① 틈에 칼을 꽂는다 — 강철 쐐기로 추락을 문다.', k:'break', dc:26, wake:1,
      ok:`반 층 — 미끄러지는 승강기 바닥 모서리와 벽 보 사이, 그 한 뼘에 날을 — 옆면으로 — 꽂아 넣고 자루를 어깨로 눌렀다.<br><br>
        강철이 강철을 물었다. 끼이이 — 불꽃 한 줄 — 멎었다.<br>
        안의 넷이 기어 나오는 동안 어깨로 버텼다. 마지막 발이 나오고 칼을 빼자 승강기가 — 바닥까지 — 미끄러져 내려 쿵.<br><br>
        칼이 쐐기가 된 반 호흡 — 대검의 두께와 이쪽 어깨가 넷의 바닥이었다. 어깨는 사흘 저렸고, 사흘 내내 넷이 번갈아 밥을 펐다.`,
      ng:`꽂는 순간 — 승강기 무게가 날을 타고 팔로 왔다. 쐐기는 물렸는데 이쪽 발이 밀렸다.<br><br>
        반 층을 더 — 칼째 끌려 내려가며 — 벽 보에 등을 받치고서야 같이 멎었다.<br>
        넷은 나왔다. 등과 어깨가 보 모양으로 멍들었다. 쐐기 일은 꽂는 자리만큼 — 디딜 자리가 반이다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 칼이 아니라 — 추를 본다. 내려오는 균형추 길에 침목을 던져 괸다.', k:'sense', dc:26,
      ok:`승강기가 내려가면 — 추는 올라온다. 멈출 것은 둘 중 아무거나다.<br><br>
        추가 오르는 길목 — 추 레일 턱에 침목 토막을 걸쳐 던졌다. 추가 침목을 치받고 — 물렸다. 줄 전체가 멎었다.<br>
        승강기도 반 층에서 멎었다. 넷이 창살을 타고 올라왔다.<br>
        내려가는 것만 보면 — 올라오는 것을 놓친다. 도르래의 양끝은 한 몸 — 기계 싸움은 반대쪽부터 볼 것.`,
      ng:`던진 침목이 — 추에 맞고 튕겨 승강로 바닥으로 떨어졌다. 헛수.<br><br>
        결국 칼을 꽂는 수로 — 반 층 늦게 — 돌아갔다. 늦은 반 층만큼 꽂는 자리가 나빴고, 버티는 어깨가 더 비쌌다.<br>
        넷은 나왔다. 침목은 걸치는 것 — 던지는 게 아니라는 걸, 어깨가 두고두고 복습시켰다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, spirit:-15 } }
  ] },

{ at:'S2', t:'고목 — 세 번의 도끼질',
  x:`물이 불어 길이 끊겼다. 건널 것은 — 물가의 죽은 고목 하나. 베어 눕히면 다리다.<br><br>
    도끼가 없다. 대검이 도끼 노릇을 한다 — 늘 있는 일이다. 문제는 소리와 시간. 고목 베는 소리는 멀리 가고, 무리의 귀는 밝다.<br>
    대검사의 셈 — 몇 번에 벨 것인가. 세 번이면 소리 세 번. 열 번이면 열 번.<br><br>
    세 번에 베는 각도와 깊이 — 그걸 아는 것이 대검사다.`,
  o:[
    { l:'① 세 번 — 물매 각으로 두 번, 반대에서 한 번.', k:'break', dc:26, wake:1, cost:{ might:38 },
      ok:`첫 번 — 물 쪽으로 기울 방향에 비스듬히 깊게. 둘째 — 같은 자리 아래에서 마주 올려, 쐐기꼴 입을 땄다. 셋째 — 반대쪽 한 치 위를 끊었다.<br><br>
        고목이 — 물 위로 — 천천히 누웠다. 소리는 세 번, 눕는 소리는 물이 삼켰다.<br>
        무리가 소리 자리에 닿았을 때 다섯은 이미 건너 — 고목 끝을 물로 밀어 다리까지 끊은 뒤였다.<br><br>
        세 번의 셈 — 나무의 결과 기울 셈과 날의 각이 한 줄에 서는 세 번. 도끼장이 평생 일을 대검이 세 번에 했다.`,
      ng:`둘째 쐐기 입이 — 얕았다. 셋째에 안 눕고, 넷째 다섯째 — 소리가 다섯 번.<br><br>
        여섯째에 누웠다. 무리의 발소리가 벌써 가깝다.<br>
        구르다시피 건너 고목을 밀어 끊었다. 건너편에서 무리가 물가를 서성이는 걸 보며 숨을 골랐다. 쐐기 입은 — 손가락 세 개 깊이. 두 개로는 셈이 밀린다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-29, mind:-14 } },
    { l:'② 베지 않는다 — 고목의 썩은 뿌리 쪽을 지렛대로 들어 눕힌다.', k:'fix', dc:25,
      ok:`고목 밑동을 돌았다 — 물 쪽 뿌리가 반은 삭아 떠 있다. 베는 나무가 아니라 — 미는 나무다.<br><br>
        칼을 뿌리 밑에 꽂고 바위를 받침 삼아 — 다섯이 자루에 체중을 걸었다. 두 번의 들썩임에 뿌리가 — 뚝 — 놓았다.<br>
        고목이 물 위로 누웠다. 소리는 — 뿌리 끊기는 소리 한 번.<br>
        베는 소리 세 번보다 싼 한 번. 나무도 벽처럼 — 급소가 있다. 늘 날부터 댈 일이 아니다.`,
      ng:`뿌리가 — 반만 놓았다. 고목이 비스듬히 걸쳐 흔들리는 반다리가 됐다.<br><br>
        건너기는 건넜다 — 한 사람씩, 흔들림을 발바닥으로 달래 가며. 막내는 기어서.<br>
        마지막에 뿌리가 마저 놓으며 고목이 떠내려갔다 — 다리 끊는 수고는 덜었다. 반만 놓은 뿌리는 반다리 — 셈에 넣고 디딜 것.`,
      win:{ exp:21, dream:2 }, lose:{ hp:-27, spirit:-16 } }
  ] },

{ at:'S2', t:'둥지 곁 — 소리 나는 등짐',
  x:`둥지 곁을 지나는 좁은 길 — 소리를 내면 안 되는 백 걸음이다.<br><br>
    대검사의 적은 이번에는 제 등이다. 두 자 반 강철과 멜빵 쇠고리 — 걸음마다 철컥일 수 있는 것이 여섯 군데.<br>
    출발 전에 — 고리마다 천을 물리고, 칼집 입구에 이끼를 다져 넣고, 멜빵을 한 번 더 조인다. 대검사의 몸단장은 싸움 전이 아니라 — 침묵 전이 제일 길다.<br><br>
    새끼들의 숨소리가 들리는 거리다. 어미의 숨소리도.`,
  o:[
    { l:'① 여섯 군데를 다 죽이고 — 숨 박자로 백 걸음을 걷는다.', k:'hide', dc:26, wake:1,
      ok:`고리 여섯에 천 여섯 — 칼집 입에 이끼 — 멜빵 두 번 조임. 그리고 마지막으로 — 한 바퀴 제자리 뜀. 소리 — 없음. 그게 검사다.<br><br>
        백 걸음을 — 새끼들 숨 박자에 발을 묻고 — 걸었다. 등의 강철이 한 번도 입을 안 열었다.<br>
        어미의 숨이 한 번 끊겼다 이어졌다 — 꿈이었기를. 백한 걸음째부터 다시 보통 걸음.<br><br>
        대검을 메고 침묵을 지나는 법 — 제일 큰 칼의 제일 작은 걸음. 몸단장 순서를 교본 여백에 적었다.`,
      ng:`아흔 걸음 — 다 왔다 싶은 그 걸음에 — 칼집 바닥과 허리띠 버클이 — 철컥.<br><br>
        조인 멜빵이 걸음에 늘어난 것이다. 어미의 숨이 — 멎었다.<br>
        남은 열 걸음을 숨도 안 쉬고 — 어미의 숨이 다시 돌 때까지 바위처럼 섰다가 — 마저 걸었다. 멜빵은 백 걸음마다 다시 조일 것. 가죽은 걸으면 는다.`,
      win:{ exp:23, dream:3 }, lose:{ mind:-18, spirit:-17 } },
    { l:'② 등에서 내린다 — 칼을 두 팔로 안고, 요람 안듯 지난다.', k:'steady', dc:25,
      ok:`철컥일 것들은 전부 등과 멜빵 사이에 있다 — 그러면 등에서 내리면 된다. 칼집째 두 팔로 — 아기 안듯 — 가슴에 안았다.<br><br>
        안은 쇠는 울지 않는다. 백 걸음 — 팔은 저렸지만 소리는 영이었다.<br>
        지나고 나서 막내가 웃음을 참은 얼굴로 봤다. 뭐라도 말하면 — 이 요람으로 한 대, 라는 눈으로 답했다.<br>
        안기는 칼의 백 걸음 — 우스운 그림이 제일 조용한 그림일 때가 있다.`,
      ng:`여든 걸음 — 저린 팔이 반 뼘 처지며 칼집 끝이 — 바닥 돌을 톡.<br><br>
        작은 소리. 새끼 하나가 — 깼다. 울음 반 호흡 전에 — 어미의 숨이 뒤척였다.<br>
        전원 정지 — 반 각 — 새끼가 도로 잠들고서야 마지막 스무 걸음을 났다. 안는 수는 좋은 수지만 — 팔의 장부도 백 걸음짜리인지 먼저 셈할 것.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-16 } }
  ] }

]);
